window.STORY_CATEGORIES = window.STORY_CATEGORIES || {}; window.STORY_CATEGORIES[8] = [{"id":1040,"category_id":8,"category_code":"s8","source_id":1,"title":"اتحاد کبوترها","content":"روزی روزگاری در یک جنگل بزرگ، تعدادی کبوتر زندگی می‌کردند. در آن نزدیکی یک شکارچی هم بود که هر روز به سراغ این پرندگان می‌رفت و تورش را روی زمین پهن می‌کرد و وقتی پرنده‌ای روی تور می‌نشست آن را شکار می‌کرد. کبوترها از این موضوع خیلی ناراحت بودند،چون کم‌کم تعدادشان کم می‌شد و غم و غصه در جمع آنها نفوذ کرده بود.\r\nیک روز کبوتر پیر، همه کبوترها را جمع کرد تا با آنها صحبت کند و بعد همگی با هم تصمیم بگیرند که چه کاری باید انجام دهند تا از دست این شکارچی بدجنس راحت شوند. هر کدام از کبوترها یک نظر می‌دادند و کبوترهای دیگر موافقتشان را اعلام می‌کردند. در بین آنها یک کبوتر دانا بود که در آخر جلسه به دوستانش گفت من فقط یک مطلب را می‌خواهم یادآوری کنم‌ و آن هم این است که همه ما باید قبل از هر چیز و هر کاری اتحاد داشته باشیم، چون‌ هیچ‌کس به تنهایی نمی‌تواند کاربزرگی انجام دهد، مگر آن که در یک گروه هماهنگ باشد. \r\nتمام کبوترها با سرهای کوچکشان حرف او را تایید کردند و همه با هم‌پیمان بستند و بال‌هایشان را یکی‌یکی روی هم گذاشته و یک صدا گفتند ما با هم دشمن را شکست می‌دهیم. \r\nفردای آن روز سروکله شکارچی پیدا شد و دوباره تورش را روی زمین پهن کرد و مقداری دانه هم روی تور پاشید و در گوشه‌ای پنهان شد. چندی نگذشت که همه پرندگان با هم روی تور نشستند و مشغول دانه خوردن شدند. شکارچی که خیلی خوشحال شده بود سریعا تور را جمع کرد و تمام کبوترها داخل تور گیر افتادند و منتظر شدند تا او نزدیک شود. زمانی که شکارچی سر تور را گرفت همه کبوترها با هم به پرواز درآمدند و آنقدر بال زدند و بالا رفتند تا او را از زمین بلند کردند. شکارچی هم دست و پا می‌زد و کمک می‌خواست. کبوتر دانا از بین جمع فریاد زد: پرواز به سمت دریاچه و همه به گفته او عمل کردند و شکارچی را به سمت دریاچه بردند. شکارچی که خیلی ترسیده بود کم‌کم دست‌هایش شل شد و طناب را رها کرد و به داخل دریاچه افتاد و کبوترها هم به وسط جنگل رفتند و تور آنها در جنگل به شاخه درختی گیر کرد. داخل آن درخت یک سنجاب زندگی می‌کرد و سنجاب که دید کبوترها داخل تور گیرافتاده‌اند دوستانش را صدا کرد و همه با هم طناب‌ها را جویدند و کبوترها را از داخل تور نجات دادند‌. شکارچی هم دیگر هیچ‌وقت آن طرف ها پیدایش نشد.\r\n"},{"id":1041,"category_id":8,"category_code":"s8","source_id":2,"title":"دو درخت همسایه","content":"در یک باغچه کوچک ، دو درخت زندگی می کردند . یکی درخت آلبالو و دیگری درخت گیلاس .\r\nاین دو تا همسایه با هم مهربان نبودند و قدر هم را\r\nنمی دانستند، بهار که می رسید شاخه های این دو تا همسایه پر از شکوفه های قشنگ می شد ولی به جای این که با رسیدن بهار این دو هم مهربانتر و با صفاتر بشوند بر سر \r\nشکوفه هایشان و این که کدامیک زیباتر است ، بحث می کردند. در فصل تابستان هم بحث آنها بر سر این بود که میوه های کدامیک از آنها بهتر و خوشمزه تر است .\r\nدرخت آلبالو می گفت : آلبالو های من نقلی و کوچولو و قشنگ هستند ، اما گیلاس های تو سیاه و بزرگ و زشتند. \r\nدرخت گیلاس هم می گفت : گیلاس های من شیرین و خوشمزه است ، اما آلبالوهای تو ترش و بدمزه است. \r\nسالها گذشت ، تا این که دو تا درخت پیر و کهنسال شدند اما عجیب بود که آنها هنوز هم با هم مهربان نبودند.\r\nدر یکی از روزهای پاییزی که طوفان شدیدی هم می وزید ناگهان یکی از شاخه های درخت گیلاس، شکست ، بعد هم شروع کرد به ناله و فریاد .\r\nدرخت آلبالو که تا آن روز هیچ وقت دلش برای درخت گیلاس نسوخته بود و اصلاً به او اهمیتی نداده بود یکدفعه دلش نرم شد و به درد آمد و گفت همسایه عزیز نگران نباش اگر در برابر باد قدرت ایستادگی نداری می توانی به من تکیه کنی، من کنار تو هستم و تا جایی که بتوانم کمکت می کنم ،آخر من و تو که به جز همدیگر کسی را نداریم .\r\nدرخت گیلاس از محبت و مهربانی درخت آلبالو کمی آرامش پیدا کرد و گفت : آلبالو جان از لطف تو متشکرم می بینی دوست عزیز دوستی و مهربانی خیلی زیباست !\r\nحیف شد که ما این چند سال گذشته را صرف کینه و بد اخلاقی خودمان کردیم . \r\nبعد هر دو تصمیم گرفتند که خود خواهی را کنار بگذارند و \r\nزیبایی های دیگران را هم ببینند . فصل بهار که از راه رسید درخت گیلاس رو کرد به آلبالو و گفت : «به به چه شکوفه های قشنگی چه قدر خوشبو و خوشرنگ، اینطوری خیلی زیبا شده ای !»\r\nو درخت آلبالو جواب داد « دوست نازنینم ، این زیبایی وجود توست که من را زیبا می بیند . به خودت نگاهی بینداز که چه قدر زیبا و دلنشین شده ای !»\r\nدیگر هر چه حرف بین آنها رد و بدل می شد از مهربانی بود و همدلی و دوستی !\r\nو راستی که دوستی و محبت چقدر زیباست.\r\n"},{"id":1042,"category_id":8,"category_code":"s8","source_id":3,"title":"خرگوش با هوش","content":"در جنگل سر سبز و قشنگي خرگوش باهوشي زندگي مي كرد. \r\nيك گرگ پيرو يك روباه بدجنس هم هميشه نقشه مي كشيدند تا اين خرگوش را شكار كنند. \r\nولي هيچوقت موفق نمي شدند. \r\nيك روز روباه مكار به گر گ گفت : من نقشه جالبي دارم و اين دفعه مي توانيم خرگوش را شكار كنيم. \r\nگرگ گفت : چه نقشه اي ؟\r\nروباه گفت : تو برو ته جنگل ، همانجا كه قارچهاي سمي رشد مي كند و خودت را به مردن بزن . من پيش خرگوش مي روم و مي گويم كه تو مردي . وقتي خرگوش مي آيد تا تو رو ببيند تو بپر و او را بگير .گرگ قبول كرد و به همانجائي رفت كه روباه گفته بود. \r\nروباه هم نزديك خانه خرگوش رفت و شروع به گريه و زاري كرد. \r\nبا صداي بلند گفت : خرگوش اگر بدوني چه بلائي سرم آمده و همينطور با گريه و زاري ادامه داد ، ديشب دوست عزيزم گرگ پير اشتباهي از قارچ هاي سمي جنگل خورده و مرده اگر باور نمي كني برو خودت ببين \r\nو همينطور كه خودش ناراحت نشان ميداد دور شد. \r\nخرگوش از اين خبر خوشحال شد پيش خودش گفت برم ببينم چه خبر شده است.\r\nاو همان جائي رفت كه قارچهاي سمي رشد مي كرد . از پشت بوته ها نگاه كرد و ديد گرگ پير روي زمين افتاده و تكان نمي خورد. \r\nخوشحال شد و گفت از شر اين گرگ بدجنس راحت شديم . خواست جلو برود و نزديك او را ببيند اما قبل از اينكه از پشت بوته ها بيرون بيايد پيش خودش گفت :‌ اگر زنده باشد چي ؟ آنوقت مرا يك لقمه چپ مي كند . بهتر است احتياط كنم و مطمئن شوم كه او حتما مرده است. \r\nبنابراين از پشت بوته ها با صداي بلند ، طوريكه گرگ بشنود گفت : پدرم به من گفته وقتي گرگ ميمرد دهنش باز مي شود ولي گرگ پير كه دهانش بسته است .گرگ با شنيدن اين حرف كم كم و اهسته دهانش را باز كرد تا به خرگوش نشان بدهد كه مرده است .خرگوش هم كه با دقت به دهان گرگ نگاه مي كرد متوجه تكان خوردن دهان گرگ شد و فهميد كه گرگ زنده است . بعد با صداي بلند فرياد زد : اي گرگ بدجنس تو اگر مرده اي پس چرا دهانت تكان مي خورد . پاشو پاشو باز هم حقه شما نگرفت . و با سرعت از آنجا دور شد.\r\n"},{"id":1043,"category_id":8,"category_code":"s8","source_id":4,"title":"کوآلای قهرمان","content":"یکی بود یکی نبود توی جنگل ما کنار یک رود خانه درخت بزرگی قرار داشت که خانم کاکلی و جوجه هایش در آنجا زندگی می کردند هر چه زمان گذشت جوجه ها بزرگتر می شدند و به غذای بیشتری نیاز داشتند برای همین خانم کا کلی و آقای کا کلی با هم به دنبال غذا رفتند .\r\nجوجه ها تنها مانده بودند یک دفعه یک پروانه قشنگ پر زد و روی شا خه ای نشست جوجه ها که پروانه ندیده بودند از ترس سر هایشان را زیر پرهایشان کردند « مثلا پنهان شدند» .\r\nپروانه گفت : چرا می ترسید ؟ به من می گن پروانه معمولا?پرنده ها از دیدن من خوشحال می شوند چون من غذای آنها هستم .جوجه ها که گرسنه بودند تلاش کردند پروانه را بگیرند و بخورند ولی پروانه بالاتر پرید .\r\nآنها به پروانه گفتند: چقدر تو زیبا هستی و چه قشنگ می پری ، پروانه گفت: خداوند این بالهای زیبا را به من داده بعد هم پر زد بالاتر چون می ترسید پرنده ها بخورنش .\r\nجوجه ها داشتند درباره پروانه حرف می زدند که درخت تکان خورد فوری ترسیدند وسر هاشونو لای پر هم پنهان کردند.\r\nیک حیوان بزرگ با پنجه های قوی به درخت چسبیده بود با گوشهای پهن و بدن پشمالو خیلیم با نمک و مهربون به نظر می ر سید . به جوجه ها گفت :\r\nنترسید شما که غذای من نیستید.جوجه ها گفتند : ما را چه جوری دیدی ما که غایم شدیم . او گفت : ولی فقط شما سرتان را پنهان کردید بدنتان بیرون بود جوجه های قشنگ اسم من کوآلا است من نوعی خرس درختی هستم و در همسایگی شما با خا نواده ام کنار کلبه زندگی میکنم .\r\nجوجه ها گفتند : خوش به حالت می تونی همه جا بروی . کوآلا گفت : ولی من و همه حیوانات که با ل نداریم دوست داریم مثل شما پرنده باشیم ودر آسمان آبی و زیبای خداوند پرواز کنیم خدا نعمت بزرگ پرواز کردن را به شما داده صبر کنید بزرگتر شوید ، عجله نکنید .\r\nیک مرتبه کوآلا دید پرنده ی شکاری به سوی جوجه ها می آید فریاد زد : خطر! کوآلا خود را روی لانه ی جوجه ها انداخت و با پنجه های خود به بالهای پرنده شکاری می زد .\r\nپروانه خود را به خانم کاکلی رساند و گفت : مرا نخورید جوجه هایتان در خطر هستند زود بیائید . خانم کاکلی و کو آلا با کمک هم به هر زحمتی که بود پرنده ی شکاری را دور کردند .\r\nکوآلا کمی زخمی شده بود ولی خوشحا ل بود که توانسته جوجه های همسایه را نجات بدهد.\r\nخانم کاکلی از پروانه و کوآلا تشکر کرد و بعد از آن داستان شجاعت کوآلا در جنگل پیچید و همه او را کوآ لای قهرمان می نا میدند .\r\nقصه ی ما به سر رسید پرنده ی شکاری به مقصود نرسید . بالا رفتم دوغ بود پائین آمدیم ماست بود قصه ی ما راست بود .\r\n"},{"id":1044,"category_id":8,"category_code":"s8","source_id":5,"title":"اسراف نمی کنم زنده بمانم","content":"یکی بود یکی نبود غیر از خدای مهربون هیچ کس نبود توی یک جنگل سبز چند تا آهو با بچه هایشان زندگی می کردند .بچه های عزیز هر وقت که آهو خانم برای بچه هایش غذا تهیه می کرد و می آورد که بین آنها تقسیم کند یکی از بچه هایش به نام دم قهوه ای میگفت : من بیشتر می خوام .آهو خانم می گفت : آخر عزیز دلم باید به اندازه ای که می توانی بخوری ، و برداری اگر بیشتر برداری نیمه خور و اسراف می شود . \r\nولی آهو کوچولو گوشش بدهکار نبود . یک روز که با برادرش د نبا ل رنگین کمان می گشت تا سر رنگین کمان را پیدا کند و بگیرد ، یک سبد میوه که شاید انسانها آنجا ، جا گذاشته بودند را دید که ریخته شده روی زمین .\r\nطبق معمول از برادرش جلو زد و گفت: کنده ترین میوه مال من است و یک گلابی بزرگ را با پوزه خود (دهان ) به سمت خود کشید و یک گاز زد و سیر شد و آن را پرت کرد آن طرف . بقیه ی میوه ها را هم برای آهو خانم بردند.\r\nحالا بشنوید از آهو خانم که داشت لانه اش را تمیز می کرد دید لاک پشت ها دارند یک پرستوی بیمار را می برند گفت : صبر کنید این پرستو دوست بچه های من است چه اتفاقی افتاده گفتند : او بیمار است و دکتر لاک پشتیان گفته : اگر گلابی بخورد مداوا خواهد شد.\r\nآهو خانم گفت هر طور که شده برایش گلابی پیدا می کنیم لطفا?او را به لانهی ما بیاورید.\r\nبچه های آهو خانم آمدند هوا تاریک شده بود. آهو خانم سبد میوه را که دید گفت : توی میوه ها گلابی هم هست گفتند: نه ،آهو خانم گفت : پرستو اگر گلابی بخورد مداوا می شود .\r\nدم قهوه ای ناراحت به خواب رفت در خواب گلابی را که نیمه خور کرده بود دید\r\nکه گریه میکند به او گفت چرا گریه می کنی ؟ گلابی جواب داد : تو مرا به دور انداختی در حالی که می توانستم مفید باشم و بعد این شعر را به دم قهوه ای یاد داد :\r\nگلابی تمیزم همیشه روی میزم\r\nاگر که خوردی مرا نصفه نخور عزیزم\r\nخدا گفته به قرآن همان خدای رحمان\r\nاسراف نکن تو جانا در راه دین بمانا\r\n\r\nآهو کوچولو صبح زود بیدار شد و با برادرانش به جنگل رفت و به دنبال گلابی گشت . گلابی که نصفه خور کرده بود را پیدا کردند آن را در آب چشمه شستند و برای پرستو آوردند . وقتی پرستو گلابی را خورد نجات پیدا کرد و چشمانش را باز کرد و از آهو کوچولو تشکر کرد که جانش را نجات داده بود از آن به بعد دم قهوه ای دیگر اسراف نمی کرد و فریاد نمی زد زیاد می خواهم گنده می خواهم و حالا او می داند اسراف وهدر داد ن هر چیزی بد است و خدا اسراف کاران را دوست ندارد .\r\nقصه ی ما به سر رسید اسراف کار به بهشت نرسید.\r\n"},{"id":1045,"category_id":8,"category_code":"s8","source_id":6,"title":"دخترک شجاع","content":"یکی بود یکی نبود زیر گنبد کبود دختری به نام سیما در کلاس سوم ابتدایی درس می خواند او پدرش را زمانی که کلاس اول رفت از دست داده بود ولی با این حال درس اش نسبتا خوب بود دختری شاداب و کنجکاو بودهر چیزی را که می دید و می شنید یک قطار سوال برایش پیش می آمد . روز پنج شنبه به خاطر امتحان ریاضی سر صف جایزه کتاب تمدن سفید گرفت، که عکس های بزرگ شاه و خانواده اش بود که زندگی خود را صرف چه کارهایی می کنند او صفحه به صفحه کتاب را با دقت نگاه کرد و هر روز برای خواهر و مادر و حتی مهمانا نی که به خا نه شان می آمدند مثل یک نقال « قصه گو» تصاویر را توضیح می و از این کار لذت می برد زیرا عکس ها رنگ قشنگی داشت داد . چند روزی گذشت به درس نماز رسیده بودند .معلم شان گفت : بچه های عزیز از امروز نماز به شما واجب می شود چون شما 9 ساله شده اید همانطور که به بزرگترها نماز واجب است. عزیزان ،به جمع بزرگترها خوش آمدید!\r\nسیما گفت :اجازه خانم\r\nمعلم: بگو عزیزم\r\nاجازه نماز به دایی ما واجب است؟ بله\r\nبه شوهر خاله مان واجب است؟ بله \r\nمعلم دیگر اجازه نداد گفت : حتما ? می خواهی بگویی به دایی و پدرو برادر و عمو همه حتی رفتگر ، مهندس، دکتر و غیره همه واجب است ؟ بله عزیز به همه واجب است .\r\nسیما : اجازه ؛پس چرا شاه نماز نمی خواند؟\r\nمعلم :از کجا می دانی ؟\r\nسیما :توی کتاب تمد ن سفید که جایزه گرفته ام شاه هیچ کجا نماز نخوانده !\r\nمعلم :آخر شاه است وقت نمی کند خیلی کار دارد .\r\nسیما :پس چرا وقت می کند کنار دریا برود و خلبانی کند و گردش برود ولی وقت ندارد نماز بخواند.معلم دست سیما را محکم می گیرد و از کلاس بیرون می برد بعد خودش وارد دفتر شد به سیما گفت روی یک پا با یست و بعد از چند دقیقه با مدیر از دفتر خارج شد مدیر با خط کش بلندش به سمت سیما می آید سیما رنگش پریده بود.\r\nمدیر گفت: زود بگو کی این حرف ها را به تو یاد داده ؟ \r\nسیما :هیچ کس خانم اجازه خودمان پرسیدیم.\r\nمدیر گفت : دیگر از این سو الها نکن چند ضربه به کف دستش زد و گفت :\r\nسوال بی سوال با خدمتگذار برو خانه و مادرت را بیاور .\r\nمادرش تا درب را باز کرد گفت :چه اتفاقی افتاده درس نخوانده ؟ اذیت کرده؟\r\nخدمتگذار گفت : نمی دانم دختر خوبیه.\r\nمادر سیما به دفتر مدرسه وارد شد و سیما پشت چادر مادرش قایم شده بود .\r\nمدیر سوالا تی از مادر او کرد و بعد مادر سیما گفت :خانم جان قربونتون برم این دخترم همین جوری هر سوالی به دهنش برسد می پرسد به خدا خودش سر زیا ده هیچ کس یادش نداده شما به بزر گی خودتون ببخشید.مدیر گفت ما راهی جز اخراج کردن سیما نداریم زیرا نمی خواهیم پای ساواک به مدرسه ما باز شود و خودمان را به درد سر بیندازیم بروید خانه و سیما را از مدرسه بیرون کرد.مادرش ناراحت بود در راه خانه به سیما غر زد سیما می گفت :آخر من حرف بدی نزد م فردا دوباره مادر سیما برای لتماس پیش مدیر مدرسه رفت مدیر او را به مدرسه راه نمی داد آخر با آشنایی یکی از همسایه ها یشان به مدرسه دیگری رفت دو سال بعد انقلاب اسلامی با راهپیمایی و اعلامیه های امام خمینی (ره) آشنا شد .سیما با مادرش که از ظلم شاه و اطرافیانش ضربه خورده بودند در راهپیمایی ها شرکت می کرد او فهمیده بود که شاه چرا نماز نمی خواند ؟ حالا او برای دیدن امام خمینی لحظه شماری می کرد تا در روز 12 بهمن 1357 امام خمینی (ره ) از پاریس با هواپیما بعد از 15 سال دوری از وطن به ایران بازگشت و سیما امام را در تلویزیون دید و علا قه اش دو چندان شد .او امام را مانند پدرش دوست می داشت .\r\nسیما هیچ وقت این شعار زیبا را فراموش نمی کرد« مرگ بر شا ه، مرگ بر شاه ،مرگ بر شاه »\r\n"},{"id":1046,"category_id":8,"category_code":"s8","source_id":7,"title":"کاکولی ها","content":"یکی بود یکی نبود توی یک جنگل زیبا روی یک درخت قشنگ یک لانه پرنه بود توی لانه سه تا تخم زرد بود وقتی پرنده زرد روی تخمها می خوابید پرنده جفت برای او غذا می آورد چند روزی گذشت جوجه ها از توی تخم بیرون امدند اول خیلی قشنگ نبودند.\r\nجایی را هم نمی دیدند فقط دهانشان را باز می کردند و خانم پرنده و آقای پرنده برای آنها غذا می آوردند آنها با اتحاد وهمکاری جوجه ها را بزرگ کردند و زمان یاد دادن کارهایی شد که معمولا پرنده ها به بچه هایشان یاد می دهند خانم پرنده پرید پایین و یک تکه چوب را با منقار گرفت و پرید روی درخت جوجه ها هر کدام می خواستند به تنهایی یک شاخه چوب بزرگ را بالا بیاورند یکی میگفت من قوی ترم الان بلندش می کنم یکی دیگر میگفت خودم بلندش میکنم دعوا بالا گرفت و شروع کردند به هم نوک زدن خانم پرنده مهربون گفت جوجه های قشنگ با نمک من بیایید اینجا کارتون دارم 1 - دعوا نکنید شما برادر و خواهرهستید. 2- با هم باشید همیشه – کارها همه پیش .3- به این مورچه های کوچک نگاه کنید آن دانه که می برند مگر نه اینکه چندین برابر قد و قواره آنهاست ولی آنها با اتحاد و همدلی و انسجامی که دارند با هم دانه را بلند می کنند و همه در یک جهت حرکت میکنند در حالی که اگر این طرف و آن طرف میرفتند هرگز موفق به بردن دانه نمی شدند . کاری را انجام دهید که از عهده آن برآیید.حالا عزیزانم ببینم که چه میکنید. بعد هر سه پرنده با هم متحد شدند و آن تکه چوب را از زمین بلند کردند و پیش مامان پرنده نشستند.\r\nو مامان پرنده گفت آفرین و آنها را در آغوش گرفت آنها از مورچه ها یاد گرفتند که با هم متحد باشند تا توان انجام کارها را پیدا کنند .\r\n"},{"id":1047,"category_id":8,"category_code":"s8","source_id":8,"title":"سفینه ی زمان","content":"سعید و سعیده سوار بر سفینه زمان شده بودند. این خواهر و برادر می خواستند از قرن پانزدهم هجری قمری به چهارده قرن پیش سفر کنند. آن دو تصمیم داشتند به دورانی برگردند که رسول خدا در آن زندگی می کرد. سعید و سعیده می خواستند به اولین سال های حکومت اسلامی بازگردند و گزارش مفصلی از ماجرای غدیر خم را برای بچه های قرن بیست ویکم گزارش کنند.\r\nپنج، چهار، سه، دو، یک. . .بالاخره سفینه زمان از ایستگاه مرکز تحقیقات تاریخی به گذشته دور پرتاب شد. کودکانی که در ایستگاه ماهواره ای حاضر بودند با اشتیاق تمام این سفر جذاب و پرماجرا را دنبال می کردند و به طور دائم با دو زمان نورد در ارتباط بودند.\r\nسعید و سعیده سواربر سفینه کوچکشان به سال دهم هجری سفر نمودند. زمانی که رسول خدا (صلی الله علیه وآله و سلم) آخرین ماه های زندگی خویش را پشت سر می گذاشت و می خواست که آخرین حج خود را به انجام برساند.\r\nمدتی گذشت. ناگهان سعید ازداخل سفینه برای ایستگاه تحقیقاتی پیامش را این گونه مخابره کرد.\" بچه ها سلام. اکنون من از سرزمین وحی برای شما گزارش می کنم. حضرت محمد( صلی الله علیه وآله و سلم) مراسم حج را به پایان رسانیده وبه همراه کاروانی از حجاج در حال بازگشت به مدینه هستند. از این بالا کاروان های زیادی را مشاهده می کنیم که با فاصله های کمی از یکدیگر در حال حرکت به سوی سرزمین های مختلفی می باشند.\r\nهم اکنون رسول خدا به محلی رسید که به آن غدیرمی گویند. اینجا محلی است که کاروان های حجاج از یکدیگر جدا می شوند وهرکدام به سمت سرزمینی می روند. اینجا مثل یک چهارراه است. در غدیر برکه ای از آب زلال وجود دارد که دور تادورش را جمعیت حاجیان در برگرفته اند.\r\nکودکان جهان در پایگاه تحقیقاتی بی صبرانه منتظر اخبار جذاب تری از غدیر خم هستند و گزارشات لحظه به لحظه از غدیر را پیگیری می کنند.پس از مدتی سعیده با شور و شوق فراوانی می گوید:هم اکنون فرشته وحی بر پیامبر نازل گشت وبه او گفت: ای پیامبر آنچه که از طرف خدا فرستاده شده به مردم ابلاغ کن و اگر ابلاغ نکنی رسالت خود را تکمیل نکرده ای.\r\nسعید با خوشحالی ادامه می دهد: الله اکبر! این همان آیه شصت و هفت از سوره مائده است.\r\nایستگاه تحقیقاتی حال و هوای دیگری دارد. سعیده در ادامه گزارش می گوید:اکنون رسول خدا فرمود: من همین جا می مانم. حاجیانی که از راه نرسیده اند باید به اینجا برسند و آنانی که از این محل رفته اند باید هرچه زودتر به غدیر برگردند.\r\nسعید گزارش می دهد: به فرمان پیامبر حدود صد و بیست هزار نفر از مسلمانان در محل غدیر اجتماع کردند. این جمعیت در تاریخ اسلام واقعا بی سابقه است.\r\nکودکان جهان سکوت کرده اند و در این مدت با دقت به گزارشات گوش می دهند.کم کم واقعه غدیر خم به صورت صحیحی برای آنها بازگو می شود: رسول خدا بر روی جهاز شتران بالا رفته اند و پس از حمد و ستایش خدا دستور می دهند حضرت علی علیه السلام در کنار ایشان قرار بگیرد. سپس دست حضرت علی علیه السلام را در دست گرفته و جلوی چشمان صد و بیست هزار نفر بالا می برد و می گوید: ای مردم بدانید:\r\nهرکس تا امروز من ولی و سرپرست او بوده ام، از این به بعد این علی ولی و سرپرست اوست. این حکمی است از طرف خدا که علی امام و وصی پس از من است و امامان امت از فرزندان او هستند.\r\nسعید ادامه می دهد: الان پیامبر اعلام می کند: خداوندا! کسانی که علی علیه السلام را دوست دارند، دوست بدار وبا دشمنان او دشمن باش. خدایا! یاران علی علیه السلام را یاری کن و دشمنان او را خوار و ذلیل گردان.\r\nسعیده می گوید: اکنون لازم است که با سفینه مدت سه روز دیگر را در زمان حرکت کنیم. حالا سه روز\r\nاز ماجرای غدیر خم گذشته است و هنوز زنان و مردان مسلمان به طور جداگانه درمحل غدیر حضور دارند و با علی علیه السلام بیعت می کنند. مسلمانان در این روز با گفتن کلمه یا امیرالمومنین به ایشان دست می دهند.\r\nسعید می گوید: در چنین روزی دوست و دشمن با علی علیه السلام بیعت کردند وبه او تبریک گفتند.حاضرانی که دراین روز شاهد ماجرا بودند رفتند تا طبق وظیفه برای غایبان این واقعه را تعریف کنند. خدا کند که فراموش نکنند و سفارشات پیامبر را جدی بگیرند زیرا خداوند پیمان شکنان را در هم می شکند.\r\nبا معرفی حضرت علی علیه السلام وامامان از فرزندان او از سوی خداوند و اطاعت مردم از ایشان دیگر انسانها به سوی زشتی ها نمی روند وهیچ گاه از مسیر درست دور نمی شوند و منحرف نمی گردند.\r\nپس از گزارش این ماجرا سفینه زمان پیما با دو زمان نورد خود در روز عید غدیر خم به ایستگاه تحقیقات فضایی بازگشتند و از سوی کودکانی که در ایستگاه مستقر بودند مورد استقبال قرار گرفتند و آن روز را به جشن و شادمانی پرداختند.\r\n"},{"id":1048,"category_id":8,"category_code":"s8","source_id":9,"title":"پسر نجار و انگشتر جادویی","content":"یکی بود یکی نبود. غیر از خدای مهربان هیچ‌کس نبود. سالیان سال پیش، مرد دوره ‌گرد و دستفروشی همراه با همسرش زندگی می‌کرد. آنها صاحب فرزند پسری شدند اما هنوز مدت زیادی از تولد فرزندشان نگذشته بود که مرد دوره ‌گرد دچار بیماری مهلکی شد و از دنیا رفت و بار زندگی و وظیفه‌ی بزرگ کردن پسر بر گردن همسرش افتاد و زن، با وجود همه‌ی سختی‌ها و زحمات، فرزندش را پرورش داد تا به سن جوانی رسید و برومند شد.\r\nتا روزی رسید که برای آنها از تمام مال دنیا کیسه‌ای با سیصد سکه‌ی نقره باقی ماند. صبح هنگام، زن کیسه را که برای روز مبادا نگاه داشته بود از پستو بیرون آورد و صد سکه از آن بیرون آورد و پسرش را صدا کرد و گفت: پسرم، از دار و ندار دنیا همین سکه‌ها برای ما باقی مانده، آنها را بگیر و برو به کسب و کاری بپرداز تا خرج زندگی خودت و من کنی. حالا دیگر به سنی رسیده‌ای که بتوانی کار کنی و زندگی هر دویمان را سامان بدهی. \r\nپسر هم سکه‌ها را گرفت و راهی بازار شد. همین‌طور که مشغول گشتن در بازار و ورانداز کردن اجناس گوناگون بود، چشمش به چند جوان افتاد که بابت تفنن گربه‌ای را در کیسه‌ای انداخته بودند و می‌خواستند کیسه را در چاهی بیاندازند و گربه‌ی بیچاره دائم ناله می‌کرد. پسر جلو رفت و گفت: حیوان بیچاره را چرا آزار می‌دهید؟ من حاضرم آن را از شما بخرم. و بعد از مدتی چانه زدن سرانجام تمام سکه‌هایی را که به همراه داشت به آنان داد و کیسه را گرفت و گربه را از آن بیرون آورد و آزاد کرد. گربه خودش را به پای پسر مالید و در چشم‌هایش نگاه کرد و گفت: خوبی تو را هیچ وقت فراموش نمی‌کنم و روزی محبتت را جبران خواهم کرد و از امروز هر خدمتی که بتوانم در حقت به جا می‌آورم.\r\nپسر به خانه رفت و وقتی مادرش از کار آن روز پرسید، ماجرای گربه را برای او تعریف کرد. مادر، کمی رنجیده شد اما شکایتی نکرد. فردای آن روز، دوباره صد سکه از درون کیسه بیرون آورد و شمرد و به دست پسر داد و به او سپرد که مبادا این بار پولت را به پای کار بی‌مزد بریزی، برو و کسبی راه بیانداز و به فکر زندگیت باش. پسر سکه‌ها را گرفت و راهی بازار شد. در راه به چند نفر برخورد که طنابی به گردن سگی انداخته بودند و او را به ضرب چوب و لگد می‌کشیدند و می‌بردند. دلش به حال حیوان بینوا سوخت. جلو رفت و گفت: با این حیوان زبان بسته چه می‌کنید؟ آزادش کنید برود. \r\nجواب دادند اگر دلت برایش می‌سوزد می توانی آن را بخری و خودت آزادش کنی. پسر هم که طاقت دیدن زجر کشیدن سگ را نداشت، سکه‌هایش را داد و سگ را خرید و بند از گردنش برداشت و او را آزاد کرد. سگ با پسر همراه شد و گفت: ای انسان نیک سرشت، تو که خوبی کردی، جواب خوبیت را خواهی دید.\r\nپسر این بار هم دست خالی به خانه بازگشت و مادرش از هدر رفتن بخش دیگری از پول‌هایشان عصبانی شد. صبح روز بعد، مادر، آخرین صد سکه را به پسرش داد و به او توصیه کرد تا مراقب باشد آخرین سکه‌های سرمایه‌شان را حیف و میل نکند که دیگر هیچ اندوخته‌ای در بساط ندارند.\r\nپسر تا نزدیکی غروب در بازار گشت و چیزی برای خرید و فروش پیدا نکرد. با ناامیدی در گوشه‌ای نشسته بود که دید چند نفر دور جعبه‌ای جمع شده‌اند و قصد آتش زدن آن را دارند. پسر پیش رفت و فهمید که حیوانی درون جعبه است. به جماعتی که آنجا بودند اعتراض کرد و گفت: چرا چنین کاری می‌کنید؟ حتی اگر به شما زیانی هم زده باشد نباید این کار را انجام دهید. من آن را از شما می‌خرم. این‌گونه شد که آخرین سکه‌هایش را هم برای خرید آن جعبه داد. وقتی که آن عده از آن جا رفتند، در جعبه را باز کرد تا ببیند در آن چیست که ناگهان ماری از آن بیرون آمد. پسر ابتدا ترسید و عقب رفت اما مار با او صحبت کرد و گفت: از من نترس، تو من را نجات دادی و من می‌خواهم محبت تو را جبران کنم. بگو که چه کاری می‌توانم برایت انجام بدهم. پسر جواب داد: سکه‌هایی که برای آزادی و خریدن تو پرداختم، آخرین پس‌انداز ما بود و حالا نمی‌دانم با دست خالی چه‌طور پیش مادرم برگردم.\r\nمار جواب داد: چون تو به من خوبی کردی من هم در عوض به تو کمک می‌کنم. پسر پرسید: چه‌طور می‌خواهی به من کمک کنی؟ مار جواب داد: پدر من کیامار نام دارد و من تنها فرزندش هستم، اگر به او بگویم که تو من را از مرگ نجات دادی به تو می‌گوید که چه پاداشی می‌خواهی و تو جواب بده که من فقط انگشتر سحرآمیزی که در نزد شماست را می‌خواهم و چیزی جز آن را هم قبول نکن.\r\nمار و پسر به نزد کیامار رفتند و فرزندش همه چیز را برای او تعریف کرد و کیامار به پسر گفت: در ازای آزاد کردن پسرم، پاداش خوبی به تو خواهم داد. بگو از من چه پاداشی می‌خواهی؟ پسر گفت: من این کار را برای پاداش نکردم، اما اگر می‌خواهید چیزی به من ببخشید، انگشتری سحرآمیزی که نزد خود دارید را به من بدهید. کیامار ابتدا نمی‌خواست انگشتری را به پسر بدهد، اما پسر با وجود همه‌ی اصرارها و پیشنهادهای او، فقط انگشتری را طلب کرد تا این که بالاخره کیامار راضی شد و انگشتری را به او بخشید. وقتی از نزد او برگشت، ماری که نجاتش داده بود از او پرسید که آیا خاصیت انگشتری را می‌داند؟ پسر گفت: نه. مار گفت: هر وقت که نیاز به چیزی داشتی و آرزویی کردی روی انگشتری دست بکش تا جن خادم انگشتری آن‌چه را می‌خواهی برایت فراهم کند. \r\nپسر از او تشکر کرد و چون خیلی خسته و گرسنه بود، یک ظرف غذای خوشمزه آرزو کرد و روی انگشتر دست کشید. جن کوتاه قامتی در پیش چشمانش ظاهر شد و ظرف پر از غذایی را پیش او گذاشت. پسر با خوشحالی غذا را خورد و خودش را به خانه و نزد مادرش رسانید و آن چه را که اتفاق افتاده بود برایش تعریف کرد. \r\nطولی نکشید که پسر، ثروتمند و صاحب کاخ و خدمه و هر چه از مال و اموال دنیا می‌خواست شد و تصمیم گرفت همسری اختیار کند. این شد که مادرش را به خواستگاری دختر پادشاه که خواستگارهای زیادی داشت فرستاد. پادشاه که دید زنی ساده‌دل به خواستگاری دخترش آمده است، برای پشیمان کردنش طلب مقدار فراوانی طلا و نقره و حریر و ابریشم کرد و گفت که پسرت باید قصری در خور دختر من داشته باشد. مادر به خانه بازگشت و آن‌چه پادشاه خواسته بود را برای پسرش بازگو کرد و پسر نیز با کمک انگشتری سحرآمیز، در چشم بر هم زدنی همه را فراهم کرد و به نزد پادشاه فرستاد و کمی بعد، عروسی مفصلی گرفت و دختر پادشاه را به همسری اختیار کرد. \r\nاما از طرف دیگر، پسر پادشاه کشور همسایه که خواستگار همین دختر بود و بارها از پادشاه جواب رد شنیده بود، وقتی از ازدواج او با پسر یک مرد دستفروش خبردار شد از این ماجرا عصبانی شد و گفت: چه‌طور پسر یک مرد دستفروش و فقیر صاحب چنین جاه و ثروتی شده که می‌تواند دختر پادشاه را به همسری بگیرد؟ پس با اطرافیانش مشورت کرد و پیرزن حیله‌گری را به کشور همسایه فرستاد تا سر از راز این کار درآورد. پیرزن بعد از سفری دور و دراز خودش را به آن سرزمین و شهر و قصر پسر رسانید و به خدمتکاران قصر گفت: من پیرزن تنها و خسته‌ام و از راهی بسیار دور آمده‌ام اگر امکان دارد به بانوی این خانه بگویید که چند روزی به من پناه دهد تا اندکی استراحت کنم و بعد به راه خودم ادامه بدهم. \r\nدختر پادشاه که زن خوشدلی بود قبول کرد. پیرزن به زودی با چرب‌زبانی و خدمت فراوان، نظر و اعتماد دختر را به خودش جلب کرد و بالاخره یک روز از او پرسید: شوهر تو که پسر یک دستفروش بی‌پول بوده است، این همه مال و منال و ثروت را از کجا آورده؟ دختر گفت: من خبر ندارم و او هیچ وقت در این باره با من صحبت نمی‌کند. پیرزن گفت: خب تو که همسر و همدمش هستی باید از اسرار زندگی شوهرت باخبر باشی. برو به هر طریقی که می‌توانی از او بپرس و سر از رازش در بیاور.\r\nدختر هم سراغ همسرش رفت و به اصرار از او خواست که راز ثروتی را که به دست آورده با او بازگو کند. پسر هر چه گفت که دانستن این راز به صلاح تو و من نیست، اما دختر سر ناسازگاری گذاشت و آن‌قدر پافشاری کرد که سرانجام پسر راز انگشتری را به او گفت و تأکید کرد که این سر را پیش هیچ‌کس فاش نکند. اما دختر ساده‌دل راز انگشتری را در مقابل چرب‌زبانی پیرزن بازگو کرد و پیرزن هم در فرصتی مناسب انگشتری را ربود و قصر و خانواده‌ی پسر را با کمک جن انگشتری به کشور همسایه برد. زمانی که این اتفاق افتاد، پسر در قصر نبود، هنگامی که به خانه بازگشت، نه قصری دید و نه همسر و مادرش را. فقط سگ و گربه‌ای که نجات داده بود باقی بودند. پسر سرگشته و غمگین نشسته بود و نمی‌دانست چه کند. سگ و گربه به نزد او آمدند و گفتند انگار حالا موقعی است که ما دین خود را به تو ادا کنیم. پسر از آنها خواست که بروند و انگشتری را پیدا کنند. سگ و گربه به سرعت راه کشور همسایه را در پیش گرفتند و پسر هم در پی آنها به راه افتاد.\r\nدر کشور همسایه، وقتی پسر پادشاه دختر مورد علاقه‌اش را دید از او خواست که به همسریش درآید؛ ولی دختر روی خوش نشان نداد و سرانجام در مقابل تهدید و تطمیع او، چهل روز مهلت خواست و پسر پادشاه هم پذیرفت.\r\nوقتی سگ و گربه به کشور همسایه رسیدند، گربه فکری به خاطرش رسید و در اطراف قصر پادشاه آن سرزمین، رئیس موش‌های آن منطقه را پیدا کرد و او را گرفت. موش بیچاره از او درخواست کرد که از جانش درگذرد. گربه هم با او شرط کرد تا از موش‌های دیگر بخواهد بروند و از انگشتری سحرآمیز خبر بیاورند. موش‌ها راهی گوشه و کنار قصر شدند و خبر آوردند که پسر پادشاه شب‌ها به هنگام خواب انگشتری را در دهانش می‌گذارد تا به دست کسی نیافتد. رئیس موش‌ها هم به گربه پیشنهاد کرد که برای به دست آوردن انگشتری به او کمک کند و او هم جانش را نگیرد.\r\nگربه پذیرفت و به همراه سگ راهی قصر شدند. شب هنگام، موش به همراه گربه به آشپزخانه رفت و دمش را در فلفل زد و بعد هر سه راهی خوابگاه پسر پادشاه شدند. موش دمش را در بینی او فرو برد و پسر پادشاه عطسه‌اش گرفت و به شدت عطسه کرد و با این عطسه انگشتری از دهانش بیرون پرید. سگ هم جستی زد و در هوا انگشتری را قاپید و به همراه گربه به حیاط کاخ پریدند و به سرعت و بی وقفه دویدند تا از دروازه‌ی شهر خارج شدند و راه بازگشت را در پیش گرفتند. در راه به پسر مرد دستفروش که از پی آنها آمده بود برخوردند و انگشتری را به او دادند. پسر هم فوراً روی انگشتری دست کشید و از جن درون آن خواست که او و خانواده و قصرش را به شهر خودش بازگرداند. در یک چشم بر هم زدن همه چیز به جای خود بازگشت و پسر به همراه همسرش سال‌های سال به خوبی و خوشی زندگی کردند و سگ و گربه هم جای راحتی در قصر آنها برای زندگی یافتند. \r\nاما عطسه‌های پسر پادشاه کشور همسایه هیچ وقت بند نیامد و تا آخر عمر آزارش داد!\r\n"},{"id":1049,"category_id":8,"category_code":"s8","source_id":10,"title":"بچه کلاغ","content":"یك بچّه كلاغ بود كه نمي توانست پرواز كند.\r\nبابا كلاغه و مامان كلاغه، هر كار ميکردند فايده نداشت. بچّه شان پرواز\r\nرا ياد نمي گرفت.\r\nآن ها تصميم گرفتند براي او، معلّم پرواز بگيرند.\r\nمعلّم پرواز آمد. پريد بالاي درخت و به بچّه كلاغ گفت: سرت را بالا بگير\r\nبال هايت را باز كن. بدنت را كش بده. حالا بپر!\r\nبچّه كلاغ پريد پايين. اتّفاقاً زَير پايش یک بادكنك، توي هوا بود. بچّه\r\nكلاغ با سَر افتاد روي بادكنك. نوكش خورد به بادكنك. بادكنك ترق تر کید.\r\nبچّه كلاغ ترسيد. فرار كرد به آسمان. رفت و رفت. از\r\nابرها هم بالاتر رفت.\r\nبابا كلاغه و مامان كلاغه، با خوشحالي\r\nداد زدند: آفرين!... آفرين!\r\nمعلّم پرواز هم گفت: چه قدر زود ياد گرفت\r\nراستي كه بچّه ي زرنگي داريد!\r\n"},{"id":1050,"category_id":8,"category_code":"s8","source_id":11,"title":"ونوس کوچولو","content":"ونوس كوچولو در شيراز بدنيا آمده بود ولي چون پدر ونوس يك پزشك بود ، براي كمك به مردم نيازمند به بندرعباس رفته بودند تا پدرش بتواند به مردم كمك كند . و از زماني كه ونوس كوچك بود هميشه زمستانها در جنوب كشور بودند. \r\nجنوب كشور هميشه هوا آفتابي است و هيچ وقت باران و برف نمي بارد. \r\nدر زمستان كه هواي همه جاي كشور سرد است ، هواي قسمتهاي جنوب كشور خوب و قابل تحمل مي شود. \r\nتابستان گذشته وقتي ونوس پنج ساله شده بود همراه پدر و مادرش با هواپيما به تهران آمدند  در آنجا به منزل عمويشان رفتند.\r\nبعد از چند روز تصميم گرفتند با ماشين عمو همگي به شمال بروند. \r\nآنها همگي به شمال رفتند و چون دختر عموي ونوس، هم سن او بود خيلي به آنها خوش مي گذشت. \r\nبا هم در كنار رودخانه سنگ جمع مي كردند و بازي مي كردند . در كنار ساحل خانه هاي شني مي ساختند . شنا مي كردند و از مسافرتشان لذت مي بردند.\r\nيك روز غروب هنگامي كه از جنگل بر مي گشتند هوا ابري شد و باران باريد . آخه هواي شمال هميشه غيرقابل پيش بيني است و حتي وسط تابستان هم باران مي بارد . عموي ونوس كه در حال رانندگي بود ، براي اينكه جلوي خودش را بهتر ببيند برف پاك كن ماشين را روشن كرد. \r\nهمه در ماشين مشغول گفتگو بودند كه يكدفعه ونوس از مادرش پرسيد : مادر اون چيه ؟\r\nمادرش گفت : چي ؟ \r\nونوس با دستهايش به شيشه جلوي ماشين اشاره كرد و با تعجب پرسيد : اوني كه جلوي شيشه ماشين تكان مي خورد. \r\nيكدفعه توجه همه به شيشه پاك كن ماشين جلب شد و همه از اين سوال ونوس خنده اشان گرفت.\r\nمادر ونوس با لبخند گفت : خنده نداره ، خوب دختر من تا حالا برف پاك كن نديده . آخه در بندر عباس تا حالا باران نباريده و ما هيچوقت از برف پاك كن ماشين استفاده نمي كنيم. \r\nآن روز همه چيز براي ونوس خيلي جالب بود . خيس شدن زير باران ، جاري شدن آب باران در خيابان ، صداي چيك چيك باران كه روي سقف سفالي مي خورد و چترهاي رنگانگي كه مردم در دستشان داشتند. \r\nونوس هم خيلي دلش مي خواست يكي از اين چترهاي قشنگ داشته باشد . و از مادرش خواهش كرد تا يك چتر براي او بخرد. \r\nمامان ونوس يك چتر قشنگ صورتي با خالهاي سفيد براي او خريد.\r\nمسافرت تمام شد و آنها به شهرشان برگشتند . وقتي ونوس چترش را از چمدان در آورد ، به مامانش گفت : آخه اگه اينجا باران نباره من كي چترم را استفاده كنم. \r\nمادرش گفت : عزيزم تو اينجا هم مي تواني چترت را استفاده كني . چون آفتاب اين جا خيلي شديد است اگر تو از چتر استفاده كني ، آفتاب تو را كمتر اذيت مي كند. \r\nفرداي آنروز ونوس با چتر قشنگش در خيابانهاي آفتابي بندرعباس قدم مي زد و همه از ديدن اين دختر كوچولوي خوشگل با چترش قشنگش لذت مي بردند.\r\n"},{"id":1051,"category_id":8,"category_code":"s8","source_id":12,"title":"هسته ی آلو","content":"مادر مقداری آلو خرید تا بچه هایش بعد از شام بخورند او همه آنها را در یک بشقاب گذاشت.وانیا که پیش از آن هرکز آلو نخورده بود پیوسته چشمش به آنها بود. او آلوها را بسیار دوست می داشت وخیلی هم دلش می خواست که یکی از آنها را بخورد. همواره دور وبر آلوها می چرخید. موقعی که اتاق خلوت شد نتوانست خودداری کند ویکی ازآنها را خورد.\r\nقبل از شام موقعی که مادر آلوها را شمرد متوجه شد که یکی از آنها کم شده است و این موضوع را به پدر گفت. \r\nوقتی که آنها مشغول خوردن شام بودند پدر از بچه ها پرسید:\"خوب بچه ها کدامیک از شما یکی ازشما یکی از آلوها را خورده است؟\"\r\nبچه ها همگی پاسخ منفی دادند. وانیا که رنگش مثل گل آتش شده بود. گفت :\"من نخورده ام.\"\r\nسپس پدر گفت:\"هر کدام از شما این کار را کرده است باید بداند که کار بسیار نادرستی است ,اما چندان مهم نیست. مهم اینست که آلو ها هسته دارند وکسانی که نمی دانند چطور باید آنها را خورد هسته راقورت می دهند و بی تردید روز بعد می میرند و من از همین می ترسم.\"\r\nوانیا رنگش پرید و گفت:\"اما من هسته را از پنجره به بیرون پرتاب کردم.\" \r\nهمگی خندیدند و وانیا به گریه افتاد.\r\n"},{"id":1052,"category_id":8,"category_code":"s8","source_id":13,"title":"جشن تکلیف","content":"سبا كوچولو یك بابابزرگ مهربون داشت كه اكثر اوقات را به مناجات با خدا مشغول بود. \r\nسبا نماز خواندن را خیلی دوست داشت و هر وقت بابابزرگ را در حال نماز خواندن می‌دید، می‌دوید و جانماز مادرش را برمی‌داشت و روی زمین پهن می‌كرد و پشت سر بابابزرگش می‌ایستاد و كارهایی را كه باباجونش درحال نماز خواندن انجام می داد مو به مو اجرا می‌كرد و بعد وقتی نمازش تمام می‌شد جانماز را همان جا رها می‌كرد و می‌رفت و مامانش از این كار سبا فوق‌العاده عصبانی می‌شد. \r\nسبا چند روز دیگه تولدش بود و به سن 9 سالگی می‌رسید. یك روز خانم ناظم در مدرسه برای بچه‌ها صحبت می‌كرد و به آن ها گفت: بچه‌های عزیز، دخترهای خوب من، شما دیگه بزرگ شدید و همه تون امسال به سن تكلیف می‌رسید و ما می‌خواهیم برای شما جشن تكلیف بگیریم. \r\nسبا دستش را بالا گرفت و از خانم ناظم سوال كرد: ببخشید خانم ناظم، اجازه... جشن تكلیف یعنی چی؟ \r\nخانم ناظم گفت: جشن تكلیف یكی از جشن‌های بسیار بزرگ مذهبی ما مسلمانان است كه مخصوص شما كودكان می‌باشد. كه از این سن وظایف دینی شما تازه شروع می‌شود. \r\nسبا تمام روز به این جشن فكر می‌كرد و با خودش می‌گفت: یعنی باید چه كارهایی انجام بدهم ؟ \r\nو رفت پیش بابابزرگ مهربانش و از او پرسید: بابابزرگ شما می‌دونید كه من به سن تكلیف رسیدم. بابابزرگ گفت: بله دخترم، جشن تكلیفت كی هست؟ \r\nسبا: پس شما می‌دونید كه مدرسه می‌خواهد برامون جشن تكلیف بگیره. \r\nبابابزرگ: بله. \r\nهر بچه‌ای كه به سن تكلیف می‌رسه برایش جشن می‌گیرند. \r\nسبا: بابابزرگ هر كسی كه به سن تكلیف می‌رسه باید چه كارهایی انجام \r\nبده؟ \r\nبابابزرگ: سباجان یعنی تو دیگه یك خانم بزرگ شدی و از حالا به بعد همه كارها و اعمالت باید مثل یك خانم بزرگ باشه. \r\nحتماً باید حجابت رو حفظ كنی و نماز خواندن از این سن به تو واجب است و باید همیشه، اول وقت نمازت را بخوانی و وظایف دینی‌ات را كاملا ًانجام دهی. سجاده‌ات را پهن كرده و مثل بزرگ‌ترها با خدای مهربان صحبت كنی و همیشه شكرگزار باشی. از حالا به بعد تو دیگه می‌توانی روزه كامل هم بگیری و عبادت خدا را به جا بیاوری. \r\nدر این موقع مامان سبا از راه رسید و كنار بابابزرگ و سبا نشست و از صحبت‌های آن ها متوجه جشن تكلیف سبا شد. و رفت سجاده و چادر و مقنعه‌ای كه از قبل برای سبا آماده كرده بود را آورد و روی پای سبا گذاشت و گفت: بفرمایید دختر قشنگم... \r\nاین كادو مال توست و اما یادت باشه یكی از كارهایی كه اهمیت زیادی داره این است كه وقتی می‌خواهی نماز بخوانی، باید اول با احترام سجاده‌ات را رو به قبله پهن كنی و بعد از پایان نماز، چادر و مقنعه را مرتب و منظم تا كرده و داخل سجاده قرار دهی و این كار احترام گذاشتن به عبادتت است\r\n"},{"id":1053,"category_id":8,"category_code":"s8","source_id":14,"title":"اشتباه علی کوچولو","content":"یك روز علی كوچولو با مادرش به یك فروشگاه بزرگ برای خرید رفت. مادر یك چرخ خرید برداشت و با علی در فروشگاه مشغول راه رفتن شدند. \r\nعلی كوچولو بسیار ذوق زده شده بود از این‌كه در فروشگاهی به این بزرگی و خوش آب و رنگ قدم می‌زدند. انواع خوراكی‌های خوشمزه به علی كوچولو چشمك می‌زد.\r\nعلی ساعتی را تحمل كرد ولی بعد از مدتی دید چیزهایی كه مادر از فروشگاه برمی‌دارد دوست ندارد، بنابراین تصمیم گرفت خودش دست به كار شود و جلوتر از مادر به راه افتاد.\r\nمادر تا به خودش بجنبد، دید كه یه عالم خوراكی در سبد خریدشان است. خیلی سریع به علی گفت: علی جان تو با اجازه چه كسی این چیزها را برداشتی... مگر من به تو اجازه دادم؟ علی گفت: با اجازه خودم... \r\nمادر گفت: كار خیلی اشتباهی كردی... چون به اندازه پولی كه در جیبمان هست، می‌توانیم خرید كنیم نه بیشتر... \r\nعلی گفت: آخه مامان... من می‌خواهم... شما فقط برای خودتان خرید كردید... پس من چی؟\r\nمادر گفت: پسرم نوبت به تو هم می‌رسد. ما اول باید مایحتاج خانه‌مان را بخریم، بعد خوراكی‌های تو را. پس خیلی زود این چیزهایی را كه برداشتی، ببر و سر جایش بگذار... \r\nعلی كوچولو با شنیدن حرف‌های مادر زد زیرگریه و فروشگاه را روی سرش گذاشت. آنقدر گریه كرد و پاهایش را روی زمین كوبید كه آبروی مادرش را برد. \r\nمادر كه خیلی ناراحت شده بود اصلاً به رویش نیاورد و فقط سكوت كرد. وقتی به خانه رسیدند مادر با علی كوچولو صحبت نكرد و فقط گفت برو تو اتاقت. \r\nعلی كوچولو همین كار را كرد و ساعت‌ها در اتاقش ماند. از آن لحظه به بعد هیچ خوراكی‌ای متعلق به علی نبود. در نهایت علی پیش مادرش رفت و گفت: مادر... آخه چرا شما این كار را می‌كنید؟ مادر گفت: چون تو آبرویم را در فروشگاه بردی و باید بفهمی كه اشتباه كردی.\r\nاین حركتی كه تو كردی آنقدر زشت بود كه هر چی فكر می‌كنم اصلاً قابل بخشش نیست. علی فكری كرد و گفت خب من چه كار كنم مرا ببخشید؟ \r\n\r\nمادر گفت: فقط دیگه تكرار نشه. علی از مادرش عذرخواهی كرد و گفت: بله تكرار نمی‌شه و از آن روز به بعد علی هیچ وقت برای خوراكی گریه نكرد\r\n"},{"id":1054,"category_id":8,"category_code":"s8","source_id":15,"title":"سه بچه خوک","content":"يكي بود ، يكي نبود ، زير گنبد كبود در جنگلي، خوكي با سه پسرش زندگي مي كرد . اسم بچه ه به ترتيب مومو ، توتو ، بوبو بود . \r\nيك روز مادر خوكها به آنها گفت :\" بچه ها شما بزرگ شديد و بايد براي خودتان خانه اي بسازيد و زندگي جديدي را شروع كنيد . \"\r\nمومو كه از همه بزرگتر و از همه تنبل تر بود پيش خودش فكر كرد چه لزومي دارد كه زيادي زحمت بكشد براي همين با شاخ وبرگ درختها يك خانه براي خودش ساخت .توتو كه كمي زرنگتر بود با تنه درختها يك خانه چوبي ساخت . بوبو كه از همه زرنگتر و باهوشتر بود با سنگ يك خانه سنگي محكم ساخت .\r\nمدتي گذشت ، يك روز مومو جلوي خانه ، در حال استراحت بود كه گرگي بدجنس او را ديد . گرگ تا اومد مومو را بگيرد ، مومو فرار كرد و به خانه رفت و در را بست . گرگ خنديد و گفت :\" حالا فوت مي كنم و خونه ات را خراب مي كنم و تو رو مي خورم . \" بعد يك نفس عميق كشيد و فوت كرد . چون خونه مومو محكم نبود بلافاصله خراب شد . مومو ترسيد و شروع به دويدن كرد\r\nرفت ورفت تا به خانه توتو رسيد .در زد وفرياد كشيد : \" توتو ، توتو در را بازكن گرگه دنبال من است . \"\r\nتوتو در را باز كرد و گفت :\" نگران نباش خانه من محكم است و با فوت گرگه خراب نمي شه .\"\r\nگرگه كه مومو را دنبال مي كرد به خانه توتو رسيد و قاه قاه خنديد و گفت :\" الان فوت مي كنم و خونه شما را خراب ميكنم و هر دوي شما رو مي خورم . \" بعد فوت كرد ولي چون خانه توتو محكم بود خراب نمي شد\r\nآخر سر گرگه خسته شد ، پيش خودش فكر كرد كه حالا چكار كنم . بعد يك چيزي به ذهنش رسيد و پيش خودش گفت :\" چون خونه توتو چوبي هست اگر آنرا به آتش بكشم ، خوكها مجبور مي شوند كه بيرون بيايند بعد آنها رامي گيرم ومي خورم .\" براي همين خانه توتو را آتش زد.\r\nدود همه جا را پر كرده بود ، خوكه نمي توانستند نفس بكشند براي همين از در پشتي فرار كردند و به خانه بوبو رفتند . در زدند و فرياد كشيدند : \" بوبو درو بازكن گرگه دنبال ماست . \"\r\nبوبو بلافاصله در را باز كرد و به آنها گفت كه نگران نباشند.\r\n، گرگه كه دنبال آنها بود ، رسيد و دوباره قاه قاه خنديد و گفت :\" چه بهتر حالا هر سه شما را مي خورم . \" بعد شروع كرد به فوت كردن ولي هر چه فوت كرد خانه بوبو خراب نشد ، فكر كرد آن را آتش بزند ولي خانه سنگي بوبو آتش نمي گرفت .\r\nبعد سعي كرد از دودكش وارد خانه شود . همان موقع خوكها بخاري را روشن كردند و دم گرگه آتش گرفت . گرگه فرياد كشيد و از لوله دودكش بيرون پريد و به سمت جنگل فرار كرد .\r\nبعد از آن ماجرا مومو و توتو فهميدند كه هر كاري را بايد به بهترين صورت انجام بدهند تا خطر كمتري آنها را تهديد كند .بوبو هم به آنها قول داد در ساختن خانه جديد ، كمكشان كند.\r\n"},{"id":1055,"category_id":8,"category_code":"s8","source_id":16,"title":"سگ ولگرد واستخوان","content":"روزی از روزها، یک سگ ولگرد به دنبال غذا می گشت که به یک مغازه قصابی رسید. او یک تکه استخوان پیدا کرد که مقداری گوشت به اون چسبیده بودپس استخوان را برداشت و پا ه فرار گذاشت تا جای امنی پیدا کند و از غذایی که پیدا کرده بودریال لذت ببردسگ قصه ما، شروع کرد به جویدن استخوان و چون استخوان خیلی بزرگ بود، حسابی تشنه شد. پس کنار رودخانه ای رفت تا تشنگی اش را برطرف کند. او همچنان استخوان را با خودش می برد و نگران بو که مبادا سگ دیگه ای استخوانش را بدزددوقتی سگ به بالای پل رسید، به دور و برش نگاهی کرد تا ببیند که آیا می تواند استخوان را لحظه ای به زمین بگذارد و برود آب بخورد؟که به طور اتفاقی عکس خودش رو از بالای پل توی آب دید. اون نتوانست بفهمد که اون عکس، سایه خودش است و فکر کرد که سگ دیگه ای با یک استخوان اونجاست و برای اینکه حریص بود، دلش می خواست که اون استخوان هم مال خودش باشه. برای همین شروع کرد با پارس کردن با این امید که اون سگ، بترسه و فرار کنه ولی از بخت بد، استخوانی که توی دهانش بود، افتاد توی آب رودخانه"},{"id":1056,"category_id":8,"category_code":"s8","source_id":17,"title":"روباه و گنجشک","content":"یكی بود یكی نبود. در یك جنگل كوچك و دور افتاده حیوانات زیادی زندگی می‌كردند. خانم گنجشكه بتازگی 2تا جوجه كوچولویش را از تخم بیرون آورده بود و از آنها بخوبی نگهداری می‌كرد.روزها به اطراف جنگل می‌رفت تا برایشان غذا پیدا كند و بیاورد، اما چند روزی بود كه آقا روباه مكار دوباره سروكله‌اش پیدا شده بود و دوروبر گنجشك‌ها می‌پرید.یك روز از این روزها كه خانم گنجشكه می‌خواست دنبال غذا بره دید كه روباه بدجنس پایین درخت آنها نشسته و بر و بر به بچه‌هایش نگاه می‌كند. با خودش گفت این روباهه دوباره آمده تا جوجه‌هایم را بخوره... برای همین پشیمان شد و برگشت خانه و از بچه‌هایش مراقبت كرد.گنجشك‌های كوچولو خیلی گرسنه بودند و خانم گنجشكه حتما باید می‌رفت به جنگل تا غذا تهیه كند، ولی روباه مكار كه فكر می‌كرد از همه زرنگ‌تر و مكارتره، 4چشمی ‌مراقب جوجه‌ها بود تا سر یك فرصتی آنها را یه لقمه چرب كند.خانم گنجشكه فكری كرد و با خودش گفت: ای روباه بدجنس! دیگه نمی‌گذارم بچه‌هایم را بخوری و با خودش گفت حالا من چطوری خانه‌ و بچه‌هایم را تنها بگذارم و بروم... همین طور كه با خودش صحبت می‌كرد، ناگهان فكری به ذهنش رسید و بعد رفت نزدیك روباه و گفت: سلام روباه عزیز. از این طرفا...!روباه گفت: سلام گنجشك مهربون، داشتم از اینجا رد می‌شدم، گفتم یك سری به شماها بزنم.گنجشك گفت: وای چقدر كار خوبی كردی. روباه عزیز دوست خوب من! من باید بروم و برای بچه‌هایم غذا بیاورم، تو می‌توانی از آنها مراقبت كنی تا من برگردم.روباه گفت: بله حتما من خیلی خوب از آنها مراقبت می‌كنم. برو خیالت راحت باشه.گنجشك گفت: روباه عزیز! برعكس صحبت‌هایی كه درباره‌ات می‌كنند تو چقدر مهربانی، ولی من به همه می‌گم كه تو با وجود مریضی‌ات از بچه‌های من نگهداری كردی.\r\nروباه گفت: چی؟ چی گفتی... كدام مریضی؟\r\nگنجشك گفت: آخه دیدم رنگت خیلی پریده و زرد شده. من شنیدم در جنگل بیماری‌ای شیوع پیدا كرده كه كشنده است و اولین نشانه‌اش رنگ پریدگی است.روباه با شنیدن این حرف گنجشك گوشه‌ای نشست و گفت: یعنی من آن مریضی را گرفته‌ام، چه چیزی بخورم تا خوب شوم؟گنجشك گفت: تنها دارویش نوشیدن یك جرعه از آبی است كه از قله كوه پس از آب شدن برف‌ها بیاید.روباه راهی شد به سمت كوهستان و چند روز بعد هم خبر رسید كه مرده است. گنجشك‌ها و دیگر حیوانات هم از دست آزارهای روباه راحت شدند و به زندگیشان ادامه دادند.\r\nو گنجشك هم خوشحال بود از این‌كه حیله‌گرتر از روباه است.\r\n"},{"id":1057,"category_id":8,"category_code":"s8","source_id":18,"title":"دختری که دوست داشت گنجشک شود","content":"\r\nیکی بود یکی نبود.\r\nدختر کوچکی بود به نام عسل که همیشه درحیاط، کنارباغچه می نشست به گنجشکهایی که در آسمان بودند نگاه میکرد و آرزو میکرد:\r\nای کاش من هم یک گنجشک بودم!\r\nآن وقت هرجا دوست داشتم میرفتم و در آسمان پرواز میکردم.\r\nیک روز همین طور که در فکر و خیال بود، احساس کرد کوچک شده است !\r\nوقتی به خودش نگاه کرد، دید آرزویش برآورده شده و به یک گنجشک تبدیل شده است.\r\nباخوشحالی به آسمان پرید و پرواز کرد،\r\nاو از اینکه گنجشک شده خیلی خوشحال بود،\r\nتا اینکه خسته وگرسنه شد و روی شاخه درختی که پراز گنجشک بود نشست.\r\n*********\r\nگنجشکی کنار او آمد وگفت:\r\nچیه بچه جون اینجا چی میخوای؟\r\nعسل گفت:\r\nمن خسته و گرسنه ام.\r\nگنجشک قاه قاه خندید وگفت:\r\nتو یک گنجشکی و خودت باید برای خودت جا و غذا پیدا کنی.\r\nالان هم از اینجا برو چون باید از قبل جا میگرفتی !\r\n*********\r\nعسل شروع به گریه کرد، درهمین موقع دستی او را تکان داد.\r\nمادرش بود !\r\nبله بچه ها،\r\nعسل کنار باغچه خوابش برده بود وخواب دیده بود.\r\nاو فهمید که هر آرزویی مشکلات خودش را دارد وهیچ وقت نمی توان بی گدار به آب زد.\r\n"},{"id":1058,"category_id":8,"category_code":"s8","source_id":19,"title":"یک کلاغ چهل کلاغ","content":"ننه كلاغه صاحب یك جوجه شده بود . روزها گذشت و جوجه كلاغ كمی بزرگتر شد . یك روز كه ننه كلاغه برای آوردن غذا بیرون میرفت به جوجه اش گفت : عزیزم تو هنوز پرواز كردن بلد نیستی نكنه وقتی من خونه نیستم از لانه بیرون بپری و ننه كلاغه پرواز كرد و رفت .\r\nهنوز مدتی از رفتن ننه كلاغه نگذشته بود كه جوجه كلاغ بازیگوش با خودش فكر كرد كه می تواند پرواز كند و سعی كرد كه بپرد ولی نتوانست خوب بال وپر بزند و روی بوته های پایین درخت افتاد .\r\nهمان موقع یك كلاغ از اونجا رد میشد ،چشمش به بچه كلاغه افتاد و متوجه شد كه بچه كلاغ نیاز به كمك دارد . او رفت كه بقیه را خبر كند و ازشان كمك بخواهد.\r\nپنج كلاغ را دید كه روی شاخه ای نشسته اند گفت :”‌ چرا نشسته اید كه جوجه كلاغه از بالای درخت افتاده.“ كلاغ ها هم پرواز كردند تا بقیه را خبر كنند .\r\nتا اینكه كلاغ دهمی گفت : ”‌ جوجه كلاغه از درخت افتاده و فكر كنم نوكش شكسته . “ و همینطور كلاغ ها رفتند تا به بقیه خبر بدهند .\r\nكلاغ بیستمی گفت :”‌ كمك كنید چون جوجه كلاغه از درخت افتاده و نوك و بالش شكسته .“\r\nهمینطور كلاغ ها به هم خبر دادند تا به كلاغ چهلمی رسید و گفت :”‌ ای داد وبیداد جوجه كلاغه از درخت افتاده و فكر كنم كه مرده .“\r\nهمه با آه و زاری رفتند كه خانم كلاغه را دلداری بدهند . وقتی اونجا رسیدند ، دیدند ، ننه كلاغه تلاش میكند تا جوجه را از توی بوته ها بیرون آورد .\r\nكلاغ ها فهمیدند كه اشتباه كردند و قول دادند تا از این به بعد چیزی را كه ندیده اند باور نكنند .\r\nاز اون به بعد این یك ضرب المثل شده و هرگاه یك خبر از افراد زیادی نقل شود بطوریكه به صورت نادرست در آید ، می گویند خبر كه یك كلاغ، چهل كلاغ شده است.\r\nپس نباید به سخنی كه توسط افراد زیادی دهن به دهن گشته، اطمینان كرد زیرا ممكن است بعضی از حقایق از بین رفته باشد و چیزهای اشتباهی به آن اضافه شده باشد.\r\n"},{"id":1059,"category_id":8,"category_code":"s8","source_id":20,"title":"زرافه کوچولو","content":"زرافه کوچولو آرزوهای عجیب و غریبی داشت.یک شب آرزو کرد که گردنش خیلی خیلی دراز باشد. همان موقع، فرشته ی آرزو از آن جا گذشت. صدایش را شنید. به او لبخند زد. آن وقت گردن زرافه کوچولو دراز شد. دراز و درازتر. رفت و رفت تا به آسمان رسید. حالا سرش در آسمان بود وتنه اش روی زمین.\r\nزرافه کوچولو به این طرف و آن طرف نگاه کرد. همه جا پر از ستاره بود. اول، یک عالمه با ستاره ها بازی کرد، بعد، گرسنه اش شد. هام... هام... هام... ستاره ها را خورد. ماه را هم خورد. یک دفعه همه جا تاریک شد.\r\nزرافه کوچولو ترسید. مادرش را صدا زد. اما او کجا و مادرش کجا! مادرش آن پایین بود و خودش این بالا.\r\nزرافه کوچولو گریه اش گرفت فریاد زد: فرشته ی آرزو کجا هستی؟\r\nاما فرشته ی آرزو رفته بود تا آرزوی یک کوچولوی دیگر را برآورده کند.\r\nزرافه کوچولو سرش را روی یک تکه ابر گذاشت. این قدر گریه کرد که خوابش برد.\r\nصبح که بلند شد، سرش روی شکم گرم و نرم مادرش بود.\r\nزرافه کوچولو خندید. همه ی این ها ... یک خواب بود.\r\n"},{"id":1060,"category_id":8,"category_code":"s8","source_id":21,"title":"ملخ طلایی","content":"روزی روزگاری در سرزمین ما،مرد باایمان و خوش اخلاقی زندگی می کرد که خیلی دوست داشت به دیگران کمک کند.او همیشه مواظب آدم های فقیر و بیچاره و معلول بود و برای کمک به آنها بسیار تلاش می کرد.مردم به خاطر خیرخواهی این مرد،به او عموخیرخواه می گفتند.او کشاورز بود و هر روز روی زمین کار می کرد و زحمت می کشید و موقعی که کارش تمام می شد، به یاری مستمندان می شتافت.\r\nیک روز عصر،وقتی تمام پول هایش را برای کمک به مردم فقیر خرج کرده بود و داشت به خانه برمی گشت،حیدر را دید.حیدر کارگربود وروی زمین های مردم کار می کرد و دستمزد ناچیزی می گرفت.\r\nاو مرد فقیری بود و چندین بچه ی قد و نیم قد داشت و به زحمت شکم آنها را سیر می کرد.عمو خیرخواه به حیدر سلام کرد و حالش را پرسید.حیدر با ناراحتی گفت:«عموخیرخواه،چند روزی است که نتوانسته ام کارکنم و دستمزد بگیرم.بچه هایم گرسنه اند.پولی به من قرض بده تا بتوانم نانی بخرم و شکم آنها را سیر کنم.»\r\nعموخیرخواه جیب هایش را گشت اما هیچ پولی توی جیب هایش باقی نمانده بود.خجالت می کشید به حیدر بگوید که پول ندارد.ناگهان ملخ درشتی روی دستش نشست.عموخیرخواه ملخ را کف دستش گذاشت و به آن نگاه کرد.بدن ملخ زردرنگ بود و در غروب آفتاب، مثل طلا می درخشید.هیکلش هم از ملخ های معمولی خیلی بزرگ تر بود.عموخیرخواه با خودش گفت:«ای کاش این ملخ از جنس طلا بود تا آن را به حیدر می دادم.با پولش می توانست به راحتی زندگی کند.»\r\nتوی همین فکرها بود که حیدر پرسید:«عموخیرخواه،چی توی دستت داری؟»عموخیرخواه ملخ را کف دست حیدر گذاشت.حیدر به ملخ نگاه کرد.ناگهان ملخ تبدیل به مجسمه ای از طلا شد.عموخیرخواه و حیدر با تعجب به آن خیره شدند.\r\nحیدر چندبار ملخ را لمس کرد و با شادی فریاد زد:«معجزه شده عموخیرخواه!ملخ تبدیل به طلا شده است!»عموخیرخواه فهمید که خدا آرزویش را برآورده ساخته است.دستی به شانه ی حیدر زد و گفت:«از این ماجرا به کسی چیزی مگو.ملخ را به بازار ببر و بفروش و سرمایه ی کارکن.»بعد هم خداحافظی کرد و رفت.\r\nحیدر ملخ طلایی را به شهر برد و به یک جواهرفروش فروخت و پول زیادی گرفت. با آن پول توانست زمین و گاو و گوسفند بخرد و ثروتمند شود. سال ها گذشت. حیدر به فکر افتاد تا ملخ طلایی را بخرد و به عموخیرخواه بدهد.او پول زیادی داد و ملخ را خرید و پیش عموخیرخواه برد و آن را در دست عموخیرخواه که حالا پیرشده بود گذاشت.عموخیرخواه با لبخند به ملخ نگاه می کرد.ناگهان ملخ جان گرفت و به شکل اولش درآمد و جست و خیزکنان از آنها دور شد و رفت.حیدر با تعجب به ملخ نگاه می کرد و نمی دانست چه بگوید.اما عموخیرخواه با لبخند گفت:« حیدرجان،آن روز که تنگدست بودی خدا این ملخ را تبدیل به طلا کرد تا تو بتوانی سرمایه ای به دست بیاوری و کاری بکنی و امروز که به لطف خدا ثروتمند و بی نیاز هستی،ملخ هم به آغوش طبیعت بازمی گردد تا به زندگیش ادامه دهد.» اشک از چشمان حیدر سرازیر شد،به خاک افتاد و سجده ی شکر به جای آورد.\r\n"},{"id":1061,"category_id":8,"category_code":"s8","source_id":22,"title":"گردنبند گل گلی","content":"خانم خرسه و آقاخرسه با دختر کوچولوی تپل مپلشان خرس گل گلی ،توی یک خانه ی بزرگ زندگی می کردند.آنها خانواده ی شاد و مهربانی بودند.روزها همراه دخترشان یعنی خرس گل گلی به جنگل می رفتند و میوه های جنگلی جمع می کردند و به خانه می آوردند و برای زمستانشان انبار می کردند.دختر آنها همیشه یک پیراهن گلدار می پوشید،برای همین او را گل گلی صدا می زدند.یک روز خاله ی گل گلی به دیدنشان آمد.خانه ی خاله ی گل گلی نزدیک دریا بود.او هر روز کنار دریا می رفت و صدفهایی را که همراه موج ها به ساحل می ریخت،جمع می کرد و با آنها گردنبند و گوشواره و دستبندهای زیبایی درست می کرد.آن روز خاله خرسه یک گردنبند خیلی قشنگ به گل گلی هدیه کرد.گل گلی خیلی خوشحال شد.خاله اش را بوسید و از او تشکر کرد و گردنبند را به گردنش آویخت.او با پیراهن گلدار و گردنبند صدفی،از همیشه زیباتر شده بود.گل گلی هر روز جلوی آینه می ایستاد و گردنبندش را نگاه می کرد و از دیدنش لذت می برد.\r\nیک روز خانم و آقای خرس در خانه بودند و داشتند آش کدو می پختند.گل گلی اجازه گرفت تا از خانه بیرون برود و کمی بازی کند.بابا و مامانش هم اجازه دادند و گفتند تا آش آماده شود می تواند بیرون بماند و بازی کند.گل گلی بیرون خانه مشغول لی لی کردن بود که چشمش به خرگوش سفید افتاد.خرگوش سفید به گل گلی سلام کرد و گفت:گل گلی جان،چه گردنبند قشنگی داری!خیلی بهت میاد!\r\nگل گلی خندید و گفت:آره خیلی قشنگه!خاله ام این گردنبند را به من هدیه داده،خیلی دوستش دارم.\r\nخرگوش سفید گفت:مبارکت باشه و جست و خیزکنان به سوی تپه دوید و از گل گلی دور شد.\r\nگل گلی مدتی بازی کرد تا این که مادرش او را صدا زد و گفت:گل گلی جان،آش حاضره بیا تو آش بخور.گل گلی با خوشحالی به خانه رفت.دستهایش را شست و سر میز نشست تا آش بخورد.مادر به دستهای او نگاه کرد تا ببیند تمیز شسته است یانه.اما نگاهش به گردن گل گلی افتاد و با تعجب پرسید:گردنبندت کجاست؟گل گلی دستش را به طرف گردنش برد و با ناراحتی گفت:نیست،نمی دونم چطور شده!مادرش گفت:برو بیرون روی زمین را نگاه کن شاید اونجا افتاده.گل گلی با عجله بیرون رفت.روی زمین را نگاه کرد اما چیزی ندید.به خانه برگشت و با ناراحتی سر میز نشست.خانم خرسه و آقاخرسه فهمیدند که او گردنبندش را پیدا نکرده.اما چیزی نگفتند و صبرکردند تا غذاخوردنشان تمام شد.آن وقت هرسه با هم برای پیداکردن گردنبند بیرون رفتند.اما هرچه گشتند،آن را پیدا نکردند.هیچ کس نزدیک خانه ی آنها دیده نمی شد.ناگهان خرگوش سفید از تپه پایین آمد و به آنها نزدیک شد.به خانم و آقاخرسه سلام کرد و پرسید:چی شده؟دنبال چی می گردید؟\r\nگل گلی گفت:گردنبندم گم شده،تو آن را ندیدی؟\r\nخرگوش سفید گفت:نه ندیدم.\r\nگل گلی با اوقات تلخی گفت:اما تو از اینجا ردشدی.مطمئنم که گردنبندم را تو پیدا کردی و برای خودت برداشتی.زود باش بهم پس بده!\r\nخرگوش سفید با ناراحتی گفت:به من چه که گردنبندت گم شده؟مگه من برداشتم ؟من ندیدمش.\r\nگل گلی گفت:دروغ میگی!تو برداشتی،تو گفتی گردنبندم قشنگه،تو برش داشتی.\r\nخرگوش سفید داد می زد و می گفت:نه ،من برنداشتم و گل گلی داد می زد:تو برداشتی ...\r\nخانم خرسه و آقاخرسه هاج و واج به آنها نگاه می کردند.بالاخره آقاخرسه وسط دعوای آنها پرید و گفت:هردوتا تون ساکت باشید ببینم چی شده؟خرگوش سفید تو بگو ببینم گل گلی چی میگه؟\r\nخرگوش سفید گفت که یک ساعت پیش که از اینجا رد می شده گل گلی را دیده و از گردنبند او خوشش آمده و گفته که خیلی قشنگ است اما آن را برنداشته،اصلاً چطور می توانسته گردنبندی را که به گردن گل گلی آویزان بوده برای خودش بردارد؟\r\nخانم و آقاخرسه حرفهای خرگوش سفید را قبول کردند و به گل گلی گفتند که نباید بیخودی خرگوش سفید را متهم به برداشتن گردنبندش کند.آنها از خرگوش سفید خواهش کردند تا همراه آنها دنبال گردنبند بگردد.خرگوش سفید گفت:باشه،من هم دنبال گردنبند می گردم.ممکنه که گردنبند از گردن گل گلی باز شده باشه و توی بوته ها و لای سنگها افتاده باشه.برای این که به گل گلی ثابت کنم که گردنبند پیش من نیست،من هم همراه شما می گردم تا پیدا ش کنیم.\r\nآنها گشتند و گشتند اما روی زمین چیزی پیدا نکردند.تا اینکه یک موش صحرایی، از توی سوراخ بزرگی سرش را بیرون آورد و گفت:سلام دوستان،دارید چه کار می کنید؟\r\nخرگوش سفید ماجرای گم شدن گردنبند را برای او تعریف کرد.موش صحرایی گفت:صبرکنید ،من می دانم گردنبند کجاست و با عجله به سوراخ رفت و لحظه ای بعد با گردنبند گل گلی برگشت و گفت:این گردنبند شما نیست؟\r\nگل گلی با خوشحالی گفت:خودشه!همین گردنبند منه،کجا پیداش کردی؟\r\nموش صحرایی جواب داد:پسرم از خونه بیرون رفت تا کمی قدم بزنه که این گردنبند را نزدیک خونه ی شما روی زمین پیداکرد و آورد به من داد.فکر کردم شاید مال شما باشه.می خواستم بیام و بهتون بگم که صداتون را شنیدم و اینجا دیدمتون.\r\nگل گلی با خوشحالی گردنبند را به گردنش بست و از موش صحرایی تشکر کرد.خرگوش سفید گفت:دیدی زود قضاوت کردی؟من گردنبند تو را برنداشته بودم.\r\nگل گلی سرش را زیر انداخت و خجالت کشید.بعد هم از خرگوش سفید معذرت خواست و گفت:ببخشید،من اشتباه کردم.اگر منو ببخشی ،قول میدم دیگه بیخودی به کسی شک نکنم .منو می بخشی؟\r\nخرگوش سفید که خیلی مهربان بود با خوشرویی گفت:البته که می بخشمت.به شرطی که قول بدی همیشه با من دوست باشی و هروقت دلت خواست بیایی با هم بازی کنیم.\r\nگل گلی گفت:قول میدم.\r\nخانم و آقاخرسه خندیدند و از خرگوش سفید و موش صحرایی و پسرش دعوت کردند تا به خانه ی آنها بروند و آش کدو بخورند؛چون هنوز هم توی دیگشان آَش کدو داشتند.آنها هم دعوت خرسها را قبول کردند و همه باهم به خانه ی خرسها رفتند و آش خوردند.آن روز به همه ی آنها خیلی خوش گذشت.گل گلی از رفتارخودش با خرگوش سفید شرمنده بود؛اما خرگوش سفید او را بخشید و آنها حسابی با هم دوست شدند و هنوز که هنوز است با هم دوست هستند.\r\n"},{"id":1062,"category_id":8,"category_code":"s8","source_id":23,"title":"طاووس مغرور","content":"طاووس زيبا در جنگل سبز زندگي مي كرد. او بال و پر و دم بسيار زيبايي داشت. روي پرهايش نقطه هاي بزرگي مثل چشمهاي درشت به نظر مي رسيد. رنگ سبز و آبي پرها، چشم همه ي حيوانات را خيره مي كرد. براي همين وقتي طاووس مي ديد كه حيوانات جنگل با تعجب و تحسين نگاهش مي كنند، دمش را باز مي كرد و با آن چتر زيبايي درست مي كرد و با ناز و غرور جلوي چشم آنها راه مي رفت و فخر مي فروخت.\r\nحيوانات جنگل هم كه دم زيباي او را دوست داشتند، به او نمي گفتند كه پاهاي زشتي دارد و صدايش هم اصلاً خوب نيست. طاووس چون خودش را از همه بهتر مي دانست، با هيچ كس دوست نمي شد و هميشه تك و تنها بود.\r\nدر كنار جنگل سبز ، رودخانه اي بود كه تمام حيوانات براي نوشيدن آب به آنجا مي رفتند. يك روز طاووس به سوي رودخانه رفت تا هم آب بنوشد و هم دم زيبايش را به حيوانات نشان بدهد. او سرش را بالا گرفته بود و به هيچكس نگاه نمي كرد. \r\nدوتا خرگوش كه يكي از آنها رنگش سياه بود و مشكي نام داشت و ديگري سفيد بود و به او برفي مي گفتند، داشتند با هم بازي مي كردند كه طاووس را ديدند و به او گفتند:\r\nسلام به طاووس قشنگ\r\nپرنده ي خوش آب و رنگ\r\nچتر دُمت چه نازه!\r\nوقتي كه بازِ بازه\r\nگاهي نگاه كن به زمين\r\nدوستاي خوبت را ببين\r\nاما طاووس به آنها كه سعي مي كردند توجهش را جلب كنند ، اصلاً اعتنا نكرد و همان طور كه سرش را بالا گرفته بود، با غرور به راهش ادامه داد. او بوته ي بزرگ خارداري را كه سر راهش بود نديد و دم بلندش به آن گير كرد. طاووس خواست دمش را آزاد كند، اما كار آساني نبود و تعدادي از پرهايش كنده شدند.\r\nطاووس به قدري از اين پيشامد ناراحت شد كه فرياد كشيد و با صداي بلند گريه كرد. برفي و مشكي كه كمي از او دور شده بودند، صدايش را شنيدند و پشت سرشان را نگاه كردند و او را ديدند. فوراً برگشتند و كمكش كردند تا از بوته دور شود. برفي پرهاي كنده شده ي طاووس را جمع كرد و به عنكبوت درشتي كه داشت از آنجا رد مي شد گفت:« خاله عنكبوت ، دم قشنگ طاووس كنده شده، بيا به او كمك كن .»\r\nعنكبوت ايستاد و پرسيد:« چه كار بايد بكنم؟» مشكي گفت:« من و برفي پرها را سرجايشان قرار مي دهيم و تو با آب دهانت تار درست كن و آنها را بچسبان.» خاله عنكبوت گفت: «باشه، اينكار را مي كنم.» بعد از آن برفي و مشكي پرها را يكي يكي و با دقت سرجايشان گذاشتند و عنكبوت آنها را با آب دهانش چسباند. دم طاووس به شكل اولش درآمد. طاووس خيلي خوشحال شد و از خاله عنكبوت و برفي و مشكي تشكر كرد و با آنها دوست شد.\r\nآن روز براي طاووس روزي فراموش نشدني بود؛ چون براي اولين بار دوستاني پيدا كرد و فهميد كه نبايد به خاطر زيبايي ظاهري مغرور باشد. حالا براي او مهم بود كه دوستاني داشته باشد و به آنها محبت كند؛ دوستاني كه در هنگام سختي ها به ياريش بشتابند و هنگام خوشي ها در كنارش باشند.\r\nفرداي آن روز طاووس از مشكي و برفي و خاله عنكبوت و دوستان آنها دعوت كرد كه به خانه اش بيايند و مهمانش باشند. آنها آمدند و چند ساعتي را در كنار هم با شادماني سپري كردند. پس از آن نيز حيوانات جنگل نديدند كه طاووس سرش را با غرور بالا بگيرد و به آنها فخر بفروشد.\r\n"},{"id":1063,"category_id":8,"category_code":"s8","source_id":24,"title":"موش دانا","content":"\r\nیکی بود یکی نبود غیر از خدا هیچکس نبود \r\nیه جنگلی بود که درختان آن روز به روز افسرده می شد آب چشمه هایش کمتر و کمتر می شد . در این جنگل موشی بود که خیلی جاها سفرکرده بود و چون خیلی باهوش بود هر چه را می دید سعی می کرد آن را به تجربیات خود اضافه کند و آن را یاد بگیرد .\r\nبه همین دلیل دایره اطلاعات او از همه حیوانات آن جنگل بیشتر بود . این موش بین حیوانات به موش دانا ملقب شده بود و همه آنرا موش دانا صدا می زدند .\r\nموش دانا به دوستان خود گفت بهتر است بفکر ترک این جنگل باشیم و به جنگل دیگری برویم . دوستان او چون می دانستند موش دانا حرف بی ربطی نمی زند . حرف او را قبول کردند و به دستور موش خود را آماده ترک آن جنگل کردند .\r\nآنها رفتند تا جایی حدید برای زندگی پیداکنند . چون هدفشان معلوم بود اتفاقا به جایی رسیدند که خیلی جای خوبی بود . موش از انها خواست که در این جا برای خود لانه ای بسازند . \r\nدوستان موش دانا که خاله سوسکه - عنکبوت سیاه - هزار پا و مارمولک بودند به حرف موش دانا زیاد اهمیت ندادند و مشغول بازی و تفریح شدند ولی موش بلافاصله شروع به کندن زمین کرد و یکی دو روزی را بازحمت فراوان این کار طاقت فرسا را ادامه داد و بلاخره توانست لانه خود را آماده کند دوستان بازی گوش او همیشه در حال تفریح بودند و صدای قهقهه آنها هر روز شنیده می شد .\r\nموش دانا بعد از اتمام کار ساخت لانه بفکر جمع کردن آذوقه افتاد و رفت دنبال آذوقه و یکی دو روزی هر چقدر که می توانست آذوقه فراهم کرد و دوستان خود را به میهمانی دعوت کرد در ان روز آنها دور هم خیلی خوشگذراندند و در آخر موش دانا به آنها توصیه کرد دوستان من بفکر فردا هم باشید وضعیت هوا همیشه همینجوری نخواهد بود سعی کنید لانه ای محکم برای خود تهیه کنید .\r\nآنها از هم خداحافظی کردند و رفتند چند روزی به همین روال گذشت اما هنوز هیچ یک از دوستان موش لانه ای نساخته بود چند روزی گذشت هوا بطور ناگهانی سرد شد .\r\nدوستان موش دانا بفکر لانه ساختن افتادند . آنها بدلیل سردی هوا خیلی سریع لانه ای درست کردند که خیلی هم محکم نبود . بعد از ساعتی هوا طوفانی شد و در اولین ساعات شروع طوفان همه دوستان موش دانا لانه نچندان محکم خود را از دست دادند و همگی بی پناه شدند.\r\nتحمل این وضعیت برای همه آنها خیلی سخت بود و همه آنها در صحبتهای خود متوجه این نکته شدند که باید برای راه علاج بسراغ موش دانا بروند و از او کمک بگیرند . آنها باهم بسراغ موش دانا آمده و مشکل خود را با او در میان گذاشتند . موش دانا از آنها دعوت کرد که به لانه او بیایند و چند روزی را با او زندگی کنند و بعداز پایان طوفان و خوب شدن هوا بفکر سرپناهی محکم و دائمی برای خود باشند . آنها قبول کردند و چند روزی را با هم در کنار هم به خوبی و خوشی سپری کردند و از خاطرات شیرین گذشته خودشان تعریف کردند . خیلی به همه آنها خوش گذشت و بعد از اینکه طوفان فروکش کرد آنها همگی با همفکری همدیگر و کمک به همدیگر برای ساخت لانه ای محکم برای هم کار را آغاز کردند . \r\nآنها سالهای زیادی را در کنار هم با شادی و خوشی زندگی کردند . \r\n"},{"id":1064,"category_id":8,"category_code":"s8","source_id":25,"title":"پیرمرد و حیوانات جنگل","content":"در یک جنگل سبز و خرم، کلبه چوبی کوچکی بود که پیرمرد مهربانی در آن زندگی می کرد. او عاشق حیوانات بود و به خاطر علاقه به حیوانات بود که به تنهایی در جنگل زندگی می کرد.\r\nپیرمرد مهربان روزها در جنگل می گشت اگر حیوانی زخمی پیدا می کرد آن را به کلبه می برد معالجه و مداوا می کرد. اگر کسی به کمک احتیاج داشت به او کمک می کرد. اگر گاهی شکارچیان برای شکار حیوانات به آن جنگل می آمد، حیوانات را خبر می کرد و کمک می کرد از دست شکارچیان فرار کنند. در جنگل سبز همه ی حیوانات پیرمرد مهربان را دوست داشتند . فقط یک عقاب بود که او را دوست نداشت بلکه دشمن پیرمرد بود.\r\nماجرا این بود که عقاب، پنج سال پیش در دام یک شکارچی افتاده بود. و بال بزرگش شکسته بود. اما توانسته بود از دام فرار کند. عقاب با خودش فکر می کرد شاید این پیرمرد بوده که آن دام را برای او پهن کرده و داستان شکارچیان دروغ است.او همیشه منتظر فرصتی بود تا از پیرمرد انتقام بگیرد.\r\nتا اینکه یک روز از حیوانات دیگر شنید که پیرمرد بیمار شده است و در کلبه ی خود استراحت می کند. عقاب دید که هر کسی دوست دارد به پیرمرد کمک کند. خرس بزرگ از رودخانه برای او ماهی می گیرد. میمون باهوش با کمک خرگوش و سنجاب ،ماهی را برای پیرمرد روی آتش کباب می کند. کلاغ و دارکوب هم به چشمه می روند و برای پیرمرد آب زلال و تمیز می آورند. عقاب با خودش فکر کرد اکنون وقت خوبی برای انتقام گرفتن است. او به اعماق جنگل رفت جایی که می دانست یک مار بزرگ زندگی می کند. او یک غذای لذیذ برای مار برد و از او خواست تا مقداری از زهر کشنده اش را به او بدهد. مار در عوض غذای خوشمزه ای که عقاب برایش آورده بود مقداری از کشنده ترین زهر خودش را به او داد. عقاب زهر را گرفت و پیش حیوانات بازگشت . به حیوانات گفت من تا حالا کاری برای پیرمرد نکرده ام اجازه بدهید این بار من غذایش را ببرم. حیوانات که از نقشه ی مار خبر نداشتند قبول کردند و غذای پیرمرد را به او دادند. مار غذا را زهرآلود کرد و به سمت کلبه راه افتاد. اما وقتی به کلبه رسید دید یک نفر دیگر در کلبه است . یک شکارچی که با تفنگ قصد کشتن پیرمرد را دارد. عقاب پشت در پنهان شد و به حرفهای آنها گوش کرد. شکارچی به پیرمرد می گفت تو همیشه مزاحم کار من هستی. امروز تو را می کشم و برای همیشه از شرت خلاص می شوم. پیرمرد گفت اگر می خواهی مرا بکش اما کاری به حیوانات بیچاره نداشته باش.\r\nشکارچی با صدای بلند خندید و گفت من همه ی آنها را یکی یکی شکار می کنم و هیچ حیوانی در جنگل باقی نمی گذارم این را به تو قول می دهم.\r\nپیرمرد آهی کشید و گفت امیدوارم هرگز موفق به این کار نشوی.\r\nشکارچی تفنگش را روی سر پیرمرد گذاشت و گفت یادت هست پنج سال پیش، عقاب بزرگ و باشکوهی را در دام انداخته بودم و تو آن دام را پاره کردی و کمک کردی تا عقاب فرار کند؟ اکنون تو را می کشم و بدنت را جلوی همان عقاب می اندازم تا تو را با منقارش تکه تکه کند.\r\nدر همین لحظه عقاب که همه ی حرفها را شنید شروع به بال زدن کرد. شکارچی متوجه عقاب شد و به دنبال او دوید و به سمت عقاب شلیک کرد. عقاب فرار کرد و ماهی زهرالود را روی زمین انداخت. شکارچی ماهی را برداشت و بی معطلی شروع به خوردن آن کرد. بعد از خوردن ماهی دوباره به سراغ پیرمرد رفت اما قبل از اینکه تیری شلیک کند سرش گیج رفت و روی زمین افتاد و مرد. یک ساعت بعد عقاب به کلبه ی پیرمرد برگشت و برایش یک ماهی کباب دیگر آورد ولی این بار ماهی زهرالود نبود. از آن روز به بعد عقاب بهترین دوست پیرمرد شد.\r\n"},{"id":1065,"category_id":8,"category_code":"s8","source_id":26,"title":"تا یکی بود یکی نبود... ","content":"\r\nروزی روزگاری خانه ای بود بسیار بزرگ با خدمه و پرستار و آشپز و....\r\nاین خانه رو به رودخانه ای که به دریاچه ای متصل می شده وسواحل آن پر از نیزار های زیبا و مکان زندگی پرندگان رنگارنگ با آواز های صبحگاهی بسیار دل انگیز بود. \r\nزیبایی منظریه ای که از پنجره این خانه هنگام طلوع خورشید دیده می شد قابل وصف نبود و زیبایی آن را دو چندان می کرد.\r\nصاحب این خانه شخصی بسیار مشهور بود .\r\nروزی همه افراد خانه مشغول انجام وظیفه بودند که یکی از کارکنان متوجه می شود که چهار نفر در ملک شخصی ارباب وارد شده اند .\r\nآنها مسافرانی بودند که راه خودشان را گم کرده بودند.\r\nکارکنان این خانه همگی به طرف این مسافران رفتند و تذکر دادند که این یک ملک شخصی است و باید آنجا را ترک کنند .\r\nمسافران گفتند : ما همگی بسیار تشنه و گرسنه هستیم و خیلی هم خسته اگر ممکن است به ما کمک کنید .\r\nارباب به دلیل در حال ورشکستگی بودن بسیار آشفته بود و مدام به دنبال رفع این مشکل به اینطرف و آنطرف می رفت و هنوز نتیجه ای نگرفته بود .\r\nیکی از کارکنان گفت : ما در وضعیتی نیستیم که به شما کمک کنیم لطفا اینجا را ترک کنید .\r\nدر این حال ارباب خودش از راه رسید و پرسید چه شده است و اینها چه کسانی هستند .\r\nوقتی فهمید آنها به کمک نیاز دارند دستور داد که آنها را به حمام راهنمایی کنند و به آنها غذای خوب و کافی بدهند و جایی را تدارک ببینندتا آنها کمی بخوابند و بعد خانه را ترک کنند .\r\nهمه آنها به حمام رفتند با صابونهای خوشبو که تابحال ندیده بودند خودشان را شستند .\r\nسپس به اتاق غذاخوری راهنمایی شدند و مانند مهمانان بسیار عزیز پذیرایی شدند و غذاهای لذیذی را میل کردند .\r\nاتاقی در اختیارشان قرار داده شد تا استراحت کنند . \r\nپس از ساعاتی که مسافران تجدید قوا کردند تصمیم گرفتند آنجا را ترک کنند . اما قبل از اینکه آنجا را ترک کنند به همدیگر گفتند: بهتر است چیزی بعنوان یادبود به ارباب این خانه بدهیم و بعد خداحافظی کنیم . \r\nیکی از آنها ساعتی قدیمی به ارباب داد !\r\nدیگری سکه ای قدیمی به ارباب هدیه کرد ... ‌‌‌‌سومی جعبه ای نسبتا گرانقیمت به او هدیه کرد و چهارمی که چیزی نداشت مجبور شد تابلوای فرسوده که بین بساط خود یافت به او هدیه دهد . \r\nمسافران خانه را ترک کردند و ارباب دستور داد که آنها را تا ایستگاه قطار بدرقه کنند .\r\nارباب که برای حل مشکل خود راهی را پیدا نکرده بود برای سرگرمی خود و برای اینکه خود را برای مدتی از مشکلات دور سازد به فکر این افتاد که هدیه هایی که شاید آخرین هدیه هایی بودند که قبل از ورشکستگی می گیرد را در جایی بهتر قرار دهد .\r\nهمه آنها را جابجا کرد وفقط تابلو مانده بود که آنرا هم به دیواری که روبروی پنجره اصلی خانه بود آویزان کرد .\r\nدر حالی که روی مبلی نشسته بود خوابش برد و در عالم خواب انگار صدایی را شنید که می گفت: وقتی از خانه خارج می شوی روی تابلو را خوب نگاه کن و هر جمله ای که روی آن نوشته شده را عمل بکن .\r\nبعد از ساعتی باسر و صدای ورود افرادی که از بدرقه مسافران بازمی گشتند از خواب بیدار شد و سراسیمه به سراغ تابلو رفت .\r\nروی آن تابلو نوشته بود: هرگز امروز پا به خیابان نگذار..\r\nچند ساعت خودش را در خانه مشغول کرد ...مدتی بعد یکی از افراد خانه که برای انجام کاری بیرون از خانه بود سراسیمه خود را به خانه رساند و گفت : ارباب خوب شد گرفتندش - گرفتندش.... \r\nارباب گفت : چه کسی راگرفتند؟؟!!\r\nکسی را که دیوانه بود و چاقویی را در دست داشت و داد می زد: تو را (ارباب) می کشم .\r\nارباب به فکر فرو رفت و با خود گفت عجب تابلوای گیرم افتاده شاید این تابلو مرا از ورشکستگی نجات دهد . \r\nروز بعد که می خواست از خانه خارج شود به تابلو نگاه کرد و دید نوشته شده به سومین نفری که ملاقات می کنی پیشنهاد معامله بده موفق می شوی .\r\nاز خانه خارج شد و در طول انجام کارهای خود به سومین نفری که سراغش آمد سلام کرد و بدون مقدمه گفت : شما اهل معامله هستید و من دوست دارم با شما معامله کنم .\r\nاو را برای صرف چایی دعوت کرد و در مورد معامله صحبت های کاری خودشان را شروع کردند و اتفاقا معامله خوبی را هم انجام دادند .\r\nارباب هر روز که می خواست از خانه خارج شود به تابلو نگاه می کرد و به هر آنچه در تابلو نوشته می شد عمل می کرد .\r\nو هر روز تابلو ارباب را در کارهایش راهنمایی می کرد .ارباب دیگر بفکر حل مشکل ورشکستگی نبود بلکه بفکر ثروت بیشتر و بیشتر بود ....\r\nارباب دقیقا متوجه شده بود که کمک به آن مسافران سبب این موفقیت شده است٬پس از آن ماجرا ارباب از ثروتی که بدست می آورد قسمتی از آن را به در راه ماندگان و آوارگان و مسافران خرج می کرد و روزگار خوشی داشت....\r\n"},{"id":1066,"category_id":8,"category_code":"s8","source_id":27,"title":"دخترک آوازه خان","content":"دختری بود که با پدر و مادرش برای تفریح به جنگل رفته بودن پس از کلی بازی و تفریح دخترک پروانه خیلی خوشگلی را می بیند که دور سر او پرواز میکند.\r\nدخترک دلش می خواست که این پروانه را بگیرد و با خودش به خانه ببرد . \r\nبه همین دلیل دخترک پروانه را به قصد گرفتتن دنبال کرد .\r\nدخترک خیلی خوشحال بود چرا که خودش را در گرفتن پروانه موفق می دید . همینجور که پروانه را دنبال می کرد و می خندید پروانه او را از پدر و مادر دور تر و دورتر می کرد .\r\nدخترک پس از ساعتی که پروانه را دنبال کرد و خسته شد تصمیم گرفت استراحتی کند. در حال استراحت متوجه شد که از پدر و مادرش خبری نیست . بسیار ترسید و شروع به گریه کردن نمود .\r\nاما هر قدر گریه کرد کسی به دادش نرسید . از گریه کردن خسته شد . \r\nکمی با خود فکر کرد با خود می گفت: خدایا چه کار کنم؟ کدام سمت بروم ؟ خانواده خودم را از کجا پیدا کنم . شروع کرد به نفرین کردن پروانه و به دور برش نگاهی کرد اما پروانه را ندید .\r\nاو خودش را کاملا تنها حس کرد و ناچار شد به فکر راه چاره باشد . از کتاب علوم بعضی چیزها را که می توان سمت شمال را فهمید به خاطر آورد و با علم ناقصی که داشت سمتی را به عنوان شمال انتخاب کرد و قدم در راه گذاشت تا به سمت پدر و مادرش راه بیفتد. \r\nساعتی بود که مسیری را طی می کرد خسته شده بود و دلش می خواست با کسی صحبتی بکند ُ اما کسی نبود . \r\nدخترک زمزمه ای را شروع کرد و بعد از مدتی صدایش را بلند کرد و آوازی سرداد .\r\nدر جنگل صدایش پیچید تا آن روز دخترک از نعمت آواز خوش خودش خبری نداشت و باخود گفت : من چه صدای قشنگی دارم . \r\nهمینطور آواز می خواند و جلو می رفت اما هیچ خبری از پدر و مادرش نبود . دخترک خسته و نا امید شده بود آواز خود را قطع کرد و نشست. \r\nدخترک ناامید شده بود اما با خودش فکر کرد حتما مسیر یابی او اشتباه بوده چون اصلا او اینهمه از پدر و مادرش دور نشده بود که اینهمه به دنبال انها راه می رود . با خود گفت نکند که گمشده باشد و هیچگاه نتواند آنها را پیدا کند سرش را بالاگرفت و متوجه حضور پرنده های زیادی شد که بالای درختان هستند به چپ و راست نگاه کرد دید حیوانات زیادی دور و برش را گرفته اند و انگار منتظر اتفاقی هستند. \r\nدخترک با خود گفت : چرا اینهمه حیوان در اینجا هست نکند همایش و جلسه دارند . دختر بلند شد و راه افتاد این بار از ترس خود شروع به آواز خواندن کرد و راه خود را ادامه داد . \r\nدر طول مسیر متوجه حرکت حیوانات به سمتی شده که خودش در حرکت بود . \r\nآواز را قطع کردیکی از پرنده ها پرید و در جلوی را ه او قرار گرفت و گفت دختر خانم چه آواز خوبی داری هیچ پرنده ای نمی تواند صدای تو را در بیاورد و به زیبایی تو آواز بخواند . جنگل در عمرش آوازی به خوبی آواز تو ندیده است . واقعا هم آواز دخترک زیبا بود .\r\nپرنده گفت : تو از کجا آمده ای و اینجا چه می کنی . دخترک جواب داد من به همراه خانواده ام به جنگل برای تفریح آمده بودیم و حالا من آنها را گم کرده ام . پروانه ای را دنبال کردم و از آنها دور شدم و حالا راهم را که آمده بودم گم کردم . پرنده صوتی زد و همه پروانه ها آنجا حاضر شدند . روبه پروانه ها گفت کدام یک از شما با این بچه بازی می کردید . \r\nیکی از پروانه ها جلو آمد و با ترس و لرز گفت : من بودم .\r\nپرنده گفت : مطمعن هستم که تو می توانی به این دخترک کمک کنی . \r\nپروانه گفت : مگر چه شده است .\r\nپرنده گفت : این بچه وقتی با تو بازی می کرده از پدر و مادرش دور شده و الان راهش را گم کرده است . \r\nفکر می کنم تو بتونی به او کمک کنی تا او پدر و مادرش را پیدا بکند.\r\nپروانه گفت : آری من می توانم پدر و مادر او را پیدا کنم . پروانه پرواز کرد و به آنها گفت دنبال من راه بیفتید دخترک و حیوانات به دنبال پروانه راه افتادند بعد از ساعتی به محلی که پدر و مادر دخترک در آنجا پیک نیک راه انداخته بودند رسیدند .\r\nاما از پدر و مادر دخترک خبری نبود.\r\nهمه حیوانات به دور و بر خودشان نگاه کردند تا شاید بتوانند اثری از پدر و مادر دخترک پیدا کنند .\r\nحیوانات هر چه گشتند اثری پیدا نکردند . دخترک گفت اگر تا جاده اصلی بتوانم خودم را برسانم می توانم راه خانه را پیدا کنم . یکی از پرندگان گفت : همینجا همگی استراحت کنید من سر و گوشی آب بدهم و برای شما خبر می آورم . \r\nپرنده پر زد و از آنجا دور شد. طولی نکشید که پرنده سراسیمه بازگشت و به آنها خبر خوشی را آورد و گفت چند صد متر آنطرف تر پدر و مادر دختر بچه دنبال دخترشان می گردند . \r\nمن به آنها خبر دادم و آنها الان به اینجا می رسند .\r\nبعد از چند لحظه پدر و مادر دخترک به پیش دخترک رسیدند و پس از گریه و زاری با همدیگر از از آنها خداحافظی کردند ولی همه حیوانات تقاضاکردند که هر هفته دخترک به جنگل بیایند و دخترک برای آنها آوازی بخواند . \r\nپدر و مادر و دختر خانم از همه حیوانات تشکر کردند و خواستند که به خانه خودشان برگردند .\r\nتازه پدر مادر دخترک متوجه شدند که دخترک با آواز خوشی که داشته سبب شده که توجه حیوانات را جلب کرده و آنها متوجه گمشدن دخترک شده و به آن کمک کنند . پدر و مادر دخترک از اینکه دخترشان صاحب آواز خوشی هست خیلی خوشحال بودند .\r\nخانواده خوشبخت با خداحافظی از حیوانات به خانه خودشان رفتند .\r\nآنها روزهای تعطیل به جنگل می رفتند تا به قول خودشان عمل کنند و خود نیز خوش بگذرانند.\r\n"},{"id":1067,"category_id":8,"category_code":"s8","source_id":28,"title":"مورچه ی تنها","content":"\r\nیکی بود یکی نبود غیر از خدا هیچ کس نبود\r\nدر یک منطقه خوش آب و هوا دره ای بود بسیار زیبا که در آن مورچه هایی برای خود لانه درست کرده بودند و زندگی خوشی داشتند . آنها کار و تلاش فراوان می کردند . \r\nمورچه ها همیشه در تلاش و جمع کردن غذا بودند و باهم در خوشی زندگی می کردند . \r\nآنها لانه خودشان را گسترش می دادند یا آن را بازسازی می کردند .\r\nخلاصه شاد شاد بودند و تفریح می کردند و باهم مهربان بودند و همدیگر را دوست داشتند.\r\nروزهای زیادی را باهم با خوشی گذراندند تا اینکه روزی آسمان آبی را ابری تیره پوشانید و به دنبال آن باران تندی درگرفت و همه جا را آب فرا گرفت باران ساعتها ادامه داشت همه حیوانات بدنبال پناهگاه می گشتند .\r\nمورچه ها همگی با سرعت خود را به لانه رساندند بجز یکی از آنها که از لانه دور بود .\r\nاین مورچه خود را به روی برگ درختی که روی زمین وجود داشت رسانید و برگ در روی آب روی زمین سریع شناور شد و مورچه به همراه برگ سرگردان با آب جاری روی زمین به اینطرف و آنطرف می چرخید و از لانه دور تر و دورتر می شد.\r\nمورچه هایی که در لانه بودند با پر شدن آب درون لانه شان همگی خفه شده بودند و هیچ مورچه ای الا مورچه شناور سرگردان و آواره شده در هوای سرد نمانده بود.\r\nمورچه از خود اختیاری نداشت آب برگ را به هر کجا که دلش می خواست می برد .\r\nساعتها بر روی برگ سرگردانی کشید و همیشه از اینکه در آب بیفتد می ترسید تا اینکه باران بند آمد .\r\nآب روی زمین فروکش کرد و یواش یواش مورچه توانست از روی برگ به روی زمین قدم بگذارد تازه مورچه به خود آمد و متوجه شد که چه بلایی به سرش امده است . \r\nمورچه متوجه شده که در عرض نیم روز همه چیزش را از دست داده است .\r\nمورچه دیگر نه صاحب لانه بود و نه خانواده و نه هیچ دوست و نه غذایی برای خوردن تازه مصیبت او شروع می شد .\r\nلحظه ای به فکر فرو رفت و خود را در موقعیتی خیلی بد دید.\r\nمی دانست که زندگی برای آن سخت شده است . اما خود را نباخت و موقعیت جدید خود را بررسی کرد و گفت : بهتر است به فکر سرپناهی باشم چون بعد از ساعتی شب فرا می رسد .\r\nاو یکه و تنها شروع به کار کرد و قبل از غروب آفتاب لانه بسیار کوچکی برای خود آماده کرد .\r\nمورچه آنقدر خسته شده بود که نفهمید کی خوابش برده است و صبح زود با طلوع آفتاب از خواب بیدار شد.\r\nمورچه از لانه اش بیرون آمد صبح زیبایی بود خورشید در آسمان می درخشید اما مورچه صبح خوبی نداشت چراکه خیلی چیزها را از دست داده بود . \r\nمحیط اطراف خود را خوب نگریست همه چیز در نظر او غیر عادی بود .\r\nاو می دانست که باید به فکر غذا باشد. بنابر این بدنبال غذا در اطراف لانه قدم زدن را شروع کرد و چند لحظه بعد متوجه حیوانی شد که تا بحال ندیده بود . به او نزدیک شده و سلام کرد و بعد نام او را پرسید .\r\nآنحیوان سوسک بود خود را برهم معرفی کردند و معلوم شد که سوسک نیز سوار بر جریان آب از آنجا سردر آورده و او نیز همه کسانش را از دست داده است .\r\nمورچه گفت پس تو هم تنهایی \r\nسوسک گفت : بلی \r\nمورچه بلافاصله به او پیشنهاد دوستی داد و او قبول کرد .\r\nمورچه و سوسک قرار ملاقات بعدی را باهم گذاشتند و مورچه برای یافتن غذا از او خداحافظی کرد و از هم دورشدند .\r\nمورچه غذایی تهیه کردو به لانه خود برگشت حالا دیگر مورچه روحیه بهتری داشت . چراکه لانه داشت \r\nغذا داشت و از همه مهمتر یک دوست خوب هم داشت .\r\nمورچه در آن موقعیت بد خود را نباخت و با صبر و حوصله و فکر درست توانست زندگی خوبی را دوباره شروع کند .\r\nدرست است گه با زندگی اولی خود فرق داشت اما این زندگی هم بد نبود و در نوع خود بسیار زیبا و جذاب بود.\r\nروز به روز لانه خود را بهتر می کرد. \r\nدوستان زیادی را برای خود یافته بود. \r\nغذاهم به مقدار کافی داشت .\r\n"},{"id":1068,"category_id":8,"category_code":"s8","source_id":29,"title":"کتاب قصه گو","content":"روزی روزگاری پسر بچه ای بود که پدر و مادرش را همان ایام کودکی از دست داده بود. \r\nتنها بازمانده او خاله اش سرپرستی او را به عهده گرفته بود . \r\nخاله اوایل با پسر بچه مهربان بود . \r\nبعدها در اثر شرایط ناجور عصبی به فردی بسیار عصبی و خشن تبدیل شد. \r\nپسر بچه جایی جز پیش خاله نداشت و سن کم باعث می شد کسی به او کار ندهد و مجبور بود که این وضع را تحمل کند .\r\nوضعیت پسر روز به روز بدتر و بدتر می شد او تمام روز را با رعب و وحشت در نزد خاله کار می کرد. \r\nبارها از دست خاله کتک خورد اما بیچاره اصلا حرفی نمی توانست به کسی بگوید .\r\nخاله پسر را روز به روز بیشتر اذیت می کرد. یک روز خاله پسر را به اتاقی منتقل کرد که بسیار تاریک و نمور و بد بو و پر از موش و سوسک بود . \r\nپسر شبها نمی توانست بخوابد چون سوسکها و موشها آرامش را از او گرفته بود .\r\nروزی از روزها پسر کوچولو کارهایش را زود تمام کرده و ساعتی زود تر به اتاقش آمد.\r\nتابحال روز روشن به اتاقش نیامده بود و همیشه روزها را با سختی تا آخر شب کار می کرد .\r\nاز روشنایی روز استفاده کرده و خوب اتاق را نگاه کرد و متوجه شد در نزدیکی جای خواب او کتابی است که سالها خاک خورده و در گوشه ای افتاده است .\r\nکنجکاو شده و کتاب را برداشت و خاک آنرا کنار زد . صفحه ای را باز کرد در صفحه چیزی نوشته نشده بود و لی با باز شدن کتاب صدایی دلنشین به گوشش رسید .\r\nبا باز شدن صفحات دیگر این جریان تکرار می شد . پسر متوجه شد که کتاب با باز کردن صفحاتش قصه ای را شروع می کند.\r\nهر شب پسر پس از یک کار طاقت فرسا به سراغ کتاب می رفت و صفحه ای از آنرا باز می کرد و قصه ای شروع می شد .\r\nپسر باشنیدن قصه به خوابی آرام فرومی رفت و خواب های خوبی به سراغش می آمد و دیگر از موش و سوسک و ازار و اذیت آنها خبری نبود.\r\nروزی خاله پیشنهاد کرد پسر اتاقش را به نزدیکی اتاق خاله منتقل کند . پسر ناراحت شد و نگران از اینکه نکند خاله از ماجرای کتاب قصه گو باخبر شود . \r\nخاله چند روزی بود که دزدکی به کنار اتاق پسر می رفت و از ماجرا خبر دار شده بود و همین هم بود که حال خاله خوب شده بود و به پسر خواهرش مهربانی می خواست بکند .\r\nخاله ماجرای کتاب را فهمیده بود و نگرانی پسر کوچولو بی جا بود .\r\nخاله به پسر خواهرش گفت من در این روزهای گذشته خیلی با تو کار بدی کردم و از تو می خواهم مرا ببخشید و الان حال من خوب شده و تنها دلیلش صبور بودن تو و کتاب قصه گویی است که تنها تو متوجه وجود آن شده ای .\r\nپسر خاله را بغل کرد و با چشمانی گریان خاله را بوسید و گفت او را بخشیده است . \r\nاز آنروزبه بعد باهم زندگی شیرینی را آغاز کردند .\r\n"},{"id":1069,"category_id":8,"category_code":"s8","source_id":30,"title":"شیر سلطان جنگل","content":"به نام خدا\r\nیکی بود یکی نبود زیر گنبد کبود شیری دانا و صبور و در جنگلی پر از حیوانات متنوع که در\r\nکمال آرامش در کنار هم زندگی می کردند...\r\nاین جنگل بدلیل حضور سلطان دانای جنگل آرامشی داشت که سبب می شد روز به روز به تعداد حیواناتش اضافه شود . \r\nروزی از روز ها با ورود یک حیوان عجیب و بسیار قدرت طلب و مغرور این آرامش به جهنم تبدیل شد ..\r\nسلطان جنگل از این ماجرا با خبر شد. دستور داد جلسه ای تشکیل دهند با حضور همه ی کسانی که به نوعی با این حیوان عجیب رو برو شده بودند.\r\nدر این جلسه شیر دانا همه ی اطلاعات لازم را از حیوانات حاضر در جلسه کسب کرد و از بین حیوانات پلنگ - ببر - فیل - خرس - گورخر - کلاغ و خرگوش را انتخاب کرد. \r\nبرای هریک از آنها ماموریتی داد تا فردا با اجرای نقشه ای دقیق از شر این حیوان عجیب خلاص شوند و آرامش را به حیوانات بازگردانند . \r\nهمه حیوانات از محضر شیر اجازه گرفته و رفتند تا فردا صبح به ماموریت خود عمل کنند . \r\nبا اطلاعاتی که حیوانات به شیر داده بودند این حیوان عجیب باید ادم باشد که با استفاده از اسلحه و ماشین به شکار حیوانات پرداخته است و صبح فردا هم کار خود را ادامه خواهد داد . \r\nبا این حساب صبح زود همه حیوانات برای شروع ماموریت آماده از خواب بیدار شدند . \r\nبا نقشه سلطان جنگل \r\nپلنگ در روی درختی بلند باید بخوابد و خوب اوضاع را بررسی کند. \r\nببر در بین درختان انبوه جنگل کمین کند و منتظر بماند . \r\nفیل با تعدادی از فیل های دیگر آماده حمله باشد. \r\nخرس با ترساندن آدم به کمک حیوانات دیگر برود. \r\nکلاغ در جابجایی پیامها دخالت کند. \r\nخرگوش همه امور را در اختیار شیر قرار دهد. \r\nگورخر در شناسایی محلی که شکارچی مستقر شده خبردار شود .\r\nهمه ماموریت خود را به خوبی بلد بودند.\r\nآدم صبح سوار بر ماشین جیپ خود وارد جنگل شد و پس از درست کردن چایی و خوردن آن اسلحه خود را برداشته و در جنگل راه افتاد\r\nاز طرف شیر دستور داده شده بود که همه حیوانات تا زمانی که به انها خبری نرسیده از لانه خود بیرون نیایند . \r\nکلاغ همینطور در جنگل چرخ می زد و اوضاع را بررسی می کرد و همه را از اوضاع مطلع می کرد کلاغ وضعیت و موقعیت شکارچی را به همه اطلاع داد.\r\nفیل و همه دوستانش در نزدیکی محل چادر شکارچی حاضر شده و آماده حمله ایستاند. \r\nببر بدون آنکه شکارچی آن را ببیند به تعقیب شکارچی پرداخت تا در موقعیت مناسب و به دستور شیر کار حمله را آغازکند. \r\nشکارچی در طول و عرض جنگل پرسه می زد اما هیچ حیوانی را پیدا نمی کرد و با خودش می گفت مثل اینکه جنگل تعطیل شده . \r\nخرس ناگهان جلوی شکارچی حاضر شد و شکارچی از ترس زبانش بند آمد ولی خودش را آماده کرد که با اسلحه اش شروع به تیز اندازی کند . \r\nفیل صدایی از پشت سرش در آورد و تمرکز شکارچیبه هم ریخت پلنگ از بالای درخت پایین پرید و به همراه ببر شکارچی را محاصره کردند شیر به همراه گورخر در صحنه حاضر شدند و شکارچی از اینهمه آمادگی متعجب شده بود و کاملا از نقشه بودن این حمله اطمینان حاصل کرد . \r\nشیر به شکارچی هشدار داد که دیگر هرگز وارد جنگل نشده و مزاحمتی به حیوانات جنگل ایجاد نکند . شکارچی از کارهایی که کرده بود اعلام پشیمانی کرد و قول داد که هرگز مزاحمتی به حیوانات جنگل ایجاد نکند و در جهت جبران کارهای بد خود برای حیوانات جنگل کاری انجام دهد. \r\nشکارچی با شیر صحبت کرد و اجازه خواست در جنگل کلبه ای درست کند و دامپزشکی را هر چند وقت یکبار به انجا بیاورد تا حیوانات مریض را مداوا کند . \r\nسلطان جنگل از همکاری همه حیوانات تشکر کرد.و بازگشت آرامش را به جنگل به همه تبریک گفت و باز همه حیوانات در کنار هم به زندگش شیرین خود ادامه دادند .\r\n"},{"id":1070,"category_id":8,"category_code":"s8","source_id":31,"title":"سیب معجزه گر","content":"روزی روزگاری در یک روستایی درختی بود که هر پنج سال یک بار یکی از سیب هایش با بقیه فرق میکرد. هر کسی این سیب را میخورد آینده را میدید.\r\nپادشاهی سه پسرداشت که همگی برسر به قدرت نشستن به جای تخت پادشاهی با هم بحث می کردند .\r\nروزی پدر آنها را خواست و گفت فرزندان من وقت آن رسیده که من یکی از شماها را به عنوان پادشان به مردم معرفی کنم.\r\nمن به شما ماموریت می دهم که هر سه بروید و گرانبهاترین شیئ دنیا را برایم بیاورید.\r\nهر کس گرانبهاترین را آورد آن را انتخاب خواهم کرد. هر سه کوله بارشان را جمع کرده و راه افتادند.\r\nهر کدام به سمتی رفتند پسر بزرگ به کشور چین رفته و کاسه ای بسیار گران قیمت را خرید و به سمت پدر برگشت .\r\nپسر وسطی به هندوستان رفت و طوطی سخنگویی را خریداری کرده و به پیش پدر برگشت . و لی پسر کوچک به جهانگردی روی آورد و هر که را که دانا می دید به پیش آن می رفت و چیزی یاد می گرفت. بطوری که هر چه پول داشت در این راه خرج کرد و مجبور شد به کار کردن روی آورد. وی در پی کار جویی سر از روستایی در آورد. در یش باغداری که پیر و فرسوده شده بود و صاحب زنی پیر بود رفت و در باغ او مشغول کار کردن شد.\r\nروزها و ماه ها گذشت و باغ سیب پربار شده بود. پیر مرد و پیر زن با او بسیار خوشرفتاری می کردند. \r\nروزگار بسیار خوش می گذشت روزی از روزها پسر پادشاه که دیگر کوله باری از تجربه شده بود تصمیم گرفت با اندک سرمایه ای که از باغداری به دست آورده بود به نزد پدر برگردد. ماجرا را با پیرمرد در میان گذاشت و پیرمرد بسیار از رفتن او ناراحت شد اما چاره ای نبود، باید پسر به نزد پدرش برمی گشت . \r\nپیرزن با اندوه و غم کوله باری برای پسر آماده کرد و با هم با گریه و زاری خداحافظی کردند. پسر وقتی از در خانه بیرون می رفت دزدان و راهزنان به خانه همه کردند و دارو ندار مردباغدار را بردند.\r\nپسر مجبور شد پولی را که پس انداز کرده بود و در جای امنی از لباسش مخفی کرده بود را به باغدار بدهد. \r\nباغدار در نهایت شرمندگی سیبی را به رسم یادگاری به پسر داد و پسر قول داد که به زودی دوباره به آنها سر بزند و از آنها خداحافظی کرد و از خانه دور شد.\r\nچون پولی نداشت مجبورد بود بیشتر راه را با پای پیاده برود در طول مسیر خسته و کوفته بدون غذا خوابید و بعد از بیدارشدن چاره ای جز خوردن آن سیب ندید.\r\nپسر مشغول خوردن سیب بود متوجه شد در بدن او تغییراتی رخ می دهد.\r\nپس از پایان متوجه شد که چیزهایی را می داند که قبلا نمی دانست این همان اینده را دیدن بود.\r\nپسر اتفاقی صاحب سیبی شده بود که قبلا صحبتش را کرده بودیم با هزار زحمت به پیش پدر رسید . \r\nقبلا برادرانش به خدمت پدر رسیده و اشیائ خریداری شده را به او تقدیم کرده بودند .\r\nپدر از پسر کوچک سوال کرد تو چه آورده ای ؟ \r\nپسر جواب داد کوله باری از تجربه و آینده نگری و دیدن آینده !!!!!\r\nباشنیدن جریان سفر پسر شاه بادیدن اینهمه تجربه و دانایی، او را به عنوان پادشاه به مردم معرفی کرد.\r\nپسر با لباس پادشاهی به آن روستا رفت و پیرمرد باغدار و پیرزن را به قصر خود آورد و دستور داد دزدان و راهزنان را پیدا کرده و به مجازات برسانند . \r\n"},{"id":1071,"category_id":8,"category_code":"s8","source_id":32,"title":"ملکه ی گلها","content":"روزی روزگاری ، دختری مهربان در كنار باغ زیبا و پرگل زندگی می كرد ، كه به ملكه گل ها شهرت یافته بود .\r\nچند سالی بود كه او هر صبح به گل ها سر می زد ، آن ها را نوازش می كرد و سپس به آبیاری آن ها مشغول می شد .\r\nمدتی بعد ، به بیماری سختی مبتلا شد و نتوانست به باغ برود . دلش برای گل ها تنگ شده بود و هر روز از غم دوری گل ها گریه می كرد .\r\nگل ها هم خیلی دلشان برای ملكه گل ها تنگ شده بود ، دیگر كسی نبود آن ها را نوازش كند یا برایشان آواز بخواند .\r\nروزی از همان روزها ، كبوتر سفیدی كنار پنجره اتاق ملكه گل ها نشست . وقتی چشمش به ملكه افتاد فهمید ، دختر مهربانی كه كبوتر ها از او حرف می زنند ، همین ملكه است ، پس به سرعت به باغ رفت و به گل ها خبر داد كه ملكه سخت بیمار شده است .\r\nگلهاكه از شنیدن این خبر بسیار غمگین شده بودند ، به دنبال چاره ای می گشتند . یكی از آن ها گفت : « كاش می توانستیم به دیدن او برویم ولی می دانم كه این امكان ندارد ! »\r\nكبوتر گفت : « این كه كاری ندارد ، من می توانم هر روز یكی از شما را با نوكم بچینم و پیش او ببرم . »\r\nگل ها با شنیدن این پیشنهاد كبوتر خوشحال شدند و از همان روز به بعد ، كبوتر ، هر روز یكی از آن ها را به نوك می گرفت و برای ملكه می برد و او با دیدن و بوییدن گل ها ، حالش بهتر می شد .\r\nیک شب، كه ملكه در خواب بود ، ناگهان با شنیدن صدای گریه ای از خواب بیدار شد .\r\nدستش را به دیوار گرفت و آرام و آهسته به سمت باغ رفت ، وقتی داخل باغ شد فهمید كه صدای گریه مربوط به كیست ، این صدای گریه غنچه های كوچولوی باغ بود .\r\n\r\nآن ها نتوانسته بودند پیش ملكه بروند ، چون اگر از ساقه جدا می شدند نمی توانستند بشكفند ، در ضمن با رفتن گل ها ، آن ها احساس تنهایی می كردند .\r\nملكه مدتی آن ها را نوازش كرد و گریه آن ها را آرام كرد و سپس به آن ها قول داد كه هر چه زودتر گل ها را به باغ برگرداند .\r\nصبح فردا ، گل ها را به دست گرفت و خیلی آهسته و آرام قدم برداشت و به طرف باغ رفت ، وقتی كه وارد باغ شد ، نسیم خنک صبحگاهی صورتش را نوازش داد و حال بهتر پیدا كرد ، سپس شروع كرد به كاشتن گل ها در خاك .\r\nبا این كار حالش كم كم بهتر می شد ، تا اینكه بعد از چند روز توانست راه برود و حتی برای گل ها آواز بخواند .\r\nگل ها و غنچه ها از اینكه باز هم كنار هم از دیدار ملكه و مهربانی های او ، لذت می بردند خوشحال بودند و همگی به هم قول دادند كه سال های سال در كنار هم ، همچون گذشته مهربان و دوست باقی بمانند و در هیچ حالی ، همدیگر را فراموش نكنند و تنها نگذارند.\r\n"},{"id":1072,"category_id":8,"category_code":"s8","source_id":33,"title":"هیولا","content":"موشی صبح زود بیدار شد . سرش را از خانه بیرون کرد . یک هیولا با شال و کلاه دید که به او خیره شده . از ترس ، جیغی کشید و ته لانه برگشت . موشا و همه ی خانواده از جیغ اش بیدار شدند وگفتند : \"چی شده \" ؟\r\nموشی با ترس و لرز گفت : \"یه ...یه هیولا . یه هیولای گنده جِ ...جلویِ خو... خونه مون هست .\"\r\nموشا ، آرام و با احتیاط سرش را بیرون کرد تا ببیند این هیولا کجاست ؛ هنوز یک قدم بیرون نگذاشته بود که جیغ بنفشی کشید و همان جا ، دم در غش کرد . همه دورش جمع شدند . یکی آب به صورتش زد . یکی نوازشش کرد . موشی که خودش هیولا را دیده بود ، آمد کنارش و پرسید :\"دیدی؟\" موشا که تازه یک چشمش را باز کرده بود ، زیر لب گفت :\"آ... آره\" و دوباره غش کرد. موشی گفت :\"او ترسیده . فعلا هیچ کس از خونه بیرون نمی رود تا ببینیم چی کار کنیم.\"\r\nآن روز گذشت . شب ، موشی و موشا و همه ی بچه ها و فک و فامیل ،دور هم جمع شدند که تا ببینند چه کار باید بکنند. \r\nیکی از بچه موش ها گفت : \" با یک طناب دست و پاشو ببندیم .\" موشی و موشا دو تایی گفتند : \"کی میخواد این کارو بکنه ؟ ما که با دیدنش غش کردیم !\"\r\nموشا گفت :\" چطوراست از لانه تا زیر پای هیولا ، یک تونل بزنیم ؛ بعد یک چاله زیر پاش بکنیم تا بیفتد توش؟ \"\r\nموشی و موشا رو به بچه ها کردند و گفتند:\"نظر شما چیه ؟ \" . بچه ها گفتند :\"خوبه ، عالیه .\"\r\nفردا صبح ،کار کندن تونل شروع شد . موشی می کند و موشا خاک ها را عقب می کشید . بچه موش ها هم خاک ها را کیسه کیسه می کردند و ته لانه می بردند . آن قدر کندند و پیش رفتند که نفهمیدند کی غروب شد ! همه خسته و کوفته گرسنه خوابیدند . \r\nفردا که آفتاب همه جا را روشن کرد ، کار دوباره شروع شد . موشی گفت : \"شما ها یک کم دیگر بِکَنید تا من سری به بیرون بزنم ببینم چه خبرها هست و چه خبرها نیست .\" و یواشکی سرش را از خانه بیرون کرد . باد می آمد .خوب که نگاه کرد ، دید انگارهیولا کوچیک تر شده . با خودش گفت : \"شاید داره فرو میره تو چاله ؟ بعد صدا زد : \" بچه ها ، بیایید . \" \r\nهمه آمدند و با هم گفتند : \" چی شده ؟ \r\nموشی با هیجان گفت : \" انگار داریم موفق می شیم ، هیولا کوچیک شده .\"\r\nبعد موشا و بچه ها ، یواشکی سرشان را بیرون کردند و دیدند راستی راستی هیولا کوچیک ترشده و از سر و تنش آب می چکد . در همین وقت ، کلاه هیولا رفت تو هوا و همه از ترس این که مبدا راه بیفتد ، دویدند توی لانه . قلب همه تاپ تاپ می زد . موشی ، گوشش را به دیواره ی لانه چسباند و بعد از مدتی گفت : \"خبری نیست ؛ بذارین ببینم چی شده ؟\" و سرش را بیرون کرد و این طرف و آن طرف را نگاه کرد وبه خانه آمد و گفت : \" خبری نیست .\" \r\nدوباره همه به تونل برگشتند و مشغول کار شدند . خاک ها یی را که به کیسه ها می ریختند و می بردند ، بوی نم می داد . موشا گفت : \"فکر کنم زیر پای هیولا می رسیم . ببینین خاک خیس خورده.\"\r\nیک روز دیگر هم گذاشت . حالا دو روز می شد که موش ها زندانی شده بودند . فردا ، همه ، دیرتر بیدار شدند . کار دو روزه ، حسابی خسته شان کرده بود . موشا اولین کسی بود که سرش را از خانه بیرون آورد و به اطراف نگاه کرد . باورش نمی شد ؛ چشم هاش را مالید با خودش گفت : \"هیولا کو! . نکنه افتاده تو چاله . بعد داد زد : \" آهای بچه ها بیایین . هیولا نیست !\"همه آمدند و دیدند ، هیولایی وجود ندارد . \r\nموشی گفت :\"شاید افتاده تو چاله و می خواهد از تونل بیاید توی لانه ! بچه ها بپرین بیرون !\" بچه ها با ترس و لرز پریدند بیرون . \r\nموشی گفت : \" بیایید این دور و بر را بگردیم . شاید رد پایی از هیولا پیدا کردیم .\" \r\nموشی راه افتاد و رسید جایی که هیولا ایستاده بود و با انگشت به همه نشان داد:\" درست همین جا بود . ببینید ؛ جاش هنوز خیس خیسه .\r\nیکی از بچه موش ها کمی آن طرف تر ،کلاه هیو لا را پیدا کرد . یکی هم شال گردنش را. اما چیزی که موشی پیدا کرد از همه ی آن ها با مزه تر بود . او یک هویج و دو تا بادام و یک قاچ گوجه پیدا کرد و گفت : \"ببینید ، هیولا برامون چه هدیه هایی داده !\"\r\nبعد همگی رفتند خانه و مشغول خوردن هدیه های هیولا شدند . موشا گفت : \"بهتر نیست حالا که هیولا رفته ،خاک ها را به تونل برگردونیم و پرش کنیم ؟\" موشی گفت : \"نه . بذارید این تونل همین طور بمونه . بعدها می تونیم خونه جدیدمون کنیم .\" موشا و بچه ها هم گفتند : \" راست میگه .\"\r\nبچه موش اولی در حالی که داشت کمی از مغز بادام را می جوید به موشی گفت : \" بابا ، تو می دونی هیولا کجا رفته؟\" \r\nموشی گفت : \" راستش من نمی دانم از کجا آمده بود که کجا رفته باشد ! ولی چیزی که می دانم این است که این هیولا اصلا ترسناک نبوده . وگرنه این همه هدیه های خوش مزه برای ما نمی گذاشت . من که تا به حال چنین چیزی ندیده بودم . انگار آب شده و رفته توی زمین! \r\nهمین طور که صحبت می کردند ،پدر بزرگ از سفر برگشت . همه دورش جمع شدند و قصه ی هیولا را برایش گفتند . پدر بزرگ خندید و گفت : \" حتما کار بچه هاست ! فکر کنم آن ها آمده اند ، بازی کرده اند و بعد یک آدم برفی درست کرده اند و رفته اند . هوا که آفتابی شده ، هیولا، آب شده !\"\r\nبچه موش ها و موشی و موشا که تو عمرشان چنین چیزهایی ندیده بودند و نشنیده بودند ، به لانه رفتند و دور پدر بزرگ نشستند و او قصه ی آدم برفی و آفتاب را با آب و تاب ،برایشان تعریف کرد .\r\n"},{"id":1073,"category_id":8,"category_code":"s8","source_id":34,"title":"پادشاه و سه فرزندش","content":"در زمان‌های قدیم و در سرزمینی دور دست پادشاه پیری با سه فرزندش زندگی می‌کرد. اسم آن‌ها شاهزاده «کریسپین، شاهزاده و هوراک» و شاهزاده امیلی بود. پادشاه هر سه آن‌ها را به یک اندازه دوست داشت اما می‌دانست که باید فقط یکی از آن‌ها را برای شاه یا ملکه شدن انتخاب کند. هر چقدر پادشاه پیرتر می‌شد بیشتر نگران این موضوع می‌شد و نمی‌گذاشت که شب‌ها بخوابد.\r\nاو از خرس عروسکی خود می‌پرسید: «کدومشون بهترین پادشاه میشه؟» بعد یک روز صبح با یک ایده خوب از خواب بیدار شد.\r\nپادشاه فرزندانش را به اتاق تاج‌گذاری فرا خواند و بعد به آن‌ها گفت: «می‌دانید که هر سه شما را به یک اندازه دوست دارم» بچه‌ها سرشان را به علامت تائید تکان دادند. «اما من می تونم فقط یکی از شما رو برای پادشاهی بعد از مرگ خودم انتخاب کنم. برای همین می‌خوام یک امتحان ازتون بگیرم» بعد دستش را درون جیبش کرد: «یک سکه طلا به هر کدامتان می‌دهم. هر کدام از شما که با استفاده از این سکه بتواند کل این قصر را از بالا تا پایین از چیزی پر کند ملکه یا پادشاه بعدی خواهد شد.»\r\nهر چند که این آزمون فرزندان پادشاه را نگران کرد، چون قصر 75 اتاق داشت و کیلومترها راهرو داشت، ولی آن‌ها عقیده داشتند که آزمون عادلانه ایست. برای همین هر یک به راه افتادند تا چیزی پیدا کنند که بتواند قصر را پر کند.\r\nپرنس کریسپین به باغ قصر رفت تا کمی فکر کند. روی یک شاخه درخت او یک پرنده را دید که شاخه‌های درخت و پر داشت برای خودش لانه می‌ساخت.\r\nناگهان فریاد زد: «خودشه . پر با این سکه طلای تونم میلیون‌ها پر بخرم به راحتی با آن‌ها قصر رو پر کنم.» به همین دلیل رفت تا مردی که تخت‌هایی از پر درست می‌کرد را ببیند. پرنس کریسپین پرسید: «درازای این سکه طلا چقدر پر به من می‌فروشی؟»\r\nچشمان لحاف دوز با دیدن سکه طلا گرد و بزرگ شدند. او جواب داد «به اندازه 5 واکن» پرنس کریسپین گفت: «قبول است» به زودی او در حال بازگشت به خانه با 5واگن پر و یک لبخند بزرگ بر لب بود.\r\nپرنس هوراک به بازار رفت. او به اطرافش که پر از توپ‌های پارچه و ظروف مربا و جعبه‌های پیاز بود نگاه کرد و گفت: «نمی تونم باید سکه طلا به اندازه کافی از این چیزها بخرم تا بتونم باهاشون قصر رو پر کنم.»\r\nتقریباً داشت ناامید می‌شد که صدای فلوت یک پسر چوپان را شنید و یک فکری به ذهنش رسید.\r\nبه پسر چوپان گفت: «فلوتت رو درازای یک سکه طلا به من می‌فروشی؟»\r\nپسر جواب داد: «حتماً»\r\nشاهزاده سکه را به پسر دارد و به سمت کاخ برگشت و در تمام طول راه یک آهنگ شاد را با فلوت جدیدش تمرین می‌کرد.\r\nشاهزاده خانم« امیلی» هم تمام شهر را برای خریدن چیزی که بتواند با آن تمام کاخ را پر کند گشت. در نهایت گفت: «فایده‌ای نداره. کاخ بیش از حد بزرگه. فکر کنم باید به پدر بگم که من توی امتحان رد شدم»\r\nوقتی که برگشت تا به سمت کاخ حرکت کند چشمش به نوری افتاد که از یک مغازه کوچک بیرون می‌آمد. شاهزاده در پنجره داخل مغازه را نگاه کرد و دید که مغازه دار در حال روشن کردن شمع‌هاو فانوس است.\r\nشاهزاده خانم فریاد زد: «معلومه»\r\nاز به درون مغازه دوید و تا آنجایی که می‌توانست شمع خرید. بعد در حالی که از خوشحالی در پوست خود نمی‌گنجید با شمع‌ها به قصر برگشت.\r\nآن روز عصر در اتاق تاج‌گذاری پادشاه به فرزندانش گفت: «چیزهایی را که آورده‌اید نشان بدهید تا من پادشاه آینده را که مرا سربلند می‌کند انتخاب کنم.\r\nشاهزاده«کریسپین» پرهایش را آورد و همه جا را پر از پر کرد و همه را به عطسه کردن انداخت. وقتی که پرها روی زمین نشستند تنها20 اتاق از قصر را پر کرده بودند.\r\nپادشاه گفت: «آفرین، تلاش خوبی بود».\r\nشاهزاده «کریسپین گفت: «اه، لعنتی»\r\nشاهزاده «هوروک» فلوتی را که خریده بود بیرون آورد. آن‌را بر روی لب‌هایش گذاشت و شروع به نواختن یک آهنگ کرد. وقتی که آهنگش تمام شد همه متعجب بودند.\r\nشاهزاده گفت: «نمی‌بینید، همه قصر را با موسیقی پر کرده‌ام.»\r\nپادشاه گفت: «عالیه، هیچ کس نمی‌تونه اون رو شکست بده»\r\nشاهزاده امیلی گفت: «یک لحظه اجازه بده پدر ، بهتر نیست که ببینیم آیا موسیقی به اتاق زیر شیروانی و انبار هم رسیده است یا نه؟»\r\nپادشاه گفت: «راست می‌گویی» و دو نفر را به بالاترین و پایین‌ترین نقطه قصر فرستاد بعد گفت: «هورویس حالا دوباره بنواز» و پسرش این بار آهنگ بلندتری نواخت. بعد از مدتی خدمتکاران برگشتند و گفتند: «پس کی می‌خواهید بنوازید؟»\r\n«شاهزاده کریسپین» لبخند زد و گفت: اونها صدای موسیقی رو نشنیده‌اند، یعنی تو با موسیقی‌ات همه جای قصر را پر نکردی.\r\nشاهزاده هوروس گفت: «اه ، لعنتی»\r\nحالا نوبت شاهزاده خانم امیلی بود. همه وقتی بسته کوچک شمع‌هاای او را دیدند خندیدند.\r\nاو بسته شمع‌هارا باز کرد و خدمتکاران را فرستاد تا شمع‌ها درون فانوس‌های قصر بگذارند.»\r\nاو دستور داد: «مطمئن شوید در هر اتاق یک فانوس وجود داشته باشد. انباری و اتاق زیر شیروانی را فراموش نکنید.» بعد وقت و همه شمع‌ها را دانه دانه روشن کرد.\r\nبعد گفت: «بفرمائید پدر ، من همه قصر را با نور پر کرده‌ام.»\r\nپادشاه بسیار خوشحال بود، دخترش را بغل کرد و گفت: «سه هورا برای ملکه آینده، تو برنده ای» برادرانش گفتند: «اه، لعنتی»\r\nشاهزاده امیلی ملکه بسیار خوبی شد و مردمش خیلی از او راضی بودند. از آن به بعد هر سال برای تولد ملکه، مردم در همه جای شهر شمع روشن می‌کردند. این یعنی اینکه نه تنها همه ی قصر بلکه همه ی کشور باشمع روشن شده بود.\r\n"},{"id":1074,"category_id":8,"category_code":"s8","source_id":35,"title":"به دنبال فلک","content":"مرد فقیری بود که آه در بساط نداشت و به هر دری که می زد کار و بارش رو به راه نمی شد. شبی تا صبح از غصه خوابش نبرد. نشست فکر کرد چه کند ، چه نکند و آخر سر نتیجه گرفت باید برود فلک را پیدا کند و علت این همه بدبختی را از او بپرسد. \r\nخرت و پرت مختصری برای سفرش جور کرد؛ راه افتاد رفت و رفت تا در بیابانی به گرگی رسید. گرگ جلوش را گرفت و گفت : «ای آدمی زاد دوپا! در این بر بیابان کجا می روی؟» \r\nمرد گفت : «می روم فلک را پیدا کنم. سر از کارش در بیاورم و علت بدبختیم را از او بپرسم».\r\nگرگ گفت :«تو را به خدا اگر پیداش کردی اول از قول من سلام برسان؛ بعد بگو گرگ گفت شب و روز سرم درد می کند. چه کار کنم که سر دردم خوب بشود.»\r\nمرد گفت : «اگر پیداش کردم ، پیغامت را می رسانم.»\r\nو باز رفت و رفت تا رسید به پادشاهی که در جنگ شکست خورده بود و داشت فرار می کرد. پادشاه تا چشمش افتاد به مرد ، صداش زد : «آهای! از کجا می آیی و به کجا می روی؟»\r\nمرد جواب داد : « رهگذرم. دارم می روم فلک را پیدا کنم و از سرنوشتم باخبر شوم.» \r\nپادشاه گفت : «اگر پیداش کردی بپرس چرا من همیشه در جنگ شکست می خورم.»\r\nمرد گفت : «به روی چشم!»\r\nو راهش را گرفت و رفت تا رسید به دریا و دید ای داد بی داد دیگر هیچ راهی نیست و تا چشم کار می کند جلوش آب است. ناامید و با دلی پر غصه نشست لب دریا که ناگهان ماهی بزرگی سر از آب درآورد و گفت: «ای آدمیزاد! چه شده زانوی غم بغل گرفته ای و نشسته ای اینجا؟»\r\nمرد گفت : «داشتم می رفتم فلک را پیدا کنم و از او بپرسم چرا من همیشه آس و پاسم و روزگارم به سختی می گذرد که رسیدم اینجا و سفرم ناتمام ماند. چون نه کشتی هست که سوار آن شوم و نه راهی هست که پیاده بروم.» \r\nماهی گفت : «تو را می برم آن طرف دریا؛ به شرطی که قول بدی فلک را که پیدا کردی از او بپرسی چرا همیشه دماغ من می خارد.»\r\nمرد قول داد و ماهی او را به پشتش سوار کرد و برد آن طرف دریا. \r\nمرد باز هم رفت و رفت تا رسید به باغ بزرگی که انتهاش پیدا نبود و پر بود از درخت های سبز و شاداب و بوته های زرد پژمرده. خوب که نگاه کرد ، دید کرت درخت های شاداب پر آب است و کرت بوته های پژمرده از خشکی قاچ قاچ شده .\r\nمرد جلوتر که رفت باغبان پیری را دید که ریش بلند سفیدش را بسته دور کمر؛ پاچه شلوارش را زده بالا؛ بیلی گذاشته رو شانه و دارد آبیاری می کند .\r\nباغبان از مرد پرسید : «خیر پیش! به سلامتی کجا می روی؟» \r\nمرد جواب داد : «می روم فلک را پیدا کنم.»\r\nباغبان گفت : «چه کارش داری؟» \r\nمرد گفت : «تا حالا که پیداش نکرده ام؛ اگر پیداش کردم خیلی حرف ها دارم از او بپرسم و از ته و توی سرنوشتم با خبر شوم.»\r\nباغبان گفت : «هر چه می خواهی بپرس. من همان کسی هستم که دنبالش می گردی.»\r\nمرد ذوق زده پرسید : «ای فلک! اول بگو بدانم این باغ بی سر و ته با این درخت های تر و تازه و بوته های پلاسیده مال کیست؟» \r\nفلک جواب داد : «مال آدم های روی زمین است.» \r\nمرد پرسید : «سهم من کدام است؟» \r\nفلک دست مرد را گرفت برد دو سه کرت آن طرفتر و بوته پژمرده ای را به او نشان داد. \r\nمرد به بوته پژمرده و خاک ترک خورده آن نگاه کرد. از ته دل آه کشید و بیل را از دست فلک قاپید. آب را برگرداند پای بوته خودش و گفت : «حالا بگو بدانم چرا همیشه دماغ آن ماهی بزرگ می خارد؟»\r\nفلک گفت : «یک دانه مروارید درشت توی دماغش گیر کرده. باید با مشت بزنند پس سرش تا دانه مروارید بپرد بیرون و حالش خوب بشود.»\r\nمرد پرسید : «چرا آن پادشاه در تمام جنگ ها شکست می خورد و هیچوقت پیروزی نصیبش نمی شود؟»\r\nفلک جواب داد : «آن پادشاهی که می گویی دختری است که خودش را به شکل مرد در آورده اگر می خواهد شکست نخورد ، باید شوهر کند.» \r\nمرد گفت : «یک سؤال دیگر مانده؛ اگر جواب آن را هم بدهی زحمت کم می کنم و از خدمت مرخص می شوم.» \r\nفلک گفت : «هر چه دلت می خواهد بپرس.»\r\nمرد پرسید : «دوای درد آن گرگی که همیشه سرش درد می کند ، چیست؟» \r\nفلک جواب داد : «باید مغز آدم احمقی را بخورد تا سر دردش خوب بشود.»\r\nمرد جواب آخر را که شنید ، معطل نکرد. شاد و خندان راه برگشت را پیش گرفت و رفت تا دوباره رسید به کنار دریا. ماهی بزرگ که منتظر او بود و داشت ساحل را می پایید ، تا او را دید ، پرسید : «فلک را پیدا کردی؟» \r\nمرد گفت : «بله.» \r\nماهی گفت : «پرسیدی چرا همیشه دماغ من می خارد؟»\r\nمرد گفت : «اول من را برسان آن طرف دریا تا به تو بگویم.»\r\nماهی او را برد آن طرف دریا و گفت: « حالا بگو ببینم فلک چی گفت.»\r\nمرد گفت : «مروارید درشتی توی دماغت گیر کرده. یکی باید محکم با مشت بزند پس سرت تا مروارید بیاید بیرون.» \r\nماهی خوشحال شد و گفت : «زودباش محکم بزن پس سرم و مروارید را بردار برای خودت.» \r\nمرد گفت : «من دیگر به چنین چیزهایی احتیاج ندارم؛ چون بوته خودم را حسابی سیراب کرده ام.»\r\nهر چه ماهی التماس و درخواست کرد, حرفش به گوش مرد نرفت که نرفت و مرد او را به حال خودش گذاشت و راهش را گرفت و بی خیال رفت. \r\nپادشاه هم سر راه مرد بود و همین که او را دید پرسید : «پیغام ما را به فلک رساندی؟» \r\nمرد گفت : «بله. فلک گفت تو دختر هستی و خودت را به شکل مرد درآورده ای. اگر می خواهی در جنگ پیروز شوی باید شوهر کنی.» \r\nدختر گفت : «سال های سال کسی از این راز سر در نیاورد؛ اما تو سر از کارم درآوردی. بیا بی سروصدا من را به زنی بگیر و خودت به جای من پادشاهی کن.»\r\nمرد گفت : «حالا که بوته ام را سیراب کرده ام ، پادشاهی به چه دردم می خورد. حیف است آدم وقتش را صرف این کارها بکند.» \r\nدختر هر قدر از مرد خواهش و تمنا کرد و به گوش او خواند که بیا و من را بگیر، مرد قبول نکرد. \r\nآخر سر به دختر تشر زد و رفت و رفت تا رسید به گرگ. \r\nگرگ گفت : «ای آدمیزاد دوپا! خیلی شنگول و سرحال به نظر می رسی. دروغ نگفته باشم فلک را پیدا کرده ای.»\r\nمرد گفت : «راست گفتی! دوای سر درد تو هم مغز یک آدم احمق است و بس.»\r\nگرگ گفت : «برایم تعریف کن ببینم چطور توانستی فلک را پیدا کنی و در راه به چه چیزهایی برخوردی؟» \r\nمرد رو به روی گرگ نشست و هر چه را شنیده و دیده بود با آب و تاب تعریف کرد. \r\nگرگ که نزدیک بود از تعجب شاخ در بیاورد ، گفت : «بگو ببینم چرا مروارید درشت را برای خودت برنداشتی و برای چه با آن دختر عروسی نکردی؟» \r\nمرد گفت : «خدا پدرت را بیامرزد! دیگر به مروارید درشت و تخت پادشاهی چه احتیاج دارم؛ چون بوته بختم را حسابی سیراب کرده ام و تا حالا حتماً برای خودش درخت شادابی شده.»\r\nگرگ سری جنباند و گفت : «اگر تو از اینجا بروی من از کجا احمق تر از تو پیدا کنم؟» و تند پرید گلوی مرد را گرفت. او را خفه کرد و مغزش را درآورد و خورد. \r\n"},{"id":1075,"category_id":8,"category_code":"s8","source_id":36,"title":"قفس طلایی","content":"قفس طلايي\r\nيكي بود و يكي نبود. غير از خدا خوب و مهربون هيچ كس نبود . در گذشته هاي نه چندان دور و نه چندان نزديك ، در كنار جنگلي سر سبز و خرم ، دختركي زندگي مي كرد اسم اين دختر كوچك مريم بود. پدر و مادر مريم براي دو سه روزي به شهر رفته بودند. تا مقداري وسايل لازم براي نوزاد جديدي كه در راه داشتند تهيه كنند. اونها به مريم سفارش كرده بودند . كه مراقب خودش باشه و توي اين مدت به جنگل نرود.\r\nاما اون بدون اينكه گوش به توصيه پدر و مادرش بكنه ، صبح كه از خواب بيدار شد. تصميم گرفت براي گشت و گذار به جنگل بره. پس دست و صورتش رو آبي زد ، مقداري خوراكي برداشت و جاده باريكي رو كه كنار خانه شان بود گرفت و رفت.\r\nمناظر زيباي جنگل حسابي هوش وحواسش رو برده بود . و تنها وقتي به خودش اومد كه متوجه شد گمشده و راه بازگشت به خانه رو نمي تونه پيدا بكنه. بغض گلوش رو گرفته بود با خودش مي گفت اي كاش به حرف پدر و مادرم گوش مي كردم و به جنگل نمي اومدم .اما ديگه براي پشيماني دير شده بود. كنار درختي نشست و به اون تكيه داد و سرش رو توي دستش گرفت و زد زير گريه. با خودش ميگفت: ديگه هرگز پدر و مادرش و نخواهد ديد.\r\nدر اين لحظه صدايي توجه اونو جلب كرد. وقتي خوب به اطراف نگاه كرد متوجه شد گنجشكي از روي شاخه درختي با او حرف مي زند. گنجشك به مريم گفت : گمشده اي؟\r\nمريم با بغض گفت :بله . من گم شده ام و راه بازگشت به خونه را نمي دانم.\r\nگنجشك گفت : گريه نكن من ميدانم خانه تو كجاست و تو را به آنجا خواهم برد . تو تنها كاري كه بايد بكني اين است كه دنبال من بيايي .و بعد آرام و با سرعتي كه مريم بتواند او را ببيند. به طرف كنار جنگل حركن كردي.\r\nساعتي نگذشته بود كه مريم. جاده كمنتهي به خانه شان را شناخت و متوجه شده كه به نزديكي خانه رسيده است. پس با سرعت بيشتري به حركت خود ادامه داد.\r\nگنجشك زماني كه خانه مريم از دور ديده شد . روي شاخه اي نشست و به مريم گفت : من ديگر \r\nبايد برگردم. تو هم از اين به بعد مراقب خودت باش و براي گردش تنها به جنگل نيا. خدانگهدار.\r\nپرنده كوچك خواست پرواز كنه و بره كه دخترك اونو صدا كرد و گفتك نه قدري صبر كن . يك خواهش كوچك از تو دارم.\r\nگنجشك دو باره روي شاخه اي نشست و منتظر شنيدن در خوواست اون شد.\r\nمريم گفت: دوست دارم براي تشكر تو را ببوسم\r\nگنجشك كه ابتدا تمايلي به انجام اينكار نداشت. اما بدليل اصرار زياد دخترك قبول كرد و نزديك او امده و در ميان دو دست او نشست. \r\nهنوز لحظه اي نگذشته بود كه مريم ناگهان دستانش را بست و بطرف خانه دويد و و بمحض رسيدن به خانه گنجشك بيچاره را درون قفسي طلايي انداخت.\r\nپرنده بيچاره كه كاملا مات و مبهوت بود ، وقتي به خود آمد كه ديگر در ميان ميله هاي طلايي قفس قرار داشت . او رو به مريم كرده و گفت: چرا اين كار را با من كردي؟\r\nمگر من به تو بدي كرده ام . مگر اين من نبودم كه تو را به خانه ات رساندم و از وحشت و ترس گم شدن در جنگل نجاتت دادم. از تو ميخواهم هر چه زودتر در قفس را باز كني تا من به خانه ام در جنگل برگردم.\r\nمريم كه اكنون كاملا عوض شده بود به پرنده كوچك و اسير گفت:در خانه ما به تو بيشتر خوش خواهد گذشت. \r\nمن اين قفس را براي تو به بهشتي زيبا تبديل خواهم كرد. بهترين و خوشمزه ترين دانه ها را برايت تهيه مي كنم.من تورا دوست دارم و نمي توانم اجازه بدم از كنارم دور بشي.\r\nاصرار و التماسهاي پرنده بيچاره كمترين تاثيري در تصميم اون نداشت. مقداري آب و دانه در قفس گذاشت و آن را به ميخي در كنار اتاق خوابش آويزان كرد.\r\nروز بعد پدر و مارد مريم از شهر به خانه برگشته و پرنده كوچك را در قفس ديدندو متوجه نارحتي او شدند. اما اصرار هاي پدر و مادر هم فايده اي نداشت و مريم . با لجاجت و اصرار گنجشك بيچاره را در قفس نگهداشت.\r\nچندر روزي از اين ماجرا گذشت و پرنده بي چاره كاملا از آزادي خود مايوس شد . در گوشه قفس كز كرد و با صدايي حزن آلود اين آواز را زمزمه كرد.\r\nمن نجاتت دادم ، \r\nاز سر همدردي \r\nمن چه كردم با تو\r\nتو چه با من كردي ؟\r\n\r\nمن از اين دلگيرم\r\nغم ز چشمت شستم\r\nچشم من غمگين و\r\nسهم من دلسردي .\r\n\r\nمن نمي خواهم اين\r\nدانه و آبت را \r\nتو نكردي با من\r\nهيچ جز نامردي\r\n\r\nعشق من آزادي\r\nجان من پرواز است\r\nاين قفس درد من\r\nدرد تو بي دردي\r\n\r\nرنگ سبز جنگل\r\nآيه آبادي\r\nاين قفس زرين است \r\nرنگ نفرت زردي\r\n\r\nمريم از شنيدن اين ترانه بسيار خشمگين شدو با پرنده كوچك مهربان كه او را نجات داده بود قهر كرده.\r\nروزها مي آمدند و مي رفتند .يك روز دخترك متوجه شد پرنده كوچك بسيار لاغر و پزمرده شده و در گوشه اي از قفس كز كرده. به طرف اون رفت و پرسيد : چه اتفاقي افتاده؟ آيا بيمار شده اي؟ پرنده گفت . بله من شديدا\" بيمار هستم.\r\nمريم گفت : فورا\" برايت دكتر خبر ميكنم.\r\nگنجشك وسط حرف او پريد و گفت : نيازي به دكتر نيست. من خودم داروي بيماري ام را مي شناسم.\r\nمريم پرسيد نام آن چيست؟\r\nبگو تا سريعا\" برايت تهيه كنم.\r\nگنجشك پاسخ داد : در قفس را باز كن و من را در بغل بگير تا نام آن را بگويم\r\nمريم در قفس را باز كرد. اما قبل از آنكه بتواند او را در مشتان خود بگيرد. پرنده پرواز كرد و بر روي شاخه درختي كه در آن نزديكي بود نشست و گفت :دارويي كه شادي و نشاط را به من بر ميگردد فقط آزاديست. و پس ا اين حرف پر كشيد و از آنجا دور شد و رفت.پرنده هر گز نفهميد. كه ايا مريم . از كرده خود پشيمان شده يا نه.\r\nاما هميشه با خود تكرار مي كرد.\r\nآدم ها موجودات عجيبي هستند. وقتي نيازمند و در مانده اند. مهربان و خوش دل مي شوند . اما زمانيكه قدرتمند و بي نياز مي گردند. همه چيز را حتي انسانيت خودرا فراموش مي كنند و بدنبال اسارت و آزار ديگران مي روند . \r\n"},{"id":1076,"category_id":8,"category_code":"s8","source_id":37,"title":"کدو قلقله زن","content":"يكي داشت؛ يكي نداشت. پيرزني سه تا دختر داشت كه هر سه را شوهر داده بود و خودش مانده بود تك و تنها.\r\nروزي از روزها از تنهايي حوصله اش سر رفت. با خودش گفت: «از وقتي دختر كوچكترم را فرستاده ام خانه بخت, خانه ام خيلي سوت و كور شده, خوب است بروم سري بزنم به او و آب و هوايي عوض كنم.»\r\nپيرزن پاشد چادرچاقچور كرد؛ عصا دست گرفت و راه افتاد طرف خانه دختر تازه عروسش كه بيرون شهر, بالاي تپه اي قرار داشت.\r\nچشمتان روز بد نبيند! از دروازه شهر كه پا گذاشت بيرون گرگ گرسنه اي جلوش سبز شد. پيرزن تا چشمش افتاد به گرگ, دستپاچه شد و سلام بلند بالايي كرد.\r\nگرگ گفت «اي پيرزن! كجا مي روي؟»\r\nپيرزن گفت «مي روم خانه دخترم. چلو بخورم؛ پلو بخورم؛ مرغ و فسنجان بخورم؛ خورش متنجان بخورم؛ چاق بشوم؛ چله بشوم.»\r\nگرگ گفت «بي خود به خودت زحمت نده. چون من همين حالا يك لقمه ات مي كنم.»\r\nپيرزن گفت «يك لقمه پوست و استخوان كه سيرت نمي كند؛ بگذار برم خانه دخترم؛ چند روزي خوب بخورم و بخوابم, تنم گوشت تر و تازه بيارد و حسابي چاق و چله بشوم, آن وقت من را بخور.»\r\nگرگ گفت «بسيار خوب! اما يادت باشد من از اينجا جم نمي خورم تا تو برگردي.»\r\nپيرزن گفت «خيالت تخت باشد. زود برمي گردم.»\r\nو راه افتاد.\r\nچند قدم كه رفت پلنگي, مثل اجل معلق پريد جلوش و پرسيد «كجا مي روي پيرزن؟»\r\nپيرزن از ترس جانش تعظيم كرد و گفت «مي روم خانه دخترم. چلو بخورم؛ پلو بخورم؛ مرغ و فسنجان بخورم؛ خورش متنجان بخورم؛ چاق بشوم؛ چله بشوم.»\r\nپلنگ گفت «زحمت نكش؛ چون من خيلي گرسنه ام و همين حالا بايد تو را بخورم.»\r\nپيرزن گفت «يك لقمه پيرزن كجاي شكمت را پر مي كند؟ بگذار برم خانه دخترم, چند روزي خوب بخورم و خوب بخوابم, حسابي چاق وچله بشوم, آن وقت برمي گردم اينجا, من را بخور.»\r\nپلنگ گفت «بدفكري نيست. تا تو برگردي, من دندان رو جگر مي گذارم و همين دور و بر مي پلكم.»\r\nپيرزن گفت «زياد چشم به انتظارت نمي گذارم؛ زود برمي گردم.»\r\nو باز به راه افتاد؛ اما هنوز به خانه دخترش نرسيده بود كه شيري غرش كنان جلوش را گرفت. پيرزن از ترس سر جاش خشكش زد و اته پته كنان سلام كرد و جلو شير افتاد به خاك.\r\nشير گفت «كجا داري مي روي پيرزن؟»\r\nپيرزن گفت «دارم مي روم خانه دخترم. چلو بخورم؛ پلو بخورم؛ مرغ و فسنجان بخورم؛ خورش متنجان بخورم؛ چاق بشوم؛ چله بشوم.»\r\nشير گفت «نه. نمي گذارم؛ چون شكم من از گشنگي افتاده به غار و غور و همين حالا تو را مي خورم.»\r\nپيرزن گفت «اي شير! تو سلطان جنگلي؛ دل و جگر گاو نر ران گورخر هم شكمت را سير نمي كند؛ تا چه رسد به من پيرزن كه يك چنگ پوست و استخوان بيشتر نيستم؛ صبر كن برم خانه دخترم, چند روزي خوب بخورم و بخوابم, حسابي چاق و چله بشوم و برگردم. آن وقت من را بخور.»\r\nشير گفت «برو! اما زياد معطل نكن كه خيلي گشنه ام.»\r\nپيرزن گفت «زياد چشم به راهت نمي گذارم.»\r\nو راهش را گرفت رفت تا به خانه دخترش رسيد.\r\nدختر و دامادش خوشحال شدند. وقت شام پيرزن را بالاي سفره نشاندند و پلو و خورش و ميوه و شربت جلوش گذاشتند و موقع خواب براش رختخواب ترمه پهن كردند.\r\nپيرزن سه چهار روز خورد و خوابيد. وقت برگشتن به دخترش گفت «برو يك كدو تنبل بزرگ براي من بيار.»\r\nدختر رفت كدوي بزرگي آورد.\r\nپيرزن گفت «در جمع و جوري براي كدو بساز و توي كدو را خوب خالي كن.»\r\nدختر پرسيد «براي چه اين كار را بكنم؟»\r\nپيرزن هر چه را كه موقع آمدن براش پيش آمده بود شرح داد و آخر سر گفت «وقتي خواستم برم, مي روم توي كدو؟ تو هم ببرم بيرون هلم بده و قلم بده.»\r\nدختر توي كدو را خوب خالي كرد. پيرزن رفت تو كدو و دختر كدو را برد بيرون و از سرازيري جاده قلش داد پايين.\r\nكدو قلقله زن قل خورد تا رسيد نزديك شير.\r\nشير تا ديد كدو دارد مي آيد, پريد جلو گفت «كدو قلقله زن! نديدي پيرزن؟»\r\nكدو گفت «والله نديدم؛ بالله نديدم؛ به سنگ تق تق نديدم؛ به جوز لق لق نديدم؛ قلم بده؛ ولم بده؛ بگذار برم.»\r\nشير گفت «خيلي خوب.»\r\nو كدو را قل داد و ول داد.\r\nكدو قل خورد و قل خورد تا رسيد نزديك پلنگ.\r\nپلنگ تا ديد كدو دارد مي آيد, رفت جلو گفت «كدو قلقله زن! نديدي پيرزن؟»\r\nكدو گفت «والله نديدم؛ بالله نديدم؛ به سنگ تق تق نديدم؛ به جوز لق لق نديدم؛ قلم بده؛ ولم بده؛ بگذار برم.»\r\nپلنگ هم گفت «خيلي خوب!»\r\nو كدو را قل داد و ول داد.\r\nكدو قل خورد و قل خورد تا رسيد نزديك گرگ.\r\nگرگ تا ديد كدو دارد مي آيد, دويد جلو گفت «كدو قلقله زن! نديدي پيرزن؟»\r\nكدو گفت «والله نديدم؛ بالله نديدم؛ به سنگ تق تق نديدم؛ به جوز لق لق نديدم؛ قلم بده؛ ولم بده؛ بگذار برم.»\r\nگرگ صداي پيرزن را شناخت. گفت «سر من كلاه مي گذاري؟ تو همان پيرزني هستي كه قرار بود بخورمت. حالا رفته اي توي كدو.»\r\nگرگ شروع كرد به سوراخ كردن كدو و همين كه از اين ور كدو رفت تو, پيرزن دركدو را ورداشت و از آن ور كدو آمد بيرون. دويد توي خانه اش و در را پشت سرش بست.\r\n"},{"id":1077,"category_id":8,"category_code":"s8","source_id":38,"title":"مردی که یک روز راه رفته بود!","content":"مردی که یک روز راه رفته بود و خسته بود، به کنار جوی آبی رسید. جوراب هایش را در آورد و پاهایش را شست. بعد، جوراب هایش را هم شست و روی علف ها انداخت تا خشک شود. خودش هم خوابید. مرد که خوابش برد، جوراب ها بلند شدند و توی آب شیرجه زدند و شناکنان دور شدند.\r\nکمی که رفتند، یک لنگه از جوراب ها به علف های کنار جوی گیر کرد و هر کاری کرد، نتوانست خودش را نجات بدهد و همان جا ماند. اما لنگه ی دیگر جوراب همراه آب رفت و رفت تا این که دو تا ماهی آن را دیدند.\r\nیکی از ماهی ها تپل بود و یکی لاغر. ماهی لاغر گفت: « اول من دیدمش. مال من است. » ماهی تپل گفت: « کجای کاری؟ من از آن دور دورها دیده بودمش. مال من است. » ماهی ها سر لنگه ی جوراب دعوا راه انداختند و هر کدام یک سر جوراب را گرفتند و کشیدند. ماهی تپل گفت: « این جوراب من است. ولش کن! » ماهی لاغر گفت: « جوراب تو؟ این جوراب مال من است! »\r\nهمین موقع اردکی که یک لنگه جوراب به پا داشت، از راه رسید و بگو مگوی آن ها را شنید. خندید و با منقار خود، جوراب را از دست آن ها بیرون کشید و گفت: « جوراب ما کسی است که پا دارد. » جلوی چشم ماهی ها لنگه ی دوم جوراب را هم پوشید؛ قِری به کمرش داد و گفت: « قشنگه؟ بهم میاد؟ »\r\nصاحب جوراب از راه رسید و داد زد: « دزد! دزد جوراب! » و دنبال اردک دوید. ماهی لاغر گفت: « چه خوب که ما اهل دزدی نیستیم. » و شناکنان رفتند پی کارشان. از آن طرف، مردی که یک روز راه رفته بود، به اردک رسید. او را گرفت و خواست جوراب ها را از پایش در بیاورد که پشیمان شد. با خودش گفت: « کی تا حالا اردک جوراب پوش دیده!؟ اما مردِ جوراب پوش تا دلت بخواهد بوده و هست! »\r\n"},{"id":1078,"category_id":8,"category_code":"s8","source_id":39,"title":"سه آرزو","content":"در یک دهکده ی کوچک، در کنار جنگلی بزرگ، هیزم شکنی فقیر به نام «مکس» همراه با همسرش «السا» زندگی می کرد. یک روز که هیزم شکن می خوسات یک درخت بلوط بزرگ را ببُرد؛ یک فرشته ی کوچک را دید که زیر یکی از شاخه ها در حال پرواز کردن است. او تا آن روز هیچ فرشته ای را ندیده بود. در حالی که چشمانش را می مالید به خود گفت: « شاید دارم خواب می بینم. » اما وقتی چشمانش را باز کرد دید که فرشته هنوز همان جا است.\r\nفرشته کوچولو گفت: « سلام، اگر این درخت بلوط را قطع نکنی سه تا از آرزوهای خودت یا همسرت را برآورده می کنم. » سپس ناپدید شد. مکس هم از آن درخت صرف نظظر کرد و به سراغ درخت دیگری رفت. او تمام روز را به سختی کار کرد. وقتی به خانه برگشت، آن قدر خسته بود که موضوع فرشته و سه آرزویش را فراموش کرده بود. وقتی وارد خانه شد از همسرش پرسید: « شام چی داریم؟ » السا جواب داد: « سوپ سیب زمینی. آن قدر پول نداریم که بخواهیم گوشت بخریم و باهاش غذا درست کنیم. »\r\nمکس غرغرکنان گفت: « دوباره...نه...داریم شبیه سیب زمینی می شویم. کاشکی می شد برای تنوع هم که شده یک کم سوسیس می خوردیم. »\r\nبه محض اینکه مکس این حرف را زد، یک سوسیس بزرگ با صدای بلندی روی میز ظاهر شد. ظاهر شدن سوسیس باعث شد، مکس به یاد فرشته بیافتد و بعد همه چیز را در مورد سه آرزو به همسرش گفت.\r\nوقتی که حرف هایش تمام شد السا از عصبانیت سرخ شده بود. پس گفت: « مرد احمق، تو یکی از آرزوهای با ارزش را به خاطر یک سوسیس از بین بردی. کاش اون سوسیس به دماغت می چسبید تا کمی دلم خنک می شد. » در همان موقع یک صدای دیگر آمد و سوسیس از روی میز بلند شد و به طرف دماغ مکس رفت و به صورت مکس چسبید. وقتی که مکس شروع به حرف زدن کرد انگار که به شدت سرماخورده بود. مکس گفت: « نگاه کن چه کار کردی. حالا بیا و کمک کن تا این را از صورتم بکنم. »\r\nالسا خیلی تلاش کرد ولی سوسیس سفت و سخت به صورت مکس چسبیده بود. بعد از این که السا مدتی تلاش کرد و نتوانست سوسیس را از صورت او جدا کند، خسته شد و گفت: « حالا بیا آرزو کنیم که همه ی طلاها و جواهرات جهان را داشته باشیم و از زندگی لذت ببریم. » مکس جواب داد: « احمق نشو! چه جوری وقتی همه من را دماغ سوسیسی صدا می کنند می تونم از زندگی لذت ببرم؟ کاش این سوسیس به صورتم نچسبیده بود. » با یک صدای دیگر سوسیس ناپدید شد و سومین آرزوی آن ها هم تمام شد. مکس و السا نشستند و سوپ سیب زمینی شان را خوردند و در مورد این که چه کسی اشتباه کرده صحبت کردند. اما آن ها فراموش کرده بودند اگر با اولین آرزویشان که سوسیس ظاهر شد، آن را می خوردند، هنوز برای دو آرزوی دیگر فرصت داشتند. راستی اگر سه تا آرزوهای تو هم برآورده می شدند چه آرزوهایی می کردی؟\r\n"},{"id":1079,"category_id":8,"category_code":"s8","source_id":40,"title":"غذای جوجه ها و مورچه ها","content":"جوجه ها گرسنه بودند . توی باغچه جیک جیک می کردند و دنبال غذا می گشتند . اما غذا پیدا نمی کردند . زیر درخت توت رسیدند . زمین را گشتند و خاک ها را پس و پیش کردند اما دانه ای پیدا نکردند .\r\nگنجشکی روی شاخه ی درخت توت نشسته بود و به جوجه ها نگاه می کرد . دلش برای آنها سوخت . نوکش را کنار دانه ی توت گذاشت و تکان داد . توت کنده شد و افتاد جلوی جوجه ها .\r\nجوجه ها جیک جیک کردند و دانه ی توت را خوردند و سیر شدند .\r\nیک ذره توت ، توی خاک مانده بود . مورچه ای از آنجا می گذشت . مقداری از آن را خورد ، خیلی شیرین بود . دلش نیامد همه ی آن را بخورد . بقیه اش را برداشت و با خود به لانه برد . برادر کوچکش به شیرینی خیلی علاقه داشت .\r\n"},{"id":1080,"category_id":8,"category_code":"s8","source_id":41,"title":"گنج پر دردسر","content":"یک مرد روستایی زمانی که گوسفندانش را برای چرا به صحرا برده بود کوزه ای پیدا کرد که پر از سکه های طلا بود.\r\nمرد روستایی کوزه را به خانه اش برد و آن را در باغچه پنهان کرد. اما همیشه از این موضوع می ترسید که این کوزه مال راهزنان باشد و آن ها بفهمند که او کوزه را برداشته و او را بکشند. یک روز روستایی سراغ کوزه رفت و شروع به شمردن سکه ها کرد،ناگهان به فکر فرو رفت....\r\nچند نفر كه جلوی صورتشان را بسته بودند از دیوار خانه بالا آمدند و پریدند توی حیاط. از زیر لباسشان شمشیر های تیزی را بیرون كشیدند و گفتند گنج ما كو؟ زود باش گنجمان را پس بده! مرد بیچاره درحالی كه خیلی ترسیده بود فوری باغچه را كند و كوزه را بیرون آورد و به آنها داد.\r\nیكی از دزدان به بقیه گفت: باید او را بكشیم. وگرنه او ماجرا را برای مردم روستا تعریف می كند، و آنها ما را پیدا می كنند و اموالی كه سرقت كردیم پس می گیرند، تازه معلوم نیست چه بلایی سر خودمان بیاورند! بقیه هم حرف دزد اول را قبول كردند و گفتند باید او را بكشیم. یكی از دزد ها شمشیر تیزش را بالا برد و تا آمد به سر مرد روستایی بزند، در خانه به صدا در آمد و رشته خیال مرد روستایی را پاره كرد و او را از شر تیغ تیز شمشیر دزدان نجات داد!\r\nبیچاره مرد روستایی، حسابی ترسیده بود از آن فكر و خیال عجیب! او با ترس و لرز زیادی در را باز كرد. یكی از بچه های روستا پشت در بود، سلام كرد و گفت: آقا، پدرمان گفته شیر امروزمان را نیاوردید. اگر دوشیده اید بدهید خودم ببرم. \r\nمرد روستایی با عصبانیت گفت: امروز شیر نداریم. یك وقت دیگر بیا، برو رد كارت... پسرك بیچاره در حالی كه از فریاد مرد روستایی ترسیده بود از آنجا دور شد.\r\nمرد در را بست و دوباره به فكر فرو رفت! چه روزهای خوبی داشت. صبح ها از خواب بیدار می شد. صبحانه ای كه از شیر و پنیر و ماست حیوانات خودش بود را با خیال راحت می خورد.\r\nبعد گوسفندانش را به دشت می برد و چرا می داد، با مردم مهربان روستا دیدنی می كرد و در قهوه خانه روستا چای می خورد. و شب كه به خانه بر می گشت با خیال راحت می توانست بخوابد. اما از روزی كه این كوزه را پیدا كرده بود نه خواب داشت و نه خوراك!\r\nآن شب راتا صبح فكر كرد و بالاخره به این نتیجه رسید كه بهتر است كوزه را برگرداند و سرجایش پنهان كند. بلند شد و لباسش را پوشید، كوزه را از توی باغچه برداشت، لای دستمالی پیچید و به همراه گوسفندانش به سمت دشت به راه افتاد. رفت و رفت تا رسید پای همان درختی كه كوزه را پیدا كرده بود و آن رادرست مثل روز اول زیر خاك پنهان كرد.\r\nوقتی آخرین مشت های خاك را روی كوزه می ریخت نفس راحتی كشید و با خودش گفت: راحت شدم. نه خواب داشتم و نه خوراك. من را چه به گنج؟ گنج من همین گوسفندانم هستند، همین دوستانم، همین خانه ام! همه زندگی من گنج است، من را چه به مال حرام؟ و بلند شد و با خیالی راحت و دلی شاد گوسفندانش را در دشت چراند.\r\nنزدیك غروب وقتی داشت به روستا بر می گشت همان پسرك دیروزی را دید كه به سمتش می آمد. مرد روستایی جلو رفت، از بقچه اش یك دانه كشك درشت كه خودش درست كرده بود بیرون آورد و گذاشت توی دست پسرك، سر و صورتش را نوازش كرد، و گفت عمو جان! ببخش كه دیروز با تو بد صحبت كردم.\r\nبرو خانه و ظرفت را بردار و بیا. می خواهم شیر گاو تازه بدهم تا با خانواده ات بخوری، بدو جانم، زود بیا كه من منتظرت هستم... پسرك در حالی كه تعجب و ترس نگاهش كم كم به لبخند تبدیل شده بود با عجله به سمت خانه شان دوید. \r\nمرد روستایی با خیال آسوده به سمت خانه اش حركت كرد. وقتی كلید را توی در چوبی خانه كوچكش چرخاند و در را باز كرد یكی از گوسفند ها بلند گفت: بعععع! كلاغی از روی درخت گفت: قار! و نسیم ملایمی برگ درختان خانه را رقصاند!\r\nانگار همه به او خوش آمد گفتند!مرد روستایی نگاهی به خانه با صفایش انداخت، نفس عمیقی كشید و در حالی كه لبخندی بر لب داشت رفت تا شیر گاوش را بدوشد...\r\n"},{"id":1081,"category_id":8,"category_code":"s8","source_id":42,"title":"کبک و عقاب","content":"\r\nیکی بود یکی نبود. روزی روزگاری... \r\nدره ای بود سبز و باصفا. یک طرفش چشمه آب. یک طرفش گل های زیبا. درخت بود، پرنده بود. چرنده بود. دو تا دوست قدیمی هم بودند؛ یک کبک و یک عقاب. انیس و مونس هم؛ هم در شادی هم در غم. کبک و عقاب با هم پیمان بستند که هیچ وقت به هم آزاری نرسانند. عقاب حتی اگر گرسنه باشد کبک را نخورد. در عوض کبک قشنگترین آوازهایش را برایش بخواند. یک روز گرم و آفتابی، زمین پر از گُل، آسمان آبی، کبک دنبال آب و دانه توی علف زار می گشت. عقاب توی آسمان بود. فکر یک شکار خوشمزه با گوشت فراوان بود. همین طور که این طرف و آن طرف پرواز می کرد، چشمش به یک موش افتاد. پایین آمد و پنجه اش را دراز کرد و روی سرش پرید. موشِ زرنگ مقل برق و باد زیر سنگی دوید. همان جا قایم شد. عقاب دنبال یک شکار دیگر رفت. این بار خرگوشی پیدا کرد. خرگوشِ تپل نشسته بود لای سبزه و گُل. عقاب با خودش گفت: « بَه بَه یک ناهار خوشمزه. این دیگر مالِ خودم است. » نوکش تیز شد. چشم هایش ریز شد. قدم قدم جلو رفت. یک دفعه جستی زد و حمله کرد. خرگوشِ باهوش دو پا داشت دو پای دیگر قرض کرد و الفرار. تا عقاب به خودش بیاید ناپدید شد. عقاب خسته و ناامید به لانه اش برگشت. هوا تاریک شده بود و پرنده ها و چرنده ها هر کدام توی سوراخی رفته بودند. دیگر خبری از شکار نبود. عقاب که شکمش از گرسنگی قارقور می کرد به خودش گفت: « حالا چه کار کنم! کاشکی چیزی برای خوردن داشتم. » یاد دوستش افتاد. به زودی کبکِ مهربان به لانه اش بر می گشت. عفاب به خودش گفت: « من خیلی نادان و احق هستم. غذای به این خوبی کنارم هست، آن وقت من باید از گرسنگی غصه بخورم. اصلا عقاب کجا! کبک کجا! مگر کبک دوست عقاب می شود! » بعد چشم هایش را بست و به خودش گفت: « بَه بَه گوشتِ کبک، خوشمزه، نرم و لذیذ و عالی است. کبک جان! جای تو، توی شکمم خالی است. »\r\nعقاب آن قدر با خودش حرف زد تا دوستی و قول و قرارهایی که با کبک گذاشته بود از یادش رفت. منتظر نشست تا کبک بیاید. کبک بی خبر از همه جا، خرامان خرامان به لانه برگشت. عقاب را دید. سلام کرد و کنارش نشست. عقاب که دیگر طاقتش تمام شده بود جستی زد و گلوی او را گرفت. کبک فریاد زد: « ای دادِ بی داد. پس کو مروت؟ چه طور شد آن همه دوستی! آن همه رفاقت! »\r\nعقاب گفت: « این حرف ها را فراموشکن. فعلا خیلی گرسنه ام. پدر بزرگم به من وصیت کرده هر وقت کبکی را دیدی او را بخور. من هم می خواهم به وصیت او عمل کنم. »\r\nکبک بیچاره زیر چنگال های تیز عقاب به نفس نفس افتاد. فکری کرد و گفت: « راستش دوست عزیز! پدربزرگ من هم سفارش کرده بود اگر اسیر عقاب شدی به او بگو قبل از این که تو را بخورد حتما خدا را شکر کند وگر نه تو، توی گلویش گیر می کنی. »\r\nعقاب آرام شد. اگر خدا را شکر می کرد بهتر بود تا لقمه توی گلویش بماند و خفه بشود. سرش را به طرف آسمان گرفت و بال هایش را باز کرد. کبک منتظر بود. همین که پنجه های عقاب باز شد مثلِ باد دوید. لایِ شکاف سنگی رفت و خودش را نجات داد. عقاب تا به خودش بیاید، شکار خوشمزه اش در رفت. خجالت زده و غمگین به لانه اش پر کشید. دیگر هیچ کس حرفی از دوستیِ کبک و عقاب نشنید.\r\n"},{"id":1082,"category_id":8,"category_code":"s8","source_id":43,"title":"بپر بپر! نه نمی پرم!","content":"دو تا جوجه می خواستند با هم بازی کنند. از هم پرسیدند: « چی بازی؟ » \r\nگقتند: « برویم بالای درخت. از آن جا پایین بپریم! »\r\nجوجه ها می خواستند روی چی بپرند؟\r\nروی سبزه ها!\r\nجوجه ها به کمک هم از درخت بالا رفتند.\r\nبرای پریدن آماده شدند.\r\nاولی گفت: « بپر! »\r\nدومی گفت: « تو اول بپر. گربه اومده می ترسم! »\r\nاولی گفت: « گربه که ترس نداره! »\r\nدومی گفت: « اگر ترس نداره تو اول بپر! »\r\nاما نه اولی پرید نه دومی!\r\nآن وقت، جوجه ها با هم شروع کردند به لج و لجبازی کردن! این گفت من نمی پرم آن گفت من نمی پرم. آخرش چی شد؟\r\nیک باد تند آمد. یکی از جوجه ها را این طرف انداخت و یکی را آن طرف.\r\nگربه هه گفت: « سلام کجا رفتید؟ می آیید بازی کنیم؟ »\r\nجوجه ها با خنده گفتند: « بازی، بازی. با گربه ها؟ نه بازی. »\r\nآن وقت دویدند و رفتند. گربه هم رفت تا برای خودش یک دوست پیدا کند.\r\n"},{"id":1083,"category_id":8,"category_code":"s8","source_id":44,"title":"کوتوله ی ناقلا و غول دندون طلا","content":"یکی بود، یکی نبود. سه تا کوتوله بودند زرنگ و شجاع و ناقلا. می‌‌خواستند بروند به جنگ غول دندان طلا.\r\nآقا غوله، خواهر موطلایی آنها را دزدیده بود. چون که می‌خواست با موهای طلایی او، دندان طلایش را خلال کند. این، عادت غول دندان‌طلا بود. دخترهای موطلایی را می‌دزدید و با تار موهایشان خلال دندان درست می‌کرد.\r\nسه کوتوله قصه ما رفتند روی پشت‌بام خانه‌شان و داد زدند: آهای غول دندان‌طلا، آماده باش! می‌خواهیم بیاییم به جنگ تو.\r\nغول دندان طلا از زیرزمین خانه‌اش جواب داد: بیایید. اما با هم نیایید. یکی یکی بیایید، تا بیشتر سرگرم شوم.\r\nکوتوله اول گفت: اول من می‌روم!\r\nو از پشت‌بام پایین آمد. شمشیر تیزی برداشت و به راه افتاد.\r\nرفت و رفت تا رسید به خانه غول، در زد.\r\nآقا غوله زیر درخت انگور ایستاده بود و انگور می‌چید. پرسید: کیه؟\r\nکوتوله جواب داد: منم، کوتوله زرنگم، با شمشیر تیز آمده‌ام به جنگت.\r\nغول گفت: در باز است. بیا تو!\r\nکوتوله زرنگ پرید تو. های کشید و هوی کشید. شمشیرش را بلند کرد تا فرو کند به شکم غول. اما دید دستش به شکم غوله نمی‌رسد. پس شمشیر را زد به ساق پای او.\r\nآقا غوله خم شد و ساق پایش را خاراند و گفت: پس این بود شمشیر تیزت؟ اینکه از نیش پشه هم کندتر است!\r\nبعد هم کوتوله را بلند کرد و پرت کرد به سر جای اولش، یعنی روی پشت‌بام خانه خودشان.\r\nکوتوله دوم روی پشت‌بام ایستاده بود و آن دور را نگاه می‌کرد. یک‌‌دفعه دید که داداش زرنگش تالاپی افتاد پیش پایش. عصبانی شد و داد کشید: آهای غول پررو! حالا دیگر داداش مرا پرت می‌کنی روی پشت‌بام؟ الان می‌آیم و خدمتت می‌رسم!\r\nبعد هم از پشت‌بام پایین آمد. یک سنگ سیاه سنگین برداشت و به راه افتاد. رفت و رفت تا رسید به خانه غول. در زد و گفت: منم، کوتوله شجاعم. با یک سنگ سنگین آمده‌ام به جنگت.\r\nغول زیر درخت انگور نشسته بود و انگور می‌خورد. گفت: در باز است، بیا تو!\r\nکوتوله پرید تو. سنگ را بلند کرد تا بکوبد به سر غوله، دید که دستش به سر غوله نمی‌رسد، پس سنگ را کوبید روی شکم او.\r\nغول دندان‌طلا دستی روی شکمش کشید و خندید و گفت: پس این بود سنگ سنگینت؟ اینکه از نخود آبگوشت من هم سبک‌تر است!\r\nبعد هم کوتوله را بلند کرد و پرت کرد روی پشت‌بام خانه خودشان.\r\nکوتوله سوم که روی پشت‌بام خوابش برده بود، از خواب پرید. دید ای داد بیداد، ‌آقا غوله، داداش شجاعش را هم پرت کرده! با خودش گفت: حالا چه کنم، چه کار کنم؟ نوبت من است که بروم به جنگ غول. اما با چی بروم؟ با دست خالی که نمی‌شود!\r\nاز پشت‌بام پایین آمد. به دور و برش نگاه کرد. نه شمشیری بود و نه سنگی. فقط یک کلّه‌ قند آنجا بود. همان را برداشت و به راه افتاد.\r\nرفت و رفت. رسید به خانه غوله. همان‌جا پشت در نشست.\r\nآقا غوله انگورش را خورده بود و زیر درخت دراز کشیده بود. یک دفعه دید که از پشت در بوی آدمیزاد می‌آید. پرسید: کی پشت در است؟\r\nکوتوله جواب داد: منم، کوتوله ناقلا.\r\nغول گفت: آمده‌ای به جنگ من؟\r\nکوتوله گفت: نه بابا، کی حوصله جنگ و دعوا دارد!\r\nغول گفت: با خودت چی آورده‌ای؟ شمشیر تیز یا سنگ سیاه؟\r\nکوتوله گفت: هیچ‌کدام. فقط یک کله‌قند دارم. هر جا می‌روم آن را با خودم می‌برم، تا اگر گرسنه شدم به آن لیس بزنم.\r\nغول دندان‌طلا خندید و گفت: آفرین، باریکلا! از تو خوشم آمد. حالا که این همه راه آمده‌ای، بیا و دندان طلای مرا با موی خواهرت خلال کن.\r\nکوتوله ناقلا گفت: چشم!\r\nو در را باز کرد و آمد توی خانه. از سر آقا غوله بالا رفت و پرید توی دهان او.\r\nغول یک تار موی طلایی به او داد و گفت: زودباش، مشغول شو!\r\nکوتوله گفت: چشم، اما کله ‌قندم را کجا بگذارم؟\r\nغول که خوابش گرفته بود، گفت: چه می‌دانم! همانجا یک گوشه‌ای بگذار. \r\nو چشمش را بست و خوابید.\r\nکوتوله ناقلا کله ‌قند را گذاشت روی دندان طلای آقا غوله و مشغول کار شد. اما چه کاری؟ خلال کردن دندان غول؟ نه! کار او این بود که کله قند را روی دندان طلای غول بمالد. آنقدر این کار را ادامه داد تا کله‌ قند آب شد و توی دندان غول رفت.\r\nبعد از ساعتی غول از خواب بیدار شد. دید که دندان طلایش درد می‌کند. داد زد: آی دندانم! وای دندانم!\r\nکوتوله ناقلا از دهان او پایین پرید و گفت: بیچاره شما! دندان طلایتان را کرم خورده. وقتی خلالش می‌کردم، دیدم.\r\nغول گفت: حالا باید چه کار کنم؟\r\nکوتوله گفت: معلوم است. دندانی را که خراب شده، باید کشید و انداخت دور.\r\nغول عصبانی شد و گفت: هیچ وقت این کار را نمی‌کنم!\r\nبعد هم کوتوله را بلند کرد و پرت کرد روی پشت‌بام خانه خودشان.\r\nکوتوله‌های اول و دوم پرسیدند: چی شد، چی کار کردی؟\r\nکوتوله ناقلا گفت: خدمتش رسیدم. گوش کنید تا صدای داد و فریادش را بشنوید!\r\nصدای داد و فریاد آقا غوله از دندان درد بلند بود و به گوش همه می‌رسید. غول دندان‌طلا هفت شب و هفت روز دندان درد کشید و آه و ناله کرد، تا بالاخره مجبور شد که دندان طلایش را بکشد و بیندازد دور.\r\nبعدش هم نشست و با خودش فکر کرد که: حالا که دندان طلا ندارم، خلال دندان طلایی را می‌خواهم چه کار؟\r\nپس خواهر کوتوله‌ها را با دو انگشت بلند کرد و پرت کرد به آن دور. دور کجا بود؟ روی پشت‌بام خانه کوتوله‌ها.\r\nکوتوله‌ها خواهر موطلایی‌شان را از پشت‌بام پایین آوردند. جشن گرفتند و شادی کردند و بقیه عمر را به‌خوبی و خوشی گذراندند.\r\n"},{"id":1084,"category_id":8,"category_code":"s8","source_id":45,"title":"آب","content":"یکی بود، یکی نبود.\r\nیه موشی بود و یه مامان موشی.\r\nمامان موشی هر جا می رفت، موشی می گفت: « منم میام. منم میام. »\r\nیک روز موشی و مامان موشی داشتند تند تند می رفتند. رسیدند به چشمه.\r\nموشی گفت: « خسته شدم. من تشنمه. من تشنمه. »\r\nمامان موشی گفت: « همین جا استراحت کن. از این چشمه، آب بخور تا من برگردم. »\r\nموشی رفت لب چشمه، آب بخورد. یکهو عکس یه ابر گُنده را توی آب دید.\r\nگفت: « تو کی هستی که افتادی تو آب؟ »\r\nابر گُنده کمی وول خورد. بامب کرد و بومب کرد. نور زد توی چشمه و گفت:\r\n« من ابر رعد و برقی ام! »\r\nموشی ترسید. پرید پشت سنگ و قایم شد. یه برگ گرفت روی سرش که پیدا نباشد و گفت: « من کوچولواَم! بامب و بومب می کنی می ترسم! »\r\nابر گُنده گفت: « آخی! موشی کوچولو. باشه بامب و بومب نمی کنم. »\r\nابر گنده یواش یواش چیک چیک کرد. باران شد و گفت: « نترس موشی! حالا دیگه بارانم. »\r\nموشی به باران نگاه کرد. باران چیک و چیک می افتاد روی زمین و قایم می شد. موشی خندید و فریاد کشید:\r\n« چه باران زیادی! » و روی زمین دنبال چیک چیک ها دوید. پرید این چیک را بگیرد، از توی دستش سُر خورد و در رفت. پرید آن چیک را بگیرد، آن یکی هم در رفت. موشی از این چیک باران روی آن چیک باران پرید. خیسِ خیس شد. سردش شد و عطسه کرد: هاپیشته ...\r\nموشی دمش را تکان داد، سرش را تکان داد. یه پا یه پا، لی لی لی، می کرد. چکه های باران، چک چک روی زمین می ریخت. \r\nموشی به ابر گفت: « من کوچولواَم! خیس که می شم، سردم می شه. می لرزم. »\r\nاما ابر جوابی نداد!\r\nموشی هر چی گوش کرد، صدائی نشنید. داد زد: « کجا رفتی؟ قهر کردی؟ »\r\nاما باز هم هیچی نشنید! نه بامبی نه چیکی. موشی، دوباره رفت سر چشمه. یک ابر کوچولو توی آب دید. گفت: « ابر کوچولو! یه ابر گُنده ندیدی؟ »\r\nابر کوچولو خندید و گفت: « دیدم دیدم. ابر گُنده، خودم بودم. گُنده بودم، بامب کردم و بومب کردم. رعد زدم و برق زدم. چیک چیکِ باران شدم. حالا هم یه ابر کوچولو شدم. »\r\nموشی خندید. نشست سر چشمه و آب خورد. ابر کوچولو هم چیک چیک بارید توی چشمه. سُر خورد تو دل موشی کوچولو و همان جا ماند.\r\n"},{"id":1085,"category_id":8,"category_code":"s8","source_id":46,"title":"جوجه اردک شجاع","content":"نبات كوچولو به همراه مادر و 4 برادرش در خانه كوچك و زيبايي كنار درياچه جنگل قصه‌ها با خوبي و خوشي زندگي مي‌كردند. برادرهاي نبات همگي از او بزرگ‌تر و قوي‌تر بودند. آنها از مادرشان خانم اردك مهربان شنا كردن را ياد گرفته بودند و بيشتر روز را در حال شنا و بازي توي درياچه بودند. \r\nاما بچه‌ها، نبات قصه ما، از آب مي‌ترسيد و دوست نداشت در آب درياچه شنا كند. به خاطر همين برادرانش او را مسخره مي‌كردند و به او مي‌خنديدند. هر چقدر مادر با او صحبت مي‌كرد هم فايده‌اي نداشت. مادر به او مي‌گفت: نبات كوچولو، بيا پشت من سوار شو تا با هم توي آب برويم، اما باز هم اردك كوچولو قبول نمي‌كرد. برادران نبات به او مي‌گفتند: تو ترسويي و جرات هيچ‌كاري را نداري. ما با تو بازي نمي‌كنيم. \r\nنبات قصه ما خيلي تنها بود بچه‌ها و تنها دوست او كرم كوچولويي بود كه هر روز كنار درياچه مي‌آمد و با او بازي مي‌كرد. كرم كوچولو، نبات را خيلي دوست داشت و دلش مي‌خواست او هر چه زودتر شنا كردن را ياد بگيرد و از آب نترسد. يك روز خوب و آفتابي مثل هميشه كرم كوچولو و نبات كنار درياچه مشغول بازي و خنده بودند. مادر نبات و برادرانش هم توي آب مشغول شنا كردن، مادر به نبات گفت: عزيزم. من و برادرانت مي‌خواهيم براي پيدا كردن غذا به آن طرف رودخانه برويم تو و كرم كوچولو مواظب خودتان باشيد تا ما برگرديم. نبات گفت: باشه. مامان جون. شما برويد، خيالتان راحت باشد. مادر و برادران نبات از آنها دور شدند و نبات و كرم كوچولو هم مشغول بازي شدند كه يكدفعه سايه بزرگي را روي زمين ديدند. آنها وقتي به بالاي سرشان نگاه كردند، پرنده بزرگي را ديدند كه با سرعت داشت به طرف آنها مي‌آمد. نبات و كرم كوچولو زود فرار كردند، اما فايده‌اي نداشت. پرنده پايين آمد و كرم كوچولو را ميان چنگال‌هايش گرفت و پرواز كرد و رفت. نبات هر چه داد و فرياد كرد، كسي صداي او را نشنيد و به كمك آنها نيامد. نبات در حالي كه ترسيده بود و اشك مي‌ريخت داد زد: كرم كوچولو پايش را گاز بگير. كرم كوچولو با تمام قدرت پاي پرنده را گاز گرفت و پرنده بزرگ از درد پايش را باز كرد و كرم كوچولو رها شد و افتاد، اما بچه‌ها كرم كوچولو توي آب درياچه افتاده بود. او شنا بلد نبود. نبات هر چه مادر و برادرانش را صدا زد تا او را نجات بدهند فايده‌اي نداشت. آنها صداي او را نمي‌شنيدند. نبات شاخه درختي را برداشت و خواست با آن كرم كوچولو را نجات بدهد، اما شاخه به كرم كوچولو نرسيد و توي آب افتاد. كرم كوچولو خسته شده بود و فرياد مي‌زد و كمك مي‌خواست. او كم‌كم داشت غرق مي‌شد و كسي هم نبود كه او را نجات بدهد.\r\nنبات مهربون كه ديد چاره‌اي ندارد سريع توي آب پريد. او شروع كرد به شنا كردن تا اين كه رسيد به كرم كوچولو و او را برداشت و روي پشت خودش گذاشت. نبات نفس راحتي كشيد و گفت:\r\nحالت خوب است كرم كوچولو، سالم هستي؟\r\nكرم كوچولو از نبات تشكر كرد و گفت: ممنونم نبات مهربان، تو واقعا جوجه اردك شجاعي هستي. نبات همين طور كه آرام، آرام داشت شنا مي‌كرد و به طرف خانه مي‌رفت صداي مادر و برادرانش را شنيد. آنها داشتند او را تشويق مي‌كردند و به او آفرين مي‌گفتند. نبات كوچولو تازه فهميده بود كه دارد توي آب شنا مي‌كند و وقتي خوب دقت كرد ديد آب اصلا ترس ندارد و شنا كردن هم خيلي خوب است.\r\nبرادران نبات سريع كنار او آمدند و گفتند: ما اشتباه مي‌كرديم، تو جوجه اردك شجاعي هستي ما به تو افتخار مي‌كنيم. از آن روز به بعد، هميشه كرم كوچولو روي پشت نبات سوار مي‌شد و با هم مي‌رفتند توي آب و شاد بودند و مي‌خنديدند. ديگر هيچ وقت نبات كوچولو از هيچ چيز نمي‌ترسيد آخه او يك جوجه اردك شجاع بود.\r\n"},{"id":1086,"category_id":8,"category_code":"s8","source_id":47,"title":"شنگل و منگول و چنگل","content":"\r\nبه نام خدا\r\nمامان شنگل و منگل و چنگل رفته بود بانك پول برق را بپردازد. \r\nتوي خانه، شنگل و منگل سرشان به بازي گرم بود. چه بازي؟ كامپيوتر بازي. آقاگرگه يواش‌يواش از پله‌هاي ساختمان بالا رفت تا رسيد به طبقة سوم. گوشش را چسباند به در آپارتمان. صداي شنگل را مي‌شنيد: «الان مي‌زنم داغونت مي‌كنم.»\r\nصداي منگل را هم شنيد: «الان خرد و خميرت مي‌كنم.»\r\nاما خبري از چنگل نبود. او توي اتاق آنطرفي نشسته بود و كاردستي درست مي‌كرد. گرگه از صداي هارت و پورت شنگل جا خورد: «هر كس بيايد جلو، يك لقمة چپ مي‌شود.»\r\nگرگه از صداي هارت و پورت منگل هم تعجب كرد: «من هفت‌تا جان دارم. به اين زودي‌ها نمي‌ميرم. هاهاها!»\r\nپيش خودش فكر كرد: «بره هم بره‌هاي قديم. اين‌ها دارند واسة من خط و نشان مي‌كشند. بهتر است بروم قصابي چند كيلو گوشت بخرم و بخورم.» پس دمش را گذاشت روي كولش و پا گذاشت به فرار. پله‌ها را دوتا يكي كرد و جيم شد. قصة ما به سر...\r\nنه، قصة ما به سر نرسيده هنوز. توي پاركينگ، چشم گرگه به چيزي خورد. كنتور و فيوز برق. ناگهان چشم‌هايش از شادي و شيطنت برق زد: «فهميدم چه كارتان كنم.» بادي به گلويش انداخت و با دستهاي سياه و پرمويش فيوزها را قطع كرد. همه جا در تاريكي فرو رفت. در آن تاريكي چه برقي مي‌زدند چشم‌هاي آقا گرگه! بعد يواش يواش از پله‌ها بالا رفت.\r\nآن بالا چه خبر بود؟ توي خانه، بچه‌ها از تاريكي ترسيدند و به هم نگاه كردند. از هارت و پورت چند دقيقه پيششان خبري نبود. از ترس مثل سيم‌هاي گيتار مي‌لرزيدند. فقط چنگل بود كه كمتر از بقيه مي‌ترسيد و مي‌لرزيد. او به آنها دلداري داد و گفت: «خجالت بكشيد! تاريكي كه ترس ندارد. الان خودم مي‌روم بيرون ببينم چه خبر است!»\r\nدر را باز كرد و رفت توي پاگرد و رو به پله‌ها سرك كشيد. همه جا تاريك بود و چيزي ديده نمي‌شد. صداي نفس‌‌نفس آقا گرگه را شنيد كه داشت بالا مي‌آمد. چنگل زود برگشت و پشت جا كفشي قايم شد. فكر كرد اگر به شنگل و منگل بگويد گرگه پشت در است، از ترس توي خودشان جيش مي‌كنند. صبر كرد ببيند چه اتفاقي مي‌افتد. \r\nگرگه رسيد پشت در. ديد از هارت و پورت بره‌ها خبري نيست. نه مي‌خواستند او را داغون كنند، نه يك لقمة چپ. در زد و قاه قاه خنديد. از آن طرف در صداي گريه‌ها و لرزيدن بره‌ها را مي‌شنيد. از خوشحالي پنجه‌هايش را به هم ماليد و آهسته گفت: «يكيش واسه صبحانه، يكيش واسه ناهار، يكيش هم واسه شام. هاهاها!»\r\nهمين طور كه داشت اين حرف‌ها را مي‌زد و اين فكرها را مي‌كرد، يك مرتبه در باز شد و گوريلي ترسناك توي صورتش فرياد زد: «هاووو! هووو!» \r\nنزديك بود از وحشت خودش را خيس كند. اما اين كار را نكرد. دوتا پا داشت، دوتاي ديگر هم قرض كرد و از پله‌ها سرازير شد. ولي آن‌قدر هول بود كه دست و پايش را گم كرد و ولو شد توي راه‌پله. با صداهاي عجيب و غريب: تالاپ... تالاپ... تالاپ! افتاد پايين.\r\nچنگل وقتي كه خيالش راحت شد كه از گرگه خبري نيست، نقابش را از روي صورتش برداشت و عرقش را پاك كرد. نقابي كه خودش با دست‌هاي خودش ساخته بود. آن را به خواهر و برادرش نشان داد و گفت: «به اين مي‌گويند يك كاردستي درست و حسابي.»\r\n"},{"id":1087,"category_id":8,"category_code":"s8","source_id":48,"title":"خر دانا","content":"یک روز يک مرد روستايي يک کوله بار روي خرش گذاشت و خودش هم سوار شد تا به شهر برود. \r\nخر پير و ناتوان بود و راه دور و ناهموار بود و در صحرا پاي خر به سوراخي رفت و به زمين غلطيد. بعد از اينکه روستايي به زور خر را از زمين بلند کرد معلوم شد پاي خر شکسته و ديگر نمي تواند راه برود. \r\nروستايي کوله بار را به دوش گرفت و خر پا شکسته را در بيابان ول کرد و رفت. \r\nخر بدبخت در صحرا مانده بود و با خود فکر مي کرد که «يک عمر براي اين \r\nبي انصاف ها بار کشيدم و حالا که پير و دردمند شده ام مرا به گرگ بيابان \r\nمي سپارند و مي روند.» خر با حسرت به هر طرف نگاه مي کرد و يک وقت ديد که راستي راستي از دور يک گرگ را مي بيند.\r\nگرگ درنده همينکه خر را در صحرا افتاده ديد خوشحال شد و فريادي از شادي کشيد و شروع کرد به پيش آمدن تا خر را از هم بدرد و بخورد. \r\nخر فکر کرد«اگر مي توانستم راه بروم، دست و پايي مي کردم و کوششي به کار \r\nمي بردم و شايد زورم به گرگ مي رسيد ولي حالا هم نبايد نااميد باشم و تسليم گرگ شوم. پاي شکسته مهم نيست. تا وقتي مغز کار مي کند براي هر گرفتاري چاره اي پيدا مي شود.» نقشه اي را کشيد، به زحمت از جاي خود برخاست و ايستاد اما نمي توانست قدم از قدم بردارد. همينکه گرگ به او نزديک شد خر گفت:«اي سالار درندگان، سلام.» \r\nگرگ از رفتار خر تعجب کرد و گفت:«سلام، چرا اينجا خوابيده بودي؟» خر گفت: «نخوابيده بودم بلکه افتاده بودم، بيمارم و دردمندم و حالا هم نمي توانم از جايم تکان بخورم. اين را مي گويم که بداني هيچ کاري از دستم بر نمي آيد، نه فرار، نه دعوا، و درست و حسابي در اختيار تو هستم ولي پيش از مرگم يک خواهش از تو دارم.» \r\nگرگ پرسيد:«خواهش؟ چه خواهشي؟» \r\nخر گفت:«ببين اي گرگ عزيز، درست است که من خرم ولي خر هم تا جان دارد جانش شيرين است، همانطور که جان آدم براي خودش شيرين است البته مرگ من خيلي نزديک است و گوشت من هم قسمت تو است، مي بيني که در اين بيابان ديگر هيچ کس نيست. من هم راضي ام، نوش جانت و حلالت باشد. ولي خواهشم اين است که کمي لطف و مرحمت داشته باشي و تا وقتي هوش و حواس من بجا هست و بيحال نشده ام در خوردن من عجله نکني و بيخود و بي جهت گناه کشتن مرا به گردن نگيري، چرا که اکنون دست و پاي من دارد مي لرزد و زورکي خودم را نگاهداشته ام و تا چند لحظه ديگر خودم از دنيا مي روم. در عوض من هم يک خوبي به تو مي کنم و چيزي را که نمي داني و خبر نداري به تو مي دهم که با آن بتواني صد تا خر ديگر هم بخري.» \r\nگرگ گفت:«خواهشت را قبول مي کنم ولي آن چيزي که مي گويي کجاست؟ خر را با پول مي خرند نه با حرف.» \r\nخر گفت:«صحيح است من هم طلاي خالص به تو مي دهم. خوب گوش کن، صاحب من يک شخص ثروتمند است و آنقدر طلا و نقره دارد که نپرس، و چون من در نظرش خيلي عزيز بودم براي من بهترين زندگي را درست کرده بود. آخور مرا با سنگ مرمر ساخته بود، طويله ام را با آجر کاشي فرش مي کرد، توبره ام را با ابريشم مي بافت و پالان مرا از مخمل و حرير مي دوخت و بجاي کاه و جو هميشه نقل و نبات به من مي داد. گوشت من هم خيلي شيرين است حالا مي خوري و مي بيني. آنوقت چون خيلي خاطرم عزيز بود هميشه نعل هاي دست و پاي مرا هم از طلاي خالص مي ساخت و من امروز تنها و بي اجازه به گردش آمده بودم که حالم به هم خورد. حالا که گذشت ولي من خيلي خر ناز پرورده اي هستم و نعلهاي دست و پاي من از طلا است و تو که گرگ خوبي هستي مي تواني اين نعلها را از دست و پايم بکني و با آن صدتا خر بخري. بيا نگاه کن ببين چه نعلهاي پر قيمتي دارم!» \r\nهمانطور که ديگران به طمع مال و منال گرفتار مي شوند گرگ هم به طمع افتاد و رفت تا نعل خر را تماشا کند. اما همينکه به پاهاي خر نزديک شد خر وقت را غنيمت شمرد و با همه زوري که داشت لگد محکمي به پوزه گرگ زد و دندانهايش را در دهانش ريخت و دستش را شکست. \r\nگرگ از ترس و از درد فرياد کشيد و گفت:«عجب خري هستي!» \r\nخر گفت:«عجب که ندارد، ولي مي بيني که هر ديوانه اي در کار خودش هوشيار است. تا تو باشي و ديگر هوس گوشت خر نکني!» \r\nگرگ شکست خورده ناله کنان و لنگان لنگان از آنجا فرار کرد. در راه روباهي به او برخورد و با ديدن دست شل و پوزه خونين گرگ از او پرسيد:«اي سرور عزيز، اين چه حال است و دست و صورتت چه شده، شکارچي تيرانداز کجا بود؟» \r\nگرگ گفت:«شکارچي تيرانداز نبود، من اين بلا را خودم بر سر خودم آوردم.» \r\nروباه گفت:«خودت؟ چطور؟ مگر چه کار کردي؟» \r\nگرگ گفت:«هيچي، آمدم شغلم را تغيير بدهم و اينطور شد، کار من سلاخي و قصابي بود، زرگري و آهنگري بلد نبودم ولي امروز رفتم نعلبندي کنم!»\r\n"},{"id":1088,"category_id":8,"category_code":"s8","source_id":49,"title":"پیرزن","content":"یکی بود یکی نبود، یک پیرزن بود، خانه ای داشت. به اندازه ی یک غربیل. اطاقی داشت، به اندازه یک بشقاب. درخت سنجدی داشت، به اندازه ی یک چیله جارو. یک خرده هم جل و جهاز سرهم کرده بود، که رف و طاقچه اش خشک و خالی نباشد.\r\nیک شب شامش را خورده بود که دید باد سردی می آید و تنش مور مور می شود. رختخوابش را انداخت و رفت توش، هنوز چشم به هم نگذاشته بود که دید صدای در می آید. شمع را ورداشت و رفت در را وا کرد، ‌دید یک گنجشکی است. گنجشک به پیرزن گفت: \"پیره زن امشب هوا سرد است، من هم جایی ندارم، بگذار امشب اینجا پهلوی تو، توی این خانه بمانم، صبح که آفتاب زد می پرم، می روم\". پیرزن دلش به حال گنجشک سوخت و گفت: \"خیلی خوب بیا تو و برو روی درخت سنجد، لای برگ ها، بگیر بخواب.\"\r\nگنجشکه را خواباند و خودش رفت توی رختخواب، هنوز چشمش گرم نشده بود، دید که باز در می زنند. رفت در را وا کرد، دید: یک خری است. خره گفت:\"امشب هوا سرد است، باد هم می آید، منهم جایی ندارم که سرم را بگذارم راحت بخوابم، بگذار امشب اینجا، توی خانه تو بمانم، صبح زود پیش از آن که صدای اذان از گلدسته بلند شود، من می روم بیرون\" پیر زن دلش به حال خر سوخت و گفت: \"خیلی خوب برو گوشه حیاط بگیر بخواب\". پیره زن خر را خواباند و رفت خودش هم خوابید. باز دید در می زنند، گفت: \"کیه؟\" و رفت دم در دید: یک مرغی است، مرغه گفت: \"پیرزن! امشب باد می یاد و هوا سرد است، ‌من هم راه بردار به جایی نیستم بگذار بیام امشب اینجا بخوابم، صبح زود همین که صدای خروس در آمد، پا می شم می رم.\" پیره زن گفت: \"خیلی خوب، برو کنج حیاط بگیر بخواب\". مرغ را خواباند و خودش هم رفت که بخوابد که دید دوباره صدای در می آید. آمد در را وا کرد دید: یک کلاغی است. کلاغه گفت: \"پیرزن! امشب هوا سرد است، ‌من هم جای درست و حسابی ندارم، بگذار اینجا توی خانه تو بخوابم. صبح زود، همین که مرغ ها سر از لانه درآوردند، می پرم، می روم\". گفت خیلی خوب و کلاغ را برد روی گرده خر خواباند و رفت خوابید دید باز در می زنند شمع را ور داشت. رفت دم در دید سگی است. گفت: \"چه می گویی؟\" گفت: \"امشب هوا سرد است، منهم خانه و لانه ای ندارم که پناه ببرم توش، بگذار امشب اینجا بخوابم. صبح پیش از آن که بوق حمام را بزنند پا می شوم می روم.\" پیر زن دلش به حال سگه سوخت آن را هم برد پهلوی خره خواباند و گوش شیطان کر، آمد خوابید. صبح از خواب بیدار شد، دید خانه اش غلغله ی روم است... رفت سراغ گنجشکه گفت: \"پاشو برو بیرون که صبح شد\". گنجشکه گفت: \"من که جیک جیک می کنم برات، تخم کوچیک می کنم برات، من برم بیرون؟\" گفت: \"نه تو بمان\". رفت به سراغ خره، گفت: \"زود باش، پاشو، برو بیرون، که صبح شده\". خر گفت:‌ \"من که عرعر می کنم برات، پشگل تر می کنم برات، همسایه خبر می کنم برات، من برم بیرون؟\" پیره زن گفت: \"نه تو بمان\". رفت پیش مرغه گفت: \"پاشو برو بیرون که صبح شده\" مرغه گفت:‌\"من که قد قد قدا می کنم برات، تخم بزرگ می کنم برات، من برم بیرون؟\" گفت: \"نه تو بمان\" آخر سر آمد به سراغ سگه، گفت: \"پاشو برو بیرون\". سگه گفت من که واق واق می کنم برات، ‌ذرد را بی دماغ می کنم برات، ‌من برم بیرون؟\" گفت: \"نه تو هم بمان\". همه آن جا ماندند و کارهای پیر زن را روبراه کردند و زندگیش را روی غلتک انداختند. قصه ما به سر رسید کلاغه به خونه ش نرسید.\r\n"},{"id":1089,"category_id":8,"category_code":"s8","source_id":50,"title":"دردسر خانم عنکبوته","content":"در گوشه ی حیاطی یک خانه کوچک و نقلی بود. خانه خالی بود و عنکبوت های زیادی در آن به خوبی و خوشی زندگی می کردند. کسی هم به آن ها کاری نداشت تا این که...\r\nیک روز گلی خانم آن خانه را خرید و به آنجا آمد. او داخل خانه شد. به در و دیوارها نگاه کرد. دست هایش را به کمرش زد و با صدای بلند گفت: وای ... چه گرد و خاکی! چه قدر هم تار عنکبوت! باید حسابی این جا را تمیز کنم.\r\nبعد جاروی دسته بلندش را آورد و مشغول گرد گیری شد. عنکبوت ها با وحشت این طرف و آن طرف فرار کردند. خیلی زود خانه هایشان جارو شد و از بین رفت. حتی بعضی از عنکبوت ها هم همراه خانه هایشان از بین رفتند.\r\nدر میان عنکبوت ها خانم عنکبوتی بود به نام نقره. او هم دختر کوچکش را به روی پشتش گذاشت و با عجله به گوشه ی تاریکی رفت.\r\nگلی خانم دست بردار نبود. هر روز صبح جارو را به دست می گرفت و خانه را گردگیری می کرد. اگر کوچک ترین تار عنکبوتی می دید آن را جارو می کرد. یک هفته گذشت، نقره صبرش تمام شد. فریاد زد: خسته شدم، این دیگر چه وضعی است؟ هر جا خانه می سازم این زن آن را جارو می کند.\r\nهر روز یک خانه. از خستگی دارم می میرم. از بس تار تنیدم، هلاک شدم. بعد به هفتمین تار عنکبوتی که درست کرده بود، نگاه کرد و گفت: چه خانه قشنگی! چه تارهای زیبا و براقی، چرا این خانه های زیبا را جارو می کند؟ بعد دخترش را پشتش گذاشت و گفت: من که می روم. اینجا دیگر جای عنکبوت ها نیست.\r\nعنکبوت هایی که در گوشه و کنار مخفی شده بودند، فریاد زدند: ترسو... ترسو. تو خیلی ترسویی. ما عنکبوت ها نباید بترسیم. هر چه قدر خانه مان خراب شد، باز هم باید خانه بسازیم. نقره به طرف در رفت و گفت: من دیگر خسته شدم. نمی توانم هر روز یک خانه بسازم.\r\nدر این موقع گلی خانم با جاروی دسته بلندش وارد اتاق شد. نقره با عجله از خانه بیرون رفت و گفت: دیگر به حرف این عنکبوت ها گوش نمی کنم. به یک خانه ی راحت احتیاج دارم.\r\nاو راهش را گرفت و رفت. رفت و رفت تا به انباری گوشه ی حیاط رسید. در یک طرف انباری، درخت گیلاسی بود. نقره به دیوار چوبی انباری نگاهی کرد، بعد هم به درخت گیلاس. آن وقت گفت: یک جای عالی برای یک خانه ی تار عنکبوتی.\r\nبعد به آن جا رفت و مشغول تار تنیدن شد. خیلی زود یک خانه ی تار عنکبوتی بزرگ و زیبا بین دیوار انباری و درخت گیلاس درست شد. نقره دختر کوچولویش را روی تار خواباند و گفت: راحت شدیم حالا دیگر هر وقت چشم هایمان را روی هم می گذاریم، خواب جارو را نمی بینیم.\r\nبعد روی تاری نشست. به درخت ها و خانه ها نگاه کرد. گلی خانم باز هم مشغول گردگیری بود. چند روز گذشت . یک روز صبح نقره با صدای عجیبی از خواب بیدار شد. با وحشت به دور و بر نگاه کرد صدا از طرف خانه ی گلی خانم می آمد. او با یک جارو برقی بزرگ مشغول گردگیری بود. نقره با دقت نگاه کرد. او می دید که آن دستگاه عجیب چه طور همه ی آشغال ها و گردو خاک ها را می بلعد. نقره با دست و پاهایش به سرش کوبید و گفت: و اااای. این دیگر چیست؟ عنکبوت های بیچاره دیگر راه فراری ندارند.\r\nدر داخل خانه عنکبوت ها از هر طرف می دویدند و لوله ی جاروبرقی به دنبالشان بود. ولی بعضی ها توانستند فرار کنند و خودشان را به خارج از خانه برسانند. عنکبوت هایی که نجات پیدا کرده بودند از ترس می لرزیدند. خانم عنکبوته به آنجا رفت همه را دلداری داد. آنها را به خانه شان دعوت کرد.\r\nعنکبوت ها به خانه ی خانم عنکبوته رفتند. مدتی در آن جا استراحت کردند. کم کم حالشان بهتر شد. خانم عنکبوته گفت: حالا فهمیدید که کار من درست بود؟\r\nعنکبوت سیاه سرش را تکان داد و گفت: بله. حق با تو بود. نباید آن قدر اصرار و لجبازی می کردیم. چند روز بعد دور و بر انباری و درخت گیلاس پر از تارهای زیبا و براق عنکبوت ها شده بود.\r\n"},{"id":1090,"category_id":8,"category_code":"s8","source_id":51,"title":"الاغ آواز خوان","content":"روزی روزگاری در دهكده ی كوچك ، آسیابانی بود كه الاغی داشت . سالها الاغ برای آسیابان كار كرده بود و بارهای سنگین را از اینجا به آنجا برده بود . ولی حالا پیر شده و نمی توانست بار بكشد .روزی از روزها آسیابان الاغ را از خانه اش بیرون كرد و گفت : « برو هر جا كه دلت می خواهد . من دیگر علف مفت به تو نمی دهم .» الاغ بیچاره تا شب این طرف و ان طرف رفت . دیگر خسته و گرسنه شده بود با خود گفت : « باید از اینجا بروم و برای خودم چیزی پیدا كنم و بخورم »\r\nالاغ از دهكده بیرون رفت . از آسیابان و آسیابش دور شد . كنار درخت پیری رسید كه شاخه هایش شكسته بود و چند شاخه تازه از روی تنه اش جوانه زده بود .كنار درخت پر از علهای سبز و تازه بود . الاغ گرسنه تا انجا كه شكمش جا داشت علف خورد و سیر شد بعد با خود گفت : « زیاد بد هم نشد . حالا دیگر بار نمی برم و منت آسیابان نمی كشم »و راه افتاد و رفت و رفت تا اینكه چشمش به سگی افتاد كه تنها و غمگین كنار جاده نشسته بود . الاغ گفت : « سلام دوست من چرا تنها نشسته ای ؟، چرا این قدر غمگین و ناراحتی؟ »سگ اهی كشید و گفت : « دست به دلم نگذار كه خیلی ناراحتم !» الاغ پرسید : «آخر برای چی ؟»\r\n\r\nسگ گفت : «سالهای سال برای صاحبم كار كردم . همراهش می رفتم آن قدر این طرف و ان طرف می دویدم كه خسته و كوفته به خانه بر می گشتم . اما دیروز که ما به شكار رفته بودیم . گرگی سر راهمان را گرفت و من كه پیر شده ام نتوانستم جلویش بایستم و با او بجنگم . صاحبم كه از گرگ ترسیده بود ، همه تقصیرها را گردن من انداخت و امروز مرا از خانه اش بیرون كرد و گفت : « برو هر جا دلت می خواهد . من با تو كاری ندارم .» من هم امدم بیرون . حالا نمی دانم كجا بروم و چه خاكی به سرم كنم .»الاغ گفت : « غصه نخور كه خدا بزرگ است و كسی را بی پناه نمی گذارد . بیا دو تایی برویم ، جای مناسبی پیدا كنیم و زندگی كنیم .»\r\nانها راه افتادند . رفتند و رفتند ، تا رسیدند به گربه ای كه تنها و غمگین روی كنده درختی نشسته بود . نزدیك گربه كه رسیدند، سلام كردند . الاغ پرسید «چی شده ؟ جرا این قدر غمگینی ؟ »گربه گفت : « باید غمگین باشم . سالها در خانه صاحبم موش گرفتم و خدمت كردم . ولی حالا كه پیر شده ام ، او گربه دیگری اورده و مرا از خانه بیرون انداخته است . می گویید غمگین نباشم ؟»\r\nالاغ گفت : « ما هم مثل تو هستیم . بیا با هم برویم ، ببینیم خدا چه می خواهد ؟ »\r\nگربه هم قبول كرد و دنبال انها راه افتاد تا بروند و جای خوبی برای زندگی پیدا كنند .\r\nآنها رفتند و رفتند تا به خروسی رسیدند . خروس روی سر در خانه ای ایستاده بود و با صدای غمگینی قوقولی قوقو می كرد . الاغ جلو رفت ، سلام كرد و گفت : «خروس جان ، چه مشكلی داری كه این قدر غمگین اواز می خوانی ؟»\r\nخروس گفت : روزگاری من سحرخیز ترین خروس آبادی بودم . هر شب سحر بیدار میشدم و آنقدر آواز می خواندم که همه را بیدار می کردم . اما حالاپیر شده ام و گاهی خواب می مانم صاحبم می خواهد سر من را ببرد و گوشتم را بپزد و بخورد . \r\nالغ گفت : « ممکن است تو پیر شده باشی و نتوانی سحر بیدار شوی . ولی هنوز صدایت زیبا و خوش اهنگ است . می توانی از این صدا استفاده كنی با ما بیا . می رویم جای مناسبی پیدا می كنیم و به خوشی روزگار می گذرانیم .\r\n"},{"id":1091,"category_id":8,"category_code":"s8","source_id":52,"title":"اسباب بازی","content":"وودی گاوچران ، اسباب بازی محبوب اندی بود . او به همراه اسلینکی ( سگ عروسکی ) ، رکس ( دایناسور ) ، پوتیتوهد ( کله سیب زمینی ) ، خوکی به نام ( هم ) و سایر اسباب بازیها در اتاق خواب اندی زندگی می کردند . این اسباب بازیها استثنایی بودند . آنها وقتیکه هیچکس در اطرافشان نبود ، جان می گرفتند . یک روز وودی همه اسباب بازیها را صدا زد و به آنها گفت : اندی و خانواده اش به زودی اسباب کشی می کنند و به همین دلیل است که اندی امروز تولدش را جشن می گیرد . اسباب بازیها نگران شدند . جشن تولد برای آنها ، به معنی ورود اسباب بازیهای جدید بود . چه اتفاقی می افتاد اگر اندی اسباب بازیهای جدیدش را بیشتر از آنها دوست می داشت ؟ رکس با ناراحتی گفت : یکی از ما ممکن است کنار گذاشته شود وودی قول داد که جای هیچ نگرانی نیست چون اندی این کار را نخواهد کرد . اسباب بازیها با دلهره منتظر بودند تا اندی کادوهایش را باز کند .\r\nهمه چیز خوب پیش رفت با اینکه آخرین بسته باز شد . آن یک فضانورد جالب بود . اندی اسباب بازی را به اتاق خوابش در طبقه دوم برد و در آنجا گذاشت سپس از اتاق بیرون رفت . تازه وارد چراغهای روی بالش را روشن کرد و گفت : من بازلایت یر پلیس فضا هستم . همه فکر کردند که باز باید اسباب بازی جالبی باشد البته همه به جز وودی . او به باز حسادت می کرد . وود ی با تمسخر گفت تو پلیس فضایی نیستی ، تو هم مثل بقیه ما یک اسباب بازی هستی . ناگهای اسباب بازیها صدای پارس کردن سگی را از بیرون شنیدند و با شتاب به طرف پنجره دویدند . سید – پسر همسایه – داشت یک سرباز اسباب بازی را خراب می کرد و اسکاد – سگ سید – با اشتیاق آنها را تماشا می کرد .\r\nاسباب بازیها بدون اینکه کمکی از دستشان برآید ، سید را نگاه می کردند که در حال خراب کردن سرباز بود . اسباب بازیها سرجایشان بازگشتند . اما وودی هنوز هم از دست باز عصبانی بود . او فکر می کرد که اگر ماشین کنترل از راه دور را به طرف باز هدایت کند ، اسباب بازی جدید پشت میز می افتد و گم می شود . ماشین با سرعت خیلی زیاد حرکت کرد و همه چیز خراب شد و باز به بیرون از پنجره افتاد وودی گفت این یک اتفاق بود . ولی هیچ یک از اسباب بازیها حرف او را باور نکردند . در همان موقع اندی وارد اتاق شد و یکراست به طرف باز رفت . او داشت به پیتزا فروشی سیاره می رفت و می خواست باز را با خودش ببرد . اندی مادرش را صدا زد و گفت : نمی توانم باز را پیدا کنم . به جای باز وودی را می آورم . اما باز به همراه آنها رفت ! او به داخل بوته ها افتاده بود و هنگامی که اتومبیل در حال حرکت بود ، پرید و به سپر آن آویزان شد . در پیتزا فروشی وسایل بازی متنوعی وجود داشت . باز فکر کرد که یکی از آنها ، سفینه ی فضایی واقعی است .\r\nوودی هم به دنبال او به درون سفینه رفت . داخل سفینه پر از اسباب بازیهای فضایی عجیب و غریب بود که به وسیله چنگک بیرون آورده می شدند . وودی و باز به شدت ترسیدند وقتیکه دیدند پسری که قرار است آنها را بدست بیاورد ، کسی جز سید – همسایه ی شرور اندی – نیست . سید آنها را به اتاق خوابش برد . وودی و باز وحشت زده بودند . آنها توسط یک دسته اسباب بازی که خیلی عجیب بودند محاصره شدند . سید آنها را از تکه های شکسته شده اسباب بازیها درست کرده بود . اسباب بازیها به وودی و باز نزدیکو نزدیک تر شدند . وودی از ترس فریاد زد : جلو نیایید شما خطرناک هستید . باز زود باش ، باید هر چه زود تر از اینجا برویم . هر دو پا به فرار گذاشتند .\r\nدر آن هنگام باز صدایی شنید که می گفت : باز پیغام را دریافت کن . از مرکز فرماندهی است . باز وودی را که درون قفسه کمد پنهان شده بود رها کرد و به طرف صدا دوید . اما آن صدا فقط آگهی تلویزیونی برای تبلیغ اسباب بازی باز بود . باز گیج شده بود و با خودش زیر لب گف : این حقیقت داره ؟ آیا من واقعا یک اسباب بازی هستم . باز می خواست ثابت کند که یک پلیس فضایی واقعی است . بنابراین سعی کرد پرواز کند ولی به زمین اصابت کرد و بازویش شکست وودی باز را پیدا کرد و در همان موقع چشمش به بیرون از پنجره اتاق سید افتاد . او دوستانش را در اتاق اندی دید و باز را به اتاق سید برگرداند . وودی با صدای بلند گفت : آهای دوستان ! کمک . او به شدت دست تکان داد . اما اسباب بازیها از دست وودی عصبانی بودند . آنها فکر می کردند او به باز آسیب رسانده است .\r\nدر همان لحظه کله سیب زمینی فریاد زد : قاتل ، و سپس سگ عروسکی کرکره را پایین کشید . وودی با ناراحتی از پشت پنجره کنار رفت . به نطر می رسید که وودی و باز در خانه سید زندانی شده بودند . خوشبختانه بعد از آن همه اتفاق ، اسباب بازیهای سید با آنها دوست شدند و همان شب بازوی باز را تعمیر کردند . بعد از چند لحظه سید وارد اتاق شد و باز را برداشت و یک موشک بزرگ به پشتش بست . او با خنده ناخوشایندی گفت : می خواهم غافلگیرت کنم فردا تو را به فضای بیکران می فرستم . آن شب باز ناراحت و دلگیر بود . او به وودی گفت : حق با تو بود ، من پلیس فضایی نیستم . من فقط یک اسباب بازی هستم . وودی گفت : اما همین اسباب بازی بودنت باعث شده تو استثنایی باشی . تو اسباب بازی اندی هستی و او فکر می کند که تو بی نظیری . اندی به ما احتیاج دارد و ما باید پیش او برگردیم . باز دقایقی فکر کرد و گفت حق با توست . بیا برویم .\r\nولی دیر شده بود . زنگ ساعت سید به صدا در آمد . سید خودش را به باز رساند آن را برداشت و گفت : حالا وقتشه فضانورد . او با شتاب به طبقه پایین روفت و به سمت حیاط دوید و شروع به ساختن سکوی پرتاب موشک کرد . وودی به طرف اسباب بازیهای سید رفت و از آنها کمک خواست . او با التماس گفت : لطفا کمکم کنید تا باز را نجات بدهم باز دوست منه . اسباب بازیها به وودی لبخند شدند و سرشان را به نشانه ی مثبت تکان دادند . همگی با هم نقشه کشیدند تا باز را نجات دهند . بیرون از خانه توی حیاط سید آماده روشن کردن فتیله ی موشک بود و معکوس می شمرد . ده ، نه ، هشت ، ... که ناگهان متوجه وودی شد و او را برداشت . در همان لحظه تمام اسباب بازیها سینه خیز به طرف سید آمدند و محاصره اش کردند . سپس وودی شروع به صحبت کرد .\r\nسید جیغ کشید و گفت : وای کمک ! این اسباب بازیها زنده اند . و فریاد زنان به طرف خانه دوید . وودی و باز آزاد شدند آنها از اسباب بازیها به خاطر کمکشان تشکر کردند و به طرف خانه به راه افتادند . باز نفس زنان گفت : امروز روز اسباب کشی است . وودی گفت : عجله کن . باید خودمان را به آنها برسانیم . آندو با عجله به دنبال کامیون دویدند . باز موفق شد که از سپر عقب کامیون بالا برود اما اسکاد – سگ سید – که در تعقیب آنها بود ، پای وودی را گرفت . وودی فریاد زد : دور شو ! او سعی می کرد خودش را نجات بدهد . اسکاد فقط خرناس می کشید . باز شجاعانه از سپر پایین پرید و اسکاد را فراری داد . در نتیجه سگ به خانه اش باز گشت .\r\nاما حالا وودی روی سپر کامیون و باز تنها و درمانده توی خیابان بود . وودی با زحمت فراوان خودش را به داخل کامیون رساند و جعبه اسباب بازیهای اندی را پیدا کرد . اسباب بازیها از دیدن وودی تعجب کردند . وودی به آنها گفت : باز اون بیرون وسط خیابونه به دردسر افتاده . ما باید به باز کمک کنیم . سپس ماشین کنترل از راه دور را برداشت و به سمت باز هدایت کرد کله سیب زمینی با صدای بلند گفت : آهای ! وودی می خواهد از شر ما خلاص شود . درست همان کاری که با باز کرد ! زود باشید بگیریمش . اسباب بازیها در حالیکه با عصبانیت فریاد می کشیدند ، وودی را از داخل کامیون به بیرون پرتاپ کردند . اما لحظاتی بعد دیدند وودی و باز سوار بر ماشین کنترل از راه دور به دنبال آنها در حرکتند عصبانیتشان به حیرت تبدیل شد .\r\nرکس دایناسور گفت : نگاه کنید ! آنها با هم هستند . پس وودی داشت راست می گفت . سرعت ماشین کمتر و کمتر و سپس متوقف شد . باز آهی کشید و گفت : باتری ها خالی شدند . از شانس بد وودی و باز ، کامیون با فاصله ی زیاد از جلوی چشم آنها ناپدید شد . ناگهان باز چیزی به خاطر آورد و گفت : وودی موشک! موشک سید هنوز به پشت باز وصل بود . آنها فتیله ی موشک را روشن کردند و موشک آنها را به آسمان برد . قبل از انفجار موشک باز دکمه روی سینه اش را فشار داد . بالهایش باز شد و از موشک جدا شدند . آنها بر فراز کامیون پرواز کردند . وودی خندید و گفت : ما داریم پرواز می کنیم . دقایقی بعد در داخل ماشین اندی فرود آمدند . وودی و باز نجات پیدا کردند و نزد پسری بازگشتند که آنها را دوست می داشت .\r\n\r\nبعد از همه ی این کاجراها ، وودی و باز دوستانی بسیار صمیمی شدند . وودی به هیچ وجه به باز حسادت نمی کرد و باز فضانورد هم خوشحال بود که مثل بقیه یک اسباب بازی است . آنها همگی با هم در خانه جدید ساکن شدند و چند ماه را به خوبی و خوشی سپری کردند تا اینکه کریسمس از راه رسید به شدت برف می بارید اندی برای باز کردن کادوی قشنگ کریسمس با شتاب به طبقه ی پایین رفت . بار دیگر اسباب بازیها منتظر ورود اسباب بازی جدیدی شدند . وودی از باز پرسید نگرانی ؟ باز جواب داد : نه ، تو چطور ؟ وودی بات شوخی و خنده گفت : باز ! بگو ببینم ممکنه اندی کادویی بدتر از تو بگیره ؟ با شنیدن صدای واق واق ، جواب سوال داده شد . اسباب بازیها خندیدند و گفتند : وای یه توله سگ !\r\n\r\nخروس هم قبول كرد و دنبال انها راه افتاد .كم كم هوا تاریك شد و انها مجبور شدند كنار درختی توقف كنند . سگ و الاغ كنار درخت خوابیدند . اما گربه و خروس رفتند بالای درخت و روش شاخه های ان نشستند . از گرسنگی خوابشان نمی برد و دور بر را نگاه می كردند ناگهان خروس گفت : « من از دور نوری را می بینم . انگار كلبه ای است بیاید برویم انجا شاید چیزی پیدا كنیم و بخوریم . » الاغ و سگ هم قبول كردند و دوباره راه افتادند رفتند و رفتند تا به كلبه رسیدند از پشت پنجره ان به داخل نگاه كردند روی میز غذاهای زیادی بود و چهار مرد دور میز نشسته بودند و غذا می خوردند . كنار دست انها هم سكه های طلا جمع بود . الاغ گفت : « اینها دزد هستند باید این دزدها را از كلبه بیرون كنیم » خروس به داخل كلبه نگاهی كرد و گفت : انها چهار نفر مرد قوی هیكل هستند ، چطوری می خواهی انها را بیرون كنیم ؟\r\n\r\nگربه گفت : راست می گید ، انها خیلی قوی هستند . قیافه هایشان را نگاه كن . ما چی ؟ خسته و گرسنه!.سگ از خستگی چرت می زد . اما الاغ در فكر بود . داشت نقشه ای می كشید الاغ می دانست كه با فكر می توان بر زور بازو پیروز شد . پس باید فكر می كرد و نقشه خوبی می كشید .الاغ دوستانش را به كناری برد و نقشه اش را برای انها گفت . همه تعجب كردند . نقشه خوبی بود . باید زودتر دست به كار می شدند .آنها آهسته جلو رفتند و الاغ دو پای جلویش را بالا اورد و گذاشت لب پنجره . سگ پرید به پشت الاغ و انجا ایستاد بعد نوبت گربه بود . او پرید بالا و روی پشت سگ ایستاد . حالا فقط خروس مانده بود . او هم پرید روی پشت گربه. سایه حیوانها افتاد داخل اتاق . سایه مثل یك غول بزرگ و ترسناك بود . دزدها با دیدن این غول به وحشت افتادند .\r\n\r\nدر همین لحظه حیوانها شروع كردند به سرو صدا كردن . صدایشان در هم پیچید و صدای وحشتناكی ایجاد كرد و دزدها بیشتر ترسیدند و وحشتزده پا به فرار گذاشتند . ان قدر ترسید بودند كه حتی سكه هایشان را هم جا گذاشتند با فرار كردن دزدها ، چهار دوست از شادی فریاد كشیدند :« زنده باد ما برنده شدیم . دزدها فرار كردند.»همه به فكر الاغ آفرین گفتند و رفتند داخل خانه . دور میز نشستند و مشغول خوردن شدند . گربه همان طور كه ماهی را به دندان می كشید ، گفت :« نقشه ات عالی بود الاغ جان !» خروس هم دانه ذرتش را قورت داد و گفت « من فكر نمی كردم این قدر زود موفق شویم !»الاغ گفت : «نقشه من خوب بود اما كمك شما هم خیلی مؤثر بود . اگر همیشه با هم باشیم در هر كاری موفق می شویم با هم بودن خیلی مهم است تنها هیچ كاری نمی شود كرد .\r\n\r\nو اما بشنوید از دزدها . انها رفتند و رفتند و كنار درختی ایستادند . سردسته دزدها گفت : « ماخیلی زود ترسیدیم و فرار كردیم باید برگردیم و با ان غول بجنگیم . غول كه ترس ندارد .» سردسته رو به یكی از دزدها كرد و ئگفت : « ما اینجا می مانیم . تو برو سرو گوشی اب بده شاید بتوانی سكه ها را با خودت بیاوری . شاید هم توانستی غول را از پا در اوری .»دزد بیچاره می ترسید و نمی خواست قبول كند . اما ان قدر به او اصرار كردند كه قبول كرد و راه افتاد امد طرف كلبه . دزد اهسته آهسته داخل كلبه شد . همه جا تاریك بود و چیزی دیده نمی شد وقتی نزدیك بخاری رسید ، دوتا شعله كوچك داخل بخاری به چشمش خورد . فكر كرد اتش بخاری است . خواست كبریتی را روشن كند . \r\n"},{"id":1092,"category_id":8,"category_code":"s8","source_id":53,"title":"درهایی که به شنا می روند","content":"آن ها قبل از تاریک شدن هوا به خانه برگشتند. اما دیدند که هیچ کدام از وسایل خانه سر جایش نیست.\r\nدزد، تمام اسباب ها را برده بود. دَرِ آشپزخانه گفت: « حالا چه کار کنیم؟ هیچ غذای خوشمزه ای نمی تواند جای وسایل خانه را برای صاحب خانه بگیرد. » \r\nدو تا دَرِ اتاق خواب که خیلی خسته بودند گفتند: « اول کمی بخوابیم. بیدار که شدیم یک فکری می کنیم. » دَرِ دستشویی گفت: « این بوگندوترین اتفاقی است که ممکن است برای کسی بیفتد. » دَرِ اتاق کتابخانه گفت: « بی فکری کردیم. باید قبل از رفتن، حساب همه چیز را می کردیم. »\r\nدَرِ ورودی گفت: « صاحب خانه ای که از در خارج می شود باید فکرش را هم بکند که کس دیگری ممکن است وارد خانه شود. »\r\nکمی گذشت و صاحب خانه از مسافرت برگشت و وقتی خانه اش را خالی دید هاج و واج شد. دزد حتی یک قوطی کبریت هم توی خانه باقی نگذاشته بود. صاحب خانه با خودش گفت: « چه دزد بی انصافی! » و آه کشید. همین موقع چشمش به یکی از سه دَرِ اتاق خواب افتاد.دَرِ اتاق خواب خیس بود. همان طور که شش دَرِ دیگر هم خیس بودند. صاحب خانه با تعجب گفت: « دارید گریه می کنید!؟ عیبی ندارد. شما که مقصر نیستید. مقصر، دزد است که همیشه در کمین یک خانه ی خالی است. »\r\nآن شب، صاحب خانه روی زمین خوابید. روز بعد هم وسایل تازه ای خرید. چند روز گذشت. صاحب خانه دوباره به سفر رفت و درها باز هم هوس شنا کردند. دَرِ کتابخانه گفت: « یادتان رفته دفعه ی قبل چه اتفاقی افتاد؟ من که نمی آیم! »\r\nدَرِ دستشویی گفت: « چه تهدید بوگندویی! باشد من هم نمی روم. »\r\nبه این ترتیب درها ماندند و از خانه مواظبت کردند. یک شب، درها سر و صدایی شنیدند. صدای پای دزد بود. دزد وارد شد و از دیدن آن همه وسایل نو، خنده ای کرد و دست به کار شد. \r\nاما وقتی توی اتاق کتابخانه رفت، دَرِ اتاق، محکم خودش را بست. درهای دیگر برایش دست زدند و به او آفرین گفتند. دزد هر کاری کرد نتوانست در را باز کند و برود.\r\nدزد تا برگشتن صاحب خانه توی اتاق کتابخانه زندانی بود. وقتی صاحب خانه برگشت و دزد را دید، قبل از هر کاری از درها تشکر کرد که مواظب خانه اش بوده اند. بعد هم دزد را به شرطی آزاد کرد که وسایلی را که بار قبل دزدیده بود پس بدهد. و خب مگر دزد با آن همه در که منتظر جوابش بودند چاره ی دیگری هم داشت!؟\r\nاما همینكه دزد بیچاره كبریت را نزدیك شعله ها برد ، گربه بود. دزد فریاد زد :« وای سوختم .آی كمك!» دزد فرار كرد ،اما پشت در پایش را روی دم سگ گذاشت . سگ هم بیدار شد و پای دزد را به دندان گرفت از درد باز فریاد دیگر زد و به حیاط دوید . اما گوشه حیاط الاغ خوابیده بود او هم بیدار شد و عصبانی لگد محكمی به دزد زد . لگد الاغ آن قدر محكم بود كه دزد چند متر آن طرف تر پرت شد دزد از وحشت فریاد می زد ئو كمك می خواست . می گفت : « به دادم برسید ! غولها دارند مرا می كشند .»\r\nخروس كه روی پشت بام خوابیده بود بیدار شد و از ان بالا روی سر دزد و با نوك تیزش به جان دزد افتاد دزد پا به فرار گذاشت وقتی به دوستانش رسید ، گفت : «آنجا خانه غولهاست . ما دیگر به ان خانه ترسناك نمی رویم من كه پا به انجا نمی گذارم . به این ترتیب دزدها رفتند و خانه شد مال حیوانها . انها دور هم جمع شدند و روزگار خوشی را آغاز كردند همه كار می كردند و غذا تهیه می كرردند و شب دور هم جمع می شدند و با خوشی می گفتند و می خندیدند انها در ان كلبه جنگلی چه روزگار خوشی داشتند !\r\n"},{"id":1093,"category_id":8,"category_code":"s8","source_id":54,"title":"دم قشنگ","content":"\r\nیکی بود یکی نبود غیراز خدا هیچ کس نبود\r\nروزی روزگاری روباهی در جنگل بلوط زندگی می کرد. او دم خیلی قشنگی داشت، برای همین دوستاش به او دم قشنگ می گفتند. دم قشنگ روزها در میان دشت و صحرا می گشت و خرگوش و پرنده شکار می کرد و می خورد و وقتی سیر میشد به جنگل بلوط بر می گشت و توی لونه اش استراحت می کرد. یه روز دم قشنگ چندتا کبک خوشمزه شکار کرد و خورد و حسابی سیر شد.اوخوشحال بود و برای خودش آواز می خوند:\r\nیه کبک خوردم یه تیهو\r\nدویدم مثل آهو\r\n\r\nدمم خیلی قشنگه\r\nقشنگه رنگ وارنگه\r\n\r\nلای لای لالا لالایی\r\nهمه میگن بلایی\r\n\r\nهمه میگن یه روباه\r\nروباه ناقلایی\r\n\r\nلای لای لالا لالایی\r\n\r\nاون آواز می خوند و به طرف لونه اش می رفت که به یک درخت بلوط که داخل تنه ش سوراخ بود رسید.بوی غذا از داخل تنه ی درخت به مشامش رسید. هیزم شکن هایی که همون نزدیکی کار می کردند، ناهارشون را که نون و گوشت بود، داخل تنه ی درخت گذاشته بودند. دم قشنگ که روباه شکمویی بود، داخل تنه ی درخت رفت و هرچه غذا اونجا بود خورد،اون قدر خورد و خورد تا شکمش باد کرد. وقتی خواست از تنه ی درخت خارج بشه، نتونست چون شکمش حسابی باد کرده و گنده شده بود و توی سوراخ گیر می کرد.\r\nدم قشنگ شروع به گریه و زاری کرد. صدای ناله هاش به گوش دوستش زیرک رسید.زیرک، روباه زرنگ و دانایی بود.وقتی دید دم قشنگ توی تنه ی درخت گیر کرده، فکری کرد و گفت:« دوست شکموی من، کمی صبرکن تا غذات هضم بشه و شکمت کوچیک بشه، اونوقت می تونی از تنه ی درخت بیرون بیایی.آخه گذشت زمان بعضی از مشکلات را حل می کنه.نگران نباش، فقط حوصله داشته باش.»\r\nدم قشنگ به حرفای زیرک خوب گوش داد.اون چاره ی دیگه ای نداشت، باید صبر می کرد تا غذاش هضم بشه و شکمش کوچیک بشه و اندازه ی اولش بشه و بتونه بیرون بیاد. فقط دعا می کرد هیزم شکنا به این زودی برنگردند و اونو تو این وضعیت نبینند.\r\nخوشبختانه شکمش زود کوچیک شد و تونست از تنه ی درخت خارج بشه. اون دوتا پا داشت، دوتا هم قرض کرد و از اونجا فرار کرد و به لونه ش رفت و خوابید. از اون روز به بعد، دم قشنگ دیگه بی احتیاطی نکرد و توی هر سوراخی وارد نشد و دست از شکم پرستی برداشت. آخه می ترسید بازم تو یه سوراخ گیرکنه و نتونه از اون بیرون بیاد!\r\n\r\nقصه ی ما به سر رسید کلاغه به خونه ش نرسید.\r\n"},{"id":1094,"category_id":8,"category_code":"s8","source_id":55,"title":"کرمولک","content":"یکي بود یکی نبود، کرمولک کوچولوی قصه ما با پدرو مادرش در باغچه کوچولوی حیاط خانه‌ای زندگی می‌کرد. کرمولک دوستان زیادی داشت که هرروز باهم در این باغچه زیبا بازی می‌کردند. کرمولک قصه ما خیلی بچه خوبی بود اما خودش همیشه فکر می‌کرد که نمی‌تواند کارهای بزرگ را درست انجام دهد. او همیشه نگران بود که اگر اتفاق بدی بيفتد او توانایی هیچ کاری را ندارد. \r\nاو همیشه دوست داشت خیلی شجاع باشد و همیشه در رویا‌هایش خودش را خیلی قوی می‌دید ولی در واقعیت این‌طور نبود!\r\nکرم کوچولوی قصه ما هر وقت تنها می‌شد با خودش فکر می‌کرد که ‌ای کاش بتواند شجاع باشد ولی نمی‌توانست این شجاعت را نشان بدهد. گاهی که با دوستانش دور هم جمع می‌شدند واز کارهایی که می‌توانستند انجام دهند تعریف می‌کردند، کرمولک چون با خودش فکر می‌کرد نمی‌تواند کاری را درست انجام دهد ساکت می‌ماند ودوستانش همیشه فکر می‌کردند که او یا خجالتی است یا ترسو و این باعث می‌شد کرمولک غصه بخورد. \r\n\r\nیک شب کرمولک قصه ما با غصه این‌که او هرگز نمی‌تواند کار بزرگی را درست انجام دهد به خواب رفت ولی از شدت ناراحتی از خواب پرید ودید که مادرش در کنار اونشسته وبه آرامی اورا نوازش می‌کند. مادرش علت پریشانی‌اش را پرسید و کرمولک هم به او توضیح داد که خیلی دوست دارد بتواند کارهای بزرگی را خودش به تنهایی انجام دهد ولی نمی‌تواند واین باعث شده تا دوستانش کمی به او بخندند... \r\n\r\nمادر کرمولک به او گفت: «عزیزم، اتفاقا تو توانایی‌هایی داری که شاید دیگران نداشته باشند و با استفاده از این توانایی‌ها می‌توانی کارهایی انجام بدهی که خیلی بزرگ ومفید باشند، مثلا این خیلی خوب است که تو در مورد مشکلی که احساس می‌کنی وجود دارد فکر می‌کنی ودوست داری آن را حل کنی.» \r\n\r\nکرمولک کمی در تخت خوابش این طرف و آن طرف کرد و فکر کرد تا این‌که فکری به خاطرش رسید. او به یاد آورد که پدرش همیشه می‌گوید با تمرین کردن کارهای سخت راحت می‌شود! پس لبخندی زد و باآرامش به خواب رفت. از فردای آن روز کرمولک در وقت تنهایی به جای این‌که به این فکر کند که هرگز کاری را درست انجام نمی‌دهد، تمرین می‌کرد تا بتواند از توانایی‌هایش استفاده کند. ورزش می‌کرد، به مادرش کمک می‌کرد، کار‌هایش را با دقت و به تنهایی انجام می‌داد. \r\n\r\nکم کم دیگر آن احساس بد را نداشت و می‌توانست باور کند که می‌تواند، تا این‌که در یک روز بارانی یک چاله کوچک آب در باغچه جمع شده بود. بعد از باران بچه‌ها به دیدن رنگین کمان آمدند و خواستند کمی بازی کنند که یک دفعه موش کوچولو یکی از دوستان کرمولک که همیشه تند‌تر از همه حرکت می‌کرد، افتاد داخل چاله. كرم همه‌اش تکان می‌خورد چون نمی‌توانست از آن بیرون بیاید. همه جا گلی ولیز بود و همه بچه‌ها ترسیده بودند. در همین حال بود که کرمولک فکری به ذهنش رسید و سریع رفت یک شاخه کوچک ونازک چوب پیدا کرد وبا شجاعت به چاله نزدیک شد واز دوستش خواست تا شاخه را بگیرد وآرام آرام بیرون بیاید. بعد از این‌که کرمولک دوستش را از چاله بیرون آورد تمام دوستانش برایش هورا کشیدند و همه به او می‌گفتند: «کرمولک قهرمان!» \r\n\r\nکرمولک خیلی خوشحال بود که توانسته بود کار بزرگی را به درستی انجام دهد و به یاد تصمیم مهمی که آن شب گرفته بود افتاد که باید تمرین کند تا از توانایی‌هایش درست استفاده کند. پس زودی به خانه رفت وماجرا را به مادرش گفت، مادر کرمولک او را بوسید و به او آفرین گفت، چون کرمولک فکر خیلی خوبی کرده بود وتوانسته بود مشکلش را حل کند. پس او حالا هم توانایی خوب فکر کردن را داشت و هم کمک کردن به دوستانش. کرمولک کوچولوآن شب خواب خوشی کرد.\r\n"},{"id":1095,"category_id":8,"category_code":"s8","source_id":56,"title":"دندان خرگوش","content":"یکی بود یکی نبود غیر از خدا هیچ کس نبود در یک جنگل زیبا یک خرگوش بازیگوش بود که خیلی هویج دوست داشت .خرگوش کوچولو هویجاشو زیر بالشش می گذاشت . صبح که می شد یک هویج بر می داشت و می خورد .یک روز یک هویج بزرگ برداشت تا اومد گاز بزند دندونش لق شد.\r\nخرگوش کوچولو خیلی ترسید دویدو رفت پیشه آقا بزه آخه آقا بزه دکتر جنگل بود. آقا بزه گفت بشین تا دندونتو برات بکشم تا اومد وسایلش و بیار خرگوش کوچولو ترسید و سریع بلند شد و رفت . خرگوش رفت پیشه آقا فیل و داستان و برای فیل تعریف کرد. آقا فیل گفت من یک راهی بلدم تا دندونتو بکشم آقا فیل یک نخ آوردو وصل کرد به دندان خرگوش یک سردیگر نخ هم که می خواست به در خونه وصل کنه خر گوش ترسید و نگذاشت و دوید و رفت. خرگوش خیلی ناراحت بود. رفت و روی سنگی نشست به هویج تو دستش نگاهی کرد و یه گاز زد وقتی هویج و درآورد دندونش و روی هویج دید.\r\n\r\nخرگوش کوچولو خیلی خوشحال شد که راحت شده بودو با خوشحالی رفت و با بقیه شروع به بازی کرد.\r\n"},{"id":1096,"category_id":8,"category_code":"s8","source_id":57,"title":"هاله و هیولا","content":"هاله کوچولو می‌ترسید شب‌ها تنهایی توی اتاق خودش بخوابد، چون هر شب موقع خواب، از زیر تختش صداهای عجیب و غریب می‌شنید. صدای خش‌خش، تق‌تق، پیف‌پیف و کلی صدای دیگر. هاله کوچولو وقتی این صدا‌ها را می‌شنید، می‌ترسید و مامان را صدا می‌زد. وقتی مامان هاله می‌آمد دیگر از این صدا‌ها خبری نبود. مامان هم مجبور بود بیاید توی اتاق و تا هاله خوابش ببرد، کنار تختش بنشیند. \r\nیک شب وقتی هاله مامان را صدا کرد، مامان به او گفت: «تو دیگه بزرگ شدی. امشب باید خودت تنهایی توی اتاقت بخوابی. دختر خوبی باش و سعی کن نترسی.» وقتی مامان رفت، باز‌‌ همان صداهای عجیب از زیر تخت آمد. هاله گوش‌هایش را گرفت، سرش را کرد زیر پتو و کمی بعد خوابش برد. \r\n\r\nآن شب هاله یک خواب عجیب دید. خواب دید که از زیر تختش صدا می‌آید و تخت تکان می‌خورد. هاله یواش صدا زد: «تو کی هستی زیر تخت من؟» یک دفعه یک موجود گنده تپل قرمز سرش را از زیر تخت بیرون آورد و گفت: «با من دوست می‌شی؟» \r\n\r\nهاله خیلی ترسید، پتویش را بغل کرد و چسبید به دیوار. موجود قرمز رنگ گفت: «از من نترس. من شب‌ها اینجا تنها می‌مانم و می‌ترسم.» هاله گفت: «تو هیولایی. اومدی منو بخوری؟» هیولا گفت: «هیولا‌ها که آدم نمی‌خورند.» بعد گفت: «من یه بچه هیولام. مامانم شب‌ها منو می‌ذاره اینجا و می‌ره سرکار. من زیر تخت تو از تاریکی می‌ترسم.» هاله دلش برای بچه هیولا سوخت. اول از همه چراغ خوابش را روشن کرد تا هیولا از تاریکی نترسد. بعد کلی سوال از هیولا پرسید تا فهمید هیولا‌ها موجودات تپلی هستند که خیلی مهربانند، آدم‌ها را دوست دارند و اصلا ترس ندارند. هاله اسباب‌بازی‌ها و کتاب‌هایش را به هیولا نشان داد و برای هیولا از مامان و بابایش تعریف کرد. هیولا هم گفت که یک خواهر و برادر دارد، در مدرسه هیولا‌ها درس می‌خوانند و امسال می‌روند کلاس دوم. هاله و هیولا یکی از کتاب‌های هاله را برداشتند و با هم شروع کردند به خواندن تا هر دو خواب‌شان برد. \r\n\r\nصبح که هاله از خوب بیدار شد خیلی خوشحال بود. به مامان گفت که دیگر شب‌ها از هیچ صدایی نمی‌ترسد. از آن به بعد هاله شب‌ها بدون این‌که بهانه بگیرد تنهایی در اتاق خودش می‌خوابد و بعضی وقت‌ها هم خواب هیولا، دوست گنده قرمز رنگش را می‌بیند.\r\n"},{"id":1097,"category_id":8,"category_code":"s8","source_id":58,"title":"تافی ببر بی راه","content":"تافی، ببر کوچولویی بود که داشت بین شاخ و برگ درخت‌ها بازی می‌کرد. این‌ور می‌دوید، اون‌ور می‌دوید و از روی این درخت به اون درخت دنبال شاپرک‌ها می‌کرد. یكهو یک باد تند آمد و درخت‌ها را تکان داد. تافی محکم شاخه یک درخت را گرفت. اما باد آمد، از روی تافی رد شد و راه‌های او را با خودش برد. تافی کوچولو دنبال باد دوید و صدا زد: «وایسا، من راه‌هام رو لازم دارد.» اما باد دور شد و تافی به آن نرسید.\r\nتافی بدون راه‌های سیاهش خجالت می‌کشید توی جنگل راه برود. اول فکر کرد برود پشت شاخ و برگ درخت‌ها تا راه‌راه به نظر برسد و معلوم نشود راه‌هایش گم شده. اما کمی بعد دید با ایستادن پشت درخت‌ها حوصله‌اش سر می‌رود. به همین خاطر تصمیم گرفت برود، باد را پیدا کند و راه‌هایش را پس بگیرد. تافی که نمی‌دانست باید کجا دنبال باد بگردد، فکر کرد برود پیش درخت بزرگ جنگل که همه چیز را می‌دانست و از او آدرس خانه باد را بپرسد.\r\nتافی از تپه بلند جنگل بالا رفت تا رسید به درخت بزرگ. درخت تا تافی را دید به او گفت: «تافی کوچولو، راه‌های خوشگلت کو؟» تافی نفس‌نفس زنان به درخت گفت: «باد بدجنس اومد و راه‌هام رو برد.» درخت گفت: «باد که بدجنس نیست. هر روز میاد، منو تمیز می‌کنه، برگای خشک رو از روی شاخه‌هام برمی‌داره و می‌بره تا همیشه سبز و تازه باشم.» تافی گفت: «ولی راه‌های منو برداشت و رفت. می‌خوام اونا رو ازش پس بگیرم. تو می‌دونی خونه باد کجاست؟» درخت گفت: «باد که خونه نداره. به همه جا سر می‌کشه. حالا هم رفته پیش گندمزار. اگه تند بدوی بهش می‌رسی.» تافی کوچولو از درخت خداحافظی کرد و با سرعت به سمت گندمزار دوید.\r\nتافی رسید به گندمزار. گندمزار تا تافی را دید، به او گفت: «تافی کوچولو، راه‌های خوشگلت کو؟» تافی نفس‌نفس زنان به او گفت: «باد بدجنس اومد و راه‌هام رو برد.» گندمزار گفت: «باد که بدجنس نیست. هر روز میاد منو ناز می‌کنه تا گندم‌ها موج بزنن و قشنگ بشن.» تافی گفت: «ولی راه‌های منو برداشت و رفت. می‌خوام اونا رو ازش پس بگیرم. تو می‌دونی باد کجاست؟» گندمزار گفت: «رفته پیش ابر. اگه تند بدوی بهش می‌رسی.» تافی کوچولو خداحافظی کرد و به سمت کوهی دوید که ابر بالای اون نشسته بود.\r\nتافی از کوه بالا رفت تا رسید به ابر. ابر تا تافی را دید به او گفت: «تافی کوچولو، راه‌های خوشگلت کو؟» تافی نفس‌نفس زنان به او گفت: «باد بدجنس اومد و راه‌هام رو برد.» ابر گفت: «باد که بدجنس نیست. هر روز میاد منو این‌ور و اون‌ور می‌بره تا به زمین‌های خشک بارون برسونم.» تافی گفت: «ولی راه‌های منو برداشت و رفت. می‌خوام اونا رو ازش پس بگیرم. تو می‌دونی باد کجاست؟» ابر گفت: «رفته به سمت ساحل. اگه تند بدوی بهش می‌رسی.» تافی کوچولو خداحافظی کرد و به سمت ساحل دوید.\r\n\r\nتافی رسید به ساحل. ساحل تا تافی را دید به او گفت: «تافی کوچولو، راه‌های خوشگلت کو؟» تافی نفس‌نفس زنان به او گفت: «باد بدجنس اومد و راه‌هام رو برد.» ساحل گفت: «باد که بدجنس نیست. هر روز میاد منو تمیز می‌کنه، بعد می‌ره دریا و برمی‌گرده. اگه اینجا منتظرش بمونی می‌تونی باهاش حرف بزنی.» تافی کوچولو توی ساحل منتظر باد نشست. کمی که گذشت، چیز خنکی به صورتش خورد. تافی از جا پرید و گفت: «باد بدجنس. راه‌های منو کجا بردی؟» باد گفت: «وای، معذرت می‌خوام. اون نوارهای سیاه براق راه‌های تو بود؟» تافی گفت بله. باد گفت: «من همه چیزهایی رو که توی روز جمع می‌کنم می‌برم توی جزیره وسط دریا می‌گذارم. راه‌های تو هم الان اونجاست. سوار قایق شو و برو به جزیره، راه‌هات رو بردار.»\r\nتافی کوچولو سوار قایق شد. بادبان‌ها را هم بالا کشید اما قایق از جایش تکان نمی‌خورد. تافی با ناراحتی به ساحل گفت: «قایق راه نمی‌افته. حالا چیکار کنم؟» ساحل گفت: «بدون باد که قایق نمی‌تونه حرکت کنه.» بعد رو کرد به باد و گفت: «باد مهربون. تافی راه‌هاش رو لازم داره. بهش کمک می‌کنی بره جزیره و پیداشون کنه؟» باد چرخی زد و به بادبان‌ها وزید. قایق راه افتاد و رفت به سمت جزیره. مدتی بعد ساحل قایق و باد و تافی را دید که با هم دارند به سمتش می‌آیند.\r\nراه‌های تافی سر جایش بود و داشت می‌خندید. وقتی به ساحل رسیدند، باد چرخی دور تافی زد و گفت: «از این به بعد راه‌هات رو سفت بگیر، ببر کوچولو. من باید برم که خیلی کار دارم.» بعد هوی بلندی کشید، از ساحل و تافی خداحافظی کرد و رفت. تافی به ساحل گفت: « باد اصلا بدجنس نبود. راه‌های منو برام پیدا کرد و با هم دوست شدیم. حالا هم باید برم و به ابر و گندمزار و درخت بگم که باد چقدر مهربونه.»\r\n"},{"id":1098,"category_id":8,"category_code":"s8","source_id":59,"title":"کرمولک به خانه ی خاله می رود!","content":"یکی بود یکی نبود. در یک صبح آفتابی، کرمولک کوچولو که دلش خیلی برای خاله‌اش که آن طرف باغچه زندگی می‌کرد تنگ شده بود، از مادرش اجازه گرفت و یک بقچه خوراکی برداشت تا به دیدن خاله‌اش برود اما او خیلی خوب نمی‌دانست که خانه خاله‌اش کجاست؟ \r\nاو فقط می‌دانست که باید از کنار درخت چنار وسط باغچه عبور کند. رفت و رفت و رفت، تا رسید به خانم مورچه. دید که خانم مورچه در کنار سوراخ کوچکی نشسته و گریه می‌کند. خانم مورچه وقتی کرمولک را دید، به او گفت: «دختر کوچولوی من داشت بازی می‌کرد ولی این سوراخ را ندید، حالا افتاده توش و من نمی‌توانم به او کمک کنم، مي‌شود به دخترم کمک کنی؟» و شروع کرد به گریه کردن. \r\nکرمولک بقچه‌اش را در گوشه‌ای گذاشت و آرام آرام به سوراخ نزدیک شد و دمش را داخل سوراخ کرد و از آن آویزان شد. مورچه کوچولو دم کرمولک را گرفت و از سوراخ بیرون آمد. خانم مورچه خیلی خوشحال شد و از کرمولک تشکر کرد و از او خواست تا اگر کاری دارد حتما به او بگوید تا کمکش کند. کرمولک که خانه خاله‌اش را کامل بلد نبود، از او پرسید، چون فکر می‌کرد شاید اورا بشناسد. خانم مورچه کمی فکر کرد تا این‌که یادش آمد خاله کرمولک را می‌شناسد و به او نشان داد تا از کجا برود. کرمولک از آنها خداحافظی کرد و رفت.\r\nکرمولک رفت و رفت و رفت تا رسید به یک پروانه کوچولو که خیلی خسته نشسته بود زیر سایه یک گل. وقتی کرمولک به او نزدیک شد دید که یکی از بال‌هایش کمی زخم شده و نمی‌تواند پرواز کند. از او پرسید «پروانه خانم، چه اتفاقی برای تو افتاده؟» \r\nپروانه زیبا به او گفت: «وقتی داشتم روی گل‌ها بال می‌زدم یک دفعه بالم خورد به یکی از تیغ‌های گلی که در کنارم بود، حالا نمی‌توانم پرواز کنم و خیلی هم گرسنه هستم. نمی‌دانم چه کار کنم.» کرمولک کوچولو بقچه‌اش را باز کرد و یک دستمال کوچک برداشت و بال پروانه را بست و بعد هم خوراکی‌هایش را با پروانه قسمت کرد. او خوشحال از این‌که به پروانه کمک کرده، خواست حرکت کند و برود که پروانه از او پرسید: «کجا می‌خواهی بروی، بگو شاید من بتوانم کمکت کنم.» \r\nکرمولک به پروانه گفت: «می‌خواهم به خانه خاله‌ام بروم اما کامل بلد نیستم که کجاست؟ خانم مورچه گفت که بعد از درخت چناره... ولی بقیه‌اش را بلد نیستم.» \r\nپروانه لبخندی زد وگفت: «درست است، پشت همین درخت خانه خاله توست، من او را می‌شناسم.» \r\nکرمولک خوشحال شد و به سمت پشت درخت حرکت کرد. رفت و رفت و رفت، تا رسید به یک خانه کوچک قارچی که کنار درخت بود. خسته کنارش نشست و غمگین بود، چون خانه خاله را ندید و فکر کرد شاید گمشده است و شروع کرد به بلند بلند حرف زدن و غصه خوردن: «خاله جونم، این همه راه اومدم تا ببینمت اما نتونستم خونه تو پیدا کنم، حالا چیکار کنم؟» \r\n\r\nدر همین حال بود که یک دفعه در خانه قارچی باز شد و خاله کرمولک بیرون آمد و او را صدا کرد. کرمولک کوچولو خیلی خوشحال شد و خاله‌اش او را به آغوش گرفت و به اوگفت: «عزیز دلم داشتی غصه می‌خوردی؟ صدات رو که شنیدم شناختمت عزیزم. خیلی دلم برات تنگ شده بود. خوشحالم کردی که اومدی به دیدنم. بیا بریم به خانه تا هم استراحت کنی هم غذا بخوری.» \r\n\r\nآنها با هم خوشحال و خندان به داخل خانه رفتند و کرمولک برای خاله‌اش تعریف کرد که در راه به خانم مورچه و دخترش و به پروانه کوچولو کمک کرده و توانسته خانه خاله را پیدا کند. خاله به او آفرین گفت و روی ماهش را بوسید. کرمولک خیلی خوشحال بود که توانسته بود هم خاله‌اش را ببیند و هم به دیگران کمک کند.\r\n"},{"id":1099,"category_id":8,"category_code":"s8","source_id":60,"title":"دخترک آواز خوان","content":"یکی بود یکی نبود غیر از خدا هیچ کس نبود\r\nدختری بود که با پدر و مادرش برای تفریح به جنگل رفته بودن پس از کلی بازی و تفریح دخترک پروانه خیلی خوشگلی را می بیند که دور سر او پرواز میکند.\r\nدخترک دلش می خواست که این پروانه را بگیرد و با خودش به خانه ببرد .\r\nبه همین دلیل دخترک پروانه را به قصد گرفتتن دنبال کرد .\r\nدخترک خیلی خوشحال بود چرا که خودش را در گرفتن پروانه موفق می دید . همینجور که پروانه را دنبال می کرد و می خندید پروانه او را از پدر و مادر دور تر و دورتر می کرد .\r\nدخترک پس از ساعتی که پروانه را دنبال کرد و خسته شد تصمیم گرفت استراحتی کند. در حال استراحت متوجه شد که از پدر و مادرش خبری نیست . بسیار ترسید و شروع به گریه کردن نمود .\r\nاما هر قدر گریه کرد کسی به دادش نرسید . از گریه کردن خسته شد .\r\nکمی با خود فکر کرد با خود می گفت: خدایا چه کار کنم؟ کدام سمت بروم ؟ خانواده خودم را از کجا پیدا کنم . شروع کرد به نفرین کردن پروانه و به دور برش نگاهی کرد اما پروانه را ندید .\r\nاو خودش را کاملا تنها حس کرد و ناچار شد به فکر راه چاره باشد . از کتاب علوم بعضی چیزها را که می توان سمت شمال را فهمید به خاطر آورد و با علم ناقصی که داشت سمتی را به عنوان شمال انتخاب کرد و قدم در راه گذاشت تا به سمت پدر و مادرش راه بیفتد.\r\nساعتی بود که مسیری را طی می کرد خسته شده بود و دلش می خواست با کسی صحبتی بکند ُ اما کسی نبود .\r\n\r\nدخترک زمزمه ای را شروع کرد و بعد از مدتی صدایش را بلند کرد و آوازی سرداد .\r\nدر جنگل صدایش پیچید تا آن روز دخترک از نعمت آواز خوش خودش خبری نداشت و باخود گفت : من چه صدای قشنگی دارم .\r\nهمینطور آواز می خواند و جلو می رفت اما هیچ خبری از پدر و مادرش نبود . دخترک خسته و نا امید شده بود آواز خود را قطع کرد و نشست.\r\nدخترک ناامید شده بود اما با خودش فکر کرد حتما مسیر یابی او اشتباه بوده چون اصلا او اینهمه از پدر و مادرش دور نشده بود که اینهمه به دنبال انها راه می رود . با خود گفت نکند که گمشده باشد و هیچگاه نتواند آنها را پیدا کند سرش را بالاگرفت و متوجه حضور پرنده های زیادی شد که بالای درختان هستند به چپ و راست نگاه کرد دید حیوانات زیادی دور و برش را گرفته اند و انگار منتظر اتفاقی هستند.\r\nدخترک با خود گفت : چرا اینهمه حیوان در اینجا هست نکند همایش و جلسه دارند . دختر بلند شد و راه افتاد این بار از ترس خود شروع به آواز خواندن کرد و راه خود را ادامه داد .\r\nدر طول مسیر متوجه حرکت حیوانات به سمتی شده که خودش در حرکت بود .\r\nآواز را قطع کردیکی از پرنده ها پرید و در جلوی را ه او قرار گرفت و گفت دختر خانم چه آواز خوبی داری هیچ پرنده ای نمی تواند صدای تو را در بیاورد و به زیبایی تو آواز بخواند . جنگل در عمرش آوازی به خوبی آواز تو ندیده است . واقعا هم آواز دخترک زیبا بود .\r\nپرنده گفت : تو از کجا آمده ای و اینجا چه می کنی . دخترک جواب داد من به همراه خانواده ام به جنگل برای تفریح آمده بودیم و حالا من آنها را گم کرده ام . پروانه ای را دنبال کردم و از آنها دور شدم و حالا راهم را که آمده بودم گم کردم . پرنده صوتی زد و همه پروانه ها آنجا حاضر شدند . روبه پروانه ها گفت کدام یک از شما با این بچه بازی می کردید .\r\n\r\nیکی از پروانه ها جلو آمد و با ترس و لرز گفت : من بودم .\r\nپرنده گفت : مطمعن هستم که تو می توانی به این دخترک کمک کنی .\r\nپروانه گفت : مگر چه شده است .\r\nپرنده گفت : این بچه وقتی با تو بازی می کرده از پدر و مادرش دور شده و الان راهش را گم کرده است .\r\nفکر می کنم تو بتونی به او کمک کنی تا او پدر و مادرش را پیدا بکند.\r\nپروانه گفت : آری من می توانم پدر و مادر او را پیدا کنم . پروانه پرواز کرد و به آنها گفت دنبال من راه بیفتید دخترک و حیوانات به دنبال پروانه راه افتادند بعد از ساعتی به محلی که پدر و مادر دخترک در آنجا پیک نیک راه انداخته بودند رسیدند .\r\nاما از پدر و مادر دخترک خبری نبود.\r\nهمه حیوانات به دور و بر خودشان نگاه کردند تا شاید بتوانند اثری از پدر و مادر دخترک پیدا کنند .\r\nحیوانات هر چه گشتند اثری پیدا نکردند . دخترک گفت اگر تا جاده اصلی بتوانم خودم را برسانم می توانم راه خانه را پیدا کنم . یکی از پرندگان گفت : همینجا همگی استراحت کنید من سر و گوشی آب بدهم و برای شما خبر می آورم .\r\nپرنده پر زد و از آنجا دور شد. طولی نکشید که پرنده سراسیمه بازگشت و به آنها خبر خوشی را آورد و گفت چند صد متر آنطرف تر پدر و مادر دختر بچه دنبال دخترشان می گردند .\r\nمن به آنها خبر دادم و آنها الان به اینجا می رسند .\r\nبعد از چند لحظه پدر و مادر دخترک به پیش دخترک رسیدند و پس از گریه و زاری با همدیگر از از آنها خداحافظی کردند ولی همه حیوانات تقاضاکردند که هر هفته دخترک به جنگل بیایند و دخترک برای آنها آوازی بخواند .\r\n\r\nپدر و مادر و دختر خانم از همه حیوانات تشکر کردند و خواستند که به خانه خودشان برگردند .\r\nتازه پدر مادر دخترک متوجه شدند که دخترک با آواز خوشی که داشته سبب شده که توجه حیوانات را جلب کرده و آنها متوجه گمشدن دخترک شده و به آن کمک کنند . پدر و مادر دخترک از اینکه دخترشان صاحب آواز خوشی هست خیلی خوشحال بودند .\r\nخانواده خوشبخت با خداحافظی از حیوانات به خانه خودشان رفتند .\r\nآنها روزهای تعطیل به جنگل می رفتند تا به قول خودشان عمل کنند و خود نیز خوش بگذرانند.\r\n"},{"id":1100,"category_id":8,"category_code":"s8","source_id":61,"title":"پولک طلا و قورقوری","content":"پولک طلا کمی فکر کرد و با خوش‌حالی به قورقوری گفت: «من این رو نمی‌دونستم. ممنونم که به من گفتی. من، امروز، از تو یه چیز جدید یاد گرفتم.»\r\nیکی بود یکی نبود. در یک برکه پر از آب، یه ماهی کوچولو بود به اسم پولک طلا که همراه خانواده‌اش زندگی می‌کرد. او، دوستان زیادی داشت و هر روز در برکه، با آن‌ها بازی می‌کرد.\r\n\r\nیک روزکه پولک طلا، برای بازی راهی شد، صدای دوستش، قورقوری را از بیرون آب شنید و با تعجب رفت روی آب. او، تا به حال، قورقوری را بیرون آب ندیده بود. با تعجب از او پرسید: «اون‌جا چه کار می‌کنی؟ مواظب باش بیرون آب خفه نشی!»\r\nقورقوری با لبخند گفت: «نگران من نباش. من بیرون آب هم می‌تونم نفس بکشم.»\r\n\r\nپولک طلا با تعجب گفت: «مگه می‌شه؟ پس حتما دیگه نمی‌تونی بیای توی برکه.» پولک طلا ناراحت شد و با غصه ادامه داد: «اگه دیگه نتونی بیای، من دلم برات تنگ می‌شه. آخه دیگه نمی‌تونیم با هم بازی کنیم.»\r\n\r\nقورقوری گفت: «نه، این‌طوری نیست. من باز هم می‌تونم بیام توی برکه و بازی کنیم. امروز می‌خواستم کمی آفتاب بخورم و دوستای خارج از برکه رو هم ببینم. این‌جا هم می‌تونم نفس بکشم، چون ما قورباغه‌ها، می‌تونیم هم در آب نفس بکشیم، هم بیرون آب؛ یعنی دو جا زندگی می‌کنیم.»\r\nپولک طلا کمی فکر کرد و با خوش‌حالی به قورقوری گفت: «من این رو نمی‌دونستم. ممنونم که به من گفتی. من، امروز، از تو یه چیز جدید یاد گرفتم.»\r\n\r\nپولک طلا و قورقوری شروع کردند به خندیدن.\r\n"},{"id":1101,"category_id":8,"category_code":"s8","source_id":62,"title":"کپلی در جنگل سحر آمیز","content":"یکی بود، یکی نبود …\r\nدر سرزمینی دور، جنگلی سرسبز و زیبا، اما اسرارآمیز، به اسم جنگل عجیب وجود داشت. در انتهای جنگل عجیب، کلبه‌ای زیبا بود که کپلی‌، در آن زندگی می‌کرد. با این‌که جنگل عجیب، خیلی ترسناک بود، اما کپلی‌، به‌راحتی، آن‌جا زندگی می‌کرد و هر شب، بدون ترس و دلهره، در جنگل قدم می‌زد و برای حیوانات کوچک غذا می‌برد. با درختان حرف می‌زد و برای قارچ‌ها و بوته‌های تمشک آواز می‌خواند.\r\n\r\nیک شب که کپلی‌ به جنگل رفته و گرم صحبت با درختان شده بود، از درون تاریکی، گرگ ژنرال آمد بیرون. کپلی‌، تا به حال، او را ندیده بود، اما چون در این جنگل، همه چیز عجیب بود، تعجب نکرد و با مهربانی، به او سلام کرد.\r\n\r\nگرگ ژنرال تعجب کرد و از او پرسید که چرا برایش عجیب نبود؛ چون حتی درختان هم با دیدن او، کنار رفتند و تعجب کردند. کپلی‌ خندید و گفت: «چون همه چیز در این جنگل، مثل اسم خودش، عجیب است، نباید از چیزی تعجب کرد. من، هر شب، در این جنگل قدم می‌زنم. راستی، شام خوردی؟ من، امشب، خوراکی‌های زیاد و خوش‌مزه‌ای آورده‌ام.»\r\n\r\nآن شب، گرگ ژنرال و کپلی‌، در کنار هم، شام خوش‌مزه‌ای را خوردند و جنگل عجیب، تا صبح، در سکوت، خوابید.\r\n\r\nتا به حال، به جنگل رفته‌ای؟ چه چیز عجیب و جدیدی، آن‌جا دیدی؟\r\n"},{"id":1102,"category_id":8,"category_code":"s8","source_id":63,"title":"بهترین هدیه ی تولد","content":"یکی بود یکی نبود …\r\n\r\nکوشا کوچولو جشن تولد را خیلی دوست داشت. کوشا می‌دانست چند روز دیگر تولد او است برای همین تصمیم گرفت که به پدر و مادرش کمک کند.\r\nآن روز پدر وقتی از راه رسید چند عدد بادکنک را روی میز قرار داد و از مادر کوشا خواست تا برای مراسم کوشا آنها را باد کند.\r\nکوشا می‌دانست سر مادرش خیلی شلوغ است و او باید تمام کارهای مربوط به جشن تولد را انجام دهد به همین خاطر از مادر اجازه گرفت تا بادکنک‌ها را باد کند.\r\n\r\nوقتی پدر و مادر کوشا برای خرید از خانه بیرون رفتند، کوشا به سرعت شروع به مرتب کردن خانه کرد او می‌خواست برای تشکر از زحمات پدر و مادرش به آنها کمک کند.\r\nکوشا می‌دانست که جشن تولد یعنی این‌که او یک سال بزرگتر شده است و هر کس که بزرگتر می‌شود باید رفتار بهتری با اطرافیانش داشته باشد.\r\nوقتی پدر و مادر کوشا به خانه برگشتند متوجه شدند خانه تمیز و مرتب شده است و بادکنک‌ها گوشه‌ای کنار هم چیده شده‌اند.\r\nدوستان کوشا کوچولو یکی یکی از راه رسیدند و هر کدام برای کوشا یک هدیه آوردند. کوشا بعد از این‌که شمع روی کیک را فوت کرد، هدیه‌هایش را باز کرد و با خوشحالی از همه تشکر کرد.\r\nبعد از تمام شدن مراسم جشن تولد، وقتی تمام مهمان‌ها خانه کوشا را ترک کرده و به خانه خود رفتند، کوشا با این‌که خسته بود، به مادر و پدرش در جمع کردن بشقاب‌ها و ظرف میوه، لیوان شربت و همه چیزهای دیگر کمک کرد. او با دقت تمام هدیه‌هایش را در کمد خود قرار داد.\r\nآن شب کوشا قبل از این‌که به خواب برود، با خودش احساس کرد، چقدر خوب است بچه‌ها همین‌طور که بزرگ می‌شوند، کارهای خوب و بزرگ هم انجام دهند. کارهایی که هم باعث خوشحالی خودشان و هم باعث شادمانی اطرافیانشان می‌شود.\r\nاز آن شب به بعد بود که کوشا تصمیم گرفت هر روز یک کار خوب انجام دهد و شب‌ها قبل از خواب، با به یاد آوردن آن احساس خوشحالی کند.\r\nکوشا می‌دانست هر کار خوب یک ستاره می‌شود که در آسمان به او چشمک خواهد زد.\r\nشما تا حالا چندتا کار خوب انجام دادی؟\r\n"},{"id":1103,"category_id":8,"category_code":"s8","source_id":64,"title":"شیر و آدمیزاد","content":"\r\nيکی بود يکی نبود ، غير از خدا هيچکس نبود.\r\nيک روز شير در ميدان جنگل نشسته بود و بازي کردن بچه هايش را تماشا مي کرد که ناگهان جمعي از ميمونها و شغالها در حال فرار به آنجا رسيدند. شير پرسيد: « چه خبر است؟» گفتند: « هيچي، يک آدميزاد به طرف جنگل مي آمد و ما ترسيديم.»\r\nشير با خود فکر کرد که لابد آدميزاد يک حيوان خيلي بزرگ است و مي دانست که خودش زورش به هر کسي مي رسد. براي دلداري دادن به حيوانات جواب داد:\r\n« آدميزاد که ترس ندارد.»\r\nگفتند: « بله، درست است، ترس ندارد، يعني ترس چيز بدي است، ولي آخر شما تا حالا با آدم جماعت طرف نشده ايد، آدميزاد خيلي وحشتناک است و زورش از همه بيشتر است.»\r\n\r\nشير قهقه خنديد و گفت: « خيالتان راحت باشد، آدم که هيچي، اگر غول هم باشد تا من اينجا هستم از هيچ چيز ترس نداشته باشيد.»\r\nاما شير هرگز از جنگل بيرون نيامده بود و هرگز در عمر خود آدم نديده بود. فکر کرد اگر از ميمون ها و شغال ها ببرسد آدم چييست به او مي خندند و آبرويش مي رود. حرفي نزد و با خود گفت فردا مي روم آنقدر مي گردم تا اين آدميزاد را پيدا کنم و لاشه اش را بياورم اينجا بيندازم تا ترس حيوانات از ميان برود. شير فردا صبح تنهايي راه صحرا را پيش گرفت و آمد و آمد تا از دور يک فيل را ديد. با خود گفت اينکه مي گويند آدميزاد وحشتناک است بايد يک چنين چيزي باشد. حتماً اين هيکل بزرگ آدميزاد است.\r\n\r\nپيش رفت و به فيل گفت: « ببينم، آدم تويي؟ »\r\n\r\nفيل گفت: « نه بابا، من فيلم، من خودم از دست آدميزاد به تنگ آمده ام. آدميزاد مي آيد ما فيلها را مي گيرد روي پشت ما تخت مي بندد و بر آن سوار مي شود و با چکش توي سرما مي زند. بعد هم زنجير به پاي ما مي بندد و يا دندان ما را مي شکند و هزار جور بلا بر سرما مي آورد. من کجا آدم کجا.»\r\n\r\nشير گفت: « بسيار خوب، خودم مي دانستم ولي مي خواستم ببينم يک وقت خيال به سرت نزند که اسم آدم روي خودت بگذاري.»\r\n\r\nفيل گفت: « اختيار داريد جناب شير، ما غلط مي کنيم که اسم آدم روي خودمان بگذاريم.»\r\n\r\nشير گفت: « خيلي خوب، پر حرفي نکن برو پي کارت.» و همچنان رفت تا رسيد به يک شتر قوي هيکل و گفت ممکن است آدم اين باشد. او را صدا زد و گفت: « صبر کن ببينم، تو آدمي؟»\r\nشتر گفت: خدا نصيحت نکند که من مثل آدم باشم. من شترم، خار مي خورم و بار مي برم و خودم اسير و ذليل دست آدمها هستم. اينها مي آيند صد من بار روي دوشم مي گذارند و تشنه و گرسنه توي بيابانهاي بي آب و علف مي گردانند بعد هم دست و پاي ما را مي بندند که فرار نکنيم. آدميزاد شير ما را مي خورد، پشم ما را مي چيند و با آن عبا و قبا درست از جان ما هم بر نمي دارد، حتي گوشت ما را هم مي خورد.»\r\n\r\nشير گفت: « بسيار خوب، من خودم مي دانستم . مي خواستم ببينم يک وقت هوس نکني اسم آدم روي خودت بگذاري و ميمونها و شغالها را بترساني.»\r\n\r\nشتر گفت: « ما غلط مي کنيم. من آزارم به هيچ کس نمي رسد و اگر يک ميمون يا شغال هم افسارم را بکشد همراهش مي روم. من حيوان زحمت کشي هستم و ...»\r\n\r\nشير گفت: « خيلي خوب، پر حرفي نکن برو پي کارت.» و همچنان رفت تا رسيد به يک گاو. با خود گفت اين حيوان با اين شاخهايش حتماً آدميزاد است. پيش رفت و از او پرسيد: « تو از خانواده آدميزادي؟» \r\n\r\nگاو گفت: « نخير قربان، آدم که شاخ ندارد. من گاوم که از دست آدميزاد دارم بيچاره مي شوم و نمي دانم شکايت به کجا برم. آدميزاد ماها را مي گيرد، شبها در طويله مي بندد و روزها به کشتزار مي برد و ما مجبوريم زمين شخم کنيم و گندم خرد کنيم و چرخ دکان عصاري را بچرخانيم آن وقت شير هم بدهيم و آخرش هم ما را مي کشند و گوشت ما را مي خورند.»\r\n\r\nشير گفت: « بله، خودم، مي دانستم. گفتم يک وقت هوس نکني اسم آدم روي خودت بگذاري و حيوانات کوچکتر را بترساني، اين ميمونها و شغالها سواد ندارند و از آدم مي ترسند.»\r\n\r\nگاو گفت: « نه خير قربان، موضوع اين است که من با اين شاخ...»\r\nشير گفت: « خيلي خوب، پر حرفي نکن برو پي کارت.»\r\n\r\nشير با خود گفت: « پس معلوم شد آدميزاد شاخ ندارد و تا اينجا يک چيزي بر معلوماتمان افزوده شد.» و همچنان رفت تا رسيد به يک خر که داشت چهار نعل توي بيابان مي دويد و فرياد مي کشيد. شير با خود گفت اين حيوان با اين صداي نکره اش و با اين دويدن و شادي کردنش حتماً همان چيزي است که من دنبالش مي گردم. خر را صدا زد و گفت:« آهاي، ببينم، تويي که مي گويند آدم شده اي؟»\r\n\r\nخر گفت: « نه والله، من آدم بشو نيستم. من خودم بيچاره شده آدميزاد هستم. و هم اينک از دست آدمها فرار کرده ام. آنها خيلي وحشتنا کند و همينکه دستشان به يک حيوان بند شد ديگر او را آسوده نمي گذارند. آنها ما را مي گيرند بار بر پشت ما مي گذارند. آنها ما را مي گيرند دراز گوش و مسخره هم مي کنند و مي گويند تا خر هست پياده نبايد رفت. آدمها آنقدر بي رحم و مردم آزارند که حتي شاعر خودشان هم گفته:\r\n\r\nگاوان و خران باردار\r\nبه ز آدميان مردم آزار\r\n\r\nشير گفت: « بسيار خوب، خودم مي دانستم که تو درازگوشي اما من دارم مي روم ببينم آدمها حرف حسابي شان چيست؟»\r\n\r\nخر گفت: « ولي قربان، بايد مواظب خودتان...»\r\n\r\nشير گفت: « خيلي خوب، پر حرفي نکن برو پي کارت. من مي دانم که چکار بايد بکنم.»\r\nاما شير فکر مي کرد خيلي عجيب است اين آدميزاد که همه از او حساب مي برند، يعني ديگر حيواني بزرگتر از فيل و شتر و گاو و خر هم هست؟ قدري پيش رفت و رسيد به يک اسب که به درختي بسته شده بود و داشت از تو بره جو مي خورد. شير پيش رفت و گفت:« تو کي هستي؟ من دنبال آدم مي گردم.»\r\n\r\nاسب گفت: « هيس، آهسته تر حرف بزن که آدم مي شنود. آدم خيلي خطرناک است، فقط شايد تو بتواني انتقام ما را از آدمها بگيري. آدمها ما را مي گيرند افسار و دهنه مي زنند و ما را به جنگ مي برند، به شکار مي برند، سوارمان مي شوند و به دوندگي وا مي دارند و پدرمان را در مي آورند. ببين چه جوري مرا به اين درخت بسته اند.»\r\n\r\nشير گفت: « تقصير خودت است، دندان داري افسارت را پاره کن و برو، صحرا به اين بزرگي، جنگل به آن بزرگي.»\r\n\r\nاسب گفت: « بله، صحيح است، چه عرض کنم، در صحرا و جنگل هم شير و گرگ و پلنگ حرف زدي، حيف که کار مهمتري دارم وگرنه مي دانستم با تو چه کنم، ولي امروز مي خواهم انتقام همه حيوانات را از آدميزاد بگيرم.»\r\n\r\nشير قدري ديگر راه رفت و رسيد به يک مزرعه و ديد مردي دارد چوبهاي درخت را بهم مي بندد و يک پسر بچه هم به او کمک مي کند و شاخه ها را دسته بندي مي کند.\r\n\r\nشير با خود گفت: ظاهراً اين بي بته ها هم آدميزاد نيستند ولي حالا پرسيدنش ضرري ندارد. پرسش کليد دانش است. پيش رفت و از مرد کارگر پرسيد: « آدميزاد تويي؟»\r\n\r\nمرد کارگر ترسيد و گفت: « بله خودمم جناب آقاي شير، من هميشه احوال سلامتي شما را از همه مي پرسم.»\r\n\r\nشير گفت: « خيلي خوب، ولي من آمده ام ببينم تويي که حيوانات را اذيت مي کني و همه از تو مي ترسند؟»\r\n\r\nمرد گفت: « اختيار داريد جناب آقاي شير، من واذيت؟ کسي همچو حرفي به شما زده ؟ اگر کسي از ما بترسد خودش ترسو است وگرنه من خودم چاکر همه حيوانات هم هستم. من براي آنها خدمت مي کنم، اصلا کار ما خدمتگزاري است منتها مردم بي انصافند و قدر آدم را نمي دانند. شما چرا بايد حرف مردم را باور کنيد، از شما خيلي بعيد است، شما سرور همه هستيد و بايد خيلي هوشيار باشيد.»\r\n\r\nشير گفت: « من ديدم فيل و گاو و خر و شتر و اسب همه از دست تو شکايت دارند، ميمونها و شغالها از تو مي ترسند و همه مي گويند آدميزاد ما را بيچاره کرده.» مرد گفت: « به جان عزيز خودتان باور کنيد که خلاف به عرض شما رسانده اند. همان فيل با اينکه حيوان تنه گنده بي خاصيتي است بايد شرمنده محبت من باشد. ما اين حيوان وحشي بياباني را به شهر مي آوريم و با مردم آشنا مي کنيم، به او علف مي دهيم، او را در باغ وحش پذيرايي مي کنيم. همان شتر را مانگاهداري مي کنيم، خوراک مي دهيم، برايش خانه درست مي کنيم. چه فايده دارد که پشمش بلند شود، ما با پشم شتر براي برهنگان لباس تهيه مي کنيم. اسب را ما زين ولگام زرين و سيمين برايش مي سازيم و مثل عروس زينت مي کنيم. بعد هم ما زورکي از کسي کار نمي کشيم. گاو و خر را مي بريم توي بيابان ول مي کنيم ولي خودشان راست مي آيند مي روند توي طويله. آخر اگر کسي راضي نباشد خودش چرا بر مي گردد؟ شما حرف آنها را در تنهايي شنيده ايد و مي گويند کسي که تنها پيش قاضي برود خوشحال مي شود. آنها که حالا اينجا نيستند ولي اگر مي خواهيد يک اسب اينجا هست بياورم آزادش کنم اگر حاضر شد به جنگل برود هر چه شما بگوييد درست است. ملاحظه بفرماييد ما هيچ وقت روي شير و پلنگ بار نمي گذاريم. چونکه خودشان راضي نيستند. ما زوري نداريم که به کسي بگوييم، اصلا شما مي توانيد باور کنيد که من با اين تن ضعيف بتوانم فيل را اذيت کنم؟ من که به يک مشت او هم بند نيستم.» \r\n\r\nشير گفت: « بله، مثل اينکه حرفهاي خوبي بلدي بزني.»\r\nمرد گفت: « حرف خوب که دليل نيست ولي ما کارهايمان خوب است. باور کنيد هر کاري که از دستمان برآيد براي مردم مي کنيم. حتي درست همين امروز به فکر افتاده بودم که بيايم خدمت شما و پيشنهاد کنم که براي شما يک خانه بسازم، آخر شما سرور حيوانات هستيد و خيلي حق به گردن ما داريد.»\r\n\r\nشير پرسيد: « خانه چطور چيزيست؟»\r\nمرد گفت: « اگر اجازه مي دهيد همين الان درست مي کنم تا ملاحظه بفرماييد که ما مردم چقدر مردم خوش قلبي هستيم. شما چند دقيقه زير سايه درخت استراحت بفرماييد.» مرد شاگردش را صدا زد و گفت: پسر آن تخته ها و آن چکش و ميخ را بياور.\r\n\r\nپسرک اسباب نجاري را حاضر کرد و مرد فوري يک قفس بزرگ سرهم کرد و به شير گفت: « بفرماييد. اين يک خانه است. فايده اش اين است که اگر بخواهيد هيچ کس مزاحم شما نشود مي رويد توي آن و درش را مي بنديد و راحت مي خوابيد. يا بچه هايتان را در آن نگهداري مي کنيد و وقتي در اين خانه هستيد باران روي سرتان نمي ريزد و آفتاب روي سرتان نمي تابد و اگر يک سنگ از کوه بيفتد روي شما نمي غلطد و اگر باد بيايد و يک درخت بشکند روي سقف خانه ها زندگي مي کنيم و براي شما که سالار و سرور حيوانات هستيد داشتن خانه خيلي واجب است. البته همه جور خانه مي شود ساخت، کوچک و بزرگ. حالا بفرماييد توي خانه ببينم درست اندازه شما هست؟»\r\n\r\nشير هر چه فکر کرد ديد آدميزاد به نظرش چيز وحشتناکي نيست و خيلي هم مهربان است. اين بود که بي ترس و واهمه رفت توي قفس و مرد نجار فوري در قفس را بست و گفت « تشريف داشته باشيد تا هنر آدميزا را به شما نشان بدهم.» مرد آهسته به شاگردش دستور داد« پشت ديوار قدري آتش روشن کن و آفتابه را بياور.» بعد خودش آمد پاي قفس و باشير صحبت کرد و گفت: « بله. اينکه مي گويند آدميزاد فلان است و بهمان است مال اين است که هيکل آدميزاد خيلي نازک نارنجي است اما مغز آدميزاد بهتر از همه حيوانات کار مي کند. شما آدميزاد را خيلي دست کم گرفته ايد که از توي جنگل راه مي افتيد مي آييد پوست از کله اش بکند، آدميزاد صد جور چيزها اختراع کرده که براي خودش فايده دارد و براي بدخواهش ضرر دارد. البته ما چنگ و دندان شما خيلي خطرناکتر است و اگر همه حيوانات از ما مي ترسند براي همين چيزهاست. حالا من با يک آفتابه کوچک بي قابليت چنان بلايي بر سرت بياورم که تا عمر داري فراموش نکني و ديگر درصدد انتقام جويي برنيايي.» بعد صدايش را بلند کرد و گفت:\r\n\r\nپسر، آفتابه را ببار.»\r\nمرد آفتابه آب جوش را گرفت و بالاي سر قفس شروع کرد به ريختن آب جوش روي سر و تن شير.\r\nشير فرياد مي کرد و براي نجات خود تلاش مي کرد ولي هر چه زور مي زد صندوق محکم بود. عاقبت بعد از اينکه همه جاي بدن شير از آب جوش سوخت و پوستش تاول زد و کار به جان رسيد گفت:« بله، من مي توانم تو را در اين قفس نگاه دارم، مي توانم تو را نفله کنم، مي توانم پوست از تنت بکنم اما نمي کنم تا به جنگل خبر ببري و حيوانات نخواسته باشند با آدمها زور آزمايي کنند. خودم هم برايت در قفس را باز مي کنم، اما اگر قصد بدجنسي داشته باشي صدجور ديگر هم اسباب دارم که از آفتابه بدتر است و آن وقت ديگر خونت به گردن خودت است.\r\nمرد در قفس را باز کرد و شير از ترسش پا به فرار گذاشت و ديگر پشت سرش را هم نگاه نکرد. رفت توي جنگل و از سوزش تن و بدنش ناله مي کرد. دوسه تا شير که در جنگل بودند او را ديدند و پرسيدند: « چه شده، چرا اينطور شدي؟»\r\n\r\nشير قصه را تعريف کرد و گفت: « اينها همه از دست آدميزاد به سرم آمد.» شيرها گفتند: « تو بيخود با آدميزاد حرف زدي و از او فريب خوردي. بايستي از او انتقام بگيريم. آدميزاد تو را تنها گير آورده، با دشمن نبايد تنها روبرو شد، اگر با هم بوديم اينطور نمي شد.\r\n\r\nگفت: « پس برويم.»\r\nسه شير تازه نفس جلو و شير سوخته از دنبال دوان دوان آمدند تا به مزرعه رسيدند. مرد نجار خودش به خانه رفته بود و شاگردش مشغول جمع کردن ابزار کار بود که شيرها سر رسيدند. پسرک موضوع را فهميد و ديد وضع خطرناک است. فوري از يک درخت بالا رفت و روي شاخه درخت نشست.\r\n\r\nشيرها وقتي پاي درخت رسيدند گفتند حالا چکنيم. شير سوخته گفت: « من که از آدم مي ترسم. من پاي درخت مي ايستم شماها پا بر دوش من بگذاريد، روي هم سوار شويد و او را بکشيد پايين تا با هم به حسابش برسيم.»\r\n\r\nگفتند: « ياالله». شير سوخته پاي درخت ايستاد و شيرهاي ديگر روي سرهم سوار شدند و درخت کوتاه بود. شاگرد نجار ديد نزديک است که شيرها به او برسند و هيچ راه فراري ندارد. ناگهان فکري به خاطرش رسيد و به ياد حرف استادش افتاد و فرياد کرد: « پسر، آفتابه را بيار.»\r\nشيرها دنبال او دويدند و گفتند: « چرا در رفتي؟ نزديک بود بگيريمش.»\r\n\r\nشير گفت: چيزي که من مي دانم شما نمي دانيد. من تمام اسرار آدميزاد را مي دانم و همينکه گفت « آفتابه را بيار» ديگر کار تمام است. اين بدبختي هم که بر سر من آمد مال اين بود که ما نمي توانيم آفتابه بسازيم. آدمها داناتر از ما هستند و کسي که داناتر است به هر حال زورش بيشتر است.\r\n"},{"id":1104,"category_id":8,"category_code":"s8","source_id":65,"title":"رقیه کوچولو","content":"در واقعه کربلا دختر امام حسین (ع) رقیه (ع) سه سال داشت. امام حسین دختر سه ساله خود را خیلی دوست داشتند. رقیه کوچولو هم پدر را خیلی دوست داشت لحظه آخر که امام (ع) داشتند می رفتند به میدان جنگ رقیه (ع) را روی پای خود نشاندند و برسر و موی او دست کشیدند و او را برای آخرین بار بوسیدند و با او وداع کردند.\r\nوقتی امام به شهادت رسیدند خاندان امام را به اسارت بردند، حضرت رقیه خیلی از دوری امام بی تاب بودند و گریه می کردند.\r\nصدای گریه رقیه کوچولو به گوش یزیدیان رسید و آنها برای اینکه صدای رقیه (ع) را قطع کنند سر امام حسین (ع) را برایش بردند زمانی که حضرت رقیه سر مبارک امام را در آغوش گرفتند و بوسیدند در حالی که سر مبارک در آغوششان بود جان سپردند.\r\nخدایا دشمنان امام را لعنت کن و یاد خواهرم رقیه را در دلم زنده نگه دار.\r\n"},{"id":1105,"category_id":8,"category_code":"s8","source_id":66,"title":"معلم بی سواد و مداد جادویی","content":"جینو حوصله نوشتن نداشت. با اینکه عاشق مدرسه بود به خاطر مشق نوشتن از درس و مدرسه خسته می شد. او با خودش فکر می کرد کاش یک مداد جادویی داشتم و می توانستم با آن مشقهایم را بنویسم. آن وقت فقط مداد را روی دفتر می گذاشتم و خودش شروع به نوشتن می کرد. جینو غرق در فکر و خیال بود که یک دفعه ابر آرزوها درست بالای سرش قرار گرفت. ابر آرزوها روی سر جینو شروع به باریدن کرد و آرزوی جینو براورده شد. جینو صاحب یک مداد جادویی شد.\r\nاز فردای آن روز هر وقت جینو می خواست مشقهایش را بنویسد فقط مداد را روی دفتر می گذاشت مداد خودش شروع به نوشتن می کرد و جینو هیچ زحمتی نمی کشید. جینو حالا دیگر خیلی بچه ی زرنگی شده بود. مشق های او همیشه تمیزتر و بهتر از دیگران بود. جینو خیلی خوشحال بود و فکر می کرد اینطوری از همه زرنگتر می شود.\r\nبالاخره مدرسه ی جینو با کمک مداد جادویی تمام شد و جینو معلم شد. جینو به عنوان معلم وارد مدرسه شد. او می خواست به بچه های مدرسه درس بدهد. ولی او که یک مشکل بزرگ پیدا کرده بود. او اصلا بلد نبود چیزی بنویسد. دستخط او از دستخط خرچنگها و قورباغه ها هم بدتر بود. وقتی جینو می خواست پای تخته چیزی بنویسد همه ی بچه ها به او می خندیدند. دست جینو به نوشتن عادت نداشت.\r\nحالا جینو یک معلم بی سواد بود او تازه فهمیده بود کسی که زیاد می نویسد بیشتر یاد می گیرد و دستخط بهتری هم پیدا می کند. حالا آقای معلم بعد از این همه سال تازه مجبور شده است دوباره از اول درس بخواند. حالا او کلاس اول است.\r\n"},{"id":1106,"category_id":8,"category_code":"s8","source_id":67,"title":"بزغاله ی خواب آلو","content":"بزغاله کوچولو به همراه گله گوسفندان، برای گردش و چرا، راهی دشت و صحرا شد. چوپان مهربان می دانست که بزغاله ها گوسفندان بازیگوش و سر به هوایی هستند به خاطر همین بیش از بقیه گوسفندان ،حواسش به بزغاله بود. اما بزغاله انقدر از گله دور می شد و این طرف و آن طرف می رفت که چوپان را خسته می کرد.\r\nظهر که شد چوپان زیر یک درخت به استراحت پرداخت. گوسفندان هم که حسابی خسته بودند هر جا سایه ای بود همانجا خوابیدند. اما بزغاله هنوز دوست داشت بازی کند. هی با شاخهای کوچکش سر به سر بقیه گوسفندان می گذاشت تا با او بازی کنند ولی هیچ کس حوصله نداشت.\r\nهمه دوست داشتند بخوابند. بزغاله کوچولو خیلی ناراحت و عصبانی شده بود. چون اصلا خوابش نمی آمد. او سعی کرد خودش تنهایی بازی کند. گاهی از شاخه های کوتاه تر درختان بالا می رفت. گاهی در جوی آب راه می رفت و آب بازی می کرد و گاهی هم این طرف و آن طرف می دوید . خلاصه آنقدر بازی کرد تا ظهر گذشت و وقت استراحت گوسفندان تمام شد. گله دوباره برای حرکت آماده شد. همه ی گوسفندان از خواب بیدار شدند و کمی آب خوردند و به همراه چوپان به راه افتادند.\r\nبزغاله خوشحال شد و لابلای گوسفندان شروع به حرکت و جست و خیز کرد. اما هنوز چیزی نرفته بود که احساس خستگی و خواب آلودگی کرد. دلش می خواست بخوابد. هر کجا گله، برای چریدن می ایستاد همانجا پنج دقیقه می خوابید. دوباره که گله راه می افتاد به سختی از جا بلند می شد و چند قدم می رفت. یک ساعت بعد گله به دشت سرسبزی از گلها و علفهای تازه رسید. اما بزغاله آنقدر خسته بود که فورا به خواب رفت و هیچی ندید. گوسفندان همگی خوشحال و سرحال در دشت سرسبز مشغول بازی و چرا شدند.\r\n\r\nاما بزغاله کوچولو تمام وقت خواب بود. نزدیک غروب آفتاب گله باید به سمت خانه برمی گشت. چوپان بزغاله را از خواب بیدار کرد تا همراه گله به خانه ببرد. بزغاله وقتی فهمید که چقدر به بقیه خوش گذشته است حسابی دلش سوخت و با خودش گفت کاش من هم ظهر مثل بقیه خوابیده بودم و بعد از ظهر در دشت گلها بیدار و سرحال بازی می کردم. بزغاله کوچولو فهمید اگر ظهرها یک ساعت بخوابد بقیه ی روز بیشتر به او خوش می گذرد.\r\n"},{"id":1107,"category_id":8,"category_code":"s8","source_id":68,"title":"نی نی و سنجاب کوچولو","content":"چند روز پیش، نی نی سنجابها به دنیا آمد و سنجاب کوچولو صاحب یک برادر شد. نی نی سنجاب ها خیلی ریزه میزه و با نمک بود. سنجاب کوچولو از دیدن برادر کوچولوی خودش خیلی خوشحال شده بود. می خواست بغلش کند و با او بازی کند اما مامان سنجابه اجازه نمی داد و می گفت نی نی هنوز خیلی کوچک است. باید صبر کنی تا بزرگتر بشود و بتواند با تو بازی کند.\r\nسنجاب کوچولو می خواست با مامان بازی کند اما مامان هم نمی توانست با سنجاب کوچولو بازی کند چون دائما نی نی را بغل کر ده بود. سنجاب کوچولو مدتی رفت توی اتاقش و با اسباب بازیهاش بازی کرد. اما زود حوصله اش سر رفت و خسته شد.\r\nبابا سنجابه از راه رسید. سنجاب کوچولو دوید تو بغل بابا . اما بابا خسته بود و حوصله نداشت با سنجاب کوچولو بازی کند. ولی وقتی نشست نی نی سنجابه را بغل کرد و شروع کرد به بوسیدن و بازی کردن با نی نی سنجابه .\r\n\r\nسنجاب کوچولو ناراحت شد. رفت توی اتاقش و روی تختخوابش خوابید و پتو را روی سرش کشید. مدتی گذشت . مامان سنجابه صدا زد سنجاب کوچولو غذا آماده است بیا.\r\nسنجاب کوچولو جواب نداد.\r\nبابا صدا زد \"سنجاب بابا\" بیا فندق پلو داریم.\r\nسنجاب کوچولو باز هم جواب نداد.\r\nمامان و بابا آمدند پیش سنجاب کوچولو ولی دیدند سنجاب کوچولو غصه می خورد.\r\nبابا سرفه کرد... اوهوم ...اوهوم...\r\nولی سنجاب کوچولو تکان نخورد و به بابا نگاه نکرد.\r\nمامان گفت عزیزکم سنجابکم.\r\nلبهای سنجاب کوچولو گریه ای شد چشمهاش پر از آب شد و گفت شما من را دوست ندارید .فقط نی نی را دوست دارید.\r\nمامان و بابا سرشان را انداختند پایین و یک کمی فکر کردند . بعد دوتایی باهم دستهای سنجاب کوچولو را گرفتند و از روی تختخوابش بلندش کردند و آن را حسابی تابش دادند. سنجاب کوچولو خنده اش گرفت. مامان و بابا سنجابه، بازهم سنجاب کوچولو را توی هوا تاب دادند. حالا دیگر سنجاب کوچولو بلند بلند می خندید.\r\nیک دفعه، صدای گریه ی نی نی سنجابه بلند شد. مامان و بابا هنوز داشتند با سنجاب کوچولو بازی می کردند. سنجاب کوچولو دلش برای نی نی شان سوخت و گفت مگر صدای گریه ی نی نی را نمی شنوید؟ بیایید برویم ساکتش کنیم.\r\nحالا مامان و بابا و سنجاب کوچولو سه تایی با هم رفتند نی نی سنجابه را ساکت کنند.\r\n"},{"id":1108,"category_id":8,"category_code":"s8","source_id":69,"title":"درخت سیب","content":"سال ها پیش پسر کوچولویی بازیگوش عاشق بازی کردن در اطراف درخت سیب بزرگی بود. او هر روز از درخت بالا می رفت و سیب هایش را می خورد و استراحتی کوتاه در زیر سایه اش می کرد. او درخت را دوست می داشت و درخت هم عاشق او بود. زمان به آرامی گذشت و پسر کوچولو بزرگ شد و دیگر هر روز برای بازی به سراغ درخت نمی آمد.\r\nیک روز، پسر بعد از مدت ها برگشت، اما این بار مثل همیشه خوشحال نبود.\r\nدرخت به پسر گفت: بیا با من بازی کن.\r\nپسر جواب داد: من دیگر یک پسر کوچولو نیستم و با درخت ها بازی نمی کنم. دوست دارم برای خودم اسباب بازی داشته باشم ولی پولی ندارم.\r\n\"متاسفم. ولی من پولی ندارم، اما تو می توانی همه ی سیب های مرا بچینی و آن ها را بفروشی و از پولش برای خودت اسباب بازی بخری.\"\r\nپسر بسیار خوشحال شد و تمام سیب ها را چید و با ذوق و شوق آن جا را ترک کرد. پسر هرگز بعد از چیدن سیب ها به سراغ درخت نیامد.\r\nیک روز پسر بعد از مدت ها پیش درخت برگشت این بار پسر برای خودش مردی شده بود. درخت بسیار هیجان زده شد و گفت: بیا باهم بازی کنیم.\r\n\" من وقتی برای بازی ندارم. باید کار کنم و برای خانواده ام یک خانه بخرم. تو می توانی به من کمک کنی؟\"\r\n\"متاسفم، ولی من خانه ندارم، اما می توانی شاخه های مرا ببری و با آن خانه بسازی.\" مرد هم همین کار را کرد و با شادمانی درخت را ترک کرد. درخت از دیدن دوست قدیمی اش خوشحال شد، اما او دیگر پیش درخت نیامد. درخت دوباره تنها و ناراحت شد.\r\nیک روز گرم تابستانی، مرد برگشت و درخت بسیار خوشحال شد.\r\nدرخت گفت: بیا باهم بازی کنیم!\r\nمرد گفت: من دیگر پیر شده ام و دلم می خواهد با قایق به سفر دریایی بروم. تو می توانی به من قایقی بدهی؟\r\n\" تنه ی مرا ببر و برای خودت قایقی بساز. تو با قایقت می توانی به دوردست ها سفر کنی و از آن لذت ببری.\"\r\nمرد هم تنه ی درخت را قطع کرد و از آن برای خود قایقی ساخت و به سفر دریایی اش رفت و مدت زمانی طولانی دیگر پیش درخت نیامد.\r\nسرانجام مرد بعد از چند سال بازگشت. درخت گفت: متاسفم پسرم، اما من دیگر چیزی برای دادن به تو ندارم. حتی سیبی هم ندارم تا از تو پذیرایی کنم.\r\nمرد پاسخ داد: مهم نیست، چون من هم دندانی برای گاز زدن ندارم.\r\n\"حتی تنه ای ندارم که بتوانی از آن بالا بروی\"\r\n\"من آن قدر پیر شده ام که دیگر نمی توانم از جایی بالا بروم.\"\r\nدرخت اشک ریخت و گفت: من واقعاً نمی توانم به تو کمکی بکنم، تنها چیزی که برایم باقی مانده ریشه های خشکیده ی من است.\r\nمرد جواب داد:من حالا به چیز زیادی احتیاج ندارم، تنها جایی می خواهم که بتوانم در آن استراحت کنم. من خسته و پیر شده ام.\r\n\"خب! ریشه های درخت پیر بهترین مکان برای تکیه دادن و استراحت کردن است. بیا بنشین و استراحت کن.\"\r\nمرد کنار ریشه ی درخت نشست و درخت هم از خوشحالی اشک ریخت.\r\n"},{"id":1109,"category_id":8,"category_code":"s8","source_id":70,"title":"مترسک ترسو","content":"وسط یک مزرعه دور افتاده یک مترسک تو زمین کاشته شده بود. مترسک قصه ما با بقیه مترسکها یکفرقی داشت. اون ترسو بود و از پرنده ها میترسید.\r\nیک روز صبح وقتی مترسک از خواب بیدار شد دو تا کلاغ را دید که یکی از آنها روی سرش و یکی ديگر هم روی دستش نشسته بودند.مترسک که حسابی ترسیده بود خیلی سعی کرد آنها را از خودش دور کند، اما نتوانست. کلا غها مدام با نوکشان تو سر مترسک می زدند. سرش به شدت درد گرفته بود. میدانست که اگر اوضاع به همین شکل پیش بره کلا غها و پرنده های دیگر او را نابود میکنند.\r\nروزها به همین شکل گذشت. تا اینکه یک روز خروس مزرعه اومد کنار مترسک نگاهی به چشمهای غمگین و دکمه ای مترسک انداخت و گفت: هی مترسک! برای چی جلوی پرنده ها را نمیگیری؟ چطور بگیرم. من میترسم اونها با نوکشان من را تیکه تیکه کنند. خروس گفت: نترس، آنها اگر از تو شجاعت ببینند این کار را نمیکنند. تو باید از خودت شجاعت نشان بدهی و گرنه صاحب مزرعه تو را از بین میبرد و یک مترسک جدید در مزرعه میگذارد. میدونی تا همین حالا هم که گذشته چقدر به مزرعه آسیب رسیده. بالاخره صبر مزرعه دار هم حدی دارد تا صبرش تمام نشده سعی کن آنها را دور کنی.\r\nمترسک اخمهایش را در هم کشید و گفت: یک نگاه به ریخت و قیافه من بینداز، ببین اصلا میتوانم کسی را بترسانم؟ خروس گفت: اون مشکلی ندارد. من میتوانم چهره ات را عوض کنم تو هم باید کمک کنی تا به ترس ات غلبه پیدا کنی. خروس این را گفت و رفت. عصر آن روز با خودش یک ردای سیاه و حشتناک و یک کلاه بزرگ سیاه آورده بود. خروس کمک کرد و لباسها را تن مترسک کرد و گفت: مطمئن باش آنقدر وحشتناک شدی که من هم از تو میترسم. حالا میخواهم ببینم فردا چی به سر پرنده ها میآوری؟ بعد هم خنده ای کرد و رفت.\r\nفردا صبح وقتی خورشید طلوع کرد. پرنده ها با دیدن مترسک میخکوب شدند. شاید هم فکر کردند مترسک خود شیطونه که اومده وسط مزرعه. چند تاشون خواستند شجاعت کنند و بیایند جلو. اما مترسک با اطمینان به اینکه خیلی ترسناک شده با یک حرکت شدید همه پرنده ها را از خودش دور کرد. وقتی دید واقعا پرنده ها ترسیدند شجاعت اش بیشتر شد. از آن روز به بعد هر روز که میگذشت به شجاعت مترسک افزوده میشد و دیگر هیچ پرنده ای جرات نمیکرد به مزرعه آسیب بزند.\r\n\r\nیک روز بعدازظهر که مترسک محکم و استوار سر جایش ایستاده بود یک کبوتر چاهی به طرف اش آمد. مترسک سعی کرد کبوتر را بترساند، اما کبوتر با اینکه ترسیده بود باز هم جلوتر آمد تا وقتی که این جرات را به خودش داد و روی دست مترسک نشست. مترسک با عصبانیت گفت: چی میخواهی؟ کبوتر چاهی با ترس گفت: مترسک میدونم که تو وظیفه داری از این مزرعه مراقبت کنی، ولی ما هم مخلوق خداییم و باید از این مزرعه سهمی داشته باشیم. به ما رحم کن، اگر اجازه ندی ما تو این چند روز آخر که قراره مزرعه را درو کنند، چیزی بخوریم مطمئنا همه ما از گرسنگی خواهیم مرد.\r\nمترسک با نگرانی گفت: خوب اگر من هم این کار را بکنم نابود میشوم و مزرعه دار من را از بین میبرد. کبوتر چاهی گفت: شاید مزرعه دار این کار را نکند، ولی مطمئن باش که ما و جوجه هایمان از گرسنگی میمیریم. مترسک گفت: تا فردا به من فرصت بده تا خوب فکر کنم و بتوانم یک تصمیم درست بگیرم. کبوتر چاهی گفت: باشه، فردا صبح موقع طلوع خورشید میآیم به سراغ ات. بعد هم پرواز کرد و رفت.\r\nآن شب مترسک تا صبح نخوابید و به حر فهای کبوتر چاهی فکر کرد. با خودش گفت: اگر من شجاع شدم فقط به خاطر ترس از نابودی و مرگ خودم بود. پس اینقدرها هم شجاع نیستم. چون به خاطر یک ترس بزر گتر یک ترس کوچکتر را رها کردم و این اسم اش شجاعت نیست. اگر بخواهم شجاعت را به دست بیاورم باید ترس از مرگ را رها کنم. فردا صبح درست موقع طلوع خورشید کبوترچاهی دوباره آمد سلام کرد و گفت: چی شده مترسک فکرهایت را کردی ؟مترسک گفت: دوست من شما آزاد هستيد كه از مزرعه استفاده کنید.\r\nکبوتر چاهی خوشحال نزد دوستان اش رفت و آنها را با خودش آورد، از آن روز به بعد پرنده ها می آمدند و در مزرعه خودشان را سیر میکردند و میرفتند. مزرعه دار وقتی متوجه شد که پرنده ها از مترسک نمیترسند و اون به هیچ دردی نمیخورد مترسک را برداشت و به جای هیزم در اجاق خانه سوزاند. از آن سال به بعد درست موقع درو گندمها که میرسد تمام پرنده های نواحی آن روستا، با همدیگر یک صدا، سرودی میخوانند که اسم اش هست «مترسک شجاع. »\r\n"},{"id":1110,"category_id":8,"category_code":"s8","source_id":71,"title":"شب وحشتناک","content":"آن روز، از صبح تا شب، آقاگوسفنده و خانم گوسفنده و بزچلاقه نتوانستند از آغل بيرون بروند. در آسمان باز شده بود و باراني یک ريز مي باريد. آقاگوسفنده و خانم گوسفنده و بزچلاقه با علوفه خشکي که توي آغل داشتند، شکمشان را سير کردند و شب که شد، هر کدام گوشه اي خوابيدند.\r\nنصفه هاي شب بود که هرسه تاشان از خواب پريدند و ديدند آب باران از گوش هاي راه پيدا کرده و کف آغل را خيس کرده است. خوابيدن روي زمين گل آلود و نمناک امکان نداشت.\r\nخانم گوسفنده به آقاگوسفنده گفت: «چه کنيم حالا؟ کجا بخوابيم؟ »\r\nآقاگوسفنده گفت: «نمي دانم. راه چاره اي به نظرم نمي رسد. يا بايد روي همين زمين گل آلوده بخوابيم يا تا صبح بيدار بمانيم و ببينيم صبح که شد، چه کسي به دادمان مي رسد. »\r\nخانم گوسفنده گفت: «روي گل و لاي بخوابيم يا تا صبح بيدار بمانيم؟ اين هم شد راه چاره؟ نمي دانم تو با اين عقل و هوشت، چرا مشکل گشاي مردم دنيا نشده اي! بلند شو مَرد! کاري بکن! »\r\nآقاگوسفنده گفت: «چه کار کنم؟ تو که دست تمام عاقلان دنيا را از پشت بسته اي، بگو که توي اين تاريکي شب، چه مي توانم بکنم؟ »\r\nخانم گوسفنده گفت: «چه مي دانم؟ برو ببين آب از کجا به آغل راه پيدا کرده. راه ورود آب را ببند.\r\nآغلمان را آب برداشت آقا! بجنب! من که نمي توانم تا صبح سر چهار تا دست و پاهام بيدار بمانم. »\r\nآقاگوسفنده گفت: «بستن راه ورود آب، بيل مي خواهد، کلنگ مي خواهد، زور بازو مي خواهد که هيچ کدامش را ما گوسفندها نداريم. »\r\nخانم گوسفنده گفت: «اين را که خودم هم مي دانم که بيل و کلنگ نداريم. اينکه ديگر گفتن ندارد. »\r\nآقاگوسفنده که از غرغر کردن خانم گوسفنده عصباني شده بود، صدايش را بلند کرد و گفت: «مثل اينکه تو هم جز مسخره کردن من، کار ديگري بلد نيستي. فکر مي کني خودت خيلي مي فهمي؟ اين راه حل که بايد راه ورود آب بسته شود، به فکر هر بره اي هم مي رسد. »\r\nخانم گوسفنده که ديد آقا گوسفنده هم حق دارد و هم خيلي از دستش عصباني شده، ديگر حرفي نزد و بغض کرد و حالا گريه نکن، کي گريه کن.\r\nبزچلاقه با اينکه کنار آقاگوسفنده و خانم گوسفنده ايستاده بود، حرفهاي آنها را نمي شنيد. از همان اول هم فهميده بود که نه امکانات و قدرت بستن راه ورود آب را دارد و نه مي تواند شب تا صبح روي چهار لنگه دست و پايش بايستد و بيدار بماند. با اين که خوابش مي آمد، فکر کرد و فکر کرد. ناگهان، انگار که به راه حل درستي رسيده باشد، جستي زد و به طرف کُپه علوفه هاي خشک رفت. آقاگوسفنده و خانم گوسفنده وقتي حرکت يکباره بزچلاقه را ديدند، از گريه و دعوا دست برداشتند، ببينند دوستشان چه مي کند. بزچلاقه با سر به جان بسته هاي علوفه هاي خشک افتاد. به آنها شاخ مي زد و سعي مي کرد جا به جايشان کند.\r\nآقاگوسفنده و خانم گوسفنده چشم دوخته بودند به بزچلاقه و نمي دانستند مي خواهد چه کار کند. بزچلاقه آنقدر سرش را به کپه هاي علوفه خشک کوبيد که توانست آ نها را کنار هم قرار دهد و با کنار هم گذاشتن آنها، تختخواب بزرگي که شب وحشتناک آقا گوسفنده خيلي هم از زمين نمناک فاصله داشت، بسازد. و خانم گوسفنده کارش که تمام شد، بدون اينکه به دوستانش چيزي بگويد، به بالاي کپه علوفه هاي خشک جست زد و دراز کشيد. خسته شده بود. خواب بعد از خستگي دلنشين بود. آقاگوسفنده و خانم گوسفنده نگاهي به يکديگر انداختند و گفتند که چرا اين راه حل به فکر ما دو تا نرسيد. بعد، از تختخواب علوف هاي بزچلاقه بالا رفتند و روي آن دراز کشيدند که بخوابند. خانم گوسفنده گفت: «اگر بزچلاقه نبود، ما چه کار می کردیم.\r\n"},{"id":1111,"category_id":8,"category_code":"s8","source_id":72,"title":"درخت پیر","content":"کلاغ شروع کرد به غار غار کردن، درخت پیر گوشهایش را گرفت و با صدایی لرزان گفت: هیس.... آرام باش. آواز نخوان. سرم درد می گیرد... حوصله ندارم... کلاغ ساکت شد و آرام روی شاخه نشست.\r\nدارکوب نشست روی شاخه ی دیگر و شروع کرد به نوک زدن و تق تق کردن. درخت پیر شروع کرد به ناله کردن و گفت نه نه نزن. خواهش می کنم نوک نزن. من طاقت ندارم... اعصاب ندارم... زود خسته می شوم... دارکوب ناراحت شد و رفت.\r\nپرستو دوستانش را دعوت کرده بود به لانه اش، که روی یکی از شاخه های درخت پیر بود. درخت پیر تا دوستان پرستو را دید، گفت: خواهش می کنم سر و صدا نکنید من می خواهم بخوابم... مریضم ... حوصله ندارم... پرستو هم از درخت پیر دلگیر شد.\r\nغرزدن و زود خسته شدن درخت پیر، کم کم همه ی پرندگان را ناراحت کرد. پرنده ها یکی یکی با درخت پیر قهر کردند و رفتند و فقط کلاغ پیش او ماند. کلاغ، از بقیه ی پرنده ها باوفاتر بود و درخت پیر را خیلی دوست داشت. او یادش می آمد که از زمانی که یک جوجه کلاغ بود روی شاخه های همین درخت زندگی کرده بود. یادش می آمد که چقدر همین درخت، که الان پیر و کم حوصله شده است، با او مهربان بود و به او محبت می کرد. به خاطر همین هیچ وقت حاضر نبود از پیش او برود.\r\nکلاغ پیش او ماند اما بدون سر و صدا و وروجک بازی . کلاغ آرام و با حوصله با درخت پیر زندگی می کرد.\r\nیک روز درخت پیر که خیلی دلتنگ شده بود، به کلاغ گفت: دلم برای پرستو و دارکوب تنگ شده است. ای کاش آنها هم مثل تو کمی مهربان بودند و با من قهر نمی کردند. من دیگر پیر شده ام و نمی توانم سروصداهای زیاد را تحمل کنم. نمی توانم مثل قبل، زحمت بکشم و کار کنم. بیشتر وقتها می خواهم بخوابم اما همه ی پرنده ها را مثل تو دوست دارم و دلم می خواهد هر روز آنها را ببینم اما آنها خیلی زود از دست من عصبانی می شوند و با من قهر می کنند.\r\nکلاغ حرفهای درخت پیر را شنید و خیلی غصه خورد او تصمیم گرفت هر طوری شده به بقیه ی پرنده ها یاد بدهد که چگونه با درختان پیر با مهربانی رفتار کنند. کلاغ هر روز با پرنده ها صحبت کرد و از مهربانی های قدیم درخت پیر برایشان خاطرات زیادی نقل کرد.\r\nپرنده ها دوباره دلشان برای درخت پیر تنگ شد و پیش او برگشتند اما از این به بعد وقتی پیش درخت پیر می آمدند آرام حرف می زدند و مراقب رفتارشان بودند تا درخت پیر اذیت نشود. اینطوری دوباره شادی و صفا در بین شاخ و برگ درخت پیر پیدا شد و همه از هم راضی و خوشحال بودند.\r\n"},{"id":1112,"category_id":8,"category_code":"s8","source_id":73,"title":"ببر و مرد مسافر","content":"روزی چند مسافر ببری را به دام انداختند و او را در قفس اسیر کردند.\r\nآن ها قفس او را در کنار جاده قرار دادند تا همه ببینند ببری که تاکنون جان حیوانات و بچه های بسیاری را گرفته الان خود به دام افتاده.\r\nحالا ببر توی یک دردسر بزرگ افتاده بود. او نه غذایی برای خوردن داشت و نه آبی برای نوشیدن. ببر درنده از هر رهگذر و عابری درخواست می کرد تا او را نجات دهد و به آن ها قول می داد اگر او را از این قفس نجات دهند کاری به کار آن ها نخواهد داشت. اما هیچ کس حرف ببر وحشی و درنده را باور نمی کرد.\r\nاما در آخر مسافری مهربان بعد از این که قول ببر را شنید حاضر شد او را از بند رها کند.\r\nببر وحشی به محض این که از قفس آزاد شد می خواست مسافر مهربان را بکشد. مسافر از او خواست تا به قول و عهدش وفا کند. اما حیوان درنده توجهی به التماس مرد مسافر نمی کرد. ببر وحشی گفت: من گرسنه ام و تو هم شکار منی، چگونه تو را آزاد کنم؟\r\nدر همین حین، روباهی به آن جا رسید. او تمام حرف های ببر و مرد مسافر را شنید و گفت: باور نمی کنم چنین ببر بزرگی در چنین قفس کوچکی جا شده باشد.\r\nببر گفت: الان به تو نشان می دهم که چگونه در قفس جاشدم. و بعد داخل قفس شد و روباه ناقلا فوراً در قفس را بست و با مرد مسافر از آن جا دور شد.\r\n"},{"id":1113,"category_id":8,"category_code":"s8","source_id":74,"title":"روباه در یک روز برفی","content":"درآن كوه بزرگ خانه كوچك عمو حسن قرار داشت. او به تنهایی در خانه ی خیلی كوچكی در میانه راه بالائی كوه زندگی می كرد. خانه كوچك او بیرون از جنگل كاج ساخته شده بود. او قد بلندی نداشت ولی خیلی پیر و عاقل بود. او ریش سفید رنگ بلندی داشت و یك كلاه خیلی بامزه می پوشید . با اینكه تنها زندگی می كرد هنوز هم دوستان زیادی داشت. همه حیوانات و پرندگان دوستانش بودند .\r\nهوا سرد می شد و پرندگان به مناطق گرمسیر جنوب پرواز می كردند. زمستان نزدیك بود. برخی از حیوانات كه مجبور بودند در جنگل بمانند در بدنشان برای مدتی طولانی غذا ذخیره می كردند و به زودی به خواب زمستانی می رفتند تا اینكه بهار برسد.\r\nاین داستان درباره یكی از این حیوانات است كه در این جنگل زندگی می كرد.یكی از صبح های اواسط بهمن ماه، روباه در جستجوی یافتن صبحانه ای میان جنگل آهسته قدم می زد . هوا بد بود، برف زمین را پوشانده بود و باد هر لحظه شدیدتر می شد. در این موقع از سال غذا به سختی گیر می آمد بنابراین روباه مجبور بود مسافت بیشتری را نسبت به گذشته برای یافتن غذا جستجو كند . برف و باد شكار كردن را خیلی سخت می كرد. باد هر لحظه شدیدتر می شد. روباه می خواست به لانه اش برگردد اما پیش خودش گفت \"یك كم دیگر هم می گردم، آخه خیلی گرسنه هستم و نمی توانم بودن غذا برگردم.\" \r\nیک دفعه صدای زوزه شدید باد در میان درختان پیچید . روباه كه از چیزی خبر نداشت در زیر یك درخت فرسوده كه ریشه محكمی نداشت در حال راه رفتن بود كه صدای شكستن چیزی را شنید، همانطور كه به اطراف برمی گشت كه بفهمد این صدا از كجا می آید یك درخت شكسته سیاه بزرگی را دید كه به روی او می افتاد. شروع به دویدن كرد تا آنجایی كه می توانست سریع می دوید، اما پنجه هایش در داخل برفهای عمیق گیر می كردند. وقتی كه درخت شكسته كنار او روی زمین افتاد او فكر كرد كه از این حادثه نجات پیدا كرده . اما در همان لحظه ای كه او می خواست بپرد تا از آن وضعیت نجات پیدا کند، تنه ی درخت به آهستگی چرخید و روی دم او افتاد. \r\nروباه بیچاره، گرسنه بود و كلی از خانه اش دور بود و دمش هم در زیر درخت بزرگی گیر كرده بود.خوشبختانه برف آرام می بارید و او هم صدمه جدی ندیده بود اما او ابدا خوشحال نبود. كم كم شدت بارش برف بیشتر شد . روباه به این دردسر بزرگ فكر می كرد، اگر برف همینطور ببارد بعد از مدتی حتی روی سرش را هم می پوشاند،حالا او خیلی نگران بود.\r\nآن روز صبح عمو حسن مثل همیشه صبح زود برای قدم زدن در میان جنگل از خانه بیرون آمد. راه زیادی نرفته بود كه صدایی شنید. به اطراف نگاه كرد تا ببیند آیا می تواند محل آن صدا را پیدا كند. فهمید كه صدا از طرفی می آید كه درختی افتاده است.\r\nتا آنجا كه پاهای پیرش می توانست وزن او را تحمل كند در میان برف سریع به آن سمت دوید. وقتی كه كنار درخت شكسته رسید هیچ كسی را ندید تا اینكه به آن طرف درخت رفت و در آنجا یك روباه كوچولو دید كه از باد و برف در خودش فرو رفته و خودش را جمع كرده است. عموحسن او را شناخت و پرسید: اینجا چیكار می كنی ؟ روباه كوچولو با صدای بغض آلود ماجرا را تعریف كرد. او خیلی سردش بود و گفت: من ساعتهاست كه اینجا گیر افتادم ،دیگه خیلی خسته ام ، خیلی تلاش كردم تا از این وضعیت رها شوم اما هنوز دم من گیر است. پیرمرد گفت: من سعی خواهم كرد كه درخت را تكان دهم تا تو رها شوی. اما عموحسن آنقدر قوی نبود و هر قدر تلاش كرد نتوانست تنه درخت را حركت دهد.\r\nوقتی عموحسن موفق به تكان دادن تنه درخت نشد. به فكر فرو رفت و گفت: حالا فهمیدم كه چه باید بكنم . او در جنگل به دنبال چیزی می گشت تا اینكه با یك شاخه درخت دیگر برگشت . او تلاش كرد با آن چوب، تنه درخت بزرگ را كمی بالاتر ببرد اما او به اندازه كافی قوی نبود. او یك قدم به عقب رفت و با دقت به تنه درخت نگاه كرد. او یك نگاهی به برف كرد كه همه اطرافش را پوشانده بود و سپس نگاهی به آسمان انداخت. به نظر می رسید كه بارش برف برای مدت طولانی ادامه خواهد داشت و آنها مجبورند كه سریعتر كاری كنند. \r\nعمو حسن فكری كرد. او با سرعت به كلبه اش برگشت وقتی كه به آنجا رسید به سراغ ابزار كارش رفت و با سرعت برگشت در حالی كه یك اره بزرگ را با خود حمل می كرد.\r\nوقتی به جنگل برمی گشت ، امیدوار بود كه مسیر را بخاطر بیاورد . زیرا بارش برف ردپای او را پوشانده بود.. بارش برف سنگین تر شده بود و باد شدیدتر می وزید اما عموحسن به راهش ادامه داد. او به محلی رسید كه روباه آنجا بود اما تمام آنچه كه او می توانست ببیند تنه درخت و برفی بود كه تمام زمین را پوشانیده بود. او فكر كرد كه دیر رسیده است اما او یك بینی قهو ه ای در میان برف دید . او با سرعت هر چه بیشتر با دستهایش شروع به خالی كردن برفهایی كرد كه دور روباه را پوشانده بودند. او هنوز زنده بود.او شروع به اره كردن درخت كرد اما نه به دو نیمه ، بلكه به سه قسمت. دو قسمت كه بلندتر بودند در هر انتها و یك قسمت كوچكتر در وسط، یعنی همان جائی كه دم روباه گیر كرده بود . او روباه را بلند كرد و در پتویی كه از كلبه اش آورده بود پیچاند.\r\nپیرمرد به آهستگی در حالیكه روباه را بغل كرده بود به كلبه اش برگشت. آتش خوبی را روشن كرد و یك سوپ خوشمزه برای خودشان درست كرد. آن دو، روز سختی را گذرانده بودند و خیلی خسته بودند روباه روی كفپوش كنار شومینه و پیرمرد روی صندلی مورد علاقه اش بخواب رفتند. وقتی كه صبح از خواب برخاستند هر دو مایل بوند كه روباه در تمام طول زمستان كنار عمو حسن بماند و این دقیقا همان اتفاقی بود كه رخ داد.\r\n"},{"id":1114,"category_id":8,"category_code":"s8","source_id":75,"title":"بهترین عموی دنیا","content":"عمو سعید من یک ورزشکار قوی است. من او را خیلی دوست دارم. یک روز به او گفتم تو بهترین عموی دنیا هستی. عمو سعید کمی فکر کرد و گفت :نه من بهترین عموی دنیا نیستم ولی بهترین عموی دنیا را می شناسم.\r\nگفتم خوب او کیست؟\r\nعمو سعید گفت بهترین عموی دنیا حضرت عباس علیه السلام است.\r\nگفتم چرا او بهترین عموی دنیاست؟\r\nعمو سعید گفت: خوب قضیه اش مفصل است.\r\nگفتم مفصل باشد خواهش می کنم برایم تعریف کنید.\r\nعمو سعید گفت: در کربلا، کاروان امام حسین به وسیله دشمنان محاصره شده بود. دشمنان سنگدل ،نمی گذاشتند که امام و یارانش از آب رودخانه ی فرات استفاده کنند. قحطی آب، خیلی زود همه ی اهل حرم را تشنه کرد. بیشتر از همه، بچه ها تشنه شده بودند.\r\nاما بچه های امام حسین می دانستند که عموی شجاعشان می تواند از میان محاصره کنندگان عبور کند و برایشان آب بیاورد. چون عموی آنها یک فرمانده ی بسیار قدرتمند و یک شمشیر زن ماهر بود.\r\nوقتی تشنگی شدید شد، حضرت عباس به دستور امام حسین، همراه بیست نفر دیگر به سمت گوشه ای از رودخانه ی فرات حمله کرد. او با شجاعت و مهارت زیادی مشغول جنگیدن با سربازان یزید شد و حواسشان را پرت کرد تا دوستانش بتوانند مشکها را پر از آب کنند. مشکها که پر شد همگی توانستند از دست سربازهای یزید فرار کنند و آب را برای اهل حرم بیاورند.\r\nبچه هایی که جلوی خیمه ها ایستاده بودند دیدند عمو در حالیکه مشک آب روی دوشش گرفته ،به سمت آنها می آید. بچه ها از پیروزی عمو خوشحال شدند.\r\nمن از حرفهای عمو سعید خوشم آمد و ذوق کردم اما عمو سعید با ناراحتی گفت: روز عاشورا اتفاق دیگری افتاد. آن روز این عموی مهربان دیگر نتوانست بچه ها را خوشحال کند.\r\nاو با مشک آب به سمت رودخانه رفت اما بعضی از سربازان، پشت درختها پنهان شده بودند و از پشت سر و از پهلو ،به او حمله کردند و او را تیرباران کردند.\r\nعمو عباس با وجود اینکه از دستهایش خون می ریخت، مشک آب را به دندانش گرفته بود و سعی می کرد هر طوری شده مشک آب را به خیمه ها برساند. اما دشمنان، او را محاصره کردند و مشکش را پاره کردند و خودش را هم به شهادت رساندند.\r\nعمو سعید، آخر قصه را در حالی برایم تعریف کرد که اشک می ریخت. من هم آن روز برای بهترین عموی دنیا گریه کردم .\r\n"},{"id":1115,"category_id":8,"category_code":"s8","source_id":76,"title":"کفشدوزکها","content":"یکی بودیکی نبود غیر از خدا هیچ کس نبود. بابا کفشدوزک و مامان کفشدوزک با پسرشان خال خالی در جنگل سبز زندگی می کردند.مامان کفشدوزک کفشهای قشنگی درست می کرد.همه ی حیوانات جنگل مشتری کفشهای او بودند.بابا کفشدوزک هم کفش های دوخته شده را به فروشگاه جنگل می برد و می فروخت.خال خالی کوچولو خیلی دلش می خواست مثل مادرش کفش بدوزد ولی پدر و مادرش به او می گفتند:«تو هنوز کوچکی و کار کردن برای تو زوده،تو حالا حالاها باید بازی کنی.»خال خالی کوچولو هم توی کارگاه ،پیش مامانش می نشست و کفش دوختنش را تماشا می کرد.\r\nیک روز خبر خوشی توی جنگل پیچید،خبر عروسی خاله سوسکه.این خبر حیوانات را به فکر خریدن کفش و لباس نو انداخت.همه دلشان می خواست با کفش و لباس نو در جشن عروسی شرکت کنند.باباکفشدوزک اسم حیواناتی را که کفش می خواستند نوشت و به مامان کفشدوزک داد تا برایشان کفش بدوزد.\r\nمامان کفشدوزک چندین روز پشت سر هم کارکرد.آنقدر دوخت تا خسته شد اما برای تمام حیواناتی که کفش سفارش داده بودند،کفش دوخت.بابا کفشدوزک تمام کفش ها را به حیوانات داد.آنها خوشحال شدند و از او و مامان کفشدوزک تشکر کردند.در جنگل سبز رسم بر این بود که هرکس برای دیگران کاری انجام می داد،آنها هم در مقابل برایش کاری انجام می دادند؛مثلاً برایشان خوراکی می آوردند.حیوانات جنگل آنقدر خوراکی برای بابا و مامان کفشدوزک آوردند که انبارشان پرشد.آنها از این موضوع خوشحال بودند ولی مامان کفشدوزک آن قدر کار کرده بود که خسته و بیمارشد و در رختخواب خوابید.خال خالی و بابا کفشدوزک هم مواظبش بودند تا حالش خوب شود.\r\nسه روز بیشتر به عروسی خاله سوسکه نمانده بود که آقا و خانم هزارپا به سراغ مامان کفشدوزک آمدند و از او خواستند برایشان کفش بدوزد تا بتوانند با کفش نو در جشن عروسی خاله سوسکه شرکت کنند، اما وقتی دیدند او در رختخواب خوابیده و حالش خوب نیست،ناراحت شدند و رفتند.\r\nفردای آن روز وقتی مامان و بابا کفشدوزک از خواب بیدار شدند،دیدند یک عالمه کفش اندازه ی پای هزارپاها توی کارگاه کنارهم چیده شده است.آنها با تعجب به کفشها نگاه می کردند و نمی دانستند چه کسی آن همه کفش را دوخته است.اما وقتی در گوشه ی کارگاه خال خالی را دیدند که لنگه کفشی در دست دارد و خوابش برده است،فهمیدند کسی که کفش ها را دوخته،خال خالی بوده که تمام شب بیدار مانده و برای خانم و آقای هزارپا کفش دوخته است.آقای کفشدوزک خال خالی را بغل کرد و او را توی تختش گذاشت تا راحت بخوابد.مامان کفشدوزک هم استراحت کرد تا بلکه حالش زودتر خوب شود.باباکفشدوزک به خانه ی هزارپاها رفت و کفش های آماده شده را به آنها داد.هزارپاها خیلی خوشحال شدند و به بابا کفشدوزک مقداری داروی گیاهی دادند تا به مامان کفشدوزک بدهد .باباکفشدوزک داروها را به مامان کفشدوزک داد.حال مامان کفشدوزک خیلی زود خوب شد و توانست همراه خال خالی و باباکفشدوزک در جشن عروسی خاله سوسکه شرکت کند.روزجشن عروسی،تمام حیوانات کفشهای نو پوشیده بودند و می رقصیدند.هزارپاها که فهمیده بودند کفشهای آنها را خال خالی دوخته،کفشهایشان را به دوستانشان نشان می دادند و می گفتند:« ببینید خال خالی کوچولو چقدر هنرمنده!این کفش ها را خال خالی دوخته.ببینید چقدر قشنگ دوخته،دستش دردنکنه،حالا مامان کفشدوزک یه همکار خوب و زرنگ داره و می تونه برای همه کفش بدوزه.»مامان کفشدوزک و بابا کفشدوزک هم خوشحال بودند و به پسرشان افتخار می کردند.\r\nآن روز حیوانات جنگل سبز به افتخار خال خالی و پدر و مادرش دست زدند و هورا کشیدند و از آنها تشکر کردند.خاله سوسکه هم دسته گل قشنگی را که توی دستش گرفته بود به خال خالی کوچولو هدیه کرد.\r\n"},{"id":1116,"category_id":8,"category_code":"s8","source_id":77,"title":"پسته ی اخمو","content":"\r\nهمه پسته ها خندان و خوشحال بودن . برای همین خیلی راحت باز می شدن. اما یکی از پسته ها اخمو بود .\r\nهیچ کس دوست نداشت پسته اخمو رو برداره . وقتی همه پسته ها تموم شدن، پسته اخمو تنها توی ظرف باقی مونده بود. بچه شکمو بلاخره دلش آب شد و پسته اخمو رو برداشت.\r\nهر چی بهش نگاه کرد پسته اخمو نخندید. همین طور سفت سفت دهنشو بسته بود. بچه شکمو چند تا لطیفه برای پسته اخمو تعریف کرد اما بازم نخندید . قلقلکش داد.\r\nبازم خندش نگرفت. بچه شکمو یه نگاهی این ور کرد یه نگاهی اونور کرد بعد یواشکی پسته اخمو رو گذاشت توی دهانش . یک گاز محکم ازش گرفت. ولی هیچی نشد .\r\nاین دفعه پسته اخمو رو گذاشت روی دندونای آسیاش . محکم محکم فشارش داد. یه دفعه پسته اخمو تقی صدا کرد.\r\nبچه شکمو پسته اخمو رو از دهانش دراورد البته درسته نبود خورد خورد شده بود. تازه لای اون خرده ها به غیر از پوست پسته و مغز پسته، یه خورده دندون شکسته هم بود.\r\nحالا دیگه به جای پسته اخمو، بچه شکمو ،اخمو شده بود. آخه کی با دندون شکسته می تونه بخنده! شاید پسته های اخمو هم نمی خندن که کسی تو دهنشونو نتونه ببینه.!!\r\n"},{"id":1117,"category_id":8,"category_code":"s8","source_id":78,"title":"نی نی تنبل","content":"نی نی و مامان می خواستن با هم برن خونه ی مامان بزرگ . مامان، نی نی رو بغل کرده بود ولی نی نی دوست داشت خودش راه بره. نی نی اشاره می کرد به زمین و غر می زد .مامان نی نی رو روی زمین گذاشت و گفت حالا بدو برو. نی نی یه خورده رفت ولی یه دفعه یه گنجشک توی کوچه دید و ایستاد و تماشا کرد. مامان حواسش به گنجشک نبود. هی صدا می زد نی نی بیا دیگه چرا وایسادی؟ نی نی با انگشتش گنجشکو به مامان نشون داد ولی مامان بازم گنجشکو ندید . مامان خسته شد و گفت وای نی نی چرا راه نمیای خسته شدم. گنجشک پرید و رفت . نی نی دوباره دنبال مامان راه افتاد .\r\nنی نی چند قدم بدو بدو رفت ولی یه دفعه یه سنگ کوچولو رفت توی کفشش. نی نی وایساد و دیگه راه نرفت .مامان دست نی نی رو گرفت و کشید و گفت بچه چرا راه نمیای؟ نی نی گفت آخ آخ . و هی کج کج راه رفت . مامان خم شد پای نی نی رو ببینه. ولی وقتی کفش نی نی رو دراورد سنگه خودش افتاد . به خاطر همین مامان سنگو ندید گفت نی نی پات که سالمه . کفشات هم تمیزن . آخه چرا اذیت می کنی راه نمی ری ؟\r\nنزدیک خونه ی مامان بزرگ که رسیدن مامان در زد ولی نی نی یه مورچه اسبی روی زمین دید و نشست و می خواست اونو بگیره . مامان رفت تو خونه مامان بزرگ و هی صدا زد نی نی بیا دیگه نی نی چرا نشستی رو زمین . نی نی چقد امروز تنبلی !\r\nنی نی هی مورچه اسبی رو به مامان نشون می داد و می گفت ای ... ای ... ای\r\nمامان اومد ببینه نی نی چی می گه و به چه چیزی اشاره می کنه . ولی وقتی مامان اومد مورچه اسبی رفت توی سوراخ دیوار .\r\nمامان هر چی نگاه کرد هیچی ندید. دیگه خسته شد و نی نی رو بغل کرد و برد تو .\r\nنی نی دوست داشت هنوز با مورچه اسبی بازی کنه و هی جیغ می زد و پاهاشو تکون می داد. مامان توجهی نکرد و نی نی رو برد و گذاشت تو بغل مامان بزرگ و گفت وای عزیز از دست این بچه ی تنبل خسته شدم .همش می خواد یه جا وایسه یا بشینه .\r\nمامان بزرگ نی نی رو بغل کرد و بوسید و گفت قربون نی نی تنبل خودم برم . نی نی خندید و خودشو برای مامان بزرگ لوس کرد.\r\nاون روز نی نی تا شب خونه ی مامان بزرگ بازی و شیطونی کرد و به مامانش نشون داد که تنبل نیست.\r\n"},{"id":1118,"category_id":8,"category_code":"s8","source_id":79,"title":"کفش های نو","content":"مدرسه فریبا كوچولو به خانه‌شان خیلی نزدیك بود و او هرروز خودش صبح‌ها می‌رفت و ظهرها هم برمی‌گشت البته مادرش جلوی در می‌ایستاد و مواظب او بود. كنار مدرسه یك مغازه كفش‌فروشی بود كه فریبا وقتی تعطیل می‌شد، چند لحظه‌ای می‌ایستاد و از پشت شیشه‌ كفش‌ها را نگاه می‌كرد، چون كفش‌های بچگانه خوشگل و رنگارنگی داشت.\r\nاین كار برایش بسیار لذتبخش بود و حتی گاهی وقت‌ها دلش می‌خواست همه كفش‌های مغازه مال او بودند! دیدن مغازه كار هر روز فریبا شده بود و مادرش هم كه از دور همه چیز را می‌دید از او سوال می‌كرد كه آنجا چه خبر است كه مدام نگاه می‌كنی و فریبا هم در جواب می‌گفت كه كفش‌ها را دوست دارم.\r\nیكی از روزهایی كه طبق معمول جلوی مغازه آمد دید كه یك جفت كفش كتانی سفید و صورتی خیلی قشنگ داخل ویترین گذاشته شده است. خیلی از آنها خوشش آمد و با خودش فكر كرد كه اگر می”‹توانست این كتانی‌ها را بخرد چقدر خوب می‌شد. برای همین وقتی به خانه رسید بدون معطلی موضوع كفش‌ها را به مادرش گفت و از او خواست كه كفش‌ها را برایش بخرد. اما مادرش یادآوری كرد كه كفش‌های خودش را یكی دو ماه قبل خریده‌اند و هنوز برای خرید كفش نو زود است، اما فریبا این‌قدر اصرار كرد كه مادر گفت باید صبر كند تا موضوع را با پدرش در میان بگذارد.\r\nفردای آن روز وقتی فریبا به خانه آمد اولین چیزی كه از مادرش پرسید این بود كه نظر بابا در مورد خرید كفش چه بوده است و مامان هم جواب داد كه او گفته فعلا نمی‌شود و اصرار فریبا هم هیچ فایده‌ای نداشت و با این كه ناراحت شده بود اما دیگر در موردش حرفی نزد.\r\nروزها یكی پس از دیگری گذشتند و او سعی می‌كرد از مدرسه كه تعطیل می‌شود به سرعت به خانه بیاید و اصلا به مغازه نگاه نكند تا بتواند ماجرا را فراموش كند. اما یك روز وقتی از جلوی مغازه می‌گذشت یواشكی یك نگاه كوچولو به ویترین آن انداخت و با تعجب متوجه شد كه كفش‌ها نیستند خیلی ناراحت شد اما كاری نمی‌توانست انجام دهد و با همان حال به خانه آمد و به هیچ كس هم چیزی نگفت.\r\nبعد از ظهر همان روز وقتی بابا به خانه آمد فریبا از او خواست كه با هم بروند و برایش یك دفتر بخرند و بابا هم قبول كرد و گفت كه اتفاقا من هم یك كاری دارم كه باید بیرون بروم.\r\nچند دقیقه بعد دو نفری برای خرید از خانه خارج شدند و كار‌های‌شان را كه انجام دادند موقع برگشت به مغازه كفش‌فروشی كه رسیدند بابا از فریبا خواست كه با هم داخل مغازه بروند كه آنجا هم یك كار كوچكی دارد. وارد مغازه كه شدند اول سلام كردند و بعد بابا گفت: حسن آقا ببخشید می‌شه اون امانتی من رو بدید.\r\nحسن آقا هم با لبخند و البته با نگاهی به فریبا گفت:\r\nبله، حتما.\r\nو بعد یك جعبه كفش را به دست بابا داد و او هم جعبه را به طرف فریبا گرفت و گفت: فریبا جون این مال شماست.\r\nدختر كوچولو كه از كار‌های بابا و آقای مغازه دار تعجب كرده بود، گفت: مال من !؟\r\n- بله.\r\n- چیه باباجون ؟\r\n- بازش كن خودت می‌فهمی.\r\nفریبا جعبه را از بابا گرفت و درآن را باز كرد و از دیدن كفش‌های داخل آن بسیار خوشحال شد و با هیجان زیادی گفت: بابا جون؛ بابا جون.\r\nچند لحظه‌ای ساكت شد و به كفش‌ها نگاه كرد و دوباره گفت: من ظهر دیدم كفش‌ها نیستن؛ پس كار شما بوده.\r\nو بعدش دست بابا را محكم در دستش گرفت و گفت: ممنونم بابا جون، خیلی خوشحالم؛ حالا بیا بریم به مامانم همه چی رو بگیم.\r\nو هردو خوشحال و خندان از مغازه بیرون آمدند و به سمت خانه رفتند.\r\n"},{"id":1119,"category_id":8,"category_code":"s8","source_id":80,"title":"ماهی کوچولو","content":"یکی بود، یکی نبود. تازه بهار شده بود و تپّه ی بلند دهکده پر از علف های سبز و گل های رنگارنگ بود. پروانه ها از پیله هاشون در اومده بودن و روی گل ها بازی می کردن و خبر اومدن بهار رو به همه می دادن.\r\nبالای تپه، خونه حسن بود.\r\nحسن خیلی از اومدن بهار خوشحال بود و دلش می خواست بره بیرون و روی سبزه ها بازی کند، ولی نمی تونست. چون مریض بود. چند روز گذشت و حسن هنوز بیرون نیومده بود. گل ها و پرنده ها و ماهی های روی خونه دلشون براش تنگ شده بود. آخه حسن خیلی اون ها رو دوست داشت و قبل از زمستون سال قبل همیشه باهاشون حرف می زد، مراقبوشون بود. به گل ها آب می داد به ماهی ها نون می داد، براشون آواز می خوند، خلاصه تمام بهار و تابستون سال قبل حسن و گل ها و ماهی ها با هم بازی کرده بودن و حسابی بهشون خوش گذشته بود.\r\nبعد از چند روز گل ها گفتن: آخه پس چرا حسن نمی یاد تا برامون آواز بخونه. ماهی ها گفتن: چرا نمی یاد بهمون غذا بده و بازی کنه. ماهی ها یه فکر خوب کردن. به پروانه گفتن پرواز کن و از پنجره اتاق برو تو و از حسن خبر بیار، پروانه هم سریع بال زد و رفت. هنوز چیزی نگذشته بود که برگشت و گفت: حسن مریضه، سرما خورده، ولی مامانش براش یه سوپ خوشمزه درست کرده بود و داشت بهش می داد که بخوره.\r\nبهشم گفت که می تونه تا دو روز دیگه بره بیرون. دو روز گذشت و حسن که حسابی استراحت کرده بود، حالا قوی و سالم دویید بیرون و به همه گفت سلام. بعد حسن و ماهی ها و گل ها با هم شعر بهار رو خوندن و دوباره بازی و خوشحالی کردن.\r\n"},{"id":1120,"category_id":8,"category_code":"s8","source_id":81,"title":"عروسک بهانه گیر","content":"مهسا یه عروسک جدید خریده بود که هر وقت دکمه ی روی شکمش رو فشار می داد می گفت :\"مامان ... مامان من به به می خوام\" \r\nبعد مهسا یه شیشه شیر اسباب بازی بهش می داد .عروسکش شیرشو می خورد و با لبخند از مهسا تشکر می کرد\r\nمهسا چند روز با خوشحالی با عروسکش بازی می کرد و از خوش اخلاقی عروسکش لذت می برد..اما یواش یواش عروسک مهسا بداخلاق شد .یه روز صبح وقتی مهسا دکمه ی عروسکشو زد عروسکش حرف نزد اخم کرد.\r\nمهسا دوباره دکمشو زد باز عروسکش حرف نزد. بار سوم که مهسا می خواست دکمه ی عروسکشو بزنه عروسکش جیغ زد!\r\nمهسا می خواست شیشه ی شیرشو بهش بده اما عروسک دلش نمی خواست بخوره .می خواست بهانه بگیره که اینو نمی خوام اونو دوست ندارم ...\r\nمهسا خیلی ناراحت شده بود .عروسکشو بغل کرد و برد دکتر .\r\nآقای دکتر از مهسا پرسید عروسکتون چی شده برای چی آوردینش دکتر؟\r\nمهسا گفت خیلی بداخلاق شده می ترسم مریض شده باشه!\r\nدکتر ، عروسک مهسا رو معاینه کرد و گفت فکر کنم مریضی بهانه گیری رو از کسی گرفته . شاید یه نفر تو خونه ی شما خیلی بهانه می گیره و عروسک شما ازش یاد گرفته.\r\nمهسا خجالت کشید و هیچی نگفت .\r\nبعد دکتر گفت دوای درد عروسک شما اینه که دیگه کسی توی خونه غر نزنه .همه باید خوش اخلاق و مهربون باشن تا عروسکتون دوباره حالش خوب بشه و خوش اخلاقی و مهربونی دوباره بهش برگرده.\r\nمهسا برگشت خونه و سعی کرد خودش عروسکشو درمان کنه. شب که نشست سر سفره ی شام عروسکش رو هم کنار خودش گذاشت تا عروسکش کارهای مهسا رو ببینه و یاد بگیره .\r\nمامان یه بشقاب غذا برای مهسا کشید. مهسا از مامان تشکر کرد و همه ی غذاشو خورد .\r\nبعد با آب و صابون دست و صورتشو شست و توی جمع کردن سفره به مامان کمک کرد.\r\nعروسک مهسا هیچی نمی گفت ولی داشت همه ی کارهای خوب رو از مهسا یاد می گرفت. بعد از چند روز که دیگه مهسا توی خونه بد اخلاقی و بهانه گیری نمی کرد ،عروسکش دوباره خوش اخلاق و مهربون شد .حالا دوباره می گفت : مامّان .... مامّان .... من به به می خوام .\r\nمهسا با خوشحالی شیشه ی شیرش رو بهش می داد .عروسکش همه ی شیرشو می خورد و خیلی زیبا لبخند می زد و تو بغل مهسا آروم آروم به خواب می رفت.\r\n"},{"id":1121,"category_id":8,"category_code":"s8","source_id":82,"title":"کاکتوس و جوجه تیغی","content":"یک روز سولماز کوچولو و مادرش به بازار رفتند. سر راهشان یک گل فروشی بود. سولماز کوچولو جلوی گل فروشی ایستاد. دست مادر را کشید و گفت: «مامان ... مامان... از این گل های خاردار برایم می خری؟»\r\nمادر به گل های پشت شیشه نگاه کرد و گفت: «اینها را می گویی؟ اینها کاکتوسند.»\r\nبعد هم به داخل گل فروشی رفتند و یکی از آن گلدان های کوچولوی کاکتوس را خریدند. مادر گفت: «هفته ای یکی دو بار بیشتر به آن آب نده. خراب می شود.»\r\nآن وقت رفتند، خریدشان را کردند و به خانه برگشتند. سولماز کوچولو خوشحال بود. از گل کاکتوس خیلی خوشش آمده بود. او در خانه یک جوجه تیغی کوچولو هم داشت. جوجه تیغی سولماز را دید که گلدان کوچولوی کاکتوس را به خانه آورد و گوشه اتاقش توی یک نعلبکی گذاشت. بعد هم با یک استکان به آن آب داد. جوجه تیغی کوچولو با تعجب به گل کاکتوس نگاه می کرد. او نمی دانست که آن یک گل است. با خود گفت: «چه جوجه تیغی مسخره ای! چطوری آب می خورد!»دو روز گذشت. جوجه تیغی کوچولو گفت: «باید بروم نزدیک، شاید بتوانیم با هم دوست شویم. فکر می کنم خیلی خجالتی است!»\r\nبعد هم یواش یواش به گل کاکتوس نزدیک شد. جلوی آن ایستاد و گفت: «سلام... من تیغی هستم. تو اسمت چیست؟»ولی هیچ جوابی نشنید.\r\nجوجه تیغی کوچولو باز هم با کاکتوس حرف زد؛ ولی هر چه می گفت، بی فایده بود. جوابی در کار نبود. بالاخره جوجه تیغی عصبانی شد، جلو رفت، دستش را به کاکتوس زد و گفت: «با تو هستم... چرا جواب نمی دهی؟»\r\nولی ناگهان فریادش بلند شد؛ چرا که تیغ های نوک تیز کاکتوس توی پنجه های کوچولویش فرو رفته بود.\r\nجوجه تیغی کوچولو آخ و واخ کنان گفت: «تو دیگر چه جور جوجه تیغی ای هستی؟ چقدر بد جنسی!»\r\nسولماز از دور دید که جوجه تیغی کوچولو دستش را به کاکتوس زد و دردش گرفت. تیغی کوچولو با کاکتوس قهر کرده بود و خودش را مثل یک توپ، گرد کرده بود.\r\nسولماز جلو رفت و گفت: «ناراحت نشو جوجه تیغی کوچولو... قهر نکن... این یک گل است. اسمش هم کاکتوس است. فقط گلی است که مثل تو تیغ دارد. تو با یک گل قهر می کنی ؟»\r\nجوجه تیغی کوچولو دوباره مثل اول شد. سولماز خندید و جوجه تیغی کوچولو با خود گفت: «هر گلی می خواهد باشد. هر جوری هم که می خواهد، آب بخورد؛ ولی من دیگر فقط از دور نگاهش می کنم.»و راهش را کشید و رفت.\r\n"},{"id":1122,"category_id":8,"category_code":"s8","source_id":83,"title":"قوطی کبریتهای آقا موشه","content":"آقا موشه عاشق جمع کردن قوطی کبریت بود. هر وقت یک قوطی کبریت خالی می دید، فوری آن را بر می داشت و به لانه اش می برد؛ ولی خانم موشه اصلاً از این کار خوشش نمی آمد و مدام به او غر می زد. بالاخره یک روز با عصبانیت به آقا موشه گفت: «چقدر قوطی کبریت جمع می کنی؟! اینها که هیچ استفاده ای ندارد. تو باید همین امروز همه را دور بیندازی. من دیگر نمی توانم از بین این همه قوطی کبریت درست راه بروم.»\r\nخانم موشه راه می رفت و حرص می خورد و می گفت: «اینجا جعبه، آنجا جعبه، همه جا پر از جعبه است. وای خدای من... تمام خانه پر شده. من دیگر جایی ندارم که وسایلم را بگذارم. نمی فهمم تو این همه جعبه را برای چی می خواهی!»\r\nخانم موشه آن قدر با حرص و جوش حرف می زد که نفسش بند آمده بود. آقا موشه جواب داد: «موشی جان، کسی چه می داند؟ ممکن است روزی به درد بخورند.»\r\nآقا موشه خودش هم نمی دانست با آن همه قوطی کبریت چه کار کند. فقط دلش می خواست آن ها را جمع کند. خانم موشه که دید حرف حساب به گوش آقا موشه فرو نمی رود، با عصبانیت گفت: «دیگر صبرم تمام شده. من به خانه خواهرم می روم، اگر تا زمانی که بر می گردم، یک فکری برای این قوطی کبریت ها نکنی، همه را می اندازم دور.»خانم موشه این را گفت و رفت، آقا موشه ایستاد و به قوطی کبریت هایش نگاه کرد و گفت: «چه کاری می توانم بکنم؟»\r\nفکر کرد و فکر کرد. ناگهان بالا پرید و گفت: «یک فکر خوب! یک کمد کشودار درست می کنم. آره ... آره... همه خرت و پرت ها را توی آن می ریزم. خب ... حالا به مقداری چسب و رنگ احتیاج دارم.»\r\nآقا موشه دست به کار شد. خیلی زود قوطی کبریت ها را به هم وصل کرد. بعد از مدتی قوطی کبریت ها تبدیل به یک کمد کشودار شد. او با دقت به آن نگاه کرد و گفت: «عین همان کمدی است که دیده بودم؛ فقط خیلی کوچک تر از آن است.»بعد هم آن را رنگ زد و تر و تمیز کرد. آن وقت همه خرت و پرت ها و وسایلی که این طرف و آن طرف پخش بود. توی آن ریخت. کمی بعد خانم موشه به خانه برگشت. از دیدن کمد کشودار غافل گیر شد و گفت: «وای ... چه جالب... چطوری این را درست کردی؟»\r\nآقا موشه سرش را با غرور بالا گرفت و گفت: «همیشه می گفتم آن قوطی کبریت ها یک روز به درد می خورند. امروز همان روز است.»\r\n"},{"id":1123,"category_id":8,"category_code":"s8","source_id":84,"title":"روباه پوستین دوز","content":"روزی روزگاری، روباهی پوستینی پیدا کرد. جلو رفت و آن را برداشت. خوب نگاهش کرد و با خود گفت: «عجب پوستین خوب و گرمی است. آن را بردارم، به دردم می خورد.»\r\nروباه، پوستین را روی دوشش انداخت و به راهش ادامه داد. در بین راه، گرگی به روباه رسید. با تعجب به او نگاه کرد. جلو رفت و پرسید: «عجب پوستین خوبی داری!»\r\nروباه گفت: «بله، پوستین گرم و نرمی است. زمستان که بشود، راحتم. دیگر از سرما نمی ترسم، این پوستین از پوست گوسفند درست شده. پشم های بلند آن مرا گرم نگه می دارد.»\r\nگرگ با حسرت به پوستین نگاه کرد. روباه فهمید که گرگ هم دلش می خواهد پوستینی مثل او داشته باشد، در همان لحظه نقشه ای کشید تا به گرگ کلک بزند.\r\nپس به گرگ گفت: «می خواهی پوستینی مثل این داشته باشی؟»\r\nگرگ گفت: «بله، خیلی دلم می خواهد.»\r\nروباه گفت: «اینکه کاری ندارد. خیلی راحت می توانی صاحب یک پوستین شوی.»\r\nگرگ گفت: «چطوری؟»\r\nروباه گفت: «کار من پوستین دوزی است. خودم برایت یک پوستین خوب می دوزم. فقط یک شرط دارد.»\r\nگرگ پرسید: «چه شرطی؟»\r\nروباه گفت: «شرطش این است که یک گوسفند شکار کنی و برای من بیاوری، من هم با پوست آن، پوستینی برایت می دوزم.»\r\nگرگ خوشحال شد و رفت. گوسفندی شکار کرد و آن را نزد روباه برد.\r\nروباه گوسفند را گرفت و گفت: «سه روز دیگر بیا و پوستینت را تحویل بگیر.»\r\nسه روز بعد، گرگ سراغ روباه آمد و پرسید: «پوستین من حاضر است؟»\r\nروباه گفت: «نه. گوسفندی که آورده بودی، خیلی کوچک بود. پوستش برای یک پوستین کافی نبود. گوسفند دیگر بیاور.»\r\nگرگ رفت و گوسفند دیگری آورد. روباه با خوشحالی آن را گرفت و گفت: «سه روز دیگر بیا! پوستینت حاضر است.»\r\nاما سه روز بعد، وقتی گرگ به خانه روباه رفت، پوستین حاضر نبود. روباه گفت: «گوسفندی که آورده بودی، پوستش را کندم. دیدم پوست خیلی نازکی دارد. پوستینش خوب در نمی آید. باید گوسفند دیگری بیاوری.»\r\nگرگ رفت و سومین گوسفند را آورد. روباه هم گفت که سه روز دیگر بیاید و پوستین را ببرد؛ اما سه روز بعد، باز هم پوستین حاضر نبود. این بار هم روباه خواسته بهانه ای بیاورد؛ اما گرگ خیلی عصبانی شده بود. \r\nروباه را به کناری پرت کرد و داخل خانه اش شد تا ببیند چه خبر است. دید کلی پوست و استخوان گوسفند در حیاط خانه روباه ریخته است. همه چیز را فهمید. به طرف روباه دوید تا حقش را کف دستش بگذارد. که روباه پا به فرار گذاشت. رفت که رفت.\r\nهنوز هم که هنوز است، روباه از دست گرگ فراری است و خودش را به او نشان نمی دهد.\r\n"},{"id":1124,"category_id":8,"category_code":"s8","source_id":85,"title":"روباه مریض و گنجشگ زرنگ","content":"یكی بود یكی نبود. در یك جنگل كوچك و دور افتاده حیوانات زیادی زندگی می‌كردند. خانم گنجشكه بتازگی 2تا جوجه كوچولویش را از تخم بیرون آورده بود و از آنها بخوبی نگهداری می‌كرد.\r\nروزها به اطراف جنگل می‌رفت تا برایشان غذا پیدا كند و بیاورد، اما چند روزی بود كه آقا روباه مكار دوباره سروكله‌اش پیدا شده بود و دوروبر گنجشك‌ها می‌پرید.\r\nیك روز از این روزها كه خانم گنجشكه می‌خواست دنبال غذا بره دید كه روباه بدجنس پایین درخت آنها نشسته و بر و بر به بچه‌هایش نگاه می‌كند. با خودش گفت این روباهه دوباره آمده تا جوجه‌هایم را بخوره... برای همین پشیمان شد و برگشت خانه و از بچه‌هایش مراقبت كرد.\r\nگنجشك‌های كوچولو خیلی گرسنه بودند و خانم گنجشكه حتما باید می‌رفت به جنگل تا غذا تهیه كند، ولی روباه مكار كه فكر می‌كرد از همه زرنگ‌تر و مكارتره، 4چشمی ‌مراقب جوجه‌ها بود تا سر یك فرصتی آنها را یه لقمه چرب كند.\r\nخانم گنجشكه فكری كرد و با خودش گفت: ای روباه بدجنس! دیگه نمی‌گذارم بچه‌هایم را بخوری و با خودش گفت حالا من چطوری خانه‌ و بچه‌هایم را تنها بگذارم و بروم... همین طور كه با خودش صحبت می‌كرد، ناگهان فكری به ذهنش رسید و بعد رفت نزدیك روباه و گفت: سلام روباه عزیز. از این طرفا...!\r\nروباه گفت: سلام گنجشك مهربون، داشتم از اینجا رد می‌شدم، گفتم یك سری به شماها بزنم.\r\nگنجشك گفت: وای چقدر كار خوبی كردی. روباه عزیز دوست خوب من! من باید بروم و برای بچه‌هایم غذا بیاورم، تو می‌توانی از آنها مراقبت كنی تا من برگردم.\r\nروباه گفت: بله حتما من خیلی خوب از آنها مراقبت می‌كنم. برو خیالت راحت باشه.\r\nگنجشك گفت: روباه عزیز! برعكس صحبت‌هایی كه درباره‌ات می‌كنند تو چقدر مهربانی، ولی من به همه می‌گم كه تو با وجود مریضی‌ات از بچه‌های من نگهداری كردی.\r\nروباه گفت: چی؟ چی گفتی... كدام مریضی؟\r\nگنجشك گفت: آخه دیدم رنگت خیلی پریده و زرد شده. من شنیدم در جنگل بیماری‌ای شیوع پیدا كرده كه كشنده است و اولین نشانه‌اش رنگ پریدگی است.\r\nروباه با شنیدن این حرف گنجشك گوشه‌ای نشست و گفت: یعنی من آن مریضی را گرفته‌ام، چه چیزی بخورم تا خوب شوم؟\r\nگنجشك گفت: تنها دارویش نوشیدن یك جرعه از آبی است كه از قله كوه پس از آب شدن برف‌ها بیاید.\r\nروباه راهی شد به سمت كوهستان و چند روز بعد هم خبر رسید كه مرده است. گنجشك‌ها و دیگر حیوانات هم از دست آزارهای روباه راحت شدند و به زندگیشان ادامه دادند.\r\nو گنجشك هم خوشحال بود از این‌كه حیله‌گرتر از روباه است.\r\n"},{"id":1125,"category_id":8,"category_code":"s8","source_id":86,"title":"موش کوچولو و آینه","content":"\r\nیکی بود یکی نبود.\r\nیک روز موش کوچولویی در میان باغ بزرگی می گشت و بازی می کرد که صدایی شنید:میو میو.موش کوچولو خیلی ترسید.پشت بوته ای پنهان شد و خوب گوش کرد.صدای بچه گربه ای بود که تنها و سرگردان میان گل ها می گشت و میومیو می کرد.\r\nموش کوچولو که خیلی از گربه ها می ترسید، از پشت بوته ها به بچه گربه نگاه می کرد و از ترس می لرزید.بچه گربه که مادرش را گم کرده بود، خیلی ناراحت بود. موش کوچولو می ترسید اگر از پشت بوته خارج شود، بچه گربه او را ببیند و به سراغش بیاید و او را بخورد؛ اما بچه گربه آن قدر نگران و ناراحت بود که موش کوچولو را پشت بوته ی گل سرخ نمی دید.\r\nاو فقط می خواست که مادرش را پیدا کند.با صدای بلند می گفت:«میومیو مامان جون من اینجام، تو کجایی؟» او آنقدر این جمله را تکرار کرد تا مادرش صدای او را شنید و به طرفش آمد و او را با خود از باغ بیرون برد.\r\nموش کوچولو نفس راحتی کشید و دوباره مشغول بازی شد.همین طور که زیر بوته ها می دوید و ورجه ورجه می کرد، چشمش به چیزی افتاد که زیر بوته ها برق می زد.\r\nبه طرف آن رفت، یک آینه کوچک با قاب طلایی بود.موش کوچولو توی آینه نگاه کرد و خودش را دید.خیال کرد یک موش دیگر را می بیند.خوشحال شد و شروع کرد با عکس خودش حرف زدن.می گفت:«سلام، میای با من بازی کنی؟» دهان موش کوچولوی توی آینه تکان می خورد ولی صدایی به گوش موش کوچولو نمی رسید.موش کوچولو آنقدر با موش توی آینه حرف زد که حوصله اش سر رفت و ساکت شد.\r\nبلبل که روی درختی نشسته بود و او را تماشا می کرد خنده اش گرفت و صدا زد:«آهای موش کوچولو، اون آینه است. تو داشتی با عکس خودت توی آینه حرف می زدی.»\r\nموش کوچولو سرش را بلند کرد.بلبل را دید. پرسید:«یعنی این خودِ من هستم؟من این شکلی هستم؟» بلبل جواب داد:« بله، تو این شکلی هستی.آینه تصویر تو را نشان می دهد.»\r\nموش کوچولو بازهم به عکس خودش نگاه کرد و از خودش خوشش آمد. او با خوشحالی خندید.بلبل هم خندید.چندتا پروانه که روی گلها پرواز می کردند هم خندیدند.گل های توی باغ هم خنده شان گرفت. صدای خنده ها به گوش غنچه ها رسید.غنچه ها بیدار شدند و آنها هم خندیدند و بوی عطرشان در هوا پیچید.\r\nبلبل شروع کرد به خواندن:\r\nمن بلبلم تو موشی\r\nتو موش بازیگوشی\r\nما توی باغ هستیم\r\nخوشحال و شاد هستیم\r\nگل ها که ما را دیدند\r\nبه روی ما خندیدند\r\nآن روزموش کوچولو دوستان زیادی پیدا کرد و حسابی سرگرم شد. وقتی حسابی خسته شد و خوابش گرفت، دوید و به لانه اش برگشت و خوابید.\r\n"},{"id":1126,"category_id":8,"category_code":"s8","source_id":87,"title":"پلیس جنگل","content":"اردکها هر وقت دلشون می خواست می پریدند توی آب برکه ،و آب رو کثیف و گل آلود می کردند و به حق بقیه ی حیوونا کهمی خواستن آب بخورن اهمیت نمی دادن.\r\nزرافه ی مغرور که به خاطر قد بلندش می تونست برگهای بالای درختارو بخوره ،بارها و بارها خونه ی پرنده هایی که روی شاخه های درختا بودند رو خراب می کرد و فرار می کرد.\r\nروباه پیر، با کلک زدن چندین بار سر حیوونای بیچاره کلاه گذاشته بود و غذاهاشونو خورده بود.\r\nمیمون بازیگوش هم هر وقت می رفت بالای درخت موز ،چند تا موز می خورد و پوستشونو توی راه پرت می کرد و با همین کارش باعث می شد بعضی از حیوونا در حال دویدن زمین بخورن .\r\nخلاصه مدتی بود که جنگل سبز شلوغ شده بود و بی انضباطی همه جا رو پر کرده بود.تقریبا همه ی حیوونای جنگل از این وضعیت خسته شده بودند. اینجوری جنگل دیگه جای زندگی نبود .\r\nحیوونا فهمیده بودن که باید برای بازگشتن آسایش و آرامش به جنگل یه تصمیمی بگیرن .اونا با هم تصمیم گرفتن برای جنگل یه کلانتری بسازن .اما کلانتری بدون پلیسه نمی شه.حالا چه کسی باید پلیس جنگل بشه ؟\r\nچاره ی کار قرعه کشی بود .ده تا از حیوونا داوطلب شدن تا پلیس جنگل باشن .قرعه کشی شروع شد و بعد از دوساعت نتایج اون اعلام شد .\r\n1- مار خالخالی\r\n2- یوزپلنگ تیزپا\r\n3- کلاغ راستگو\r\nاشکال این قرعه کشی این بود که به جای یه نفر، سه نفر انتخاب شده بودند چون هر سه نفرشون به اندازه ی مساوی رأی آورده بودند.از طرفی، هر سه نفرشون برای پلیس بودن مناسب بودن.\r\nاما حیونا اصرار داشتن بین این سه نفر یکی رو انتخاب کنن.می خواستن دوباره برای قرعه کشی آماده بشن که یه دفعه صدای جیغ خرگوشه حواس همه رو پرت کرد.آخه یه حیوون بدجنس که نقاب به صورتش زده بود تا کسی اونو نشناسه ،کیف پول خرگوشه رو برداشت و پا به فرار گذاشت .خرگوشه داد می زد :آی دزد ،دزد .کمکم کنید،دزد همه ی پولامو برد، بدبخت شدم.\r\nیوزپلنگ با شنیدن صدای خرگوشه، انداخت دنبال دزده تا بالاخره کنار برکه اونو دستگیر کرد .مار خالخالی خیلی سریع رسید و مثل یه طناب محکم اون حیوون بدجنس رو به درخت بست و جلوی فرار کردنشو گرفت. کلاغه خبر دستگیر شدن دزد رو به حیونای جنگل رسوند و همه ی حیوونارو برد کنار برکه .\r\nنقاب رو که از چهره ی اون برداشتند دیدن کسی نیست جز سنجاب قهوه ای، که دوست صمیمی خرگوشه است .\r\nقضیه این بود که سنجاب قهوه ای و خرگوشه نقشه کشیده بودن تا به حیونای جنگل نشون بدن که این سه نفر می تونن با همدیگه یک کارگاه پلیسی تشکیل بدن و هر سه نفرشون پلیسای جنگل باشن.\r\nهمه، از این فکر خوب،خوششون اومد و کلانتری جنگل رو به سه پلیس تازه کار تحویل دادند.\r\nدر قصه های بعدی ماجراهایی پر از هیجان راجع به اقدامات این سه پلیس جنگل خواهید خواند.\r\n"},{"id":1127,"category_id":8,"category_code":"s8","source_id":88,"title":"آپارتمان حیوانات","content":"توی جنگل سبز یه درخت کاج بود که از همه ی درختهای جنگل بلندتر و زیباتر بود .این درخت در جایی قرار داشت که از رویشاخه هاش همه ی جنگل و درختای سر سبزش دیده می شدند.\r\nبه خاطر همین مدتها بود که به خاطر این درخت بین بعضی از حیوونای جنگل دعوا می شد . سنجاب و جغد و دارکوب و کلاغ و ... همه می خواستن لونشونو روی این درخت بسازن .\r\nبلاخره اختلاف و درگیری بین اونها بالا گرفت و کار به کلانتری کشید .پلیس جنگل تصمیم گرفت با بزرگترای جنگل مشورت کنه و راه چاره ای پیدا کنه .جلسه ی شورا برگزار شد و هر کسی نظری داد .اما در بین همه ی نظر ها، حرفی که لک لک پیر زد از همه جالبتر بود .\r\nلک لک گفت من توی شهر آدمها دیدم که خونه هایی روی هم می سازن و بهش آپارتمان می گن .بهترین کار اینه که روی درخت کاج هم یه آپارتمان چند طبقه درست کنیم تا همه ی حیوانات درخت نشین جنگل، بتونن یه خونه روی اون درخت داشته باشن.این نظر با موافقت همه روبرو شد و قرار شد به زودی آپارتمان حیوانات در جنگل سبز ساخته بشه .\r\nدارکوب که مهارت زیادی توی خونه ساختن، روی درختان داشت، نقشه ی آپارتمان رو کشید و به همه نشون دارد نقشش حرف نداشت .اون یه آپارتمان ده طبقه ی خیلی زیبا طراحی کرده بود .طبقه ی اول برای سنجاب ،طبقه ی دوم برای لک لک پیر، طبقه ی سوم برای جغد ،طبقه ی چهارم برای دارکوب ،طبقه ی پنجم برای کلاغ و...\r\nقرار شد دو طبقه از آپارتمانشون رو هم برای پذیرایی از مهمونایی که به جنگل اونها مهاجرت می کنن ،خالی نگه دارن.\r\nشنبه ،اول هفته کار ساختن آپارتمان شروع شد.دارکوب با فاصله های منظم روی درخت سوراخهای بزرگی ایجاد می کرد.بعد سنجاب وارد این سوراخها می شد و با ابزاری که داشت، اتاق بزرگی توی هر سوراخ درست می کرد.بعد نوبت کلاغ بود که وارد اتاقها بشه و خاک و زباله هارو از اونجا بیرون بریزه و تمیز کنه .وقتی اتاقها تمیز می شدند جغد مبلها و تختخوابهایی اندازه ی اونها می ساخت و لک لک اونارو توی اتاقها نصب می کرد. تا آخر هفته همه ی واحدها ساخته شدند.\r\nبعدش همه کمک کردن و با هم در و پنجره های آپارتمانشون رو کار گذاشتند. آخر کار هم همه با هم قلمو دست گرفتند و شروع به رنگ کردن در و پنجره های آپارتمانشون کردن.\r\nآپارتمان که تموم شد بقیه ی حیوونای جنگل برای اونها پرده های قشنگی به عنوان هدیه آوردند تا پشت پنجره هاشون نصب کنند.با نصب پرده ها ،آپارتمان درخت کاج زیباتر و زیباتر شد.\r\nکار آپارتمان تموم شد و موقع اسباب کشی رسید هر کسی با کمک دوستاش اسباب و اثاثیه ی خودش رو توی آپارتمانش برد .اولین روزی که حیوانات وارد آپارتمانشون شدند توی جنگل یه عالمه شادی و شور برپا شده بود. نزدیک غروب که شد آپارتمان نشینها ،پنجره هاشونو باز کردن و جلوی پنجره نشستن .با این صحنه انقدر درخت کاج قشنگ شده بود که تا چند شب همه ی حیوونا می یومدن زیر درخت کاج و دور هم می نشستن و صفا می کردن. حیوونای توی آپارتمان هم از مهمونایی که اومده بودن پیش اونا شب نشینی، پذیرایی می کردن.حالا جنگل سبز یه آپارتمان قشنگ برای حیوونای کوچیکی که روی درخت زندگی می کنند،داره .اگه به جنگل سبز سر زدید از اون آپارتمان هم دیدن کنید.\r\n"},{"id":1128,"category_id":8,"category_code":"s8","source_id":89,"title":"بزغاله ی خجالتی","content":"توی یه گله بز ،یه بزغاله خجالتی بود که خیلی آروم و سر به زیر بود .وقتی همه بزغاله ها بازی و سر و صدا راه می انداختنداون فقط یه گوشه می ایستاد و نگاه می کرد.\r\nوقتی گله بزغاله ها به یه برکه ی آب می رسید،بزغاله های شاد و شیطون برای خوردن آب می دویدند سمت برکه و حسابی آب می خوردند و آب بازی می کردند .\r\nاما بزغاله ی خجالتی اینقدر صبر می کرد تا همه بزغاله ها از کنار برکه برن بعد خودش تنهایی بره آب بخوره .بعضی وقتا از بس دیر می کرد ،گله به سمت دهکده به راه می آفتاد و اون دیگه وقت آب خوردن رو از دست می داد .این جوری اون خیلی خودشو اذیت می کرد.\r\nچوپون مهربون گله بارها و بارها به بز غاله خجالتی گفته بود که باید رفتارشو عوض کنه . اما بزغاله خجالتی هیچ جوابی نمی داد و بازم همونجوری خجالتی رفتار می کرد .\r\nیه روز صبح وقتی گله می خواست برای چرا به دشت و صحرا بره ،بزغاله ی خجالتی موقع رفتن زمین خورد و یه کم پاش درد گرفت .به همین خاطر نتونست مثل هر روز خودشو به گله برسونه .اون توی خونه جا موند اما خجالت می کشید که صدا بزنه من جا موندم صبر کنید تا منم برسم.وقتی به نزدیک در رسید دید که همه رفتند و تنها توی خونه مونده. اینجوری مجبور بود تا شب تنها و گرسنه بمونه.\r\nچوپون گله در طول راه متوجه شد که بزغاله خجالتی با اونا نیومده ،به خاطر همین سگ گله رو فرستاد تا به خونه برگرده و اونو با خودش بیاره .اما اول درگوش سگ یه چیزایی گفت و بعد اونو راهی خونه کرد.\r\nسگ گله به خونه برگشت و یه گوشه گرفت خوابید .بزغاله خجالتی دل تو دلش نبود .باخودش فکر می کرد مگه سگ گله به خاطر اون برنگشته ،پس حالا چرا گرفته خوابیده .دلش می خواست با اون حرف بزنه اما خجالت می کشید.یه کم دور و بر اون راه رفت و منتظر موند، اما سگ اهمیتی نمی داد .بلاخره صبرش سر اومد و رفت جلو و به سگ گفت ببخشید من امروز جا موندم می شه منو ببرید به گله برسونید ؟سگ خندید و گفت البته که می شه .اما من تند تند می رم می تونی بهم برسی ؟\r\nچوپون مهربون چشم به جاده دوخته بود و منتظر اونا بود که یه دفه دید بزغاله خجالتی داره می دوه و میاد و سگ گله هم با کمی فاصله پشت سرش می یاد مثل اینکه با هم دوست شده بودن.اونا باهم حرف می زدن و می خندیدن.\r\nچوپون گله لبخندی زد و گفت امیدوارم بزغاله خجالتی همین طوری ادامه بده تا یه بزغاله شاد و شنگول بشه .\r\n"},{"id":1129,"category_id":8,"category_code":"s8","source_id":90,"title":"نی نی و داداشی","content":"مامان از صبح خیلی زحمت کشیده بود حالا بعد از ظهر شده بود و حسابی خوابش گرفته بود .اما نی نی و داداشی اصلا خوابشون نمی یومد. ولی به هر حال مامان می خواست هر سه نفر با هم بخوابن .اینجوری خیال مامان راحت تر بود . مامان شروع کرد به قصه گفتن.یکی بود یکی نبود غیر از خدا هیچکس ،هیچکس ،هیچکس، ...\r\nچی شد ؟مثل اینکه مامان خوابش رفت .دیگه قصه ادامه نداشت.\r\nنی نی هی تکون خورد و تکون خورد تا از تو بغل مامان بلند شد و رفت .داداشی هم یواشکی دنبال نی نی رفت .خدا به خیر کنه .حالا این دوتا می خواستن چکار کنن.\r\nدو ساعت گذشت.\r\nبعد مامان از خواب بیدار شد.از نی نی و داداشی توی اتاق خواب خبری نبود.مامان نگران شد و سریع رفت به سمت آشپزخونه . با تعجب جلوی در آشپزخونه ایستاد و گفت: وای اینجا چه خبره .چه اتفاقی افتاده، مثل اینکه لوله ی آب شکسته .همه فرش آشپزخونه خیس بود.تمام وسایل توی کابینت، روی زمین چیده شده بودند.\r\nیه دفعه نی نی از توی راهرو رسید از سر تا پاش خیس بود .یه قوری تو دستش بود که توی اون هم پر از آب بود .نی نی توی لوله قوری فوت می کرد .صدای قل قل آّبها که شنیده می شد، می خندید.\r\nنی نی تا مامانو دید قوریو بهش نشون داد و گفت :این ، آبُه... ،بعد داداشی اومد .داداشی هم حسابی خیس بود چیزی که دست داداشی بود ،عجیب تر بود .داداشی شلوارای بابا رو برداشته بود و معلوم نبود می خواست چکار کنه\r\n.داداشی که بزرگتر بود و می تونست درست حرف بزنه گفت :ما داریم کارای خونه رو می کنیم .داریم خونه تکونی می کنیم .همه ظرفای توی کابینت رو شستیم .الانم داریم لباس می شوریم.بعد گفت مامانجون تو برو بخواب تا همه کارا تموم بشن.\r\nمامان با تعجب گفت دارید لباس می شورید؟\r\nداداشی گفت آره .یه عالمه لباس شستیم .توی حیاطن.\r\nمامان با عجله به سمت حیاط رفت .\r\nبه به ،اینجا دیگه چه خبره .تا دلتون بخواد لباس خیس توی حیاط بود.سر مامان گیج رفت .حالا کی می خواست این خونه رو درست کنه !\r\nبچه ها :نی نی و داداشی اینهمه کار خوب کرده بودن .اینهمه زحمت کشیده بودن .ولی مامان اصلا از اونا تشکر نکرد .تازه عصبانی هم شده بود و می خواست به اونا دعوا هم بکنه . وای وای !می بینید بچه ها بعضی وقتا مامانا چقدر اشتباه می کنن.\r\nخلاصه به خاطر کمکهای نی نی و داداشی ،اون شب مامان و بابا مجبور شدند تا آخر شب خونه رو تمیز کنن.تازه بعدش معلوم نبود قوری کجاست تا چایی دم کنن.معلوم نبود شلوار بابا کجاست تا بابا بره از بیرون غذا بخره .\r\nاز همه بدتر نی نی حسابی سرما خورده بود حالا شربت سرما خوردگی کجاست؟\r\nراستی بچه ها شما هم به مامان و بابا کمک می کنید تا خونه تکونی کنن؟به نظر شما کارای بچه ها درست بودن؟چرا مامان عصبانی بود؟\r\n"},{"id":1130,"category_id":8,"category_code":"s8","source_id":91,"title":"کیسه ی آرد و موش کوچولو","content":"اسماعیل كارگر یك نانوایی بود. صبح به صبح ماشین بزرگ، كیسه‌های زیادی آرد می‌آورد و دم در نانوایی می‌ریخت. اسماعیل هم به محض این‌كه از خواب بیدار می‌شد این كیسه‌ها را داخل نانوایی می‌برد.مادر اسماعیل چندین روز بود كه مریض شده بود و دكترها گفته بودند او باید عمل شود و پول عملش هم زیاد بود.طبق معمول آن روز ماشین آرد آمد و تعداد زیادی كیسه آرد در مغازه خالی كرد.\r\nاسماعیل هم بلند شد و مشغول حمل كیسه‌های آرد شد.در همان حین كه اسماعیل مشغول بردن كیسه‌های آرد بود، ناگهان دید یك موش كوچولو از بین كیسه‌ها در رفت و رفت داخل مغازه. اسماعیل دنبال موش رفت ولی اثری از او نبود كه نبود. خلاصه اسماعیل تمام كیسه‌ها را داخل مغازه برد و فكر كرد كه اشتباه دیده است. آن روز به كارش مشغول بود. فردای آن روز دوباره موش كوچولو رو دید. اسماعیل رفت به دنبالش ولی باز دوباره ناپدید شد.\r\nچندین روز اسماعیل با آقا موشه مشغول قایم باشك بازی بود تا این‌كه یك روز كه اسماعیل خیلی ناراحت مادرش بود، روی زمین نشست و پول‌هایش را ‌شمرد تا ببیند در این مدت چقدر جمع كرده است و آیا به پول عمل مادرش می‌رسد؟\r\nبعد از این‌كه پول‌ها را شمرد، اسماعیل رو كرد به خداوند و گفت: «آخه خدا، چی می‌شد كه این پول‌ها دو برابر می‌شد تا من می‌تونستم مادرم رو عمل كنم.» همین موقع بود كه‌ دوباره سر و كله آقا موشه پیدا شد و خودش را به اسماعیل نشان داد و تعدادی از پول‌ها را به دهان گرفت و از مغازه در رفت و به سمتی رفت.اسماعیل هم بلند شد و دنبالش دوید و گفت: وای پولم رو بده... پولم رو بده... ای موش بد ذات...\r\nموش پشت وسایلی رفت كه سال‌های سال از آنها استفاده نشده بود. اسماعیل هم تمام روزش را مشغول جابه‌جایی وسایل بود ولی آقا موشه پیدا نشد كه نشد. در همین موقع بود كه بین كیسه‌ها یك كیسه پر از طلا پیدا كرد و با تعجب گفت: با فروختن این كیسه‌ها حسابی پولدار می‌شوم و زندگی‌ام تغییر می‌كند. این هدیه‌ای از طرف خداست، ولی بعد از كمی فكر كردن تعدادی از این سكه‌ها را برای مادرش برداشت و به خودش قول داد كه بعد از این‌كه مادرش عمل شد و حالش خوب خوب شد سكه‌ها راكم كم به داخل آن كیسه برگرداند.\r\nروز عمل فرا رسید و اسماعیل هم سكه‌ها را فروخت و به بیمارستان رفت. خوشبختانه عمل مادر اسماعیل بخوبی انجام شد. اسماعیل رفت كه پول عمل را پرداخت كند ولی خانم پرستار گفت: آقا پول عمل پرداخت شده. اسماعیل گفت من هنوز پول عمل را نداده‌ام به شما. پرستار گفت: یك آدم خیر پول عمل شما را پرداخت كرده.\r\nاسماعیل از خوشحالی نمی‌دانست چه كار كند و دوباره به داخل مغازه سكه فروشی رفت و سكه‌ها را پس گرفت و به كیسه طلاها برگرداند و از خدای بزرگ تشكر كرد و گفت: ای خدای مهربان و بزرگ، هرگز بیشتر از حد و اندازه‌ام نمی‌خواهم.\r\n"},{"id":1131,"category_id":8,"category_code":"s8","source_id":92,"title":"روباه و سنجاب","content":"\r\nیکی بود یکی نبود. غیر از خدا هیچکس نبود\r\nیک روز سنجاب مشغول بازی بود که روباه را دید. سنجاب خیلی ترسید. پا به فرار گذاشت و روباه هم به دنبال او دوید. سنجاب به لاک پشت رسید و گفت: لاک پشت جان! وقتی کسی بخواهد تو را بگیرد، چه می کنی؟ \r\nلاک پشت گفت: فوری می روم توی لاکم! سنجاب گفت: آه! خوش به حالت! من که لاک ندارم. فقط چند قدم مانده بود که روباه به سنجاب برسد، سنجاب دوباره پا به فرار گذاشت. دوید و رسید به حلزون.\r\nسنجاب از حلزون پرسید: حلزون جان! اگر کسی بخواهد تو را بگیرد،چه می کنی؟\r\nگفت: می روم توی صدفم. سنجاب گفت: آه! خوش به حالت! من که صدف ندارم. و به سرعت از پیش حلزون رفت. در راه خارپشت را دید.\r\nو گفت: خارپشت جان! تو نه لاک داری، نه صدف، بگو اگر کسی بخواهد تو را بگیرد، چه می کنی؟ خارپشت گفت: خودم را گرد می کنم و می شوم یک توپ پر از خار! سنجاب گفت: آه! خوش به حالت! تو خار داری. اما من نه خار دارم، نه لاک دارم نه صدف.\r\nخارپشت گفت: اما تو لانه داری! لانه ای که فقط تو می توانی توی آن بروی! سنجاب با خوش حالی گفت: آه! راست گفتی خارپشت جان! من یک لانه دارم! سنجاب به سرعت از درخت بالا رفت و رسید به لانه اش. روباه بیچاره پایین درخت ماند و نتوانست سنجاب را بگیرد، چون او یک لانه داشت که هیچ کس جز خودش نمی توانست توی آن برود!\r\n"},{"id":1132,"category_id":8,"category_code":"s8","source_id":93,"title":"قورباغه ای به نام سبزک","content":"قورباغه ای در برکه زندگی می کرد بنام سبزک. این قورباغه همیشه توی برکه بود و دوتا آرزو توی زندگیش داشت،اول این که یه روز از برکه بره بیرون جنگل و دشت وبیشه رو ببینه ، دوم یه دوست خوب داشته باشه.یه روزی تصمیم گرفت از برکه بره بیرون که هم دشت و بیشه و جنگل رو ببینه و هم تلاش کنه تا یه دوست خوب پیدا کنه.\r\nپس از مادرش اجازه گرفت و از برکه بیرون اومد و به سمت جنگل رفت .توی جنگل به حیوونا و حشرات زیادی برخورد کرد .\r\nاول به لشگر مورچه ها برخورد که برای خودشون خوراکی جمع می کردند.\r\nباخودش گفت : شاید بتونم با یکی از مورچه ها دوست بشم اما مورچه ها سخت مشغول کار بودند و هیچکدوم حتی متوجه سبزک نشدند، پس به راهش ادامه داد.\r\nپرنده های زیادی رو دید که توی آسمون دائما پرواز می کردند اما اونها هم اون بالا بودند و نمی شد باهاشون دوست بشه.\r\nبازهم تصمیم گرفت به راهش ادامه بده . به دشت رسید، همین طوری داشت به حشرات جورواجور نگاه می کرد و با خودش فکر می کرد که با کدومشون می تونه دوست بشه که ملخک پرید جلوش و گفت: سلام اسم تو چیه؟\r\nسبزک گفت: اسم من سبزکه!\r\nملخک گفت: می یای با هم بازی کنیم من تنهام؟\r\nسبزک گفت: نه نمی تونم من اومدم دنبال آرزوهام.\r\nملخک گفت:منم می تونم با تو بیام چون منم آرزوهایی دارم؟\r\nسبزک گفت: بیا.\r\nدوتایی با هم حرکت کردند و کلی باهم حرف زدند و شادی کردند و از هم دیگه کارا و حرفهای خوب و جدید یاد گرفتند.خلاصه خیلی به هردوشون خوش گذشت.\r\nدیگه هوا کم کم داشت تاریک می شد، سبزک و ملخک باید می رفتند خونشون اما دوستی پیدا نکرده بودند.\r\nاز هم خدا حافظی کردندو هر کدومشون رفتند به سمت خونشون که یکدفعه هر دو با هم گفتند: آره ما دو تا با هم دوست شدیم ، دویدند طرف هم دیگه و گفتند:\r\nدوست خوب من خدا نگهدار تا فردا.\r\nحالا دیگه سبزک هم خارج از برکه رو دیده بود و هم یه دوست خوب پیدا کرده بود.\r\n"},{"id":1133,"category_id":8,"category_code":"s8","source_id":94,"title":"لاکی و فیلی","content":"صدای پای فیل کوچولو بود که از دور شنیده می شد. لاک پشت کوچولو تا صدا را شنید، ترسید و و سرش را توی لاکش برد؛ ولی یادش رفت که دست ها و پاهای کوچولو موچولش را قایم کند.\r\nفیل کوچولو نزدیک و نزدیک تر شد. تا لاک پشت را دید، آهسته جلو آمد و با خرطومش دُم و پاهای لاک پشت را قلقلک داد. لاک پشت ترسید و خودش را روی شن ها نرم به جلو کشید. فیل کوچولو رفت توی رودخانه.\r\nلک لک تا فیل کوچولو را دید، از آب بیرون آمد و به طرف لاک پشت پرواز کرد. آب رودخانه بالا و بالاتر آمد و لاک پشت کوچولو را با خودش برد. کمی بعد او را رها کرد. لاک پشت به پشت افتاد. هر چه دست و پا زد، غصّه خورد و مامانش را صدا زد. لک لک هر کاری کرد نتوانست لاک پشت را تکان بدهد. لاک پشت هم هرچه دست و پا زد، حرکت نکرد که نکرد.\r\nفیل کوچولو که داشت از رودخانه آب می خورد، لاک پشت را دید. گوش های بزرگش را تکان تان داد. آب های خرطومش را خالی کرد. خرطومش را کج کرد و لاک پشت را به جلو هل داد. لاک پشت چند بار دست و پا زد، چرخید و چرخید و به شکم روی شن ها افتاد. لاک پشت خوش حال شد و شادی کرد. دیگر از صدای تلاپ و تلوپ پای فیل کوچولو نمی ترسید.\r\n"},{"id":1134,"category_id":8,"category_code":"s8","source_id":95,"title":"رود خونه ی تنها","content":"یکی بود یکی نبود غیر از خدای مهربان هیچ کس نبود. در کنار یک کوهستان زیبا رودخانه ای وجود داشت که بسیار تنها بود.او هیچ دوستی نداشت. رودخانه یادش نمی آمد که چرا به کسی یا چیزی اجازه نمی دهد تا داخلش شنا کنند. او تنها زندگی می کرد و اجازه نمی داد ماهی ها، گیاهان و حیوانات از آبش استفاده کنند.\r\nبه خاطر همین او همیشه ناراحت و تنها بود. یک روز، یک دختر کوچولو به طرف رودخانه آمد. او کاسه ی کوچکی به دست داشت که یک ماهی کوچولوی طلایی در آن شنا می کرد. دختر کوچولو می خواست با پدر و مادرش از این روستا به شهر برود و نمی توانست با خود ماهی کوچولو را ببرد. بنابراین تصمیم گرفت، ماهی کوچولو را آزاد کند. دختر کوچولو ماهی کوچکش را در آب انداخت و با او خداحافظی کرد و رفت.\r\nماهی در رودخانه بسیار تنها بود، چون هیچ حیوانی در رودخانه زندگی نمی کرد. ماهی کوچولو سعی کرد با رودخانه صحبت کند اما رودخانه به او محل نمی گذاشت و به او می گفت:\"از من دور شو.\"\r\nماهی کوچولو یک موجود بسیار شاد و خوشحال بود و به این آسانی ها تسلیم نمی شد. او دوباره سعی کرد و سعی کرد، به این سمت و آن سمت شنا کرد و از آب به بیرون پرید.\r\nبالاخره رودخانه از کارهای ماهی کوچولو خنده و قلقلکش گرفت.\r\nکمی بعد، رودخانه که بسیار خوشحال شده بود، با ماهی کوچولو صحبت کرد. آن ها دوستان خوبی برای هم شدند.\r\nرودخانه تمام شب را فکر می کرد که داشتن دوست چقدر خوب است و چقدر او را از تنهایی بیرون می آورد. او از خودش پرسید که چرا او هرگز دوستی نداشته، ولی چیزی یادش نیامد.\r\nصبح روز بعد، ماهی کوجولو با آب بازی رودخانه را بیدار کرد و همان روز رودخانه یادش آمد چرا او هیچ دوستی ندارد.\r\nرودخانه به یاد آورد که او بسیار قلقلکی بوده و نمی توانست اجازه بدهد کسی به او نزدیک شود.\r\nاما حالا دوست داشت که ماهی در کنار او زندگی کند، چون ماهی کوچولو بسیار شاد بود و او را از تنهایی در می آورد.\r\nحالا دیگر رودخانه می خواست کمی قلقلکی بودنش را تحمل کند، اما شاد باشد.\r\n"},{"id":1135,"category_id":8,"category_code":"s8","source_id":96,"title":"آقا غوله و بزهای ناقلا","content":"داستان ما در یک روز سرد، در یک چمنزار سبز و زیبا اتفاق افتاد. سه بز برادر بودند که با هم در یک چمنزار بزرگ زندگی می کردند.یک روز بز بزرگ به دو تای دیگر گفت \"خسته شدم از این که هر روز به این چمنزار اومدم، دلم می خواد چمن های اون طرف نهر رو هم مزه مزه کنم.\"\r\nبرادر کوچکتر گفت \"ما نمی تونیم به اون طرف بریم، چون نهر خیلی عمیقه و ما رو با خودش می بره.\"\r\nبرادر وسطی گفت \"ما حتی نمی تونیم از روی پل رد بشیم، چون یک غول بزرگ زیر اون زندگی می کنه و اگه ما رو ببینه، یه لقمه ی چربمون می کنه.\"\r\nبز بزرگ سرش را که شاخ های بزرگ گردی داشت باغرور بالا گرفت و گفت \"من از آقا غوله نمی ترسم.\" بعد پاهایش را روی زمین کوبید و گفت \"باید باهاش بجنگیم. بعد ببینیم کی توی این مبارزه برنده می شه.\"\r\nبز وسطی گفت \"ولی ما به اون جا نمی آیم، چون آقا غوله حتماً بز کوچیکه و منو می خوره.\"\r\nبز بزرگتر چرخی توی چمنزار زد و سمش را با قدرت روی زمین کوبید و گفت \"هرگز این اتفاق نمی افته، چون من یه نقشه دارم.\"\r\nسه بز به هم نزدیک شدند و بز بزرگتر نقشه اش را برای آن ها گفت و بعد هر سه یورتمه کنان به سمت پل حرکت کردند.\r\nبز کوچکتر نفس عمیقی کشید و روی پل رفت. وقتی بز کوچولو روی پل راه می رفت پل کمی به این طرف و آن طرف حرکت می کرد.\r\nناگهان یک جفت چشمان بزرگ و گرد از تاریکی زیر پل ظاهر شد و غرش کنان گفت \"کی جرات کرده روی پل من بیاد؟\" بعد دست بزرگ و پشمالویی از تاریکی بیرون آمد و با انگشتان بزرگش کناره ی پل را گرفت.\r\nبز کوچولو با صدای آرام و لرزانی گفت \"منم،بز کوچولوی لاغر و استخونی، داشتم می رفتم چمنزار تا کمی علف بخورم تا چاق و چله بشم.\"\r\nآقا غوله با صدای بلندش که پل را می لرزاند گفت \"من می خوام تو رو بخورم.\"\r\nبز کوچولو که تمام بدنش از ترس می لرزید گفت \"منو بخوری؟ من خیلی کوچیکم. یه گاز تو هم نمی شم. صبر کن بذار برادر وسطیم بیاد اون چاق و چله تر از منه.\"\r\nآقا غوله که داشت زیر پل می رفت، غرش کنان گفت\" بیا برو و تا وقتی چاق نشدی دیگه اینجا نیا.\"\r\nبز کوچولو گفت \"چشم\" و بعد با غرور و خوشحالی از روی پل رد شد و به بالای تپه رفت.\r\nوقتی بز کوچولو به بالای تپه رسید، بز وسطی قدم روی پل چوبی گذاشت. وقتی بز وسطی با سم های بزرگش روی پل راه می رفت، پل تکان می خورد. ناگهان یک جفت چشمان گرد و بزرگ از تاریکی از زیر پل ظاهر شد. آقا غوله با صدای بلند و وحشتناکش پرسید \"کی داره روی پل من راه می ره؟\" بعد دست پشمالوی بزرگش را از تاریکی بیرون آورد و کناره ی پل را گرفت.\r\nبزهای ناقلا\r\nبز وسطی گفت \"منم منم بز استخونی. داشتم می رفتم چمنزار تا علف و یونجه بخورم. آخه می خوام چاق بشم.\"چ\r\nآقا غوله با صدای بلند فریاد کشید \"من می خوام تو رو بخورم.\"\r\nبز وسطی با خنده گفت \"منو بخوری؟ چرا می خوای منو بخوری؟من خیلی لاغرم، دو تا گاز تو هم نمی شم. استخون هام هم تو گلوت گیر می کنه. صبر کن بذار برادر بزرگترم بیاد. اون خیلی چاق و بزرگه.\"\r\nآقا غوله کمی فکر کرد و گفت \" بیا تو هم زودتر از روی پل رد شو و تا وقتی چاق نشدی دیگه برنگرد.\"\r\nبز وسطی هم با غرور از روی پل رد شد و به بالای تپه پیش برادر وسطی اش رفت، آن دو از بالا به پل نگاه می کردند تا ببینند برادر بزرگتر آن ها چه می کند.\r\nبالاخره برادر بزرگتر با غرور روی پل چوبی قدم گذاشت. بز بزرگتر خیلی سنگین بود و به همین خاطر و قتی روی آن راه می رفت پل به شدت تکان می خورد. از تکان های زیاد پل آقا غوله بیدار شد و غرش کنان پرسید \"کی جرات کرده روی پل من بیاد.\"\r\nبز بزرگ گفت \"منم، بز بزرگ.\" بعد بز بزرگ چشم هایش را تنگ کرد و شاخ هایش را به طرف او نشانه گرفت و با شاخ هایش به شکم آقا غوله زد و او را به هوا پرتاب کرد. بعد آقا غوله داخل آب پرتاب شد و آب او را با خودش برد و دیگر کسی آقا غوله را آن طرف ها ندید.\r\nبز بزرگ هم به بالای تپه پیش برادرانش در چمنزار رفت و کل تابستان را از علف های تازه و سرسبز چمنزار چریدند و بعد دوباره از روی پل رد شدند و به چمنزار قبلی برگشتند.\r\n"},{"id":1136,"category_id":8,"category_code":"s8","source_id":97,"title":"جادوی مار سفید","content":"سال ها قبل پادشاهی بود که در علم و دانایی شهره ی جهان بود. هیچ چیز از نظر او پنهان نمی ماند و به نظر می رسیدکه رازها ی نهان از آسمان به او می رسد. اما این پادشاه عادت عجیبی داشت، هر شب باید خدمتکاری معتمد ظرفی سربسته را بعد از شام برایش می آورد، هیچکس از محتویات درون ظرف خبر نداشت، چون پادشاه جلوی کسی در ظرف را برنمی داشت.\r\nمدت ها به همین منوال گذشت تا این که یک روز خدمتکاری که ظرف غذا را برای پادشاه می برد، وسوسه شد تا درون ظرف را ببیند ، به همین خاطر ظرف غذا را به اتاقش برد و در را قفل کرد. سپس در ظرف را برداشت و یک مار سفید درون آن دید. وقتی خدمتکار مار را دید کمی از آن را برید و در دهانش گذاشت. همین که تکه ی مار به زبانش رسید، صداهای عجیبی از بیرون پنجره شنید. او کنار پنجره رفت و به صداها با دقت گوش داد. صدای پرندگان را شنید که با هم در مورد زمین ها و جنگل هایی که رفته بودند، حرف می زدند. او بسیار تعجب کرد و فهمید خوردن مار سفید قدرت درک زبان حیوانات را به او داده است.\r\nروزها گذشتند تا این که یک روز ملکه حلقه ی طلای بسیار زیبای خود را گم کرد. ملکه به خدمتکار مظنون شد، چون تنها او اجازه داشت به همه جا سر بزند. پادشاه به سربازانش دستور داد تا خدمتکار را به حضورش بیاورند. پادشاه با عصبانیت زیاد خدمتکار معتمدش را تهدید کرد که اگر تا فردا صبح حلقه را نزد او حاضر نکند، او را اعدام خواهد کرد.\r\nخدمتکار بیچاره که خیلی ترسیده بود از قصر خارج شد و به باغ رفت.\r\nدر باغ چند اردک با هم در کنار برکه نشسته بودند و استراحت می کردند. آن ها با نوکشان بین پرهایشان را تمیز می کردند و با هم حرف می زدند. آن ها در مورد جاهایی که رفتند، غذایی که خوردند صحبت می کردند. یکی از آن ها گفت \" چیزی روی دلم مونده، فکر کنم حلقه ای را که زیر پنجره ی اتاق ملکه بوده، قورت دادم.\" خدمتکار با شنیدن این کلمه اردک را برداشت و به آشپزخانه برد و به آشپز داد و گفت: امروز خوراک اردک آماده کن.\" وقتی آشپز داشت اردک را برای شام آماده می کرد حلقه ی طلا را پیدا کرد.\r\nحالا خدمتکار به راحتی می توانست بی گناهیش را اثبات کند. پادشاه برای جبران اشتباهش به او اجازه داد تا چیزی از او بخواهد و حتی می خواست بهترین پست دربار را به او اعطاء کند، ولی خدمتکار قبول نکرد و از پادشاه خواست تا یک اسب و مقداری پول به او بدهد تا او رویای کودکی اش را که سفر به دور دنیا بود، به حقیقت برساند.\r\nوقتی پادشاه درخواستش را قبول کرد، خدمتکار اسبش را گرفت و راهی شد، یک روز بعد به رودخانه ای رسید که سه ماهی بین نی ها گیر افتاده بودند و برای رسیدن به آب لحظه شماری می کردند. حالا بگذریم از این موضوع که می گویند ماهی ها گنگ و لال هستند، خدمتکار صدای آن ها را شنید که آه و ناله می کردند و بسیار ناامید و مایوس بودند. از آن جایی که خدمتکار قلب رئوف و مهربانی داشت، ماهی ها را با دست گرفت و در آب رها کرد. ماهی ها با خوشحالی داخل آب پریدند، سرشان را از آب بیرون آوردند و از خدمتکار تشکر کردند و گفتند یک روز لطف و مهربانیت را جبران می کنیم.\r\nخدمتکار سوار بر اسبش شد و راه افتاد، کمی بعد صدایی از زیر شن و ماسه ها شنید. کمی دقت کرد و بعد متوجه شد که صدای ملکه ی مورچه هاست. مورچه با اعتراض و ناراحتی می گفت چرا این آدم ها با این اسب های بزرگ و بدقیافه شان از روی ما رد می شوند و ما را له می کنند. مرد با شنیدن این جمله افسار اسبش را کشید و کمی مسیرش را عوض کرد. ملکه ی مورچه ها از مرد تشکر کرد و گفت \"هرگز لطفت را فراموش نمی کنم.\"\r\nمرد اسب سوار رفت و رفت تا به یک جنگل رسید. او آنجا دو کلاغ پیر را دید که جوجه هایشان را از آشیانه بیرون می کردند. آن ها داد می زدند \"از اینجا دور شوید، شما سه تا به هیچ دردی نمی خورید، ما دیگر نمی توانیم برای شما غذا پیدا کنیم، شما دیگر بزرگ شدید و خودتان باید غذایتان را تهیه کنید.\" اما جوجه های بیچاره روی زمین افتادند و گفتند \"چقدر ما بدبخت هستیم، ما هنوز نمی توانیم پرواز کنیم، چطوری برای خودمان غذا تهیه کنیم، ما حتماً از گرسنگی می میریم.\" مرد جوان با دیدن این منظره دلش به حال جوجه کلاغ ها سوخت و غذایش را به آن ها داد.\r\nآن ها از غذای مرد جوان خوردند و از گرسنگی نجات یافتند و بعد به او گفتند \"هرگز لطفت را فراموش نمی کنیم.\"\r\nمرد جوان اسب سوار روزها به راهش ادامه داد تا به شهر بزرگی رسید. در آن جا سر و صدای زیادی به گوش می رسید. مردی سوار بر اسب، بلند فریاد می زد \"دختر پادشاه می خواهد از میان شما مردی را برای همسری انتخاب کند، اما هرکس بخواهد با او ازدواج کند، باید کار بسیار دشواری را انجام دهد و اگر موفق به انجام آن نشود، زندگی اش را از دست می دهد.\" افراد زیادی تلاش بسیار کردند، اما همه ی آن ها ناموفق بودند، با این وجود مرد جوان می خواست شانس خود را امتحان کند. بنابراین خود را خواستگار دختر پادشاه اعلام کرد.\r\nبنابراین او را به دریا بردند و پادشاه حلقه ای طلا را در برابر چشمان او به دریا انداخت، سپس به او دستور داد تا آن را بیاورد و اگر نتواند خود او را به دریا خواهند انداخت. همه ی مردم دلشان به حال مرد جوان سوخت، همه رفتند و او را تنها گذاشتند.\r\nمرد جوان کنار ساحل ایستاده بود که دید سه ماهی به طرفش می آیند. آن ها همان سه ماهی ای بودند که او روزی آن ها را نجات داده بود. یکی از ماهی ها صدفی در دهانش بود که آن را به مرد جوان داد. وقتی مرد جوان آن را باز کرد حلقه ی طلا را درون آن دید و بسیار خوشحال شد و آن را نزد پادشاه برد و منتظر بود که پادشاه به وعده اش عمل کند.\r\nاما دختر پادشاه خیلی مغرور بود و این شرط را قبول نداشت. او خود شرطی دیگر برای مرد جوان گذاشت. دختر پادشاه به باغ رفت و ده کیسه ارزن را با دستانش روی چمن ها ریخت و گفت \" تا فردا قبل از طلوع آفتاب باید تمام این ارزن ها را جمع کنی وگرنه کشته می شوی.\"\r\nمرد جوان همانجا نشست و با خودش فکر کرد چطوری این کار را انجام دهد، اما فکری به ذهنش نرسید و مایوس و نا امید منتظر صبح شد. اما با تابش اولین پرتو آفتاب، او ده کیسه ی ارزن را کنار خودش دید. ملکه ی مورچه ها با هزاران هزار مورچه به کمک او آمده بود، سربازان ملکه تمام ارزن ها را از روی چمن ها جمع آوری کرده بودند و داخل کیسه ها ریخته بودند.\r\nحالا دختر پادشاه خود به تنهایی به باغ آمد و از دیدن کیسه های ارزن سخت متعجب شد. اما دختر پادشاه بازهم مغرور و خودخواه گفت \"اگرچه همه ی کارها را به درستی انجام دادی، اما نمی توانی همسرم شوی تا سیب درخت زندگی را برایم بیاوری.\"\r\nمرد جوان اصلاً نمی دانست درخت زندگی کجاست، اما باز راهی شد و بعد از پیاده روی بسیار به جنگلی رسید. مرد جوان بسیار خسته شده بود و دیگر نمی توانست راه برود. او زیر درختی نشست و خوابش برد. کمی بعد صدای خش خشی از لابه لای شاخه های درخت شنید. ناگهان سیبی طلا از میان شاخ و برگ درختان در دستانش افتاد. در همین هنگام سه کلاغ به سمت او پرواز کردند و در کنار او نشستند و گفتند \" ما همان سه بچه کلاغیم که تو غذایت را به ما دادی. حالا ما بزرگ شدیم و سیب طلا را پیدا کردیم و برایت آوردیم.\" مرد جوان بسیار خوشحال شد و از آن ها تشکر کرد و راهی قصر پادشاه شد. او سیب طلا را به دختر پادشاه داد. دختر پادشاه دیگر بهانه ای نداشت. آن ها هر دو سیب را خوردند و برای سال های سال به خوبی خوشی با هم زندگی کردند.\r\n"},{"id":1137,"category_id":8,"category_code":"s8","source_id":98,"title":"خانم و آقای غول","content":"خانم غول آمد دیگ را بردارد، پایش لیز خورد و افتاد. دماغش کج شد، چشم هایش چپ شد. خانم غول، خودش راتوی آیینه دید و گفت: « وای وای چه دماغ کجی! چه چشم چپی! تا آقا غول نیامده، باید درستش کنم.»\r\nخانم غول یک تکه خمیر چسباند گوشه ی دماغش، دماغش صاف شد. سیم را گرد کرد، شکل عینک کرد. دو تا دکمه هم چسباند وسط دایره هایش. عینک دکمه ای را گذاشت به چشم هایش. آقا غول که آمد گفت: «به به چه بوی غذایی! چه خانه ی تمیزی! دست شما درد نکند خانمی!» بعد یکهو، عینک را دید و گفت: «چی به چشم هایت زدی خانمی؟! بگذار ببینم! تو جایی را هم می توانی ببینی؟» و آمد عینک را بردارد که عینک گیر کرد به دماغ خمیری.\r\nخمیر ترک خورد و افتاد و چشم و دماغ پیدا شد. آقا غول گفت: «چرا این شکلی شدی خانمی؟» و در اتاق راه رفت و فکر کرد، هی راه رفت و فکر کرد و بعد هم از خانه رفت. خانم غول گفت: «ای داد! رفت! آقا غول دیگر برنمی گردد.» و های های اشک ریخت. هی اشک ریخت، هی اشک ریخت. اشک هایش سیل شد و خانه را برد. برد و برد تا به جنگل رسید.\r\nخانه بین درخت ها گیر کرد. درخت ها گفتند: «خانم غول بس است دیگر! اگر باز هم گریه کنی، سیل ما را هم می برد!» خانم غول رفت و بالای یک درخت بلند، خوابید. ماه که آمد، آقا غول به خانه برگشت. اما نه خانه را دید، نه خانم غول را، آقا غول، رد خانه را گرفت و رفت و رفت تا به جنگل رسید. از درخت ها پرسید: «شما خانم غول را ندیدید؟» درخت ها، بالای یک درخت بلند را نشان دادند و گفتند: «خانم غول آن جاست!» آقا غول از درخت بالا رفت. از جیبش برگ و گلبرگ در آورد.\r\n\r\nبرگ ها را روی دماغ کج گذاشت، گلبرگ ها را روی چشم چپ گذاشت. خانم غول را توی خانه برد، لحاف را انداخت رویش تا سرما نخورد، بعد خانه را کول کرد و برد سرجایش گذاشت. خانم غول بیدار که شد، دید توی خانه است نه بالای درخت.\r\n\r\nگفت: «آقا غول برگشتی؟» آقا غول گفت: «بله که برگشتم! تو هر شکلی که باشی خانومیه آقا غولی!» بعد آیینه را به خانم غول داد. خانم غول به آیینه نگاه کرد، دماغش کمی صاف شده بود. چشم هایش هم کمی راست شده بود! خانم غول از خوشحالی به آسمان پرید! آقا غول هم به دنبال او پرید!\r\n"},{"id":1138,"category_id":8,"category_code":"s8","source_id":99,"title":"نی نی دایناسور مهربان","content":"یکی بود یکی نبود، غیر از خدا هیچ کس نبود. یک دایناسور کوچولو بود که پدر و مادرش او را «نی نی» صدا می زدند. مادرش به او می گفت: «نی نی مامان.» پدرش به او می گفت: «نی نی بابا.»\r\n\r\nدایناسور کوچولو دوست داشت مثل بقیه ی حیوانات کوچولو، بازی کند؛ اما هیچ کس با او بازی نمی کرد. بچه خرگوش به او گفته بود: «نه، نه، من با تو بازی نمی کنم. من خیلی کوچولو هستم. یک وقت توی بازی حواست نیست و من را زیر پایت لگد می کنی.»\r\nچند بچه سنجاب هم همین حرف را به او زده بودند. تازه آن ها به او گفته بودند: «تو قدّ یک درخت بزرگی، فقط برای بابا و مامانت نی نی هستی.» آن وقت نی نی دایناسور دلش تنگ شد. حوصله اش سر رفت و یواشکی گریه کرد. یک روز آفتابی که خورشید خانم موهای طلایی اش را روی دشت پهن کرده بود، چند بچه خرگوش و سنجاب روی تپه ی سبز قایم موشک بازی می کردند. نی نی دایناسور هم بازی آن ها را تماشا می کرد. یک دفعه سر و کله ی گرگ پیدا شد.\r\n\r\nچشمان گرگ از خوشحالی برقی زد. با خنده گفت: «به به، امروز چه غذاهایی چاق و تپلی گیرم آمده!» بعد زبان درازش را دور دهانش چرخاند. حیوان های کوچولو با دیدن گرگ جیغ کشیدند. قلبشان مثل یک گنجشک تند تند می زد. هر چه فرار می کردند گرگ به آن ها نزدیک می شد.\r\n\r\nیک دفعه یکی از بچه خرگوش ها گفت: «برویم پشت نی نی دایناسور، بعد همه دویدند و پشت نی نی دایناسور قایم شدند.\r\nنی نی دایناسور مهربان\r\n\r\nگرگ به نی نی دایناسور رسید، نفس نفس می زد و زبانش در آمده بود. بچه خرگوش ها و سنجاب کوچولوها روی پاهایشان می پریدند و گریه می کردند. دل نی نی دایناسور پر از غصّه شد. خودش را روی گرگ خم کرد و گفت: «آن ها دوستان من هستند. هر چه زودتر از این جا برو.» دل گرگ لرزید. پیش خودش فکر کرد چه بد شانسی آورده ام؛ اما به نی نی دایناسور گفت: «اگر نروم چه کار می کنی؟ نی نی دایناسور با عصبانیّت گفت: «اگر نروی با دست های بزرگم تو را هل می دهم تا از روی تپه بیفتی.» گرگ نمی خواست گرد و قلنبه شود، نمی خواست قل بخورد و از تپه بیفتد.\r\n\r\nاین بود که دمش را روی کولش گذاشت و فوری از آنجا رفت. بچه خرگوش ها و بچه سنجاب ها خوشحال شدند. با صدای بلند خندیدند و دور نی نی دایناسور چرخیدند.\r\n\r\nپدر و مادر نی نی دایناسور از آن دور، تپه را نگاه کردند و خوشحال شدند. چون حالا روی تپه ی سبز، نی نی دایناسور آن ها با چند سنجاب و خرگوش مشغول بازی بودند.\r\n"},{"id":1139,"category_id":8,"category_code":"s8","source_id":100,"title":"شیر بدجنس و روباه ی باهوش","content":"یکی بود یکی نبود. در جنگلی بزرگ و سرسبز شیری پیر زندگی می کرد. او آن قدر پیر شده بود که دیگر نمی توانست برای خودش شکاری پیدا کند. آقا شیر از گرسنگی بسیار ضعیف شد. پس با خودش فکر کرد و بالاخره راه حلی پیدا کرد.\r\nاو تصمیم گرفت در غارش دراز بکشد و خودش را به مریضی بزند و وقتی دیگران به ملاقاتش آمدند، آن ها را شکار کند. شیر پیر نقشه ی پلیدش را عملی کرد. در غارش دراز کشید و منتظر ماند. حیوانات زیادی به ملاقات شیر آمدند، اما شیر بدجنس همه ی آن ها را شکار کرد.\r\nیک روز، روباه به ملاقات آقای شیر آمد، اما از آن جایی که روباه طبیعتاً حیوان زرنگ و باهوشی است، دم در غار ایستاد و اطراف غار را وارسی کرد. حس ششم روباه به کمکش آمد و متوجه ی موضوع شد. بنابراین روباه از بیرون غار با صدای بلند پرسید، آقای شیر، خدا بد نده، چطوری؟\r\nشیر گفت: اصلاً حالم خوب نیست. حالا چرا بیرون ایستادی، بیا تو؟\r\nروباه باهوش جواب داد: خیلی دلم می خواهد از نزدیک حال شما رابپرسم، اما نمی توانم. چون تمام ردپاها نشان می دهد که حیوانات وارد غار شده اند ولی هیچ کدام برنگشته اند. منم که احمق نیستم، پس از همین بیرون احوال شما را می پرسم.\r\nبعد روباه به سمت جنگل برگشت و همه چیز را برای بقیه ی حیوانات تعریف کرد.\r\n"},{"id":1140,"category_id":8,"category_code":"s8","source_id":101,"title":"موهای جادویی","content":"روزگاری زن و مردی زندگی می کردند که فرزندی نداشتند . بالاخره آرزوی آنها به حقیقت پیوست. آنها منتظر ورود کوچولویی به خانه اشان بودند.\r\nپشت خانه آنها پنجره ای قرار داشت که به یک باغ زیبا و بزرگ باز می شد . باغ پر از گلهای زیبا و درختهای میوه بود . این باغ متعلق به یک جادگرو بدجنس بود و هیچ کس جرات نمی کرد به داخل باغ برود.\r\nزن باردار بود و از پنجره به این باغ زیبا نگاه می کرد . روزی در باغ مقدار زیادی کاهو وحشی با برگهای سبز و تازه دید . از آن روز به بعد او نمی توانست به هیچ چیز دیگری به غیر از آن سبزیها فکر کند . کم کم رنگ و رویش پرید و صورتش هر روز سفیدتر از روز قبل می شد و بیماری به سراغ او آمد.\r\nمرد از همسرش علت بیماری را پرسید .\r\n\r\nزن گفت : من می دانم که هیچ وقت نمی توانم از آن کاهو یی که پشت خانه امان است بخورم و می دانم که الان در هیچ جایی به غیر از آن باغ نمی توان کاهو پیدا کرد و می دانم که بزودی می میرم .\r\nمرد خیلی نگران شد و تصمیم گرفت که به هر قیمتی که شده است آن سبزی را برای همسرش فراهم کند بنابراین یک شب مخفیانه به آن باغ رفت و از آن کاهو ها چید و به خانه برگشت و برای همسرش سالاد درست کرد\r\nزن آنرا خورد و حالش بهتر شد . اما عجیب بود که مرتب هوسش برای خوردن کاهو بیشتر می شد . مرد دوباره به باغ برگشت ولی این بار توسط جادوگر گرفتار شد .\r\nجادوگر در حالیکه از عصبانیت فریاد می کشید به او گفت : تو چگونه به خودت اجازه دادی که سبزیهای راپونزل ( همان کاهو ها منظورش بود ) مرا بچینی ؟\r\nمرد ماجرای همسرش را تعریف کرد . جادوگر فکر کرد و گفت : تو می توانی هر چقدر که بخواهی از این کاهوها بچینی اما یک شرطی دارد . تو باید وقتی فرزندت بدنیا آمد آنرا به من بدهی.\r\nمرد بیچاره که می دانست حال همسرش خوب نیست به ناچار این شرط را پذیرفت.\r\nبه زودی فرزند آنها بدنیا آمد و جادوگر او را با خودش برد . او نام این دختر را راپونزل نامید .\r\nراپونزل بزرگ شد و هر چه می گذشت زیباتر می شد جادوگر تصمیم گرفت ،اجازه ندهد که کسی اور ا ببیند.\r\nوقتی که راپونزل 12 ساله شد او را به برج بلندی در وسط جنگل برد . این برج خیلی بلند بود و هیچ پله یا دری نداشت و راپونزل بیچاره نمی توانست از آنجا بیرون برود. برج فقط یک پنجره داشت. زمانیکه پیرزن به دیدنش می آمد او را صدا می کرد .\r\nراپونزل > راپونزل موهای طلایی ات را پایین بیانداز .\r\n\r\nدخترک موهای بلندش را از پنجره به بیرون می انداخت و جادوگر موهایش را می گرفت و به بالای برج می آمد.\r\nچند سالی گذشت . روزی پرنسی بطور اتفاقی از آن قسمت جنگل می گذشت که ناگهان صدای قشنگ و دلنشینی را شنید. او برج را پیدا کرد . اما هیچ راهی را برای ورود به برج نیافت.\r\nاو نمی توانست صدا را فراموش کند برای همین هر روز به آنجا می آمد و به آن صدا گوش می داد و شبها با قلبی شکسته برمی گشت\r\nاو هنوز هیچ راهی برای ورود به برج پیدا نکرده بود\r\nتا اینکه روزی پیرزنی را دید که به سمت برج می آید در گوشه ای مخفی شد و صدای پیرزن را شنید که می گفت .\r\nراپونزل ، راپونزل موهای طلایی ات را پایین بیانداز .\r\nسپس یک موی بافته شده بلند از پنجره به سمت زمین پرت شد و پیرزن از آن بالا رفت .\r\nپرنس فکر کرد من هم شانس خود را امتحان می کنم تا از این برج بالا بروم .\r\nبعد از مدتی پیرزن از آنجا رفت و پرنس کنار پنجره آمد و حرفهای او را تکرار کرد .\r\nراپونزل > راپونزل موهای طلایی ات را پایین بیانداز .\r\nسپس از آن موی بلند بالا رفت و به برج رسید .\r\nدر ابتدا راپونزل از دیدن مرد ترسید چون تا آن روز هیچ کسی را ندیده بود . اما پرنس برایش توضیح داد که صدای قشنگش او را به آنجا کشانده است . پرنس که تا آن روز دختری به آن زیبایی و مهربانی ندیده بود از دختر خواست که برای همیشه در کنار او باشد و پیشنهاد ازدواجش را قبول کند.\r\nراپونزل احساس می کرد که در کنار این مرد خوش اندام و مودب زندگی لذت بخش تر از زندگی کنار آن پیرزن است بنابراین پیشنهاد پرنس را قبول کرد .\r\n\r\nاما او از هیچ راهی نمی توانست از آن برج خارج شود بنابراین از پرنس خواست که برایش گلولهای ابریشمی بیاورد تا با آن طنابی درست کند و از آنجا خارج شود .\r\nتا زمانی که طناب بافته شود پرنس هر شب به دیدن راپونزل می آمد . راپونزل دقت می کرد که ملاقاتش را با پرنس مخفی نگه دارد . اما یک روز بدون اینکه به حرفهایش فکر کند به جادوگر گفت : چرا شما اینقدر سنگین تر از پرنس هستید ؟\r\nیکدفعه جادوگر با عصبانیت فریاد کشید . من چی شنیدم ؟ من فکر می کردم تو را در جای امنی پنهان کردم اما تو برخلاف نظر من با دیگران ملاقات داشتی . تو به من کلک می زدی !\r\nاو با عصبانیت موهای راپونزل را دور دستش پیچاند و با یک قیچی آنرا برید .و لحظه ای بعد موهای بلند راپونزل روی زمین افتاده بود . اما پیرزن هنوز عصبانی بود . آن سنگدل یک ورد جادویی خواند و راپونزل را به یک جای خیلی دور فرستاد تا برای همیشه بدبخت و تنها باشد .\r\n\r\nسپس موهای راپونزل را به موهای خودش گره زد و کنار پنجره منتظرپرنس نشست . هنگامیکه پرنس از پنجره داخل شد بجای راپونزل عزیزش آن پیرزن زشت را دید\r\nپیرزن در حالی که خنده ی مسخره ای سر داده بود گفت : تو فکر می کنی عشقت را پیدا خواهی کرد ؟ اما آن پرنده زیبا پرواز کرد و رفت و صدایش خاموش شد . راپونزل برای همیشه گم شده و تو هیچگاه او را نخواهی دید .\r\nپرنس از خود بیخود شده بود و خودش را از پنجره به بیرون پرت کرد . اما از خطر مردن نجات پیدا کرد چون روی بوته های خار افتاد . اما خارها چشمان او را زخمی کردند و پرنس نابینا شد . حالا او چطور می توانست راپونزل را پیدا کند ؟\r\n\r\nبرای ماه ها پرنس نابینا در میان جنگل سرگردان بود . هرگاه که به کسی می رسید از آنها در مورد دختر زیبایی بنام راپونزل می پرسید . او برای همه نشانه های او را توصیف می کرد اما کسی او را ندیده بود .\r\nاو آنقدر رفت و رفت تا روزی صدای آهنگ غمگینی را شنید . او صدا را شناخت و به آنطرف رفت. صدا زد : راپونزل\r\nراپونزل به طرف پرنس دوید و از شوق دیدار او اشک در چشمانش سرازیر شد . اما وقتی قطرات اشک بر روی چشمهای پرنس افتاد اتفاق عجیبی پیش آمد . پرنس دوباره می توانست ببیند.\r\nپرنس راپونزل را به سرزمین خودش برد و بعد از ازدواج سالها به خوشی زندگی کردند\r\n"},{"id":1141,"category_id":8,"category_code":"s8","source_id":102,"title":"کسی کمک من می کند؟","content":"\r\nيك مرغ حنايي كوچولو همراه با دوستانش در مزرعه زندگي مي كرد.دوستان او يك سگ خاكستري، يك گربه ي نارنجي و يك غاز زرد بودند.\r\nيك روز مرغ حنايي مقداري دانه گندم پيدا كرد. او پيش خودش فكر كرد ، \"من مي توانم با اين دانه ها ، نان درست كنم .\r\nمرغ حنائي كوچولو پرسيد: كسي به من كمك مي كند تا اين دانه ها را بكارم؟\r\nسگ گفت: من نمي توانم.\r\nگربه گفت: من دلم مي خواهد ولي كار دارم و نمي توانم.\r\nغاز گفت: من امروز بايد به بچه هايم شنا ياد بدهم و نمي توانم.\r\nمرغ حنائي گفت: پس من خودم اين كار را خواهم كرد.او بدون كمك كسي دانه ها را كاشت.\r\nمرغ حنائي كوچولو پرسيد: كسي مي تواند در دروكردن گندم به من كمك كند؟\r\nسگ گفت: من بايد به شكار بروم.\r\nگربه گفت: من تازه از خواب بيدار شدم و حال ندارم.\r\n\r\nغاز گفت: من بالم درد مي كند.\r\nمرغ گفت: پس خودم تنهايي آنرا انجام مي دهم. مرغ كوچولو بدون كمك كسي گندم ها را دروكرد.\r\nمرغ حنايي كه خسته شده بود، پرسيد: كسي به من كمك مي كند كه اين گندمها را به آسياب ببريم و آنها را آرد كنيم؟\r\nسگ گفت: من نمي توانم.\r\nگربه گفت :من نمي توانم.\r\nغاز گفت: من هم نمي توانم.\r\nمرغ حنايي گفت: خودم اينكار را خواهم كرد. او گندمها را به آسياب برد و تنهايي آنها را آرد كرد بدون اينكه كسي به او كمك كند.\r\nمرغ حنايي كه خيلي خيلي خسته بود، پرسيد: كسي به من كمك مي كند تا با اين آرد نان بپزيم؟\r\nولي باز هم سگ و گربه و غاز به او كمك نكردند و هر كدام بهانه اي آوردند.\r\nمرغ حنايي گفت:خودم اين كار را خواهم كرد. و بعد مرغ خسته بدون كمك كسي نان پخت.\r\nنان تازه و داغ بوي خيلي خوبي داشت. مرغ حنايي پرسيد: آيا كسي به من كمك مي كند تا نان را بخوريم.\r\nسگ گفت: من كمك خواهم كرد.\r\nگربه گفت: من كمك خواهم كرد.\r\nغاز گفت: من كمك خواهم كرد.\r\nاما مرغ حنايي با عصبانيت فرياد كشيد، من نيازي به كمك شما ندارم و خودم تنها اين كار را خواهم كرد.\r\n\r\nمرغ حنايي نان را جلوي خودش گذاشت و همه آن را خورد.\r\n"},{"id":1142,"category_id":8,"category_code":"s8","source_id":103,"title":"باغ گلابی","content":"حامد در حالیکه بشدت خسته و گرسنه بود به کنار باغ مش‌نعمت رسید. از شکاف دیوار نگاهی به داخل باغ انداخت.\r\nگلابی‌های رسیده و آبدار از شاخه‌ها آویزان بودند و هر رهگذر خسته‌ای را بسوی خود می‌خواندند.حامد با دقت داخل باغ را نگاه کرد، هیچ‌کس آنجا نبود. با زحمت خود را از شکاف دیوار به داخل باغ کشاند.\r\nبه سراغ یکی از درخت‌های گلابی رفت و آن را تکان داد.چند گلابی درشت و رسیده بر زمین افتاد. حامد دیگر معطل نکرد و با اشتهای فراوان شروع به خوردن گلابی‌ها کرد.\r\nاو آنقدر مشغول خوردن شده بود که صدای پای مش‌نعمت را نشنید.در حالیکه دهانش پر از گلابی بود، ناگهان مش‌نعمت را در مقابل خود دید که با چوب‌دستی‌اش روبروی او ایستاده و با خشم نگاهش می‌کند.\r\nحامد به زحمت گلابی‌ها را فرو داد و قبل از آنکه مش‌نعمت چیزی بگوید، گفت:این باغ، باغ خداست. این میوه‌ها هم از آن خداست. من هم بنده‌ی خدا هستم.\r\nحالا تو بگو آیا اشکالی دارد که بنده‌ی خدا، از باغ خدا، میوه‌ی خدا را بخورد؟مش‌نعمت که از شدت عصبانیت سرخ شده بود، چوبدستی‌اش را بلند کرد و محکم بر پهلوی حامد کوبید.حامد فریادی از درد کشید و گفت:.\r\n\r\n\r\n\r\nاین باغ، باغ خداست. این میوه‌ها هم از آن خداست. من هم بنده‌ی خدا هستم. حالا تو بگو آیا اشکالی دارد که بنده‌ی خدا، از باغ خدا، میوه‌ی خدا را بخورد؟\r\nمش‌نعمت که از شدت عصبانیت سرخ شده بود، چوبدستی‌اش را بلند کرد و محکم بر پهلوی حامد کوبید.\r\nحامد فریادی از درد کشید و گفت:\r\nمگر من برایت توضیح ندادم؟ پس چرا می‌زنی؟\r\nمش‌‌نعمت در حالیکه با یک دست چوبدستی‌اش را بر کف دست دیگرش می‌زد، گفت:\r\nاین چوبدستی را می‌بینی؟ این چوب خداست. دست مرا هم می‌بینی؟دست یک بنده‌ی خداست.\r\nخودت هم که گفتی بنده‌ی خدا هستی. حالا بگو ببینم آیا اشکالی دارد که بنده‌ی خدا با چوب خدا، بنده‌‌ی دیگر خدا را کتک بزند؟\r\nآنگاه دوباره چوب‌دستی‌اش را بلند کرد و بر پشت حامد کوبید.\r\nحامد از جا بلند شد و در حالیکه از درد به خود می‌پیچید گفت:\r\nاز آنچه گفتم معذرت می‌خواهم. باغ، باغ خداست ولی من نباید دزدانه داخل آن می‌شدم.\r\nچوب هم چوب خداست ولی تو را به خدا دیگر مرا با آن نزن!\r\nمش‌نعمت با شنیدن این سخنان چوب‌دستی‌اش را بر زمین انداخت و گفت:\r\nزود از باغ من بیرون برو\r\nو سپس از آنجا دور شد.\r\nگلابی‌های رسیده و آبدار از شاخه‌ها آویزان بودند و هر رهگذر خسته‌ای را بسوی خود می‌خواندند.حامد با دقت داخل باغ را نگاه کرد، هیچ‌کس آنجا نبود.\r\nبا زحمت خود را از شکاف دیوار به داخل باغ کشاند. به سراغ یکی از درخت‌های گلابی رفت و آن را تکان داد.چند گلابی درشت و رسیده بر زمین افتاد. حامد دیگر معطل نکرد و با اشتهای فراوان شروع به خوردن گلابی‌ها کرد.\r\nاو آنقدر مشغول خوردن شده بود که صدای پای مش‌نعمت را نشنید.در حالیکه دهانش پر از گلابی بود، ناگهان مش‌نعمت را در مقابل خود دید که با چوب‌دستی‌اش روبروی او ایستاده و با خشم نگاهش می‌کند.\r\nحامد به زحمت گلابی‌ها را فرو داد و قبل از آنکه مش‌نعمت چیزی بگوید، گفت:این باغ، باغ خداست. این میوه‌ها هم از آن خداست.\r\nمن هم بنده‌ی خدا هستم. حالا تو بگو آیا اشکالی دارد که بنده‌ی خدا، از باغ خدا، میوه‌ی خدا را بخورد؟مش‌نعمت که از شدت عصبانیت سرخ شده بود، چوبدستی‌اش را بلند کرد و محکم بر پهلوی حامد کوبید.حامد فریادی از درد کشید و گفت:.\r\nاین باغ، باغ خداست. این میوه‌ها هم از آن خداست. من هم بنده‌ی خدا هستم. حالا تو بگو آیا اشکالی دارد که بنده‌ی خدا، از باغ خدا، میوه‌ی خدا را بخورد؟\r\nمش‌نعمت که از شدت عصبانیت سرخ شده بود، چوبدستی‌اش را بلند کرد و محکم بر پهلوی حامد کوبید.\r\n\r\nحامد فریادی از درد کشید و گفت:\r\nمگر من برایت توضیح ندادم؟ پس چرا می‌زنی؟\r\nمش‌‌نعمت در حالیکه با یک دست چوبدستی‌اش را بر کف دست دیگرش می‌زد، گفت:\r\nاین چوبدستی را می‌بینی؟ این چوب خداست. دست مرا هم می‌بینی؟دست یک بنده‌ی خداست.\r\n\r\n\r\nخودت هم که گفتی بنده‌ی خدا هستی. حالا بگو ببینم آیا اشکالی دارد که بنده‌ی خدا با چوب خدا، بنده‌‌ی دیگر خدا را کتک بزند؟\r\nآنگاه دوباره چوب‌دستی‌اش را بلند کرد و بر پشت حامد کوبید.\r\nحامد از جا بلند شد و در حالیکه از درد به خود می‌پیچید گفت:\r\nاز آنچه گفتم معذرت می‌خواهم. باغ، باغ خداست ولی من نباید دزدانه داخل آن می‌شدم.\r\nچوب هم چوب خداست ولی تو را به خدا دیگر مرا با آن نزن!\r\nمش‌نعمت با شنیدن این سخنان چوب‌دستی‌اش را بر زمین انداخت و گفت:\r\nزود از باغ من بیرون برو\r\nو سپس از آنجا دور شد.\r\n"},{"id":1143,"category_id":8,"category_code":"s8","source_id":104,"title":"گرگ و الاغ","content":"روزي الاغ هنگام علف خوردن ،‌كم كم از مزرعه دور شد . ناگهان گرگ گرسنه اي جلوي او پريد\r\nالاغ خيلي ترسيد.\r\nولي فكر كرد كه بايد حقه اي به گرگ بزند وگرنه گرگه اونو يك لقمه مي كنه ، براي همين لنگان\r\nلنگان راه رفت و يكي از پاهاي عقب خود را روي زمين كشيد .\r\nالاغ ناله كنان گفت : اي گرگ در پاي من تيغ رفته است ، از تو خواهش مي كنم كه قبل از\r\nخوردنم اين تيغ را از پاي من در بياوري .\r\nگرگه با تعجب پرسيد : براي چه بايد اينكار را بكنم من كه مي خواهم تو را بخورم .\r\nالاغ گفت : چون اين خار كه در پاي من است و مرا خيلي اذيت مي كند اگر مرا بخوري در\r\nگلويت گير مي كند وتو را خفه مي كند .\r\nگرگ پيش خودش فكر كرد كه الاغ راست مي گويد براي همين پاي الاغ را گرفت و گفت : تيغ\r\nكجاست؟ من كه چيزي نمي بينم و سرش را جلو آورد تا خوب نگاه كنه .\r\nدر همين لحظه الاغ از فرصت استفاده كرد و با پاهاي عقبش لگد محكمي به صورت گرگ زد و\r\nتمام دندانهاي گرگ شكست .\r\nالاغ با سرعت از آنجا فرار كرد . گرگ هم خيلي عصباني بود از اينكه فريب الاغ را خورده است .\r\n"},{"id":1144,"category_id":8,"category_code":"s8","source_id":105,"title":"گربه ی تنها","content":"در يك باغ زيبا و بزرگ ، گربه پشمالويي زندگي مي كرد .او تنها بود . هميشه با حسرت به گنجشكها كه روي درخت با هم بازي مي كردند نگاه مي كرد .\r\nيكبار سعي كرد به پرندگان نزديك شود و با آنها بازي كند ولي پرنده ها پرواز كردند و رفتند .\r\nپيش خودش گفت : كاش من هم بال داشتم و مي توانستم پرواز كنم و در آسمان با آنها بازي كنم .\r\n\r\nديگر از آن روز به بعد ، تنها آرزوي گربه پشمالو پرواز كردن بود .\r\nآرزوي گربه پشمالو را فرشته اي كوچك شنيد . شب به كنار گربه آمد و با عصاي جادوئي خود به شانه هاي گربه زد .\r\nصبح كه گربه كوچولو از خواب بيدار شد احساس كرد چيزي روي شانه هايش سنگيني مي كند .وقتي دو بال قشنگ در دو طرف بدنش ديد خيلي تعجب كرد ولي خوشحال شد\r\nخواست پرواز كند ولي بلد نبود .\r\nاز آن روز به بعد گربه پشمالو روزهاي زيادي تمرين كرد تا پرواز كردن را ياد گرفت البته خيلي هم زمين خورد .\r\nروزي كه حسابي پرواز كردن را ياد گرفته بود ،‌در آسمان چرخي زد و روي درختي كنار پرنده ها نشست.\r\n\r\n\r\nوقتي پرنده ها متوجه اين تازه وارد شدند ، از وحشت جيغ كشيدند و بر سر گربه ريختند و تا آنجا كه مي توانستند به او نوك زدند . گربه كه جا خورده بود و فكر چنين روزي را نمي كرد از بالاي درخت محكم به زمين خورد .\r\nيكي از بالهايش در اثر اين افتادن شكسته بود و خيلي درد مي كرد\r\nشب شده بود ولي گربه پشمالو از درد خوابش نمي برد و مرتب ناله مي كرد .\r\nفرشته كوچولو ديگر طاقت نياورد ، خودش را به گربه رساند .\r\nفرشته به او گفت : آخه عزيز دلم هر كسي بايد همانطور كه خلق شده ، زندگي كند . معلوم است كه اين پرنده ها از ديدن تو وحشت مي كنند و به تو آزار مي رسانند . پرواز كردن كار گربه نيست . تو بايد بگردي و دوستاني روي زمين براي خودت پيدا كني .\r\n\r\nبعد با عصاي خود به بال گربه پشمالو زد و رفت\r\nصبح كه گربه پشمالو از خواب بيدار شد ديگر از بالها خبري نبود . اما ناراحت نشد .\r\nياد حرف فرشته كوچك افتاد . به راه افتاد تا دوستي مناسب براي خود پيدا كند .\r\nبه انتهاي باغ رسيد . خانه قشنگي در آن گوشه باغ قرار داشت . خودش را به خانه رساند و كنار پنجره نشست .\r\nدر اتاق دختر كوچكي وقتي صداي ميو ميوي گربه را شنيد ، با خوشحالي كنار پنجره آمد . دختر كوچولو گربه را بغل كرد و گفت : گربه پشمالو دلت مي خواد پيش من بماني . من هم مثل تو تنها هستم و هم بازي ندارم . اگر پيشم بماني هر روز شير خوشمزه بهت مي دم .\r\nگربه پشمالو كه از دوستي با اين دختر مهربان خوشحال بود ميو ميوي كرد و خودش را به دخترك چسباند.\r\n"},{"id":1145,"category_id":8,"category_code":"s8","source_id":106,"title":"گردش لاکپشتها","content":"يكي بود يكي نبود . خانم لاك پشت و آقا لاك پشت تصميم گرفتند كه همراه پسرشان به گردش بروند . آنها بيشه اي كه كمي دورتر از خانه اشان بود را انتخاب كردند .\r\nوسايلشان را جمع كردند و به راه افتادند و بعد از يك هفته به آن بيشه قشنگ رسيدند .\r\nسبدهايشان را باز كردند و سفره را چيدند ولي يكدفعه مامان لاك پشته با ناراحتي گفت : يادم رفت درقوطي بازكن را بياورم .\r\nپدر لاك پشت به پسرش گفت : پسرم تو برگرد و آن را بياور .\r\n\r\nپسرك اول قبول نكرد ، ولي پدر برايش توضيح داد كه ما بدون دربازكن نمي توانيم قوطي ها را باز كنيم و چيزي بخوريم و صبر مي كنيم تا تو برگردي . ما به تو قول مي دهيم.\r\nپسرك با ناراحتي به راه افتاد\r\nسه روزگذشت ، آنها خيلي گرسنه بود . ولي چون قول داده بودند ، باز هم انتظار كشيدند .\r\nيك هفته گذشت ، مادر به پدر گفت : مي خواهي چيزي بخوريم ، او كه نخواهد فهميد .\r\nپدر گفت : نه ما قول داده ايم و بايد صبر كنيم .\r\nخلاصه سه هفته گذشت . مادر گفت : چرا دير كرده بايد تا حالا مي رسيد .\r\nپدر گفت : آره حق با شماست ، بهتر است تا او برگردد ، لااقل ميوه اي بخوريم .\r\nآنها ميوه اي بر داشتند اما قبل از اينكه بخورند صدايي به گوششان رسيد كه گفت : آهان ! مي دانستم تقلب مي كنيد .\r\nاين صداي بچه لاك پشت بود كه از پشت بوته ها بيرون آمد .\r\nو گفت : ديديد زير قولتان زديد ؟ چه خوب شد كه نرفتم !\r\n"},{"id":1146,"category_id":8,"category_code":"s8","source_id":107,"title":"چشمه ی سحر آمیز","content":"روزی روزگاری در یک جنگل بزرگ خرگوش کنجکاوی زندگی می کرد. یک روز، خرگوش کنجکاو درحال دویدن و بازی کردن بود که به چشمه ای سحر آميز رسید.\r\n\r\nخرگوش می خواست از چشمه آب بنوشد که ناگهان زنبوری خود را به خرگوش رساند و به او گفت: از این چشمه آب ننوش. هر كه از اين آب بنوشد كوچك مي شود.\r\nاما خرگوش به حرف زنبور گوش نکرد و از آب چشمه نوشید. خرگوش به اندازه ی یک مورچه، كوچك شد.\r\nخرگوش خیلی ناراحت شد و از زنبور پرسيد: حالا چکار کنم؟ خواهش می کنم به من کمک کن تا دوباره مثل قبل شوم .\r\nزنبورگفت: من به تو گفتم از این چشمه، آب نخور ولي تو توجه نكردي.\r\nخرگوش پرسيد: حالا چه کار کنم؟\r\nزنبورگفت : توباید به کوه جادو بروی تا راز چشمه را کشف کنی. خرگوش و زنبور رفتند و رفتند تا به کوه جادو رسیدند.\r\nخرگوش پرسيد: حالا باید چکار کنم ؟\r\nزنبور گفت : تو باید جواب معمایی را که روی کوه جادو نوشته شده پیدا کنی.\r\nخرگوش شروع به خواندن معما کرد .\r\nمعمای اول این بود: آن چیست که گریه می کند اما چشم ندارد ؟\r\nخرگوش نشست و فکر کرد. ناگهان فریاد زد و گفت: فهمیدم، فهمیدم، آن ابر است .\r\nبا گفتن این حرف خرگوش ، سنگی که معما روی آن نوشته شده بود كنار رفت و آنها داخل يك راهرو شدند ولي اتنهاي راهرو هم بسته بود و معمای دیگری روي ديوار نوشته شده بود .\r\nمعما این بود: آن چیست که جان ندارد ولی دنبال جاندار می گردد؟\r\nخرگوش باز هم فکرکرد و گفت: فهمیدم تفنگ است.\r\nبا گفتن جواب معما، سنگ دوم هم كنار رفت و غاری در برابر خرگوش ظاهر شد .زنبور به خرگوش گفت : تو باید به درون غار بروی . خرگوش به درون غار رفت و در آنجا چشمه ای دید که شبیه چشمه جادویی بود.\r\n\r\n\r\nزنبور به خرگوش گفت که تو باید از این آب بنوشی. خرگوش از آب چشمه نوشید و دوباره به شکل عادی خود برگشت و از زنبور تشکر کرد.\r\nزنبور گفت حالا راز چشمه را فهمیدی ؟\r\nخرگوش گفت: بله. من باید به تو اعتماد می کردم و چون مرا آگاه كرده بودي نبايد از آب چشمه می نوشیدم .\r\nمن ياد گرفتم كه به نصيحت دلسوزانه بزرگتران توجه كنم و به حرف آنها اعتماد كنم تا دچار مشكلي نشوم . آري راز چشمه اعتماد بود .\r\n"},{"id":1147,"category_id":8,"category_code":"s8","source_id":108,"title":"گنج دزد دریایی","content":"ريش آبي غرغر مي كرد و مي گفت: ده قدم از ايوان و بيست قدم از بوته رز، اينجا . گنج اينجاست . اين خوابي بود كه اون شب جاويد ديد.\r\nروز بعد جاويد شروع به كندن زمين كرد او آنقدر زمين را كند كه يك گودال عميق بوجود آمد.\r\nاو به كندن ادامه داد . هر چه گودال عميق تر مي شود تله خاكي كه كنار آن بود بلندتر مي شد.\r\nاو آقدر زمين را كند كه حفره اي بسيار عميق و تله خاكي بسيار بلند درست شد. او نفسي تازه كرد و گفت: خيلي خسته شدم ، ديگه نمي توانم ادامه دهم . ناگهان چيزي توجه او را جلب كرد.\r\nاما بجاي گنج، فقط يك استخوان پيدا كرد . جاويد يك تكه استخوان و يك حفره و يك تل خاك بزرگ روبرويش بود . او پيش خودش فكر كرد \" آن دزد دريايي به من دروغ گفت\"\r\nاماوقتي مادر جاويد مشاهده كرد كه پسرش چه كاري كرده است برايش دست زد و لبخند زد .\r\nاوه جاويد متشكرم . من هميشه مي خواستم بوته بزرگ گل در اينجا بكارم و از تو متشكرم كه اين گودال را برايم كندي. اين هم يك اسكناس براي كندن گودال!\r\n"},{"id":1148,"category_id":8,"category_code":"s8","source_id":109,"title":"مورچه ی بی دقت","content":"آن شب برف سنگيني باريده بود . همه جا سرد بود .موچي ( مورچه كوچولو ) و فيلو ( فيل كوچولو ) در خانه خوابيده بودند . بخاري كوچك آنها روشن بود اما نمي توانست همه خانه را گرم كند .\r\nموچي گفت : \" بايد يك فكري بكنيم كه خانه را گرم كنيم .\r\nو بعد گفت : \" يك فكر حسابي دارم . ما مي توانيم تمام شعله هاي اجاق گاز را روشن كنيم تا خانه گرم شود .\"\r\nفيلو گفت : \" اما اين كار خطرناك است . مگر يادت نيست كه آقاي ايمني مي گفت هيچوقت اين كار را نكنيد ؟\r\nموچي گفت : آقاي ايمني در خانه گرمش خوابيده و نمي داند كه ما داريم از سرما مي لرزيم .\r\nموچي اين را گفت و سراغ اجاق گاز رفت و همه شعله ها را روشن كرد .\r\n\r\nكم كم خانه گرم شد ولي بوي گاز همه جا را گرفته بود .\r\nموچي كه گرمش شده بود پنجره را باز كرد .\r\nچند دقيقه بعد صداي زنگ در بلند شد . فيلو با تعجب در را باز كرد . آقاي ايمني پشت در بود .\r\n\r\nآقاي ايمني گفت :\" داشتم از اينجا عبور مي كردم ، ديدم توي اين سرما پنجره هايتان باز است، تعجب كردم . گفتم در بزنم و بپرسم اينجا چه خبر است ؟ ! \"\r\nفيلو گفت : \" موچي سردش بود و اجاق گاز را روشن كرد تا خانه را گرم كند و حالا هم گرمش شده و رفته پنجره را باز كرده\r\nآقاي ايمني فرياد زد : \" چي ؟ مگر اجاق گاز بخاري است كه با آن خانه را گرم مي كنيد ؟\r\nاول اين كه گرم كردن خانه با شعله هاي اجاق گاز كار اشتباهي است . \"\r\nفيلو با سرعت دويد و گاز را خاموش كرد .\r\n\r\nبعد آقاي ايمني ادامه داد : شما نبايد آنقدر خانه را گرم كنيد كه مجبور شويد پنجره ها را باز كنيد . هيچ مي دانيد اينطوري چقدر گاز هدر مي رود ؟\r\nشما مي توانيد لباس گرم بپوشيد و يا جلو در و پنجره ها پرده هاي كلفت بزنيد تا گرماي خانه هدر نرود .\r\nبايد در زمستان جلوي دريچه كولر را بپوشانيد تا گرماي خانه هدر نرود .\r\nفيلو با سرعت رفت و مقداري لباس آورد و به موچي گفت : اين لباسها را بپوش . من مي روم جلوي پنجره ها پرده بزنم .\r\nساعتي بعد، پرده هاي پنجره زده شد . فيلو با يك تكه نايلن، جلوي دريچه كولر را هم پوشاند .\r\nآقاي ايمني گفت : دوستان عزيز يادتان باشد موقع خواب شعله بخاري را كم كنيد و از پتو و لحاف مناسب استفاده كنيد .\r\nآقاي اميني خداحافظي كرد و رفت . حالا خانه گرم شده بود و همه راحت بخواب رفتند .\r\n"},{"id":1149,"category_id":8,"category_code":"s8","source_id":110,"title":"اردک خوش شانس","content":"پدر برای دختر و پسرش کتاب می خواند .اسم کتاب اردک خوش شانس، خوش شانس، خوش شانس بود. قصه اینطوری بود که.... روزی یک اردک خوشگل و دوست داشتنی برای گردش بیرون رفت و خیلی زود یک گودال آب تمیز و دوست داشتنی پیدا کرد.\r\nاوه، چه اردک خوش شانسی! اردک خوش شانس گفت: \"کواک\" اردک کوچک و دوست داشتنی، توی گودال کوچک و زیبا شیرجه رفت. اوه، چه اردک خوش شانس، خوش شانسی. اردک خوش شانس، خوش شانس گفت: \"کواک\" ، \"کواک\" اردک کوچک و دوست داشتنی، از توی چاله پز از آب قشنگ بیرون آمد و زیر نور آفتاب چرتی زد . اوه ، چه اردک خوش شانس ، خوش شانس ، خوش شانسی.\r\nالبته اردک خوش شانس خوش شانس خوش شانس طوری خر و پف می کرد که انگار می گفت : \"کواک\" ، \"کواک\" ، \"کواک\" دختر کوچولو که به قصه گوش می داد ، نفس عمیقی کشید و گفت: چه اردک بانمکی. شاید این قشنگترین چیزی باشد که من تا بحال دیده ام پسر کوچولو سرش را خاراند و گفت: اما توی این قصه همه چیز خیلی خوب و دوست داشتنی بود و این نمی تواند واقعیت داشته باشد .\r\nمن باید قصه را طوری تغییر دهم که کمتر جذاب و دوست داشتنی باشد او یک مداد و مقداری کاغذ برداشت و از اتاق بیرون رفت . مدتی بعد پسرک به اتاق آمد و گفت: آماده شد .من قصه بهتری نوشته ام بعد صدایش را صاف کرد و گفت: اسم این داستان ، اردک بدشانس، بد شانس بد شانس است اردک بانمکی یک چاله پر از گل پیدا کرد اوه ، چه اردک بد شانسی! اردک بد شانس گفت:\r\n\"کواک\" اردک کوچولو و دوست داشتنی، توی گودال پر از گل شیرجه رفت. اوه ، چه اردک بد شانس ، بد شانسی. اردک بد شانس بد شانس گفت: \"کواک\" ، \"کواک\" اردک کوچک و دوست داشتنی، از توی چاله پر از گل بیرون آمد و زیر نور آفتاب چرتی زد . اوه ، چه اردک بد شانس ، بد شانس ، بد شانسی. اردک بد شانس بد شانس بد شانس گفت : \"کواک\" ، \"کواک\" ، \"کواک\"\r\nقصه ی من تمام شد پسرک دفترچه اش را بست و پرسید: نظرتون چیه ؟ دخترک دماغش را خاراند و گفت: من از قصه ی اولی بیشتر خوشم آمد. پسر گفت: اما فکر می کنم قصه ای که من نوشتم بهتر است. پدر نظر شما چیه ؟ پدر به آنها گفت: هر دو خوب هستند البته هر کدام به نوعی . دخترک و پسرک گفتند : اوه پدر ، شما همیشه همین را می گوئید .\r\n"},{"id":1150,"category_id":8,"category_code":"s8","source_id":111,"title":"کلاغ سفید","content":"يكي بود يكي نبود غير از خدا هيچكس نبود لانه ي آقا كلاغه و خانم كلاغه توي دهكده ي كلاغها روي يك درخت سپیدار بود. آنها سه تا بچه داشتند. اسم بچه هايشان سياه پر ، نوك سياه و مشكي بود. وقتي بچه ها كمي بزرگ شدند، آقا و خانم كلاغ به آنها پرواز كردن ياد دادند. بچه كلاغها هر روز از لانه بيرون مي آمدند و همراه پدر و مادرشان به گردش مي رفتند.\r\n\r\nيك روز همه ي آنها در يك پارك دور حوض نشسته بودند و آب مي خوردند كه چندتا پسربچه ي شيطان آنها را ديدند و با تير و كمان به سويشان سنگ انداختند. كلاغها ترسيدند و فرار كردند ؛ اما يكي از سنگها به بال مشكي خورد و او حسابي ترسيد. تا آمد فرار كند ، سنگ ديگري به سرش خورد و كمي گيج شد. اما هرطور بود پرواز كرد و از بچه ها دور شد. او خيلي ترسيده بود و رنگ پرهايش از ترس، مثل گچ سفيد شده بود . براي همين پدر و مادرش نفهميدند كه پرنده ي سفيدرنگي كه نزديك آنها پرواز مي كند، مشكي است و روي زمين دنبالش مي گشتند. مشكي هم كه گيج بود، نفهميد كه بقيه كجا هستند ، پريد و رفت تا اينكه افتاد توي لانه ي كبوترها و از حال رفت. كبوترها دورش جمع شدند و كمي آب به او دادند تا حالش جا آمد اما يادش نبود كه كيست و اسمش چيست و چطوري به آنجا آمده است. زبانش هم بند آمده بود و ديگر قار قار نمي كرد. كبوترها فكر كردند كه او هم كبوتر است. جا و غذايش دادند و مشكي پيش آنها ماند.چند روز گذشت و مشكي چيزي يادش نيامد.\r\nپدر و مادر و خواهر و برادرش خيلي دنبالش گشتند اما پيدايش نكردند. مشكي خيلي غمگين بود، چون نميدانست كيست و اسمش چيست. يك روز صبح تازه از خواب بيدار شده بود كه صداي قارقاري به گوشش رسيد.خوب گوش داد و اين آواز راشنيد: قارقار خبردار كي خوابه و كي بيدار؟ منم ننه كلاغه مشكي من گم شده كسي او را نديده؟ مشكي من بلا بود خوشگل و خوش ادا بود رنگ پراش سياه بود قارقار خبردار هركي كه او را ديده بياد به من خبر بده قارقار قارقار مشكي صداي مادرش را مي شنيد. صدا برايش آشنا بود اما نمي دانست كه اين صدا را كي و كجا شنيده است. از جايش بلند شد و نزديكتر رفت. به ننه كلاغه نگاه كرد. چشم ننه كلاغه كه به او افتاد ، از تعجب فريادي كشيد و گفت :« خداي من يك كلاغ سفيد! چقدر به چشمم آشناست!»\r\n\r\nپريد و به مشكي كاملاً نزديك شد. او را بو كرد و به چشمانش خيره شد و چند لحظه بعد داد زد:« خدايا اين مشكي منه! پس چرا سفيد شده؟» كبوترها دور آنها جمع شده بودند و نگاهشان مي كردند. يكي از كبوترها گفت:« اما اين كه رنگش مشكي نيست ، سفيده...»\r\n\r\nننه كلاغه گفت:« اما من بوي بچه ام را مي شناسم ، از چشمهايش هم فهميدم كه اين بچه ي گم شده ي من مشكيه ....فقط نميدونم چرا رنگش سفيد شده ، شايد خيلي ترسيده و از ترس رنگش پريده ، اما مهم نيست من بچه ي عزيزم را پيدا كردم...»\r\n\r\nمشكي كم كم چيزهايي به يادش آمد. جاي ضربه هايي كه به سر و بالش خورده بود، هنوز كمي درد مي كرد. يادش آمد كه در پارك كنار حوض نشسته بود و آب مي خورد اما سنگي به بالش و سنگي هم به سرش خورد و حسابي ترسيد. او مدتي به ننه كلاغه نگاه كرد و بعد با خوشحالي گفت :« يادم اومد ، اسم من مشكيه ، تو هم مادرم هستي ، من گم شده بودم اما حالا پيش تو هستم آه مادرجون ...» كبوترها با خوشحالي و تعجب به آنها نگاه مي كردند. مشكي و مادرش از خوشحالي اشك مي ريختند. وقتي حالشان جا آمد، از كبوترها تشكر كردند و به دهكده ي كلاغها بازگشتند. همه ي كلاغها مخصوصاً آقا كلاغه و پرسياه و نوك سياه از بازگشت مشكي خوشحال شدند و جشن گرفتند. از آن روز به بعد همه ي كلاغها مشكي را سفيدپر صدامي زدند چون او تنها كلاغ سفيد دهكده ي آنها بود.\r\n\r\n"},{"id":1151,"category_id":8,"category_code":"s8","source_id":112,"title":"کلاه فروش بیچاره","content":"يكي بود و يكي نبود ، مردي از راه فروش كلاه زندگي مي كرد . روزي شنيد كه در يكي از شهرها، كلاه طرفداران زيادي دارد . براي همين با تمام سرمايه اش كلاه خريد و به طرف آن شهر راه افتاد .\r\nروزهاي زيادي گذشت تا به نزديكي آن شهر رسيد . جنگل با صفائي نزديكي آن شهر بود و مرد خسته تصميم گرفت كه آنجا استراحت كند كلاه فروش در خواب بود كه باصدايي بيدار شد با تعجب به اطرافش نگاه كرد و چشمش به كيسه كلاه ها افتاد كه درش باز شده بود و از كلاه ها خبري نبود مرد نگران شد دور و بر خود را نگاه كرد تا شايد كسي را ببينند ولي كسي را نديد . ناگهان صدائي از بالاي سر خود شنيد و سرش را بلند كرد و از تعجب دهانش باز ماند . چون كلاه هاي او بر سر ميمونها بودند . مرد با ناراحتي سنگي به طرف ميمونها پرت كرد و آنها هم با جيغ و هياهو به شاخها هاي ديگر پريدند .\r\n\r\nمرد كه از اين اتفاق خسارت زيادي ديده بود نمي دانست چكار كند ، زيرا بالارفتن از درخت هم فايده نداشت چون ميمونها فرار مي كردند . ناراحت بود و به بخت بد خود نفرين فرستاد . پيرمردي از آنجا عبور مي كرد ، مرد كلاه فروش را غمگين ديد از او پرسيد : گويا تو در اينجا غريبه اي ! براي چه اينقدر غمگين هستي . پيرمرد وقتي ماجرا را شنيد به او گفت : چاره اينكار آسان است آيا تو كلاه ديگري داري ؟‌\r\nمرد كلاه فروش ، كلاه خود را از سرش در آورد و به پيرمرد داد . پيرمرد كلاه را بر سرش گذاشت و مثل ميمونها چندبار جيغ كشيد و بعد كلاه را از سر برداشت و در هوا چرخاند و بعد آنرا بر زمين انداخت .\r\nمرد كلاه فروش خيلي تعجب كرد ولي مدتي گذشت و ميمونها نيز كار پيرمرد را تقليد كردند و كلاه را از سرشان به طرف زمين پرتاب كردند . كلاه فروش با خوشحالي كلاه ها را جمع كرد و از تدبير و چاره انديشي مناسب آن پيرمرد تشكر كرد . هديه اي براي تشكر به پيرمرد داد و به راه خود ادامه داد .\r\n"},{"id":1152,"category_id":8,"category_code":"s8","source_id":113,"title":"دو موش بد","content":"روزی و روزگاری يك خانه عروسكي بسيار زيبایي در کنار شومینه اتاق قرار داشت .ديوارهاي آن قرمز و پنجره هايش سفيد بود . آن خانه پرده هاي توري واقعي داشت. همچنين يك درب در جلوی خانه و يك دودكش هم روی سقفش دیده می شد.\r\nاين خانه متعلق به دو عروسك بود. یک عروسک بلوند که لوسيندا نام داشت و صاحبخانه بود ولي هيچوقت غذا سفارش نمي داد. دیگری هم جين نام داشت و آشپز بود اما هيچوقت آشپزي نمي كرد چون غذاهاي آماده از قبل خريداري شده بودند و در يك جعبه قرار داشتند. توي جعبه دو عدد ميگوي درشت قرمز ، يك ماهي ، يك تكه ران ، يك ظرف پودينگ و مقداري گلابي و پرتقال بود.\r\nآنها را نمي شد از بشقابها جدا كرد ولي بي نهايت زيبا بودند. يك روز صبح لوسيندا و جين براي گردش با كالسكه عروسكيشان بيرون رفتند. هيچكس در اتاق كودك نبود و همه جا سكوت بود . يكدفعه صداي حركت آرام چيزي به گوش رسيد . صداي خراشيدگي از گوشه اي نزديك شومينه مي امد جائيكه سوراخي در زير قرنيز وجود داشت .\r\nتام شستي سرش را براي لحظه اي بيرون آورد و دوباره صداها شروع شد. لحظه اي بعد خانم موشه هم سرش را بيرون آورد .او وقتي ديد كسي در اتاق نيست با جرات و بدون ترس بيرون آمد. خانه ي عروسكي در سمت ديگر شومينه قرار داشت آنها با دقت از روي قاليچه ي مقابل شومينه گذشتند و به خانه عروسكي رسيدند و درب را باز كردند.\r\n\r\nدو موش از پله ها بالا رفتند و چشمشان به اتاق غذاخوري افتاد . غذاهاي مورد علاقه موشها روي ميز چيده شده بود . قاشق ، چاقو و چنگال هم روي ميز بود و دو صندلي عروسكي هم كنار ميز قرار داشت . همه چيز فراهم بود. آقا موشه خواست تكه ای از ران خوش آب و رنگ را با چاقو ببرد. اما نتوانست چاقو را كنترل كند و دستش را زخمي كرد. خانم موشه گفت:\r\nفكر كنم به اندازه كافي پخته نشده و سفت است بايد بيشتر تلاش كني. خانم موشه روي صندلي اش ايستاد و سعي كرد با چاقوي ديگري آنرا خرد كند اما تنوانست و گفت : اين خيلي سفت است تكه ران با يك فشار از بشقاب جدا شد و قل خورد و زير ميز افتاد. آقا موشه گفت : آن را ول كن و يك تكه ماهي به من بده .\r\nخانم موشه سعي كرد تا با آن قاشق حلبي تكه اي از ماهي را جدا كند ولي ماهي به ظرفش چسبيده بود. همانطور كه ماهي به بشقاب چسبيده بود آنرا در آشپزخانه روي آتش قرار دادند ولي آن نپخت . آقا موشه خيلي عصباني شد. تكه ران را وسط اتاق گذاشت و با خاك انداز به آن كوبيد. بنگ، بنگ، و آنرا را تكه تكه كرد. تكه هاي ران به اطراف پرت شدند ولي هيچ چيزي داخل آن نبود. موشها خيلي خشمگين و نااميد شدند. آنها پودينگ، ميگوها، گلابي ها و پرتقال ها را هم شكستند\r\nخانم موشه جعبه هاي كوچكي را توي قفسه پيدا كرد كه رويشان نوشته بود برنج ، شكر ، چاي ، اما وقتي كه آنها را برگرداند بجز دانه هاي قرمز و آبي چيزي داخلش نبود. آنها از ناراحتي تا آنجا كه مي توانستند رفتار زشت از خودشان نشان دادند. آقا موشه لباسهاي جين را از كشو در آورد و آنها را از پنجره به بيرون پرتاپ كرد.\r\n\r\nخانم موشه كه داشت پرهاي داخل بالشت لوسيندا را بيرون مي ريخت بياد آورد كه خيلي دلش يك تشك پر مي خواست. او با همكاري اقا موشه بالشت را به طبقه پايين برد و از روي قاليچه جلوي شومينه عبور كردند. رد كردن بالشت از آن سوراخ خيلي مشكل بود اما به هر سختي كه بود اين كار را انجام دادند. خانم موشه برگشت و يك صندلي و قفسه كتاب و قفس پرنده و چند تا خرت و پرت ديگر را برداشت و با خودش آورد.\r\nقفسه كتابها و قفس پرنده از سوراخ رد نشدند بنابراین خانم موشه آنها را پشت ذغالها رها كرد. او برگشت و يك كالسكه با خودش آورد خانم موشه دوباره برگشت و يك صندلي ديگر با خودش آورد كه يكدفعه صدايي را در پاگرد شنيد . او بسرعت به سواخش برگشت و عروسكها وارد اتاق كودك شدند . اما چشمهای لوسیندا و جین چه دید! لوسیندا روی اجاق وا ژگون شده نشست و به اطراف خیره شد. جین هم به کشوهای آشپرخانه تکیه داد و نگاه کرد .\r\nاما هیچکدام حرفی نزدند. قفسه کتابها و قفس پرنده در کنار جعبه ذغالها رها شده بود ولی گهواره و تعدادی از لباسهای لوسیندا را خانم موشه برده بود. البته خانم موشه چند تابه و قابلمه بدرد بخور و مقداری چیزهای دیگر را برداشته بود. دختر کوچولویی که خانه عروسکی متعلق به او بود گفت : من می روم و یک عروسک پلیس می آورم. اما پرستارش گفت: من یک تله موش خواهم گذاشت . این آخر داستان دو موش بد بود اما آنها خیلی بدجنس نبودند . آقا موشه خسارت آنچه که شکسته بودند پرداخت کرد . چون عید کرسیمس بود موش و همسرش یک اسکناس داخل جورابهای لوسیندا و جین انداختند. و خانم موشه هم صبح خیلی خیلی زود با خاک انداز و جاروش به خانه عروسکی آمد تا آن را تمیز کند.\r\n"},{"id":1153,"category_id":8,"category_code":"s8","source_id":114,"title":"گرگی در لباس میش","content":"روزي روزگاري يك گرگ بدجنس براي پيدا كردن غذا دچار مشكل شد. چون گله اي كه براي چرا به آن كوه و چمنزار مي آمد يك چوپان دلسوز و يك سگ دقيق داشت. آنها مواظب هر اتفاقي در گله بودند. گرگ گرفتار شده بود و نميدانست چكار بكند تا اينكه يك روز اتفاق عجيبي افتاد.\r\n\r\nاو يك پوست گوسفند را پيدا كرد. گرگ آنرا برداشت و بسرعت فرار كرد. روز بعد گرگ با دقت پوست را روي خودش انداخت و خودش را به شكل يك گوسفند درآورد و هنگاميكه گله در صحرا مشغول چرا بود به ميان آنها رفت. گوسفندها متوجه وجود گرگ نشدند.\r\n\r\nيكي از بره ها به كنار او آمد گرگ ناقلا به او گفت: كمي آنطرفتر علفهاي خوشمزه تري وجود دارد و بره بيچاره به دنبال گرگ از گله دور شد. خلاصه آن روز گرگ بدجنس توانست شكار خوبي را پيدا كند.\r\nتا مدتها گرگ به گله مي آمد و به روشهاي مختلف گوسفندان را فريب مي داد. و گوسفندها هم فريب ظاهر گرگ را مي خوردند و حرفهاي او را قبول مي كردند. اين ماجرا مدتها ادامه پيدا كرد. البته چوپان و سگ گله بعد از مدتها توانستند به علت ناپديد شدن گوسفندها پي ببرند و گرگ بدجنس را حسابي ادب كنند. ولي...ولي حيف كه يك عده گوسفند ساده گول گرگ را خورده بودند و ديگه در ميان گله نبودند.\r\n"},{"id":1154,"category_id":8,"category_code":"s8","source_id":115,"title":"قصه ی فرشته ها","content":"روزي روزگاري يك گرگ بدجنس براي پيدا كردن غذا دچار مشكل شد. چون گله اي كه براي چرا به آن كوه و چمنزار مي آمد يك چوپان دلسوز و يك سگ دقيق داشت. آنها مواظب هر اتفاقي در گله بودند. گرگ گرفتار شده بود و نميدانست چكار بكند تا اينكه يك روز اتفاق عجيبي افتاد.\r\nاو يك پوست گوسفند را پيدا كرد. گرگ آنرا برداشت و بسرعت فرار كرد. روز بعد گرگ با دقت پوست را روي خودش انداخت و خودش را به شكل يك گوسفند درآورد و هنگاميكه گله در صحرا مشغول چرا بود به ميان آنها رفت. گوسفندها متوجه وجود گرگ نشدند.\r\nيكي از بره ها به كنار او آمد گرگ ناقلا به او گفت: كمي آنطرفتر علفهاي خوشمزه تري وجود دارد و بره بيچاره به دنبال گرگ از گله دور شد. خلاصه آن روز گرگ بدجنس توانست شكار خوبي را پيدا كند.\r\n\r\nتا مدتها گرگ به گله مي آمد و به روشهاي مختلف گوسفندان را فريب مي داد. و گوسفندها هم فريب ظاهر گرگ را مي خوردند و حرفهاي او را قبول مي كردند. اين ماجرا مدتها ادامه پيدا كرد. البته چوپان و سگ گله بعد از مدتها توانستند به علت ناپديد شدن گوسفندها پي ببرند و گرگ بدجنس را حسابي ادب كنند. ولي...ولي حيف كه يك عده گوسفند ساده گول گرگ را خورده بودند و ديگه در ميان گله نبودند.\r\n"},{"id":1155,"category_id":8,"category_code":"s8","source_id":116,"title":"جوجه اردک زشت","content":"یکی از بعداز ظهرهای آخر تابستان بود . نزدیک یک کلبه قدیمی در دهکده ،خانم اردکه لانه اش را کنار دریاچه ساخته بود.\r\nاون پیش خودش فکر می کرد: مدت زیادی هست که روی این تخم ها خوابیده ام . او تنها نشسته بود و بقیه اردکها مشغول شنا بودند .\r\nکم کم تخم ها شروع به حرکت کردند و با نوکهای قشنگ کوچکشان پوسته ی تخم شان را شکستند . آنها یکی یکی بیرون آمدند اما هنوز خیس بودند و نمی توانستند که بخوبی روی پاهایشان بایستند.\r\n\r\nبزودی جوجه ها روی پا هایشان ایستادند و شروع به تکان دادن خودشان کردند.تا اینکه پرها یشان خشک شد خانم اردکه نگاهش به تخم بزرگی افتاد و پیش خودش گفت : اوه نه هنوز یکی از تخم ها اینجاست اردک پیری کنار خانم اردک آمد .\r\nبه تخم نگاه کرد و گفت: شاید این تخم یک بوقلمون باشد این اتفاق یکبار برای من هم رخ داده است اون جوجه حتی نمی توانست به آب نزدیک شود. چرا ناراحتی ؟ من پیشنهاد می کنم که او را ول کنی . سپس اردک پیر آهسته شنا کرد و رفت.\r\nخانم اردکه فکر کرد کمی بیشتر روی این تخم بنشیند . بعد از مدتی صداهای ضعیفی از داخل تخم شنید و بزودی جوجه کوچولو از تخم بیرون آمد.\r\nمادر مدتی به جوجه نگاه کرد او با پرهای خاکستریش ظاهر عجیبی داشت و مادر را نگران کرد. اما وقتی که به پاهایش نگاه کرد خیالش جمع شد که این جوجه ی بوقلمون نیست.\r\nاما جوجه ی بزرگ و زشتی بود روز بعد مادر جوجه هایش را به کنار دریاچه برد . جوجه ها یکی یکی داخل آب پریدند . بزودی همه آنها حتی جوجه اردک زشت روی آب شناور بودند.\r\nسپس مادر جوجه هایش را به حیاط طویله برد .سرش در برابر اردک پیر به نشانه ی احترام خم کرد و گفت : نوار بین پاهای این جوجه نشان می دهد که یک جوجه بوقلمون نیست بوقلمونی که در نزدیکی آنها راه می رفت سرش را بالا آورد و گفت : تا حالا چنین جوجه اردک زشت و بزرگی ندیده ام این تازه شروع مشکلات جوجه اردک بود .\r\nحیوانات با او رفتار دوستانه ای نداشتند چون اوخیلی زشت بود . جوجه اردکهای دیگر با او بازی نمی کردند و او را اذیت می کردند . مرغها به او نوک می زدند و همه حیوانات به او می خندیدند.\r\nجوجه اردک بیچاره خیلی غمگین و تنها بود . و با گذشت زمان بیشتر ناراحت می شد . هرچند که مادرش سعی می کرد به او دلداری بدهد احساس می کرد کسی او را دوست ندارد و فکر می کرد چرا با بقیه برادرهایش فرق دارد .\r\nیک شب که دیگر جوجه اردک زشت نتوانست این همه ناراحتی را تحمل کند از حیاط طویله خارج شد و تا جایی که می توانست دوید . بزودی به جنگل رسید . هر چه جلوتر می رفت پیدا کردن راه سخت تر می شد .\r\nاما او به دویدن ادامه داد تا اینکه به نزدیکی مردابی رسید که اردکهای وحشی در آنجا زندگی می کردند . جوجه اردک پشت درختی پنهان شد . احساس می کرد که خیلی تنها و خسته است صبح هنگامیکه تعدادی از اردکها پرواز میکردند متوجه جوجه تازه وارد شدند ایستادند به او سلام کردند .\r\nاز او پرسیدند: تو کی هستی ؟ جوجه اردک زشت گفت : من اردک مزرعه هستم آیا تا حالا جوجه اردکی مثل من دیده اید که پرهای خاکستری داشته باشد. او مدت طولانی به اردکهای وحشی که با اردک های مزرعه خیلی فرق داشتند نگاه کرد آنها گفتند : یک اردک ؟ ولی ما تا حالا جوجه اردکی مثل تو ندیده ایم . اما مهم نیست . تو می توانی اینجا بمانی چون این مرداب به اندازه کافی برای همه ما جا دارد .\r\nجوجه اردک زشت خوشحال بود که می توانست در کنار مرداب استراحت کند و از حیوانات بیرحم مزرعه دور باشد هوا سرد بود جوجه اردک زشت به برگ های درختها نگاه کرد که طلایی و قرمز بودند . همانطور که او میان نیزار برای پیدا کردن غذا می گشت دو غاز وحشی جوان از آسمان کنار او به زمین نشستند.\r\nسلام دوست داری از ما باشی. ما داریم به مرداب دیگری پرواز می کنیم که کمی از اینجا دورتر است جائیکه غازهای جوان زیادی مثل ما آنجا زندگی می کنند .\r\nجوجه اردک زشت از این اتفاق خوشحال بود اما قبل از اینکه کاری کند صدای شلیک گلوله ای را شنید و غاز به درون مرداب افتاد . یک سگ گنده داخل آب پرید تا آنها را بگیرد .\r\nاسلحه ها شروع به شکلیک در اطراف مرداب کردند سگ دیگری از میان نیزارها بطرف جوجه اردک آمد سگ لحظه ای به او نگاه کرد و سپس از آنجا دور شد .\r\nجوجه اردک در حالیکه از ترس نفس نفس می زد گفت : خدایا متشکرم . من اینقدر زشتم که حتی سگ هم مرا نمی خواهد . او تمام روز در میان نیزار ماند .بالاخره زمانیکه خورشید غروب کرد سگها رفتند و شلیک ها قطع شد .\r\nاو آشفته خودش را از کناره دریاچه به میان جنگل رساند همانطور که او در تاریکی راه می رفت باد شدیدی می وزید .ناگهان خودش را جلوی یک کلبه خیلی قدیمی دید . نور ضعیفی از لای سوراخ در دیده می شد . جوجه اردک فکر کرد که باید داخل بروم و از دست باد خلاص شوم .بنابر این بزور از سوراخی وارد خانه شد و در گوشه ای شب را گذراند.\r\n\r\nزن پیری با گربه و مرغش در این کلبه زندگی می کرد . صبح روز بعد که پیرزن جوجه اردک را دید از خودش پرسید : این دیگه چیه ؟ از کجا آمده ؟ اردک آنجا ماند .\r\nاما جوجه بیچاره در گوشه ای غمگین نشسته بود لذت شنا کردن روی آب را بیاد آورد . به مرغ گفت من می خواهم به دنیای وحشی بروم مرغ به او گفت : تو دیوانه هستی . اما من نمی توانم تو را اینجا نگه دارم .\r\nجوجه اردک گشت و حوضچه بزرگی را پیدا کرد . و در زیر نور خورشید شناور شد . روز بعد یکباره یک گروه از پرندگان سفید بزرگی رابا گردنها دراز و جذاب در حال پرواز دید .\r\nاو تا آن روز چنین پرندگان زیبایی را ندیده بود . او پیش خودش فکر کرد ، کاش می توانستم با آنها دوست شوم .\r\nاین پرندگان به سمت جنوب مهاجرت می کردن باد سرد زمستان شروع به وزیدن کرد . جوجه اردک مجبور بود برای محافظت از یخ زدگی به سختی با پاهایش پارو بزند .\r\nیک روز صبح پاهایش یخ زد کشاورزی که از آنجا عبور می کرد او را نجات داد . او پرنده بیچاره را به خانه گرمش برد .اما بعد بچه های کشاورز جوجه اردک را ترساندن و او بال و پر زد و به آشپزخانه پرید و چیزهای مختلفی برخورد کرد و وقتی که در برای لحظه ای باز شد او بیرون پرید.\r\nخلاصه جوجه اردک از زمستان جان سالم بدر برد یک روز صبح که لای نیزار خوابیده بود گرمای خورشید را احساس کرد . کش و قوسی به بالهایش داد و به آسمان پرواز کرد . او بطرف یک باغ که یک حوض بزرگ در وسطش داشت پرواز کرد .\r\nاو سه پرنده سفید زیبا راروی آب دید که خیلی با جذبه و نرم شنا می کردند . آنها قو بودند ولی او این را نمی دانست او خیلی نرم بدون آنکه بال بزند بالای سر قوها پرواز کرد و سرش را برای احترام خم کرد .\r\nدر انعکاس آب قوی زیبای دیگری دید . دو بچه کوچک به سمت باغ می دویدند فریاد زدند ، نگاه کن یکی دیگه . این یکی از بقیه زیباتر است آن جوجه اردک زشت حالا یک قو بود . قلب او پر از عشق به قوها دیگر بود و فهمید که چه حقیقتی رخ داده است . و قبلا که یک جوجه زشت بود فکرنمی کرد روزی چنین اتفاقی بیافتد.\r\n"},{"id":1156,"category_id":8,"category_code":"s8","source_id":117,"title":"دوستی شیر وشغال","content":"در یک جنگل بزرگ شیر و شغالی زندگی می کردند که با هم دوستان صمیمی بودند. شیر پادشاه جنگل بود و شغال وزیرش. همه ی حیوونای جنگل شیر را دوست داشتند و از وجودش راضی بودند اما شغال همیشه به فکر کشتن شیر بود تا خودش پادشاه جنگل بشه.\r\n\r\nیک روز شغال نقشه ای کشید. شیر هر روز نزدیک های ظهر عادت داشت کنار رودخانه بره و از آن آب بخوره. شغال تصمیم گرفت توری را در آن جا پنهان کنه تا هر وقت شیر برای نوشیدن آب به اونجا می ره توش گیر بیفته و بعد اون تور را به داخل رودخانه بندازه و خودش پادشاه جنگل بشه. شغال بدجنس از فکر پلیدش خنده اش گرفت و به خودش افتخار کرد.\r\n\r\nروز بعد شیر برای نوشیدن آب به کنار رودخانه رفت و در تور شغال گیر افتاد. شغال که خودش را پشت درختی پنهان کرده بود از مخفیگاهش بیرون آمد. شیر با دیدن شغال خوشحال شد و از او کمک خواست و گفت: لطفاً منو از این تور بیرون بیار.\r\n\r\nشغال با صدای بلند خندید و گفت: از این به بعد من پادشاه جنگل هستم.\r\n\r\nبعد شغال با بی رحمی شیر را توی رودخانه انداخت و به همه ی حیوونای جنگل اعلام کرد شیر مرده و از این به بعد من پادشاه جنگلم.\r\n\r\nشغال با همه ی حیوونا رفتار بدی می کرد و آن ها را مورد رنج و عذاب قرار می داد. بعضی از حیوونا از بی رحمی های شغال خسته شدند و از جنگل فرار کردند.\r\n\r\nبعد از چند هفته یک شیر از باغ وحش فرار کرد و به جنگل آمد. شیر متوجه ی یک خرس غمگین شد. ازش پرسید: چرا شما اینقدر غمگینی؟\r\n\r\nخرس گفت: شغال، شیر شاه ما رو کشته و حالا خودش توی جنگل فرمانروایی می کنه. اون خیلی بی رحمه و خیلی از حیوونا به خاطر رفتارای اون جنگل رو ترک کردند.\r\n\r\nوقتی شیر این حرف ها رو در مورد شغال شنید، خیلی ناراحت و خشمگین شد. از خرس آدرس شغال رو گرفت و به سمت خونه ی شغال رفت. شغال سعی کرد فرار کنه ولی موفق نشد. شیر با دندونای تیزش او را درید و کشت. از اون به بعد همه ی حیوونای جنگل شیر را پادشاه خود می دونستند و همه از اون راضی بودند.\r\n\r\nاز اون زمان به بعد دیگر هیچ شیری با هیچ شغالی دوست نشد.\r\n"},{"id":1157,"category_id":8,"category_code":"s8","source_id":118,"title":"بازی کامپیوتری","content":"علی از مدرسه برگشت و سریع ناهارش را خورد و نشست پشت کامپیوتر تا بازی جدیدی را که از دوستش گرفته بود نصب کند. بعد از آن غرق بازی شد و زمان را فراموش کرد. او علاقه ی زیادی به این بازی ها داشت و همیشه همه چی را فراموش می کرد.\r\nبا صدای زنگ آیفون علی به خودش آمد ساعت 6 غروب بود و او نزدیک 4 ساعت بی وقفه پشت کامپیوتر نشسته بود. در را باز کرد، پدرش بود. پدر با دیدن علی سرش را تکان داد و گفت: باز که چشم هایت قرمز شده، حتماً بازم داشتی بازی می کردی؟\r\nعلی سرش را پایین انداخت و با خجالت گفت: بله! علی از پدرش خجالت کشید چون چندین بار به پدرش قول داده بود که از کامپیوترش درست استفاده کند.\r\nعلی به اتاقش رفت و کامپیوترش را خاموش کرد. بعد به آشپزخانه رفت و یک چایی برای پدرش ریخت. مادر علی خانه نبود او به شهرستان به دیدن پدر و مادرش رفته بود.\r\nعلی خیلی تکلیف داشت که باید انجام می داد. اما او خیلی خسته بود و نمی توانست تمرکز کند. وقتی علی داشت تکلیف ریاضی اش را می نوشت خوابش برد و تکالیفش نیمه کاره ماند.\r\n\r\nفردا علی آماده شد که به مدرسه برود اما کمی استرس داشت چون تمام تکالیفش را نصفه نیمه کاره انجام داده بود.\r\nزنگ اول ریاضی داشت. معلم از علی خواست که مسئله ها را حل کند ولی علی آن ها را بلد نبود. معلم از علی خواست تا دفترش را بیاورد و متوجه شد که علی مسئله ها را حل نکرده معلم ریاضی به نشانه ی تاسف سرش را تکان داد و گفت: علی! چرا چند وقتیه تکالیفت را انجام نمی دهی. اگر این طوری پیش بری حتماً امتحاناتت را خراب می کنی.\r\nعلی در همه ی درس هایش افت کرده بود. یک روز مشاور مدرسه از او خواست تا به اتاقش برود. او از علی پرسید: علی! چرا به تکالیفت اهمیت نمی دهی. علی گفت: من اصلاً وقت نمی کنم آن ها را انجام بدهم. مشاور: می شه ازت بخواهم بهم بگی وقتی به خانه می ری چه کارهایی انجام می دی تا شاید اینجوری بتونیم اشکال کار را پیدا کنیم و با هم یک برنامه ریزی خوب بکنیم. علی گفت: اول ناهار می خورم بعد می رم سراغ کامپیوترم تا کمی بازی کنم، اما نمی دونم چی می شه که ساعت ها می گذره. بعد که می خوام تکالیفم رو بنویسم آ نقدر خسته ام که نمی تونم.\r\nبعد مشاور لبخندی زد و گفت: عزیزم بهتر نیست وقتی می ری خونه کمی استراحت کنی و بعد تکالیفت رو انجام بدی و زمان استراحتت سراغ بازی بری. البته حتماً باید برای خودت وقت بذاری مثلاً نیم ساعت هر روز. تا اینجوری به همه ی کارهات برسی.\r\nعلی گفت: من همیشه می خوام کم بازی کنم اما نمی دونم چرا نمی شه؟\r\nمشاور: تو باید اول به خودت قول بدهی و بعد یک ساعت را کوک کنی تا بهت خبر بده که زمان بازی تمام شده و تو کارهای مهم تری هم داری. این روش را امتحان کن و نتیجه را به من خبر بده.\r\nاون روز علی وقتی به خانه آمد تمام کارهایی را که مشاورش به او پیشنهاد داد انجام داد. فردا صبح وقتی بیدار شد برای رفتن به مدرسه استرس نداشت چون تمام تکالیفش را انجام داده بود.\r\n"},{"id":1158,"category_id":8,"category_code":"s8","source_id":119,"title":"خرگوش دم دراز","content":"در روزگاران قدیم خرگوشی زندگی می کرد که دم دراز و گوش های کوچکی داشت؛ یعنی همه ی خرگوش ها این شکلی بودند. اما این خرگوش با یک روباه حیله گر دوست شده بود. هر چه قدر همه می گفتند دوستی خرگوش و روباه درست نیست، خرگوش به حرف آن ها گوش نمی داد. چون با روباه بازی می کرد و بسیار شاد بود.\r\nروزی از روزها روباه پیش خرگوش آمد و گفت: امروز می آیی برویم ماهیگیری؟\r\nخرگوش گفت: چه طوری برویم ماهیگیری؟ وقتی نه قلاب داریم و نه طعمه؟!\r\nروباه گفت: کاری ندارد! با هم کنار ساحل می نشینیم. آن وقت تو دم درازت را درون اب بینداز. هر وقت سر و کله ی ماهی برای گاز گرفتن پیدا شد، تو او را به ساحل پرتاب کن.\r\nخرگوش دم دراز گفت: تو چرا دمت را در آب نمی اندازی؟\r\nروباه جواب داد: چون دم تو قشنگ تر و بلندتر است و به همین خاطر ماهی ها را گول می زند.\r\nخرگوش بیچاره قبول کرد و دوتایی به طرف ساحل به راه افتادند. وقتی به ساحل رسیدند، خرگوش دمش را در آب گذاشت. چیزی نگذشت که خرگوش فریاد زد: فکر کنم با دمم ماهی گرفتم. حالا چه کار کنم؟\r\nروباه گفت: با دمت ماهی را به ساحل بینداز!\r\nخرگوش گفت: فکر کنم ماهی بزرگی است؛ چون او دارد من را به درون آب می کشد!\r\nروباه با خوش حالی به آب نزدیک شد و گفت: اما این که ماهی نیست! لاک پشت است.\r\nخرگوش فریاد زد: کمکم کن، هرچه که هست دارد من را غرق می کند. الان خفه می شوم.\r\nروباه گفت: ولی من چطوری تو را نجات بدهم؟\r\nخرگوش گفت: خب تو هم من را به سمت ساحل بکش!\r\nروباه هم گوش های خرگوش را گرفت و شروع کرد به کشیدن. آن قدر کشید که گوش های خرگوش دراز و درازتر شد. از آن طرف هم لاک پشت دم خرگوش را گاز گرفته بود و می کشید. آن قدر محکم گرفته بود که دم دراز خرگوش کنده شد. لاک پشت هم رفت.\r\nازآن روز به بعد گوش های خرگوش دراز شد و دمش کوتاه!\r\n"},{"id":1159,"category_id":8,"category_code":"s8","source_id":120,"title":"مینی در رستوران جغد مهربان","content":"مینی، پسر کوچولوی خیال‌پرداز، یک روز مثل همیشه، روی تختش دراز کشیده بود و فکرهای جورواجور می‌کرد تا خوابش برد. در خواب، وارد جنگل سرسبزی شد که در آن، همه حیوانات، با هم دوست بودند و بازی می‌کردند.\r\nبرای مینی عجیب بود؛ چون او، همیشه فکر می‌کرد جنگل، جای خطرناکی است و هیچ‌وقت ندیده بود که حیوانات، با هم بازی کنند و حرف بزنند! در همین فکرها بود که یک شتر کوچولو به او نزدیک شد.\r\nمینی خیلی تعجب کرد و از او پرسید: \r\n\"تو، این‌جا چی کار می‌کنی؟ مگه شترها، توی صحرا زندگی نمی‌کنن؟!\" \r\nشتر کوچولو خندید و گفت: \r\n\"درسته؛ ما توی صحرا زندگی می‌کنیم، اما این‌جا، جنگل رویاست و همه حیوانات می‌تونن به این‌جا بیان. ما، این‌جا، همه با هم، دوست هستیم و بازی می‌کنیم.\" مینی هم مشغول بازی شد.\r\nپس از مدتی، حیوانات، از مینی و شتر کوچولو جدا شدند و رفتند خانه، اما مینی و شتر کوچولو، هنوز، از بازی کردن، خسته نشده بودند. وقتی همه رفتند، شتر کوچولو، به مینی پیشنهاد داد با هم، به رستوران آقای جغد بروند؛ چون بسیار مهربان و دست‌پخت‌اش، عالی است و همه حیوانات، برای غذا خوردن و گذراندن بعدازظهر، به آن‌جا می‌روند.\r\nمینی هم تصمیم گرفت به رستوران جغد مهربان برود و دست‌پخت او را امتحان کند.\r\n\r\nوقتی آن‌ها به رستوران جغد مهربان رسیدند، مینی از تعجب، دهانش باز ماند. دوستان مینی، همه، در رستوران نشسته بودند. وقتی دوستانش، او را دیدند، با خوشحالی صدایش کردند. دوستان مینی برایش تعریف کردند که چگونه، از طریق رویا، وارد جنگل شدند. جغد مهربان، آب‌میوه خوش‌مزه‌ای را برای مینی تازه‌وارد آورد که ناگهان، با صدای زنگ در، مینی از خواب پرید.\r\nفکر می‌کنی در رستوران حیوانات، چه غذاهایی را درست می‌کنند و می‌خورند؟\r\n"},{"id":1160,"category_id":8,"category_code":"s8","source_id":121,"title":"حساسیت زنبوری","content":"زنبوری مریض شده بود و هی عطسه می کرد و می گفت: زیچّی...زیچّی ...\r\nفکر می کرد سرما خورده به خاطر همین شروع کرد به خوردن عسل سرماخوردگی و عسل ضد سرفه...\r\nاما حالش بهتر نمی شد و هی بیشتر عطسه می کرد ... زیچّی .... زیچّی ...\r\nعطسه هاش بهتر نشد که هیچی، سرفه هم بهش اضافه شد.\r\nبا هر سرفه صدا می کرد زوه زوه ... زوه زوه...\r\nکم کم عطسه و سرفه اش با هم قاطی شد... زیچّی... زوه زوه ... زیچّی..... زوه زوه ...\r\nبالاخره زنبوری مجبور شد بره پیش دکتر.\r\nدکتر « زا زو زی» زنبوری رو معاینه کرد و گفت:... ززززمریضی شما حساسیته ززز...\r\n\r\nباید چیز میزززایی که برای حساسیت بده نخورید. ززز اگه بخورید اصلا خوب نمی زید.\r\nزنبوری با عطسه و سرفه گفت هر چی بگید...زیچّی ....گوش می کنم... زوه زوه... زیچّی... زوه زوه...\r\n\r\nدکتر « زا زو زی » گفت: فقط غذاهای آب پززززز بخور. ضمنا روی هر میوه ای هم نباید بشینی اما سیب و هویج برات خوبه.\r\nزنبوری از سرفه و عطسه خسته شده بود و می خواست دقیق به نسخه ی دکتر عمل کنه.\r\nبنابراین از یه جا رد می شد دید چند تا زنبور دارن از شهد گل فلفل نمکی می خورن. طفلکی از چند متر اون طرف تر پرید و رفت.\r\nتازه تو کندوشون هم بوی موز پیچیده بود. همه داشتن موز می خوردند. اما دکتر« زا زو زی » گفته بود موز هم برای حساسیت بده.\r\nالبته زنبوری باید فقط تا وقت خوب شدنش از خوردن این میوه ها پرهیزززززززززززز کنه .\r\nای بابا من دیگه چرا می گم ززززز\r\n"},{"id":1161,"category_id":8,"category_code":"s8","source_id":122,"title":"اردوی مفید","content":"قرار بود جمعه از طرف مدرسه به یک اردوی تفریحی برویم. محلی که برای اردو انتخاب شده بود یکی از کوه های زیبا و معروف بود که رودخانه های زیبا از میان آن عبور می کرد.\r\nبی صبرانه برای رسیدن آن روز لحظه شماری می کردم.\r\nبالاخره جمعه آمد و من تمام وسایلم را جمع کرده بودم. مادرم برای صبحانه و ناهار برایم غذا گذاشته بود و خودم هم بدمینتونم را برداشتم تا آن جا با دوستانم بازی کنم.\r\nدر مدرسه همه جمع شدیم و با هم به سمت کوه حرکت کردیم.\r\nمدتی پیاده روی کردیم تا به یک رودخانه رسیدیم می خواستیم آن جا بنشینیم و صبحانه مان را بخوریم که دیدیم بطری ها و باقیمانده ی غذاهایی که اطراف رودخانه ریخته فضایی برای نشستن باقی نگذاشته.\r\nدوست نداشتم آن جا بنشینم به خاطر همین پیشنهاد کردم که از آن جا برویم و جایی بهتر پیدا کنیم.\r\nاما دیدم که یکی از دوستانم پلاستیکی بزرگ برداشته و با یک چوب شروع به جمع آوری زباله ها کرده و بقیه ی بچه ها هم به کمک او رفتند اولش دوست نداشتم به آن ها کمک کنم چون آشغال ها را ما نریخته بودیم که حالا باید جمع می کردیم و لی بعد دیدم که این کار من به نفع خودم و طبیعت است من هم یک پلاستیک برداشتم و به آن ها کمک کردم.\r\nبعد از تمام شدن کار از دیدن آن منظره ی زیبا واقعاً خوشحال شدم و با بچه ها بساط صبحانه را مهیا کردیم و همانجا نشستیم و از طبیعت زیبا لذت بردیم.\r\nموقع برگشت به خانه با خودم فکر می کردم که اگر هر کسی مواظب رفتار خود باشد و با طبیعت با بی رحمی رفتار نکند چقدر همه چیز و زیبا و دوست داشتنی می شود.\r\n"},{"id":1162,"category_id":8,"category_code":"s8","source_id":123,"title":"الاغ حکیم","content":"الاغ خاکستری دوست داشت یک جهانگرد بشود و همه ی دنیا را ببیند. او راجع به جهانگردی چیزهای زیادی شنیده بود. با خودش فکر می کرد اگر به همه جای دنیا سفر کند و همه چیز را به چشم خود ببیند حتما یک الاغ دانا و حکیم می شود.\r\nبنابراین الاغ خورجینش را از وسایل مورد نیاز پر کرد و به راه افتاد. ابتدا به سمت شهرهای شمالی رفت. کناره های جاده پر از علفهای تازه و خوشمزه بود.\r\nالاغ تمام راه مشغول خوردن علفها شد. و چنان زیاد خورد که شکمش باد کرد و دیگر توان راه رفتن نداشت و مجبور شد شب را همان جا بماند.\r\n\r\nفردا صبح سفرش را ادامه داد. در حالیکه تمام راه سرش پایین بود و مشغول خوردن.\r\nیک جا در گوشه ای از مسیر تصادف شده بود و عده ی زیادی در آنجا جمع شده بودند، بعضی ها کمک می کردند بعضی ها درباره ی تصادف صحبت می کردند و...\r\nاما الاغ متوجه هیچ چیز نمی شد.\r\nکمی جلوتر یک آبشار زیبا منظره ی بسیار جالبی درست کرده بود. خیلی ها مشغول تماشا بودند. عده ای فیلمبرداری و عکاسی می کردند...\r\nاما الاغ همچنان سربه زیر بود و می خورد.\r\nو باز هم خورد و خورد تا شکمش باد کرد و مجبور شد چند ساعت همانجا بخوابد.\r\nخوابهای طولانی بعد از یک عالمه خوردن به الاغ خیلی کیف می داد.\r\nالاغ از سفرش خیلی راضی بود چون اینطوری خور و خوابش بهتر شده بود. او تعجب می کرد که وقتی دانا و حکیم شدن این همه کیف دارد چرا دیگران این کارها را نمی کنند.\r\nخلاصه ،اگر چه سفر الاغ سالها طول کشید، اما پرخوری و نفهمی الاغ باعث شد تا او هیچ چیزی از سفرش نفهمد و یاد نگیرد.\r\nبعد از سالها سفر، الاغ هیچ فرقی نکرده بود. او فکر می کرد حکیم و دانا شده است اما حتی یک داستان جالب هم از سفرش به یاد نداشت تا برای کسی تعریف کند. البته او به هر که می رسید راجع به همه چیز نظر می داد و بسیار هم حرف می زد اما باز هم همه او را یک الاغ نفهم می دانستند و هیچ کس او را به عنوان یک الاغ دانا و حکیم قبول نداشت.\r\nاما این چیزها مهم نبود چون بالاخره الاغ خودش نمی دانست چقدر نادان است او خودش خودش را بسیار قبول دارد.\r\n"},{"id":1163,"category_id":8,"category_code":"s8","source_id":124,"title":"خرس تنبل","content":"بهار اومده و برفا آب شدند و برگای درختان از دوباره در اومدند و همه ی حیوانات جنگل بیدار شدند و با هم بازی می کنند.\r\nاما خرس کوچولو هنوز خوابه و نمی دونه که بهار اومده. گوش بدید صدای خرخرش میاد.\r\nحالا فصل تابستونه. هوا گرم شده و حیوونای جنگل مشغول بازی و شادی اند. اما بازم خرس کوچولو نیست. اون کجاست؟\r\nخرس کوچولو هنوز خوابه. اون نمی دونه که تابستون شده.\r\nحالا پاییزه. برگ درخت ها زرد و قرمز و نارنجی شده. همه ی حیوونا دارن خودشون رو برای زمستون آماده می کنن. اما خرس کوچولو کجاست؟\r\nخرس کوچولو هنوز خوابه. اون نمی دونه که پاییزم اومده.\r\nحالا زمستون شده! هیچ حیوونی تو جنگل دیده نمی شه. اونا همه به خونه های گرمشون رفتند و خوابیدند. اما خرس کوچولو کجاست؟\r\nخرس کوچولو از خواب بیدار می شه و می گه: وای که چه خواب خوبی بود. چقدر خوابیدم! الان زمستونه! من که خیلی تنهام! و باز دوباره خوابید.\r\nدوبار بهار اومد و همه ی حیوونا شاد و سرحال بودند. اونا با هم یک جشن بزرگ گرفتند. اما خرس کوچولو کجاست؟\r\nهمه با صدای بلند خرس کوچولو رو صدا کردند. خرس کوچولو! بالاخره خرس کوچولو از خواب بیدار می شه و فصل بهار رو می بینه.\r\n"}];
